Object.assign(window.OTPU_CODE,{"opentpu/llm/generate.py": "\"\"\"The decode loop on the card: one device run generates up to N tokens (docs/autodecode.md).\n\nThe generate program of an attention bucket wraps the model's resident decode step (its step\nkernel at a run-time position, qwen3.RunPos; the step itself is unchanged) in a hardware loop:\n\n    LD the state block (the token, the position's run-time values, the tokens left, stop ids)\n    LOOP min(tokens left, block - tpos) times (RLD of the device-computed count):\n        each run-time argument c * var: RLD MUL of the variable's state word into its\n            argument register (the registers the host wrote before each run)\n        the step: the LM head hands each logits chunk to the sampler (m.lm_sink)\n        the model's post of the sampler's token, if it has one (m.post_token: Gemma 4 E4B\n            asks the host for the token's PLE record, which the next token's step waits for)\n        the token -> out[p + 1]  (fp32 ids, one word per position)\n        stop: the token is a stop id, or the host's stop word is set -> LOOP stop {HALT}\n        the state: tok = the token, tpos + 1, ring + 1 mod K, tokens left - 1\n    ST the state block, HALT\n\nThe host writes the state block, marks out[], starts the run and reads the tokens from out[]\nas they appear (Engine.generate_card); it never reads the logits. The ISA pieces are RLD (a\nTMEM word to a register), VOP ARGMAX and LOOP with a register count (docs/isa.md).\n\nThe run-time arguments are integers mod 2^32 as the host's (compiler.arg_words), whatever c:\nRLD MUL multiplies in the sequencer (a PLE row's bytes, tok * 9344, pass 2^31).\n\"\"\"\nfrom __future__ import annotations\n\nimport math\nfrom types import SimpleNamespace\n\nimport numpy as np\n\nfrom .. import fp32 as F\nfrom .. import isa as I\nfrom .. import language as ol\nfrom ..compiler import CompileError, Tensor, current, trace_fit\n\n# ---- the state block (fp32 words in DRAM, one per slice; 128-byte aligned). Its 64-byte beats\n# have one writer each during a run: words 0..15 the card's (the run-time variables), 16..31 the\n# host's (its stop word: BoardBackend.run_generate writes that beat alone, mid-run), 32..47 the\n# MTP loop's (mtp.py)\nSTATE_WORDS = 64\nS_TOK, S_TPOS, S_RING, S_LEFT = 0, 1, 2, 3       # the run-time variables, the tokens left\nS_K, S_ITEMP, S_TOPP = 4, 5, 6                    # sampling: top-k, log2(e) / T, top-p\nS_STOP = 8                                        # 8 stop ids (-1: none)\nN_STOP = 8\nS_HALT = 16                                       # the host's stop word (1.0: stop)\nS_PEN, S_PENINV = 17, 18                          # the repetition penalty R and 1 / R\nSLOT = {\"tok\": S_TOK, \"tpos\": S_TPOS, \"ring\": S_RING}\nOUT_MARK = 0xFFFFFFFF                             # out[] before the token lands (the device\n                                                  # stores ids, never this NaN)\n\n\nMODES = 2                  # chain areas: 0 greedy, 1 sampled (Samp)\nBLK = 64                   # the sampler's block of logits (block maxima, gathers)\nK_MAX = 64                 # the largest top-k the sampler takes\nTOPP_MIN = 2.0 ** -126     # the smallest top-p the sampler takes (below: the first token only)\n\n\ndef buckets(cap: int, block: int) -> int:\n    return -(-cap // block)\n\n\ndef _vpad(spec) -> int:\n    return -(-spec.vocab // BLK) * BLK\n\n\ndef prog_bytes(imem_words: int, waitc: bool = False) -> int:\n    \"\"\"A bucket program's slot in the chain area (bytes): two programs of IMEM's instructions\n    (32 bytes each), a split program's two parts (256 KiB at the card's 32K-word IMEM); on a\n    WAITC device (Config.SEQ_WC) each with its wait entries after it (opentpu.waits.area:\n    320 KiB).\"\"\"\n    from .. import waits as W\n    return 2 * W.area(imem_words, waitc)\n\n\ndef alloc(b, spec, cap: int, block: int, imem_words: int = 1 << 15, waitc: bool = False) -> dict:\n    \"\"\"DRAM of the generate loop: the state block, out[] (one fp32 id per position), the\n    bucket programs a run chains through (one slot per bucket and mode) and their tables\n    ([address, instructions] per bucket, raw words, one table per mode); the sampler's\n    logits (this slice's rows, -inf after them to a whole block), repetition penalty factors\n    (pa, pb: 1 / R and R for the ids in the context, 1 for the others), uniforms (one per\n    position, from the host) and constants (iota: 0 .. BLK - 1). A program slot holds two\n    programs that fit IMEM (`imem_words`: prog_bytes), with their wait entries on a WAITC device\n    (`waitc`: Config.SEQ_WC).\"\"\"\n    nb = buckets(cap, block)\n    V = _vpad(spec)\n    slot = prog_bytes(imem_words, waitc)\n    return {\"state\": b.alloc(4 * STATE_WORDS), \"out\": b.alloc(4 * (cap + 1)),\n            \"ptab\": b.alloc(8 * (nb + 2) * MODES), \"progs\": b.alloc(slot * nb * MODES),\n            \"slot\": slot,\n            \"lg\": b.alloc(4 * V), \"pa\": b.alloc(4 * V), \"pb\": b.alloc(4 * V),\n            \"uni\": b.alloc(4 * (cap + 1)), \"iota\": b.alloc(4 * BLK), \"nb\": nb,\n            \"ptab2\": b.alloc(16 * (nb + 2) * MODES), \"xs\": b.alloc(4 * spec.hidden)}\n\n\ndef prog_slot(g: dict, blocks: int, mode: int = 0, part: int = 0) -> int:\n    \"\"\"The chain area's slot of bucket `blocks` (1, 2, ...) in chain area `mode`; a split\n    program's second part in the slot's second half.\"\"\"\n    return g[\"progs\"] + g[\"slot\"] * (mode * g[\"nb\"] + blocks - 1) + part * g[\"slot\"] // 2\n\n\ndef slot_words(backend, prog) -> np.ndarray:\n    \"\"\"What a chain slot holds for `prog` (one slice's): its assembled words, and when the\n    backend's device loads wait entries (WAITC: backend.slot_words) its entries after them,\n    where HALT CHAIN's load reads them.\"\"\"\n    f = getattr(backend, \"slot_words\", None)\n    return f(prog) if f is not None else np.asarray(I.assemble(prog), np.uint32)\n\n\ndef ptab_addr(g: dict, mode: int = 0) -> int:\n    return g[\"ptab\"] + 8 * (g[\"nb\"] + 2) * mode\n\n\ndef ptab2_addr(g: dict, mode: int = 0) -> int:\n    \"\"\"The chain table of split programs: [address, instructions] of bucket k's part j at\n    words 2 (2k + j), 2 (2k + j) + 1.\"\"\"\n    return g[\"ptab2\"] + 16 * (g[\"nb\"] + 2) * mode\n\n\ndef build(put, s: int, S: int, spec, cap: int, g: dict) -> None:\n    put(s, g[\"out\"], np.full(cap + 1, OUT_MARK, np.uint32).view(np.float32))\n    V, v_loc = _vpad(spec), spec.vocab // S\n    lg = np.full(V, -np.inf, np.float32)\n    put(s, g[\"lg\"], lg[:-(-v_loc // BLK) * BLK])\n    put(s, g[\"pa\"], np.ones(V, np.float32))\n    put(s, g[\"pb\"], np.ones(V, np.float32))\n    put(s, g[\"iota\"], np.arange(BLK, dtype=np.float32))\n\n\ndef desc(g: dict, spec, cap: int) -> SimpleNamespace:\n    V = _vpad(spec)\n    return SimpleNamespace(state=Tensor(g[\"state\"], (STATE_WORDS,), (1,)),\n                           xs=Tensor(g[\"xs\"], (1, spec.hidden), (spec.hidden, 1)),\n                           out=Tensor(g[\"out\"], (cap + 1,), (1,)),\n                           uni=Tensor(g[\"uni\"], (cap + 1,), (1,)),\n                           lg=Tensor(g[\"lg\"], (V,), (1,)), pa=Tensor(g[\"pa\"], (V,), (1,)),\n                           pb=Tensor(g[\"pb\"], (V,), (1,)), iota=Tensor(g[\"iota\"], (BLK,), (1,)),\n                           addr=g)\n\n\ndef ptab_words(g: dict, progs: dict, mode: int = 0, split: bool = False) -> np.ndarray:\n    \"\"\"The chain table of `mode` for {blocks: assembled words}: [address, instructions] of\n    bucket k at words 2k, 2k + 1 (absent buckets 0). split: the table at ptab2_addr for\n    {blocks: (first part's words[, second part's])}: part j of bucket k at words 2 (2k + j),\n    2 (2k + j) + 1 (a bucket in one program: its program as the first part).\"\"\"\n    t = np.zeros(2 * (2 if split else 1) * (max(progs) + 2), np.uint32)\n    for k, w in progs.items():\n        for j, wj in enumerate(w if split else (w,)):\n            e = 2 * k + j if split else k\n            t[2 * e], t[2 * e + 1] = prog_slot(g, k, mode, j), len(wj) // 8\n    return t\n\n\n# ---- the per-token variables\ndef rules(spec, block: int) -> dict:\n    \"\"\"How each run-time variable moves from one token to the next: tok is the sampled id;\n    the others count (step, modulus). tpos = p mod block (it wraps to 0 as the last token of a\n    bucket moves the position into the next one, whose program the run chains to); ring =\n    (p + 1) mod K (LFM2's convolution ring, qwen3.RunPos).\"\"\"\n    return {\"tok\": None, \"tpos\": (1, block), \"ring\": (1, getattr(spec, \"conv_k\", 1))}\n\n\ndef check_args(run_args, spec, block: int) -> None:\n    \"\"\"Every run-time variable has an update rule and stays an exact fp32 integer in the state\n    block (below 2^24); RLD MUL forms c * var in the sequencer, mod 2^32 as the host's\n    arg_words.\"\"\"\n    bound = {\"tok\": spec.vocab, \"tpos\": block, \"ring\": getattr(spec, \"conv_k\", 1)}\n    for v, c in run_args:\n        if v.name not in bound:\n            raise CompileError(f\"run-time variable {v.name}: no update rule (generate.rules)\")\n        if bound[v.name] > 1 << 24:\n            raise CompileError(f\"{v.name} < {bound[v.name]} is not exact in fp32\")\n\n\ndef state_words(spec, tok: int, p: int, n: int, stop_ids, block: int,\n                samp: \"Sampling | None\" = None) -> np.ndarray:\n    \"\"\"The state block for generating up to n tokens after token `tok` at position p.\"\"\"\n    st = np.zeros(STATE_WORDS, np.float32)\n    ids = list(stop_ids)[:N_STOP]\n    if len(stop_ids) > N_STOP:\n        raise ValueError(f\"at most {N_STOP} stop ids\")\n    st[S_TOK], st[S_TPOS] = tok, p % block\n    st[S_RING] = (p + 1) % getattr(spec, \"conv_k\", 1)\n    st[S_LEFT] = n\n    st[S_STOP:S_STOP + N_STOP] = -1.0\n    st[S_STOP:S_STOP + len(ids)] = ids\n    if samp is not None:\n        st[S_K], st[S_ITEMP], st[S_TOPP] = samp.k, samp.itemp, samp.top_p\n        st[S_PEN], st[S_PENINV] = samp.penalty, np.float32(1.0) / np.float32(samp.penalty)\n    return st\n\n\nclass Sampling:\n    \"\"\"The sampled decode loop's parameters, as chat.sampler takes them: temperature (0:\n    greedy, with the penalty), top_k (1 .. K_MAX), top_p, repetition_penalty (>= 1). kmax,\n    penalty: what the program is compiled for (the candidate buffers; the penalty's loads);\n    the rest are run-time words of the state block. top_p <= 0 keeps the first token, as\n    Hugging Face's top-p (min_tokens_to_keep 1) and chat.sampler: greedy too (Sampler's rule\n    keeps the first i with sum(p[:i]) < P * sum(p): none below the smallest normal P, which\n    the VPU flushes to 0).\"\"\"\n\n    def __init__(self, temperature: float, top_k: int, top_p: float = 1.0,\n                 repetition_penalty: float = 1.0):\n        greedy = temperature <= 0 or top_p < TOPP_MIN\n        if not greedy and not 0 < top_k <= K_MAX:\n            raise ValueError(f\"the sampler on the device takes top_k 1 .. {K_MAX}\")\n        if repetition_penalty < 1.0:\n            raise ValueError(\"the sampler on the device takes repetition_penalty >= 1\")\n        self.k = 1 if greedy else int(top_k)\n        self.itemp = 1.0 if greedy else math.log2(math.e) / temperature\n        self.top_p = 1.0 if greedy else float(top_p)\n        self.penalty = float(repetition_penalty)\n        self.kmax = -(-self.k // 8) * 8\n        self.pen = self.penalty != 1.0\n\n    @property\n    def key(self) -> tuple:\n        return (self.kmax, self.pen)\n\n    @staticmethod\n    def fits(temperature: float, top_k: int, top_p: float, repetition_penalty: float) -> bool:\n        return (temperature <= 0 or top_p < TOPP_MIN or 0 < top_k <= K_MAX) and \\\n            repetition_penalty >= 1.0\n\n\n# ---- the sampler\nclass Greedy:\n    \"\"\"The LM head's sink: each chunk's ARGMAX while the next chunk streams, then the ARGMAX\n    of the chunk maxima picks the chunk and its index (ties: the first id, as np.argmax).\n    raw: the LM head does not soft-cap its chunks (a softcap keeps their order).\"\"\"\n\n    raw = True\n\n    def __init__(self, b, vocab: int, chunk: int):\n        self.b, self.chunk = b, chunk\n        self.nc = -(-vocab // chunk)\n        self.cm = b.alloc((self.nc, 2))              # per chunk (max, id)\n        self.seen = 0\n\n    def __call__(self, y, col0: int) -> None:\n        \"\"\"y: the logits of vocabulary rows col0.. (the chunks come in order).\"\"\"\n        k = self.seen\n        if k >= self.nc:\n            raise CompileError(\"the LM head gave more chunks than its rows\")\n        self.seen += 1\n        self.b.argmax(y, base=col0, out=self.cm[k:k + 1, :])\n\n    def token(self):\n        b = self.b\n        if self.seen != self.nc:\n            raise CompileError(f\"the LM head gave {self.seen} of {self.nc} chunks\")\n        best = b.argmax(_col(b, self.cm, 0))          # [max, chunk]\n        tok = _pick(b, best[1:2], 2, self.cm.base + 1, \"the best chunk's id\")\n        if b.S > 1:                                   # the slices' vocabulary rows, in order\n            ix = ol.all_gather(tok)\n            best = b.argmax(ol.all_gather(best[0:1]))\n            tok = _pick(b, best[1:2], 1, ix.base, \"the best slice's id\")\n        return tok\n\n\nNEG = -math.inf\nBIG = 2.0 ** 126                 # step(): x * BIG >= 1 for every normal x > 0\n\n\ndef _step(x):\n    \"\"\"1.0 where x > 0, else 0.0 (denormals count as 0: the VPU flushes them).\"\"\"\n    return ol.minimum(ol.maximum(x * BIG, 0.0), 1.0)\n\n\ndef _fill(b, t, v: float, ra: int = 0, n: int | None = None, comment: str = \"\") -> I.Instr:\n    return I.vop(I.V_FILL, t.base, 0, 0, 1, t.cols if n is None else n, 0, 0, 0, I.B_SCALAR, v,\n                 ra=ra, comment=comment or \"fill\")\n\n\ndef _loop(b, rcount: int, body: list) -> None:\n    b.emit(I.loop(len(body), 0, rcount=rcount))\n    for ins in body:\n        b.emit(ins)\n\n\ndef _select(b, vals, ids, kreg: int, out_v, out_id) -> None:\n    \"\"\"The R[kreg] largest of vals (a 1-D tile; knocked out to -inf as they are taken) in\n    descending order into out_v, and their ids (the same positions of `ids`) into out_id:\n    ARGMAX, the position by RLD, knock-out, the pair's value and id to the next outputs.\n    Ties: the first position.\"\"\"\n    pr = b.alloc((2,))\n    ri, rq = b.scratch(), b.scratch()\n    _loop(b, kreg, [\n        I.argmax(pr.base, vals.base, 1, vals.cols, comment=\"select\"),\n        I.rld(rq, pr.base + 1, comment=\"its position\"),\n        _fill(b, vals, NEG, ra=rq, n=1, comment=\"knock out\"),\n        I.vop(I.V_COPY, out_v.base, pr.base, 0, 1, 1, 0, 0, 0, ra=ri, comment=\"value\"),\n        I.vop(I.V_COPY, out_id.base, ids.base, 0, 1, 1, 0, 0, 0, ra=ri, rb=rq, comment=\"id\"),\n        I.addi(ri, ri, 1)])\n    b.unscratch(ri)\n    b.unscratch(rq)\n\n\nclass Sampler:\n    \"\"\"The LM head's sink of the sampled loop (chat.sampler's pick on the device):\n\n    each chunk: the repetition penalty (min(l * pa, l * pb): l / R for l > 0 and l * R for\n    l < 0 for the context's ids, as Hugging Face's), the logits to DRAM (lg) and the maxima of\n    their blocks of BLK;\n    token(): the k blocks with the largest maxima (ARGMAX, knock-out) gathered from lg, the k\n    largest logits among them (their order: descending, ties by position), with S > 1 the k\n    largest of all slices' (all_gather); p = exp2((l - l0) * log2(e) / T), the cumulative sums\n    (RDOT with a triangular matrix), top-p (keep the first i with sum(p[:i]) < P * sum(p)), the\n    pick = #{cum <= u * cum[last kept]} for the position's uniform u (at most the last kept),\n    its id. after(tok): tok joins the penalty's context. lg: the DRAM of this sink's logits\n    (default the loop's lg; MTP's verify has one per row), u_at: its uniform's position (default\n    pos.pos + 1, the next token's). pen_from (MTP's verify): the sink of the chunk's row before,\n    whose factors this one takes (loaded once per chunk; both then keep them).\"\"\"\n\n    def __init__(self, b, m, g, samp: Sampling, st, pos, consts, lg: int | None = None,\n                 u_at=None, pen_from: \"Sampler | None\" = None):\n        self.b, self.m, self.g, self.samp, self.st, self.pos = b, m, g, samp, st, pos\n        self.U, self.iota = consts\n        self.lg = g.addr[\"lg\"] if lg is None else lg\n        self.u_at = pos.pos + 1 if u_at is None else u_at\n        self.pen_from, self.shared = pen_from, False\n        if pen_from is not None:\n            pen_from.shared = True\n        self.chunk_seen = 0\n        v = m.v_loc\n        self.o = ol.program_id() * v             # this slice's first vocabulary row\n        self.nb = -(-v // BLK)\n        self.bm = b.alloc((self.nb,))            # block maxima\n        self.pt = None                           # the penalty's tiles (at the first chunk)\n\n    @staticmethod\n    def constants(b, g, samp: Sampling):\n        \"\"\"Before the token loop: the triangular [kmax, kmax] ones (U[r, c] = c <= r) from\n        iota, and iota.\"\"\"\n        km = samp.kmax\n        iota = ol.load(g.iota)\n        col = iota[0:km]\n        U = b.alloc((km, km))\n        # U[r, c] = step(r + 1 - c): A = iota per column (ars 0), B = iota + 1 per row\n        r1 = col + 1.0\n        b.emit(I.vop(I.V_RSUB, U.base, col.base, r1.base, km, km, km, 0, 1, I.B_ROW,\n                     comment=\"r + 1 - c\"))\n        U.set(_step(U))\n        return U, iota\n\n    def __call__(self, y, col0: int) -> None:\n        b, g = self.b, self.g\n        self.chunk_seen += 1\n        y = y[0, :] if len(y.shape) == 2 else y\n        n = y.cols\n        c0 = col0 - self.o                       # this slice's row\n        a = y.base\n        if self.samp.pen and not (self.shared or self.pen_from):     # in place in the\n            if self.pt is None:                                          # penalty's tiles\n                # two for the whole LM head: fresh ones per chunk would be freed under the\n                # next chunk's MM output, which then waits for this chunk's work (a TMEM write\n                # after read), and the MXU with it\n                self.pt = (b.alloc((n,)), b.alloc((n,)))\n            assert n <= self.pt[0].cols, \"LM head chunks of different sizes\"\n            pa, pb = (t.base for t in self.pt)\n            b.emit(I.ld(g.addr[\"pa\"] + 4 * col0, pa, n, comment=\"pa\"))\n            b.emit(I.ld(g.addr[\"pb\"] + 4 * col0, pb, n, comment=\"pb\"))\n            b.emit(I.vop(I.V_MUL, pa, y.base, pa, 1, n, n, n, n, comment=\"l * pa\"))\n            b.emit(I.vop(I.V_MUL, pb, y.base, pb, 1, n, n, n, n, comment=\"l * pb\"))\n            b.emit(I.vop(I.V_MIN, pa, pa, pb, 1, n, n, n, n, comment=\"the penalty\"))\n            a = pa\n        elif self.samp.pen:          # shared factors: the product, then l * pb in place in l\n            if self.pt is None:\n                self.pt = (b.alloc((n,)),) + ((b.alloc((n,)), b.alloc((n,)))\n                                               if self.pen_from is None else ())\n            assert n <= self.pt[0].cols, \"LM head chunks of different sizes\"\n            fa, fb = (t.base for t in (self.pen_from or self).pt[-2:])\n            if self.pen_from is None:\n                b.emit(I.ld(g.addr[\"pa\"] + 4 * col0, fa, n, comment=\"pa\"))\n                b.emit(I.ld(g.addr[\"pb\"] + 4 * col0, fb, n, comment=\"pb\"))\n            t = self.pt[0].base\n            b.emit(I.vop(I.V_MUL, t, y.base, fa, 1, n, n, n, n, comment=\"l * pa\"))\n            b.emit(I.vop(I.V_MUL, y.base, y.base, fb, 1, n, n, n, n, comment=\"l * pb\"))\n            b.emit(I.vop(I.V_MIN, t, t, y.base, 1, n, n, n, n, comment=\"the penalty\"))\n            a = t\n        b.emit(I.st(self.lg + 4 * c0, a, n, comment=\"lg\"))\n        nf, k0 = n // BLK, c0 // BLK\n        if nf:\n            b.emit(I.vop(I.V_RMAX, self.bm.base + k0, a, 0, nf, BLK, 1, BLK, 0,\n                         comment=\"block maxima\"))\n        if n % BLK:\n            b.emit(I.vop(I.V_RMAX, self.bm.base + k0 + nf, a + nf * BLK, 0, 1, n % BLK, 1,\n                         n % BLK, 0, comment=\"block maxima\"))\n\n    def token(self):\n        b, g, st, samp = self.b, self.g, self.st, self.samp\n        self.pt = None\n        km = samp.kmax\n        # the blocks: k1 = min(k, blocks) of them, each block's logits and ids gathered\n        cand, ids = b.alloc((km * BLK,)), b.alloc((km * BLK,))\n        b.emit(_fill(b, cand, NEG, comment=\"candidates\"))\n        kk = st[S_K:S_K + 1]\n        k1 = ol.minimum(kk, float(self.nb))\n        pr, off, base = b.alloc((2,)), b.alloc((1,)), b.alloc((1,))\n        rk, rj, rb_, ro = b.scratch(), b.scratch(), b.scratch(), b.scratch()\n        b.rld(rk, k1, comment=\"blocks\")\n        _loop(b, rk, [\n            I.argmax(pr.base, self.bm.base, 1, self.nb, comment=\"block\"),\n            I.rld(rb_, pr.base + 1, comment=\"its index\"),\n            _fill(b, self.bm, NEG, ra=rb_, n=1, comment=\"knock out\"),\n            I.vop(I.V_MUL, off.base, pr.base + 1, 0, 1, 1, 0, 0, 0, I.B_SCALAR, 4.0 * BLK,\n                  comment=\"block bytes\"),\n            I.vop(I.V_MUL, base.base, pr.base + 1, 0, 1, 1, 0, 0, 0, I.B_SCALAR, float(BLK),\n                  comment=\"block id\"),\n            I.vop(I.V_ADD, base.base, base.base, 0, 1, 1, 0, 0, 0, I.B_SCALAR, float(self.o),\n                  comment=\"+ the slice's first row\"),\n            I.rld(ro, off.base),\n            I.ld(self.lg, cand.base, BLK, ra=ro, rb=rj, comment=\"the block's logits\"),\n            I.vop(I.V_ADD, ids.base, self.iota.base, base.base, 1, BLK, 0, 0, 0, I.B_ROW,\n                  ra=rj, comment=\"their ids\"),\n            I.addi(rj, rj, BLK)])\n        for r in (rj, rb_, ro):\n            b.unscratch(r)\n        b.rld(rk, kk, comment=\"top-k\")\n        vals, sid = b.alloc((km,)), b.alloc((km,))\n        vals.set(NEG)\n        sid.set(0.0)\n        _select(b, cand, ids, rk, vals, sid)\n        if b.S > 1:                             # the k largest of all slices\n            gv, gi = ol.all_gather(vals), ol.all_gather(sid)\n            vals.set(NEG)\n            _select(b, gv, gi, rk, vals, sid)\n        b.unscratch(rk)\n        # softmax, the cumulative sums, top-p, the pick\n        p = ol.exp2((vals - vals[0:1]) * st[S_ITEMP:S_ITEMP + 1])\n        cumx = b.alloc((km + 1,))\n        cumx[0:1].set(0.0)\n        b.emit(I.vop(I.V_RDOT, cumx.base + 1, self.U.base, p.base, km, km, 1, km, 0, I.B_COL,\n                     comment=\"cumulative sums\"))\n        cum, prev = cumx[1:km + 1], cumx[0:km]\n        pz = cumx[km:km + 1] * st[S_TOPP:S_TOPP + 1]\n        kept = _step(pz - prev)\n        zk = ol.max(cum * kept)\n        u = ol.load(g.uni[self.u_at:self.u_at + 1])\n        t = u * zk\n        le = ol.sum(_step(cum - t)) * -1.0 + float(km)\n        pick = ol.minimum(le, ol.sum(kept) - 1.0)\n        return _pick(b, pick, 1, sid.base, \"the sampled id\")\n\n    def after(self, tok) -> None:\n        \"\"\"The penalty's context gets tok: pa[tok] = 1 / R, pb[tok] = R.\"\"\"\n        if not self.samp.pen:\n            return\n        b, g, st = self.b, self.g, self.st\n        r = b.scratch()\n        b.rld(r, tok * 4.0, comment=\"the id's bytes\")\n        b.emit(I.st(g.addr[\"pa\"], st.base + S_PENINV, 1, ra=r, comment=\"pa[tok] = 1 / R\"))\n        b.emit(I.st(g.addr[\"pb\"], st.base + S_PEN, 1, ra=r, comment=\"pb[tok] = R\"))\n        b.unscratch(r)\n\n\ndef softcap_ref(x, c: float) -> np.ndarray:\n    \"\"\"kernels.lib.softcap in the ISA's fp32 arithmetic: 2c / (1 + 2^(x (-2 log2(e) / c))) - c,\n    as the LM head's VOPs compute it.\"\"\"\n    f32 = np.float32\n    t = F.recip(F.add(F.exp2(F.mul(x, f32(-2.0 * ol.LOG2E / c))), f32(1.0)))\n    return F.sub(F.mul(t, f32(2.0 * c)), f32(c))\n\n\ndef reference_pick(logits, samp: Sampling, context, u, S: int = 1, softcap: float | None = None):\n    \"\"\"The id the device's sampler picks from `logits` (the whole vocabulary) with uniform u,\n    bit for bit: Sampler's steps in numpy with the ISA's fp32 arithmetic (opentpu.fp32). An\n    array of uniforms gives an array of ids. softcap: the spec's (the LM head caps the\n    sampler's logits first).\"\"\"\n    f32 = np.float32\n    lg = F.ftz(np.asarray(logits, f32)).copy()\n    if softcap:\n        lg = softcap_ref(lg, softcap)\n    V = len(lg)\n    if samp.pen:\n        a, b = np.ones(V, f32), np.ones(V, f32)\n        ix = np.unique(np.asarray(list(context), np.int64))\n        a[ix], b[ix] = f32(1.0) / f32(samp.penalty), samp.penalty\n        lg = F.fmin(F.mul(lg, a), F.mul(lg, b))\n    km, k, v = samp.kmax, samp.k, V // S\n\n    def select(vals, ids, n_out, out_v, out_i):\n        vals = vals.copy()\n        for i in range(n_out):\n            q = int(np.argmax(F._key(vals)))\n            out_v[i], out_i[i] = F.ftz(vals[q]), ids[q]\n            vals[q] = -np.inf\n\n    vals, sid = [], []\n    for s in range(S):\n        nb = -(-v // BLK)\n        x = np.full(nb * BLK, -np.inf, f32)\n        x[:v] = lg[s * v:(s + 1) * v]\n        bm = F.chain_max(x.reshape(nb, BLK))\n        cand, ids = np.full(km * BLK, -np.inf, f32), np.zeros(km * BLK, f32)\n        for j in range(min(k, nb)):\n            q = int(np.argmax(F._key(bm)))\n            bm[q] = -np.inf\n            cand[j * BLK:(j + 1) * BLK] = x[q * BLK:(q + 1) * BLK]\n            ids[j * BLK:(j + 1) * BLK] = F.add(np.arange(BLK, dtype=f32), f32(q * BLK + s * v))\n        vs, si = np.full(km, -np.inf, f32), np.zeros(km, f32)\n        select(cand, ids, k, vs, si)\n        vals.append(vs)\n        sid.append(si)\n    vs, si = vals[0], sid[0]\n    if S > 1:\n        vs = np.full(km, -np.inf, f32)\n        select(np.concatenate(vals), np.concatenate(sid), k, vs, si)\n\n    def step(x):\n        return F.fmin(F.fmax(F.mul(x, f32(BIG)), f32(0)), f32(1))\n\n    p = F.exp2(F.mul(F.sub(vs, vs[0]), f32(samp.itemp)))\n    c = np.arange(km)\n    U = step(F.sub(F.add(c.astype(f32), f32(1))[:, None], c.astype(f32)[None, :]))\n    cum = F.rdot(U, np.broadcast_to(p, (km, km)))\n    prev = np.concatenate([[f32(0)], cum[:-1]]).astype(f32)\n    kept = step(F.sub(F.mul(cum[-1], f32(samp.top_p)), prev))\n    if not kept[0]:              # the device would pick the word before the ids\n        raise ValueError(f\"top_p {samp.top_p} keeps no token (Sampling: P >= TOPP_MIN)\")\n    zk = F.chain_max(F.mul(cum, kept)[None, :])[0]\n    uu = np.minimum(np.atleast_1d(np.asarray(u, f32)), f32(1 - 2.0 ** -24))\n    t = F.mul(uu, zk)[:, None]\n\n    def total(x):\n        return F.interleaved_sum(np.atleast_2d(x), F.RED_PARTIALS)\n    le = F.add(F.mul(total(step(F.sub(cum[None, :], t))), f32(-1)), f32(km))\n    pick = F.fmin(le, F.sub(total(kept), f32(1)))\n    ids = si[pick.astype(np.int64)].astype(np.int64)\n    return ids if np.ndim(u) else int(ids[0])\n\n\ndef _col(b, t, c: int):\n    \"\"\"Column c of a [rows, cols] tile as a new contiguous [rows] tile.\"\"\"\n    out = b.alloc((t.rows,))\n    b.emit(I.vop(I.V_COPY, out.base, t.base + c, 0, t.rows, 1, 1, t.rs, 0, comment=\"column\"))\n    return out\n\n\ndef _pick(b, k, stride: int, base: int, what: str):\n    \"\"\"A new [1] tile holding T[base + stride * k] (k a tile holding a small integer).\"\"\"\n    if stride != 1:\n        k = k * float(stride)\n    r = b.scratch()\n    b.rld(r, k)\n    out = b.alloc((1,))\n    b.emit(I.vop(I.V_COPY, out.base, base, 0, 1, 1, 0, 0, 0, rb=r, comment=what))\n    b.unscratch(r)\n    return out\n\n\n# ---- the program\ndef _sink(b, m, g, samp, st, pos, consts, debug):\n    \"\"\"The LM head's sink (Greedy or Sampler), set on m.\"\"\"\n    chunk = min(8192, b.cfg.TMEM_WORDS // 8)       # qwen3.HEAD_CHUNK, _lm_head's chunks\n    sink = (Greedy(b, m.v_loc, chunk) if samp is None\n            else Sampler(b, m, g, samp, st, pos, consts))\n    m.lm_sink, m.lm_keep = sink, debug\n    return sink\n\n\ndef _post(m, tok) -> None:\n    \"\"\"The model's post of the sampled token to the host, when it has one (m.post_token: Gemma\n    4 E4B asks for the token's PLE record, which the next token's step waits for).\"\"\"\n    post = getattr(m, \"post_token\", None)\n    if post is not None:\n        post(tok)\n\n\ndef _token_end(b, g, st, pos, spec, block, samp, sink, tok, split: bool = False) -> None:\n    \"\"\"The token to out[p + 1], HALT at a stop, the next token's state in st: tok, the\n    run-time variables the step used (in a split program's second part every one: the step\n    ran in the first part, and the chain follows tpos), the tokens left.\"\"\"\n    ol.store(g.out[pos.pos + 1:pos.pos + 2], tok)\n    if samp is not None:\n        sink.after(tok)\n    # stop: the token is one of the stop ids, or the host asks\n    ids = st[S_STOP:S_STOP + N_STOP]\n    hit = ol.minimum(ol.abs(ids - tok), 1.0) * -1.0 + 1.0     # 1 where equal (integers)\n    halt = ol.load(g.state[S_HALT:S_HALT + 1])\n    stop = ol.maximum(ol.max(hit), halt)\n    r = b.scratch()\n    b.rld(r, stop, comment=\"stop\")\n    b.emit(I.loop(1, 0, rcount=r, comment=\"stop: halt\"))\n    b.emit(I.halt())\n    b.unscratch(r)\n    # the next token's state\n    rl = rules(spec, block)\n    st[S_TOK:S_TOK + 1].set(tok)\n    used = set(SLOT) if split else {v.name for v, _ in b.run_seen}\n    for name, slot in SLOT.items():\n        rule = rl[name]\n        if rule is None or name not in used:\n            continue\n        stepv, mod = rule\n        v = st[slot:slot + 1]\n        v.set(v + float(stepv))\n        if mod:            # v - mod * [v >= mod], exact for small integers\n            w = ol.minimum(ol.maximum(v + float(1 - mod), 0.0), 1.0)\n            v.set(v - w * float(mod))\n    left = st[S_LEFT:S_LEFT + 1]\n    left.set(left - 1.0)\n\n\ndef _arguments(b, body: list, mark: int, st, spec, block) -> None:\n    \"\"\"The run-time arguments (c * var alone in an address) loaded at body[mark], now that the\n    step has named them all.\"\"\"\n    check_args(b.run_seen, spec, block)\n    body[mark:mark] = [I.rld(15 - k, st.base + SLOT[v.name], mul=int(c),\n                             comment=f\"argument {c}*{v.name}\")\n                       for k, (v, c) in enumerate(b.run_args)]\n    b.run_words = None\n\n\ndef _chain(b, tab_at: int, cond=None, off=None, what: str = \"next bucket\") -> None:\n    \"\"\"HALT CHAIN to the program of the chain table's entry at DRAM tab_at (+ R[off] bytes,\n    off a tile holding them), when cond (a tile holding 0 or 1; None: always).\"\"\"\n    tab = b.alloc((2,))\n    r, ro, ra, rb = (b.scratch() if x is not None else 0 for x in (cond, off, 1, 1))\n    if cond is not None:\n        b.rld(r, cond, comment=\"tokens left\")\n    if off is not None:\n        b.rld(ro, off, comment=\"table offset\")\n    body = [I.ld(tab_at, tab.base, 2, ra=ro, comment=what),\n            I.rld(ra, tab.base, raw=True), I.rld(rb, tab.base + 1, raw=True),\n            I.halt(chain=True, ra=ra, rb=rb)]\n    if cond is not None:\n        b.emit(I.loop(len(body), 0, rcount=r, comment=\"chain\"))\n    for ins in body:\n        b.emit(ins)\n    for x in (r, ro, ra, rb):\n        if x:\n            b.unscratch(x)\n\n\ndef _generate(m, pos, block, step, spec, chain, samp=None, debug=False):\n    b = current()\n    g = m.gen\n    st = ol.load(g.state)\n    consts = Sampler.constants(b, g, samp) if samp is not None else None\n    left = st[S_LEFT:S_LEFT + 1]\n    n = ol.minimum(left, (st[S_TPOS:S_TPOS + 1] * -1.0) + float(block))  # to the bucket's end\n    r = b.scratch()\n    b.rld(r, n, comment=\"tokens in this bucket\")\n    loop = b.begin_loop(0, rcount=r)\n    b.unscratch(r)                     # the count is read when the loop starts\n    body = b.stack[-1]\n    mark = len(body)                   # the argument loads go here (known after the step)\n    sink = _sink(b, m, g, samp, st, pos, consts, debug)\n    # a register stepping with loops from c * var starts with an RLD MUL of var's state word\n    b.run_words = {name: st.base + slot for name, slot in SLOT.items()}\n    step.fn(m=m, pos=pos, block=block)\n    tok = sink.token()\n    _post(m, tok)\n    _token_end(b, g, st, pos, spec, block, samp, sink, tok)\n    _arguments(b, body, mark, st, spec, block)\n    b.end_loop(loop)\n    ol.store(g.state[:S_HALT], st[:S_HALT])      # not the host's stop word\n    if chain:              # tokens left: on to the next bucket's program (chain table)\n        _chain(b, ptab_addr(g.addr, int(samp is not None)) + 8 * (pos.blocks + 1),\n               cond=ol.minimum(left, 1.0))\n\n\ndef _generate_layers(m, pos, block, step, spec, samp=None):\n    \"\"\"A split generate program's first part (a bucket's program over IMEM): the step's layers\n    for the state block's token, x to DRAM (qwen3._lm_head stores it there: m.lm_split), then\n    HALT CHAIN to the second part.\"\"\"\n    b = current()\n    g = m.gen\n    st = ol.load(g.state)\n    body = b.stack[-1]\n    mark = len(body)\n    b.run_words = {name: st.base + slot for name, slot in SLOT.items()}\n    m.lm_split = g.xs\n    step.fn(m=m, pos=pos, block=block)\n    _arguments(b, body, mark, st, spec, block)\n    _chain(b, ptab2_addr(g.addr, int(samp is not None)) + 8 * (2 * pos.blocks + 1),\n           what=\"the token's second part\")\n\n\ndef _generate_head(m, pos, block, step, spec, samp=None, debug=False):\n    \"\"\"A split generate program's second part: x from DRAM, the step's LM head into the\n    sampler, the token (as the loop's body), the state block back to DRAM, then with tokens\n    left HALT CHAIN to this bucket's first part, or at its end (tpos back to 0) the next\n    bucket's.\"\"\"\n    from .qwen3 import _lm_head\n    b = current()\n    g = m.gen\n    st = ol.load(g.state)\n    body = b.stack[-1]\n    mark = len(body)\n    b.run_words = {name: st.base + slot for name, slot in SLOT.items()}\n    consts = Sampler.constants(b, g, samp) if samp is not None else None\n    sink = _sink(b, m, g, samp, st, pos, consts, debug)\n    (getattr(step, \"head\", None) or _lm_head)(ol.load(g.xs), m, spec)\n    tok = sink.token()\n    _post(m, tok)\n    _token_end(b, g, st, pos, spec, block, samp, sink, tok, split=True)\n    _arguments(b, body, mark, st, spec, block)\n    ol.store(g.state[:S_HALT], st[:S_HALT])      # not the host's stop word\n    left = st[S_LEFT:S_LEFT + 1]\n    wrap = ol.minimum(st[S_TPOS:S_TPOS + 1], 1.0) * -16.0 + 16.0   # 16 bytes: the next bucket\n    _chain(b, ptab2_addr(g.addr, int(samp is not None)) + 8 * (2 * pos.blocks),\n           cond=ol.minimum(left, 1.0), off=wrap, what=\"the next token's first part\")\n\n\ndef compile_generate(image, kernel, blocks: int, lo: int, block: int, chain: bool = True,\n                     samp: Sampling | None = None, debug: bool = False,\n                     part: int | None = None):\n    \"\"\"The generate program of positions [lo, blocks * block) (compile_decode's bucket):\n    the step kernel at a RunPos in the token loop (see the module), greedy or sampled (samp),\n    then, with `chain` and tokens left, HALT CHAIN to the next bucket's program (the entry\n    blocks + 1 of the mode's table). debug: the LM head stores each token's logits to\n    m.logits as well (the resident step's store), for checks against it. part 0 / 1: the two\n    programs of the split form instead (one token each, chaining to each other through the\n    split table: _generate_layers, _generate_head), for a bucket whose program does not fit\n    (compile_bucket). Returns the programs.\"\"\"\n    from .qwen3 import RunPos\n    if not image.lookup:\n        raise ValueError(\"compile_generate needs an image with lookup tables (lookup=True)\")\n    if not (blocks - 1) * block <= lo < min(blocks * block, image.cap):\n        raise ValueError(f\"lo {lo} is not in bucket {blocks}\")\n    if part is not None and not chain:\n        raise ValueError(\"a split generate program chains (HALT CHAIN)\")\n    # the bucket's mask rows (Gemma 4 computes its own, m.mask: no table)\n    rp = RunPos(blocks, block, lo, image.lookup.get(\"zmask\", 0), image.cap)\n    fn, kw = {None: (_generate, {\"chain\": chain, \"debug\": debug}), 0: (_generate_layers, {}),\n              1: (_generate_head, {\"debug\": debug})}[part]\n    progs, k = [], ol.jit(fn)\n    for s in range(image.cfg.S):\n        def args(s=s):\n            return {\"m\": image.descriptors(s), \"pos\": rp, \"block\": block, \"step\": kernel,\n                    \"spec\": image.spec, \"samp\": samp, **kw}\n        # the split form has no smaller form to fall back to: placed best-fit where next-fit\n        # leaves no gap (trace_fit; a small TMEM), as a decode step is\n        progs.append((trace_fit(k, image.cfg, s, args) if part is not None else\n                      k.trace(image.cfg, s, args())).finish())\n    return progs\n\n\ndef fits(image, progs) -> bool:\n    return all(len(p) <= image.cfg.IMEM_WORDS // 8 for p in progs)\n\n\ndef compile_bucket(image, blocks: int, lo: int, block: int, chain: bool = True,\n                   samp: Sampling | None = None, debug: bool = False, split: bool | None = None):\n    \"\"\"A bucket's generate programs: the token loop in one program per slice (a list), or, when\n    that does not fit IMEM or TMEM (or split=True; split=False never) and the run chains, the\n    split form: (first parts, second parts), two programs per token.\"\"\"\n    if split is not True or not chain:\n        try:\n            progs = image.compile_generate(blocks, lo, block, chain=chain, samp=samp,\n                                           debug=debug)\n            if fits(image, progs) or split is False or not chain:\n                return progs\n        except CompileError:\n            if split is False or not chain:\n                raise\n    parts = tuple(image.compile_generate(blocks, lo, block, chain=True, samp=samp, debug=debug,\n                                         part=j) for j in (0, 1))\n    for j, progs in enumerate(parts):\n        if not fits(image, progs):\n            raise CompileError(f\"bucket {blocks}'s split generate program: part {j} has \"\n                               f\"{max(map(len, progs))} instructions, IMEM \"\n                               f\"{image.cfg.IMEM_WORDS // 8}\")\n    return parts\n", "opentpu/llm/lfm2.py": "\"\"\"LFM2 hybrid decoder (Liquid AI LFM2 / LFM2.5, e.g. LFM2.5-230M) on openTPU.\n\nLFM2 stacks two kinds of layers, each followed by Qwen3's pre-norm SwiGLU MLP:\n  conv   gated short convolution: in_proj -> B, C, x; y = C * conv(B * x), a causal depthwise\n         convolution (3 taps per channel, no bias); out_proj. Its state is the last two rows of\n         B * x, kept in fp32 in a 3-slot ring in DRAM (the row of position p in slot p % 3),\n         mirrored: each row is stored twice, so the last K rows are contiguous and one\n         address register reaches them at a run-time position (_ring_rows).\n  attn   GQA attention with RMSNorm on each q and k head, then RoPE: Qwen3's attention\n         (qwen3._attention). The heads are 64 wide, half the MXU depth, so the queries and\n         the cached K and V rows are padded with zeros to 128 (qwen3._padded); P.V reads only\n         V's 64 real rows, and the head outputs are not padded.\nLFM2.5-230M has 14 layers, c c A c A c A c A c A c A c: the step kernel runs the repeated\n(conv, attn) pair as a hardware loop and the other layers unrolled (`plan`).\n\nPieces:\n  Spec              model dimensions and layer kinds (from a Hugging Face config.json)\n  reference_logits  plain numpy forward pass (the math, fp32)\n  emulated_logits   float64 decode with openTPU's quantization points (see qwen3)\n  Image             per-slice DRAM layout: equal-size layer blocks of either kind, so a\n                    hardware loop over (conv, attn) pairs steps one address register\n  lfm2_step         the ol kernel for one decode token\n\n  lfm2_rows         R consecutive prompt tokens per device run (chunked prefill,\n                    qwen3.Engine.prefill_chunks): the convolution over the chunk's rows and\n                    the ring, qwen3's row attention\n\nWeights, activations and the KV cache use Qwen3's W8A8 scheme, and decoding runs on\nqwen3.Engine (one sequence: no batched decode).\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport math\nimport os\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport numpy as np\n\nfrom .. import fp32 as F\nfrom .. import qcache as QC\nfrom .. import quant as Q\nfrom .. import language as ol\nfrom .. import isa as I\nfrom ..compiler import Affine, KVDesc, QTensor, Tensor, current, k_scale_bytes, trace_fit\nfrom ..isasim import Config\nfrom ..kernels.layouts import head_parallel_attention_weights\nfrom ..kernels.lib import rmsnorm\nfrom ..kernels.mlp import _chunk, down_chunk\nfrom ..host.offload import ExpertServer, Layout\nfrom . import formats as FM\nfrom . import generate as G\nfrom . import moe as MO\nfrom . import rope_parameters\nfrom .qwen3 import (OutTokens, RunPos, RunRows, RunWords, _formats, _inputs, _inputs_rows,\n                    _amask, _lookup_alloc, _lookup_build, _lookup_desc, _tok_arg, _tokens_arg,\n                    compile_decode, put_head)\nfrom .qwen3 import (ATTN_BLOCK, _attention, _attention_rows, _Bump, _fake_k, _fake_q, _fake_w,\n                    _qk, gathered_rows, _lm_head,\n                    _lm_head_rows, _mlp, _pv, _qdesc, _tdesc, _v_parts, rope_tables, EmbedHost,\n                    fill_logits, step_descriptors)\n\nCONV, ATTN = \"conv\", \"attn\"\n# A plan with more layer bodies than this runs each MLP's F chunks as a hardware loop\n# (kernels.mlp.swiglu_down loop): LFM2-2.6B's 10 bodies with 12 unrolled chunks each would\n# fill the 4K-instruction IMEM; LFM2.5-230M's 4 keep them unrolled. OTPU_MLP_UNROLL_BODIES\n# overrides it (0: always a loop), e.g. to measure both on the same layers.\nMLP_UNROLL_BODIES = int(os.environ.get(\"OTPU_MLP_UNROLL_BODIES\", 8))\n\n\n# =============================================================================== model spec\n@dataclass(frozen=True)\nclass Spec:\n    hidden: int\n    kinds: tuple            # CONV or ATTN per layer\n    n_q: int\n    n_kv: int\n    head_dim: int\n    ffn: int\n    vocab: int\n    conv_k: int = 3         # convolution taps (the current row and conv_k - 1 before it)\n    eps: float = 1e-5\n    theta: float = 1e6\n    tied: bool = True\n    bos: int = 1\n    eos: tuple = (7,)\n    moe: MO.MoESpec | None = None   # LFM2-MoE: layers moe.first.. have routed experts\n    embed: str = \"f32\"      # the embedding rows: fp32, or \"int8\" per D block (as qwen3.Spec:\n                            # gathered on the device from the tied int8 head or a table)\n    formats: str = \"\"       # weight formats per kind over the image's wformat (KINDS)\n    mix: str = \"\"           # the recommended mix (wformat \"mix\": formats.named, MIXES)\n\n    @property\n    def layers(self) -> int:\n        return len(self.kinds)\n\n    def is_moe(self, i: int) -> bool:\n        return self.moe is not None and i >= self.moe.first\n\n    @property\n    def lkinds(self) -> tuple:\n        \"\"\"Each layer's kind, and for a MoE model whether it is a MoE layer (what the plan\n        loops over: a hardware loop runs layers of one kind).\"\"\"\n        if self.moe is None:\n            return self.kinds\n        return tuple((k, self.is_moe(i)) for i, k in enumerate(self.kinds))\n\n    @property\n    def rope_dim(self) -> int:\n        return self.head_dim\n\n    @staticmethod\n    def from_hf(model_dir) -> \"Spec\":\n        c = json.loads((Path(model_dir) / \"config.json\").read_text())\n        ff = c[\"intermediate_size\"]\n        if c.get(\"block_auto_adjust_ff_dim\"):        # as Lfm2MLP sizes it\n            ff = int(2 * ff / 3)\n            if c.get(\"block_ffn_dim_multiplier\") is not None:\n                ff = int(c[\"block_ffn_dim_multiplier\"] * ff)\n                m = c[\"block_multiple_of\"]\n                ff = m * ((ff + m - 1) // m)\n        eos = c.get(\"eos_token_id\", 7)\n        g = Path(model_dir) / \"generation_config.json\"\n        if g.exists():\n            eos = json.loads(g.read_text()).get(\"eos_token_id\", eos)\n        rope = rope_parameters(c, model_dir)\n        moe = None\n        if c.get(\"model_type\") == \"lfm2_moe\":\n            if not c.get(\"use_expert_bias\", True):\n                raise ValueError(\"LFM2-MoE without the expert bias is not supported\")\n            moe = MO.MoESpec(E=c[\"num_experts\"], k=c[\"num_experts_per_tok\"],\n                             ffn=c[\"moe_intermediate_size\"], first=c[\"num_dense_layers\"],\n                             norm=c.get(\"norm_topk_prob\", True),\n                             scale=c.get(\"routed_scaling_factor\", 1.0))\n        return Spec(hidden=c[\"hidden_size\"],\n                    kinds=tuple(ATTN if t == \"full_attention\" else CONV for t in c[\"layer_types\"]),\n                    n_q=c[\"num_attention_heads\"], n_kv=c[\"num_key_value_heads\"],\n                    head_dim=c.get(\"head_dim\") or c[\"hidden_size\"] // c[\"num_attention_heads\"],\n                    ffn=ff, vocab=c[\"vocab_size\"], conv_k=c.get(\"conv_L_cache\", 3),\n                    eps=c.get(\"norm_eps\", 1e-5),\n                    theta=rope.get(\"rope_theta\", c.get(\"rope_theta\", 1e6)),\n                    tied=c.get(\"tie_word_embeddings\", c.get(\"tie_embedding\", True)),\n                    bos=c.get(\"bos_token_id\", 1),\n                    eos=tuple(eos) if isinstance(eos, list) else (eos,), moe=moe,\n                    # a MoE's DRAM beside its layers is expert slots: its table int8\n                    embed=\"int8\" if moe is not None else \"f32\", mix=FM.mix_for(c))\n\n    def check(self, cfg: Config) -> None:\n        S, D = cfg.S, cfg.D\n        need = [((self.head_dim <= D or self.head_dim % D == 0) and self.head_dim % 2 == 0,\n                 f\"head_dim {self.head_dim}: at most D or a multiple of D {D}\"),\n                (self.n_q * self.head_dim % D == 0, \"n_q * head_dim % D\"),\n                (self.hidden % (S * D) == 0, f\"hidden {self.hidden} % S*D\"),\n                (self.ffn % (S * D) == 0, f\"ffn {self.ffn} % S*D\"),\n                (self.n_kv % S == 0, f\"n_kv {self.n_kv} % S\"),\n                (self.n_q % self.n_kv == 0, \"n_q % n_kv\"),\n                (self.n_q // self.n_kv <= cfg.MCOLS, \"query group larger than MXU columns\"),\n                (self.vocab % S == 0, f\"vocab {self.vocab} % S\"),\n                (max(self.ffn, self.n_q * self.head_dim, self.hidden) <= cfg.ACT_BLOCKS * D,\n                 \"an inner dimension exceeds ACT RAM\")]\n        if self.moe is not None:\n            need += [(S == 1, \"MoE layers run on one slice\"),\n                     (self.moe.ffn % D == 0, f\"expert width {self.moe.ffn} % D\"),\n                     (self.moe.k <= self.moe.E, \"top-k above the expert count\")]\n        bad = [m for ok, m in need if not ok]\n        if bad:\n            raise ValueError(\"model does not map onto this openTPU config: \" + \"; \".join(bad))\n\n    def image(self, cfg: Config, cap: int, batch: int = 1, rows: int = 1,\n              wformat: str = \"int8\", head_format: str | None = None,\n              lookup: bool | str = False, experts: int | None = None,\n              embed_host: bool | None = None, formats: str | None = None) -> \"Image\":\n        return Image(self, cfg, cap, batch, rows, wformat, head_format, lookup, experts,\n                     embed_host, formats)\n\n\ndef _place(b, runs, size) -> dict:\n    \"\"\"The layer blocks of the runs (plan's) from b.next on, each run's units one after the\n    other (size(key): a block's bytes): {layer: (run base, unit stride, iteration, offset in\n    the unit, unit length)}.\"\"\"\n    loc = {}\n    for first, unit, reps in runs:\n        offs = np.cumsum([0] + [size(k) for k in unit]).tolist()\n        us, base = offs[-1], b.next\n        for it in range(reps):\n            for e in range(len(unit)):\n                loc[first + it * len(unit) + e] = (base, us, it, offs[e], len(unit))\n        b.next = base + reps * us\n    return loc\n\n\ndef _kind(key) -> str:\n    \"\"\"A layer's kind from its Spec.lkinds entry (for a MoE model: kind, is a MoE layer).\"\"\"\n    return key[0] if isinstance(key, tuple) else key\n\n\ndef plan(kinds) -> list:\n    \"\"\"The layers as runs [(first layer, unit of kinds, repeats)]: the repeated unit covering\n    the most layers becomes one hardware loop; the layers before and after it are planned the\n    same way, and a layer in no repetition is a run of its own.\"\"\"\n    kinds, n = tuple(kinds), len(kinds)\n    best = None                                     # (layers covered, first, unit length)\n    for u in range(1, n // 2 + 1):\n        for f in range(n - 2 * u + 1):\n            r = 1\n            while kinds[f + r * u:f + (r + 1) * u] == kinds[f:f + u]:\n                r += 1\n            if r > 1 and (best is None or r * u > best[0]):\n                best = (r * u, f, u)\n    if best is None:\n        return [(i, (k,), 1) for i, k in enumerate(kinds)]\n    cov, f, u = best\n    tail = plan(kinds[f + cov:])\n    return plan(kinds[:f]) + [(f, kinds[f:f + u], cov // u)] + \\\n        [(f + cov + a, unit, r) for a, unit, r in tail]\n\n\ndef subs(runs, size) -> dict:\n    \"\"\"Each run's unit planned again (plan over its keys): a repeated part of the unit (Qwen3.5's\n    three DeltaNet layers before each attention layer) loops again, inside the unit's loop, as\n    Gemma 4's do. {run's first layer: [(first element, part, repeats, the part's bytes)]};\n    size(key): a layer block's bytes (the part's blocks lie one after the other: _place).\"\"\"\n    return {first: [(e0, su, r, sum(size(k) for k in su)) for e0, su, r in plan(unit)]\n            for first, unit, _ in runs}\n\n\n# =============================================================================== reference\ndef _norm(v, g, eps):\n    return (v / np.sqrt(np.mean(v * v, axis=-1, keepdims=True) + eps)) * g\n\n\ndef reference_logits(spec: Spec, W: dict, tokens) -> np.ndarray:\n    \"\"\"fp32 numpy forward of the whole sequence (causal); returns logits [T, vocab].\"\"\"\n    tokens = list(tokens)\n    T, d, G, H, K = len(tokens), spec.head_dim, spec.n_q // spec.n_kv, spec.hidden, spec.conv_k\n    x = W[\"model.embed_tokens.weight\"][tokens].astype(np.float32)\n    cs = [rope_tables(spec, p) for p in range(T)]\n    cos = np.stack([c for c, _ in cs])[:, None, :]\n    sin = np.stack([s for _, s in cs])[:, None, :]\n\n    def rot(v):\n        v1, v2 = v[..., :d // 2], v[..., d // 2:]\n        return np.concatenate([v1 * cos - v2 * sin, v2 * cos + v1 * sin], axis=-1)\n\n    mask = np.triu(np.full((T, T), -np.inf, np.float32), 1)\n    for i, kind in enumerate(spec.kinds):\n        p = f\"model.layers.{i}.\"\n        h = _norm(x, W[p + \"operator_norm.weight\"], spec.eps)\n        if kind == CONV:\n            B, C, xx = np.split(h @ W[p + \"conv.in_proj.weight\"].T, 3, axis=1)\n            bx = np.concatenate([np.zeros((K - 1, H), np.float32), B * xx])\n            w = W[p + \"conv.conv.weight\"][:, 0, :]              # [H, K], w[:, K-1]: current\n            conv = sum(bx[k:k + T] * w[:, k] for k in range(K))\n            x = x + (C * conv) @ W[p + \"conv.out_proj.weight\"].T\n        else:\n            a = p + \"self_attn.\"\n            q = (h @ W[a + \"q_proj.weight\"].T).reshape(T, spec.n_q, d)\n            k = (h @ W[a + \"k_proj.weight\"].T).reshape(T, spec.n_kv, d)\n            v = (h @ W[a + \"v_proj.weight\"].T).reshape(T, spec.n_kv, d)\n            q = rot(_norm(q, W[a + \"q_layernorm.weight\"], spec.eps))\n            k = rot(_norm(k, W[a + \"k_layernorm.weight\"], spec.eps))\n            o = np.zeros((T, spec.n_q, d), np.float32)\n            for hq in range(spec.n_q):\n                s = q[:, hq] @ k[:, hq // G].T / math.sqrt(d) + mask\n                s = np.exp(s - s.max(axis=1, keepdims=True))\n                o[:, hq] = (s / s.sum(axis=1, keepdims=True)) @ v[:, hq // G]\n            x = x + o.reshape(T, -1) @ W[a + \"out_proj.weight\"].T\n        h = _norm(x, W[p + \"ffn_norm.weight\"], spec.eps)\n        if spec.is_moe(i):\n            x = x + _moe_reference(h, W, p, spec.moe)\n            continue\n        g = h @ W[p + \"feed_forward.w1.weight\"].T\n        u = h @ W[p + \"feed_forward.w3.weight\"].T\n        x = x + ((g / (1 + np.exp(-g))) * u) @ W[p + \"feed_forward.w2.weight\"].T\n    x = _norm(x, W[\"model.embedding_norm.weight\"], spec.eps)\n    head = W[\"model.embed_tokens.weight\"] if spec.tied else W[\"lm_head.weight\"]\n    return x @ head.T\n\n\ndef _moe_reference(h, W, p: str, mo) -> np.ndarray:\n    \"\"\"The routed experts' sum for the rows of h [T, H] (fp32, Hugging Face's math).\"\"\"\n    f = p + \"feed_forward.\"\n    logits = h @ W[f + \"gate.weight\"].T\n    y = np.zeros_like(h)\n    for t in range(h.shape[0]):\n        ids, w = MO.route(logits[t], W[f + \"expert_bias\"], mo)\n        for e, we in zip(ids, w):\n            ep = f\"{f}experts.{e}.\"\n            g, u = h[t] @ W[ep + \"w1.weight\"].T, h[t] @ W[ep + \"w3.weight\"].T\n            y[t] += np.float32(we) * (((g / (1 + np.exp(-g))) * u) @ W[ep + \"w2.weight\"].T)\n    return y\n\n\nKINDS = (\"attn\", \"conv\", \"mlp\", \"gateup\", \"down\", \"head\")    # a formats string's weight kinds\n\n\ndef weight_kind(n: str) -> tuple:\n    \"\"\"(kind, layer) of checkpoint weight `n` (KINDS: the head, or a layer's attention,\n    convolution in / out, MLP w1 / w3 or w2 projection; a MoE's experts are the image's\n    wformat: \"experts\").\"\"\"\n    if not n.startswith(\"model.layers.\"):\n        return \"head\", 0\n    i = int(n.split(\".\")[2])\n    if \".experts.\" in n:\n        return \"experts\", i\n    return (\"conv\" if \".conv.\" in n else \"attn\" if \".self_attn.\" in n else\n            \"down\" if n.endswith(\".w2.weight\") else \"gateup\"), i\n\n\ndef emulated_logits(spec: Spec, W: dict, tokens, D: int = 128, wformat: str = \"int8\",\n                    head_format: str | None = None, routes: list | None = None,\n                    formats: str | None = None, S: int = 1) -> np.ndarray:\n    \"\"\"float64 decode with openTPU's quantization points and none of its rounding (as\n    qwen3.emulated_logits, on S slices): K and q zero-padded to whole D blocks (the cache's\n    rows, dk), the dense down projections' activations in their F chunks (kernels.mlp.down_chunk)\n    and the experts' in their slot's (moe.ExpertFormat).\"\"\"\n    d, G, H, K = spec.head_dim, spec.n_q // spec.n_kv, spec.hidden, spec.conv_k\n    dk = -(-d // D) * D\n    Wq: dict = {}\n\n    head = \"model.embed_tokens.weight\" if spec.tied else \"lm_head.weight\"\n    wformat, formats = FM.named(spec, wformat, formats)\n    fmt = FM.resolver(formats, KINDS, spec.formats, wformat, head_format)\n\n    def w(n):\n        if n not in Wq:        # the weight formats as in Image (wformat, head_format, formats)\n            Wq[n] = _fake_w(W[n], D, fmt(*weight_kind(n)))\n        return Wq[n]\n\n    def norm(v, g):\n        return _norm(v, g, spec.eps)\n\n    def pad(v):\n        return np.pad(v, [(0, 0)] * (v.ndim - 1) + [(0, dk - d)])\n\n    def chunk(i):\n        return down_chunk(spec.ffn // S, D, fmt(\"down\", i))\n\n    Kc = {i: [] for i, k in enumerate(spec.kinds) if k == ATTN}\n    Vc = {i: [] for i in Kc}\n    state = {i: [np.zeros(H)] * (K - 1) for i, k in enumerate(spec.kinds) if k == CONV}\n    out = []\n    for pos, tk in enumerate(tokens):\n        x = np.asarray(W[\"model.embed_tokens.weight\"][tk], np.float64)\n        if spec.embed == \"int8\":                    # the int8 embedding rows (Spec.embed)\n            x = gathered_rows(x, D)[0].astype(np.float64)\n        c, s = rope_tables(spec, pos)\n\n        def rot(v):\n            v1, v2 = v[..., :d // 2], v[..., d // 2:]\n            return np.concatenate([v1 * c - v2 * s, v2 * c + v1 * s], -1)\n\n        for i, kind in enumerate(spec.kinds):\n            p = f\"model.layers.{i}.\"\n            h = _fake_q(norm(x, W[p + \"operator_norm.weight\"]), D)\n            if kind == CONV:\n                B, C, xx = np.split(w(p + \"conv.in_proj.weight\") @ h, 3)\n                win = state[i] + [B * xx]                    # the last K rows of B * x\n                state[i] = win[1:]\n                wc = W[p + \"conv.conv.weight\"][:, 0, :]\n                y = C * sum(win[k] * wc[:, k] for k in range(K))\n                x = x + w(p + \"conv.out_proj.weight\") @ _fake_q(y, D)\n            else:\n                a = p + \"self_attn.\"\n                q = (w(a + \"q_proj.weight\") @ h).reshape(spec.n_q, d)\n                k = (w(a + \"k_proj.weight\") @ h).reshape(spec.n_kv, d)\n                v = (w(a + \"v_proj.weight\") @ h).reshape(spec.n_kv, d)\n                q = rot(norm(q, W[a + \"q_layernorm.weight\"]))\n                k = rot(norm(k, W[a + \"k_layernorm.weight\"]))\n                Kc[i].append(_fake_k(pad(k), D))\n                Vc[i].append(_v_parts(v))\n                Kh = np.stack([a for a, _ in Kc[i]], 1)\n                dK = None if Kc[i][0][1] is None else np.stack([b for _, b in Kc[i]], 1)\n                Vq, Vs = (np.stack(z, 1) for z in zip(*Vc[i]))\n                o = np.zeros((spec.n_q, d))\n                for hq in range(spec.n_q):\n                    sc = _qk(_fake_q(pad(q[hq] / math.sqrt(d)), D), Kh[hq // G],\n                             None if dK is None else dK[hq // G], D)\n                    pp = np.exp(sc - sc.max())\n                    o[hq] = _pv(pp, Vq[hq // G], Vs[hq // G], D) / pp.sum()\n                x = x + w(a + \"out_proj.weight\") @ _fake_q(o.reshape(-1), D)\n            h = _fake_q(norm(x, W[p + \"ffn_norm.weight\"]), D)\n            if spec.is_moe(i):\n                f = p + \"feed_forward.\"\n                if f + \"gate.weight\" not in Wq:     # the router is int8 in every format\n                    Wq[f + \"gate.weight\"] = _fake_w(W[f + \"gate.weight\"], D, \"int8\")\n                lg = Wq[f + \"gate.weight\"] @ h\n                ids, wts = MO.route(lg, W[f + \"expert_bias\"], spec.moe)\n                if routes is not None:              # (token, layer, ids, the choice's margin)\n                    sel = np.sort(1 / (1 + np.exp(-lg)) + W[f + \"expert_bias\"])[::-1]\n                    k = spec.moe.k\n                    routes.append((len(out), i, ids, sel[k - 1] - sel[k] if k < len(sel)\n                                   else np.inf))\n                for e, we in zip(ids, wts):\n                    ep = f\"{f}experts.{e}.\"\n                    g, u = w(ep + \"w1.weight\") @ h, w(ep + \"w3.weight\") @ h\n                    ce = MO.ExpertFormat(H, spec.moe.ffn, D, fmt(\"experts\", i)).ranges()\n                    x = x + we * (w(ep + \"w2.weight\") @ _fake_q((g / (1 + np.exp(-g))) * u, D,\n                                                                 ce))\n                continue\n            g = w(p + \"feed_forward.w1.weight\") @ h\n            u = w(p + \"feed_forward.w3.weight\") @ h\n            x = x + w(p + \"feed_forward.w2.weight\") @ _fake_q((g / (1 + np.exp(-g))) * u, D,\n                                                               chunk(i))\n        out.append(w(head) @ _fake_q(norm(x, W[\"model.embedding_norm.weight\"]), D))\n    return np.array(out)\n\n\n# =============================================================================== DRAM image\nclass Image(EmbedHost):\n    \"\"\"Per-slice DRAM layout of an LFM2 model. Every slice uses the same addresses.\n\n    [ I/O: x_in, cos, sin | final norm | logits ] [ layer 0 block ] ... [ layer L-1 block ]\n    [ LM head rows of this slice ]. A layer block's layout and size are its kind's in its\n    formats group (a layer's conv, attention, gate / up and down formats: Image.lf); both kinds\n    start with the norms and this slice's MLP rows, at the same offsets in a group; a conv\n    block then holds the taps, the state ring and this slice's rows of in_proj (its channels of\n    B, C and x) and out_proj; an attention block holds the q/k norms, the projections and this\n    slice's KV heads with room for `cap` tokens. The I/O area holds `rows` token rows (x, cos,\n    sin, logits) for chunked prefill. Weight formats as qwen3.Image (`formats` over the KINDS\n    of this file, per layer range; a MoE's experts in `wformat`, its router int8, its dense\n    layers' MLPs one format): the layers run as the runs of plan over their (kind, formats\n    group) keys, each run's blocks one after the other.\n    \"\"\"\n\n    prompt_words = (\"ringo\",)    # a prompt run reads it itself (_ring_store, prefill.run)\n\n    def __init__(self, spec: Spec, cfg: Config, cap: int, batch: int = 1, rows: int = 1,\n                 wformat: str = \"int8\", head_format: str | None = None, lookup: bool | str = False,\n                 experts: int | None = None, embed_host: bool | None = None,\n                 formats: str | None = None):\n        spec.check(cfg)\n        if batch != 1:\n            raise ValueError(\"LFM2 runs one sequence: batch=1\")\n        if cap % cfg.D:\n            raise ValueError(\"KV capacity must be a multiple of D\")\n        S, D = cfg.S, cfg.D\n        H, d, F_, K = spec.hidden, spec.head_dim, spec.ffn, spec.conv_k\n        wformat, formats = FM.named(spec, wformat, formats)\n        fmt = FM.resolver(formats, KINDS, spec.formats, wformat, head_format)\n        # each layer's formats group: conv, attention, gate / up, down where it is (the\n        # layers of a group share a block size and the common part's offsets, as one group did)\n        self.lf = tuple((fmt(CONV, i), fmt(ATTN, i), fmt(\"gateup\", i), fmt(\"down\", i))\n                        for i in range(spec.layers))\n        if spec.moe is not None:    # the dense layers' MLP region: one layout\n            FM.uniform(fmt, dict.fromkeys((\"gateup\", \"down\"), range(spec.moe.first)))\n        self.wformat, self.head_format = wformat, fmt(\"head\")\n        self.formats = _formats(spec, formats)\n        rb = lambda k, f: Q.row_bytes(k, f, D)                          # noqa: E731\n        self.spec, self.cfg, self.cap, self.batch, self.rows = spec, cfg, cap, 1, rows\n        self.dk = -(-d // D) * D                        # cached K row / query width\n        self.nq_loc, self.nkv_loc = spec.n_q // S, spec.n_kv // S\n        self.h_loc, self.f_loc, self.v_loc = H // S, F_ // S, spec.vocab // S\n        mo = spec.moe\n        b = _Bump()\n        R = rows\n        self.io = {\"x\": b.alloc(4 * H * R), \"cos\": b.alloc(2 * d * R), \"sin\": b.alloc(2 * d * R),\n                   \"gf\": b.alloc(4 * H), \"logits\": b.alloc(4 * spec.vocab * R)}\n        from .prefill import tile_scratch   # a tiled run's attention outputs, a part at a time\n        if tile_scratch(spec, layer_runs=False):    # (tiled.py; a dense image's)\n            self.io[\"o\"] = b.alloc(4 * cfg.act_rows * self.nq_loc * d)\n        self.layer0 = b.next\n        mlp = {\"wg\": (self.f_loc, H), \"wu\": (self.f_loc, H)}\n        self.mats = {CONV: {\"win\": (3 * self.h_loc, H), \"wout\": (self.h_loc, H)},\n                     ATTN: {\"wq\": (self.nq_loc * d, H), \"wk\": (self.nkv_loc * d, H),\n                            \"wv\": (self.nkv_loc * d, H), \"wo\": (self.h_loc, spec.n_q * d)}}\n        if mo is None:\n            for kind in (CONV, ATTN):\n                self.mats[kind].update(mlp)\n        # formats group -> its block layouts (_layout); layer 0's those of the image (and of\n        # a MoE's dense MLP region)\n        self.layouts = {g: self._layout(g, mlp, rb) for g in dict.fromkeys(self.lf)}\n        g0 = self.layouts[self.lf[0]]\n        self.lofs, self.mf, self.dchunk = g0.lofs, g0.mf, g0.dchunk\n        if mo is not None:\n            self.mlp_ofs, self.DS = g0.mlp_ofs, g0.DS\n        # the runs (plan): a layer's key is its kind and formats group\n        self.keys = tuple(zip(spec.lkinds, self.lf))\n        self.plan = plan(self.keys)\n        self.mlp_loop = sum(len(u) for _, u, _ in self.plan) > MLP_UNROLL_BODIES\n        self.loc = _place(b, self.plan, lambda k: self.layouts[k[1]].size[_kind(k[0])])\n        # the stack in one loop (tiled._lfm2_stack): a dense model's layers of both kinds in\n        # one formats group, whose blocks lie one after the other in layer order (the runs'\n        # do, a block its kind's size) from base\n        self.stack = None\n        if mo is None and len(set(self.lf)) == 1 and set(spec.kinds) == {CONV, ATTN}:\n            g0 = self.layouts[self.lf[0]]\n            self.stack = SimpleNamespace(base=self._off(0).const, size=dict(g0.size))\n        dk = self.dk\n        n_attn = spec.kinds.count(ATTN)\n        head = cap * dk + cap * k_scale_bytes(dk, D) + dk * cap + 4 * cap\n        self.kv_bytes = (n_attn * self.nkv_loc * head                   # KV cache and\n                         + (spec.layers - n_attn) * 8 * K * self.h_loc)  # conv state, per sequence\n        self.head = (b.alloc(self.v_loc * Q.row_bytes(H, self.head_format, D)),\n                     b.alloc(self.v_loc * Q.scale_bytes(H, self.head_format, D)))\n        # the int8 embedding rows of the resident decode are the tied int8 head's (S = 1)\n        shared = spec.tied and self.head_format == \"int8\" and S == 1\n        if embed_host is None:      # an int8 table of its own on the host by default where its\n            embed_host = (bool(lookup) and not shared         # DRAM is expert slots\n                          and getattr(spec, \"embed\", \"f32\") == \"int8\" and spec.moe is not None)\n        if embed_host and not lookup:\n            raise ValueError(\"embed_host needs the image's lookup tables (lookup=True)\")\n        self.lookup = _lookup_alloc(b, spec, cap, D=D, head=self.head if shared else None,\n                                    M=cfg.MCOLS, embed_host=bool(embed_host),\n                                    rows=rows, imem=cfg.IMEM_WORDS,\n                                    waitc=cfg.SEQ_WC) if lookup else {}\n        self.choices = {\"embed_host\": self.embed_host,          # (the compile worker's\n                        \"formats\": self.formats}                # image)\n        self.offload = None\n        if mo is not None:          # the dense MLPs, then path (a)'s words and expert slots\n            self.dense0 = (b.next + 4095) // 4096 * 4096\n            b.next = self.dense0 + mo.first * self.DS\n            self.fmt = MO.ExpertFormat(H, mo.ffn, D, wformat)\n            n = mo.E if experts is None else experts\n            if not mo.k <= n <= mo.E:\n                raise ValueError(f\"{n} expert slots per layer: from top-k {mo.k} to {mo.E}\")\n            self.offload = Layout.build((b.next + 4095) // 4096 * 4096, mo.E, mo.k,\n                                        [n] * (spec.layers - mo.first), self.fmt.nbytes)\n            b.next = self.offload.end\n        self.nbytes = b.next\n        if self.nbytes > cfg.DRAM_BYTES:\n            raise MemoryError(f\"model image needs {self.nbytes / 2**20:.0f} MiB per slice, \"\n                              f\"DRAM_BYTES is {cfg.DRAM_BYTES / 2**20:.0f} MiB\")\n\n    def _layout(self, g: tuple, mlp: dict, rb) -> SimpleNamespace:\n        \"\"\"The layer block layouts of formats group g (conv, attention, gate / up, down): each\n        projection's format (mf), W_down's chunk, the conv and attention blocks' offsets (the\n        norms and the dense MLP first, at the same offsets in both) and sizes (size).\"\"\"\n        spec, cfg, cap = self.spec, self.cfg, self.cap\n        D, H, d, F_, K = cfg.D, spec.hidden, spec.head_dim, spec.ffn, spec.conv_k\n        sb = lambda k, f: Q.scale_bytes(k, f, D)                        # noqa: E731\n        fc, fa, fg, fd = g\n        mf = {\"win\": fc, \"wout\": fc, \"wq\": fa, \"wk\": fa, \"wv\": fa, \"wo\": fa, \"wg\": fg,\n              \"wu\": fg, \"wd\": fd}\n        mo = spec.moe\n        lb = _Bump()                                    # offsets inside one layer block\n        common = {\"g_in\": lb.alloc(4 * H), \"g_post\": lb.alloc(4 * H)}\n        dchunk = _chunk(self.f_loc, D, D if fd == \"int8\" else 2 * D)\n        # the dense MLP: in every layer block, or for a MoE model (whose MoE layers have none)\n        # in a region of its own, one MLP per dense layer (layers 0 .. moe.first - 1)\n        mb = lb if mo is None else _Bump()\n        dense = {name: (mb.alloc(n * rb(k, mf[name])), mb.alloc(n * sb(k, mf[name])))\n                 for name, (n, k) in mlp.items()}\n        dense[\"wd\"] = [(mb.alloc(self.h_loc * rb(dchunk, fd)),\n                        mb.alloc(self.h_loc * sb(dchunk, fd)))\n                       for _ in range(F_ // dchunk)]\n        ns = SimpleNamespace(mf=mf, dchunk=dchunk)\n        if mo is None:\n            common.update(dense)\n        else:                       # the router (int8 in every format), its bias, j * E\n            ns.mlp_ofs, ns.DS = dense, (mb.next + 4095) // 4096 * 4096\n            common.update(router=(lb.alloc(mo.E * H), lb.alloc(mo.E * sb(H, \"int8\"))),\n                          ebias=lb.alloc(4 * mo.E), gbase=lb.alloc(4))\n        cb = _Bump(lb.next)\n        conv = dict(common, taps=cb.alloc(4 * K * self.h_loc),\n                    state=cb.alloc(4 * 2 * K * self.h_loc))         # mirrored (_ring_rows)\n        ab = _Bump(lb.next)\n        attn = dict(common, qn=ab.alloc(4 * d), kn=ab.alloc(4 * d))\n        for kind, bump, L in ((CONV, cb, conv), (ATTN, ab, attn)):\n            for name, (n, k) in self.mats[kind].items():\n                if name not in L:\n                    L[name] = (bump.alloc(n * rb(k, mf[name])), bump.alloc(n * sb(k, mf[name])))\n        dk = self.dk\n        attn[\"kv\"] = [{\"k\": ab.alloc(cap * dk), \"ks\": ab.alloc(cap * k_scale_bytes(dk, D)),\n                       \"vt\": ab.alloc(dk * cap), \"vs\": ab.alloc(4 * cap)}\n                      for _ in range(self.nkv_loc)]\n        ns.lofs = {CONV: conv, ATTN: attn}\n        ns.size = {CONV: (cb.next + 4095) // 4096 * 4096, ATTN: (ab.next + 4095) // 4096 * 4096}\n        return ns\n\n    def _off(self, li, it=None) -> Affine:\n        \"\"\"The block address of layer li (static), or of element li of its run's unit at\n        iteration `it` (a loop variable).\"\"\"\n        base, us, i, o, _ = self.loc[li]\n        return Affine(base + o) + Affine.of(i if it is None else it) * us\n\n    def _idx(self, li, it=None) -> Affine:\n        \"\"\"Layer li's index (static), or the index of element li of its run's unit at\n        iteration `it`.\"\"\"\n        base, us, i, o, n = self.loc[li]\n        return Affine(li) if it is None else Affine(li - i * n) + Affine.of(it) * n\n\n    # ---- contents\n    def build(self, W: dict) -> list[np.ndarray]:\n        \"\"\"DRAM images (one per slice) with every weight quantized in place, KV cache and\n        convolution state empty.\"\"\"\n        spec, cfg = self.spec, self.cfg\n        S, D, d, H, n = cfg.S, cfg.D, spec.head_dim, spec.hidden, self.h_loc\n        imgs = [np.zeros(self.nbytes, np.uint8) for _ in range(S)]\n\n        def put(s, addr, a):\n            v = np.ascontiguousarray(a).view(np.uint8).reshape(-1)\n            imgs[s][addr:addr + v.size] = v\n\n        qb = QC.Batch()                 # the matrices, quantized in worker processes\n\n        def put_q(addr_pair, parts, fmt):\n            for s, p in enumerate(parts):\n                qb.submit(p, fmt, D, lambda q, sc, s=s: (put(s, addr_pair[0], q),\n                                                         put(s, addr_pair[1], sc)))\n\n        def put_parts(addrs, parts, fmt, C):\n            \"\"\"Each slice's rows quantized whole and stored in column parts of C (qwen3's).\"\"\"\n            for s, p in enumerate(parts):\n                qb.submit(p, fmt, D, lambda q, sc, s=s: [\n                    (put(s, a0, pq), put(s, a1, ps))\n                    for (a0, a1), (pq, ps) in zip(addrs, Q.column_parts(q, sc, fmt, p.shape[1],\n                                                                         C, D))])\n\n        def rows(a, k):\n            return [a[s * k:(s + 1) * k] for s in range(S)]\n\n        def f32(a):\n            return F.ftz(np.asarray(a, np.float32))\n\n        for s in range(S):\n            put(s, self.io[\"gf\"], f32(W[\"model.embedding_norm.weight\"]))\n        for i, kind in enumerate(spec.kinds):\n            p, base, g = f\"model.layers.{i}.\", self._off(i).const, self.layouts[self.lf[i]]\n            mf = g.mf\n            Lo = {k: (tuple(base + x for x in v) if isinstance(v, tuple) else\n                      (base + v if isinstance(v, int) else v)) for k, v in g.lofs[kind].items()}\n            for s in range(S):\n                put(s, Lo[\"g_in\"], f32(W[p + \"operator_norm.weight\"]))\n                put(s, Lo[\"g_post\"], f32(W[p + \"ffn_norm.weight\"]))\n            if kind == CONV:\n                B, C, X = np.split(W[p + \"conv.in_proj.weight\"], 3)\n                put_q(Lo[\"win\"], [np.concatenate([B[s * n:(s + 1) * n], C[s * n:(s + 1) * n],\n                                                  X[s * n:(s + 1) * n]]) for s in range(S)],\n                      mf[\"win\"])\n                put_q(Lo[\"wout\"], rows(W[p + \"conv.out_proj.weight\"], n), mf[\"wout\"])\n                taps = W[p + \"conv.conv.weight\"][:, 0, :].T            # [K, H]\n                for s in range(S):\n                    put(s, Lo[\"taps\"], f32(taps[:, s * n:(s + 1) * n]))\n            else:\n                a = p + \"self_attn.\"\n                for s in range(S):\n                    put(s, Lo[\"qn\"], f32(W[a + \"q_layernorm.weight\"]))\n                    put(s, Lo[\"kn\"], f32(W[a + \"k_layernorm.weight\"]))\n                wq, wk, wv, wo = head_parallel_attention_weights(\n                    W[a + \"q_proj.weight\"], W[a + \"k_proj.weight\"], W[a + \"v_proj.weight\"],\n                    W[a + \"out_proj.weight\"], spec.n_q, spec.n_kv, d, S)\n                put_q(Lo[\"wq\"], rows(wq, self.nq_loc * d), mf[\"wq\"])\n                put_q(Lo[\"wk\"], rows(wk, self.nkv_loc * d), mf[\"wk\"])\n                put_q(Lo[\"wv\"], rows(wv, self.nkv_loc * d), mf[\"wv\"])\n                put_q(Lo[\"wo\"], rows(wo, n), mf[\"wo\"])\n            if spec.is_moe(i):\n                f, mo = p + \"feed_forward.\", spec.moe\n                put_q(Lo[\"router\"], [W[f + \"gate.weight\"]], \"int8\")\n                put(0, Lo[\"ebias\"], f32(W[f + \"expert_bias\"]))\n                put(0, Lo[\"gbase\"], f32([(i - mo.first) * mo.E]))\n                continue\n            mb, mofs = base, g.lofs[kind]\n            if spec.moe is not None:\n                mb, mofs = self.dense0 + i * self.DS, self.mlp_ofs\n            for name, hf in ((\"wg\", \"w1\"), (\"wu\", \"w3\")):\n                put_q(tuple(mb + x for x in mofs[name]),\n                      rows(W[p + f\"feed_forward.{hf}.weight\"], self.f_loc), mf[name])\n            put_parts([(mb + a0, mb + a1) for a0, a1 in mofs[\"wd\"]],\n                      rows(W[p + \"feed_forward.w2.weight\"], n), mf[\"wd\"], g.dchunk)\n        put_head(self, W, qb, put, put_q, rows)     # (and the tied int8 head's gather scales)\n        qb.wait()\n        if self.lookup:\n            _lookup_build(put, S, W, spec, self.cap, self.lookup)\n        return imgs\n\n    # ---- path (a): the expert pool and its server (docs/offload.md)\n    def expert(self, W: dict, g: int) -> np.ndarray:\n        \"\"\"Global expert g (MoE layer g // E, expert g % E) in its slot's bytes.\"\"\"\n        mo = self.spec.moe\n        p = f\"model.layers.{mo.first + g // mo.E}.feed_forward.experts.{g % mo.E}.\"\n        return self.fmt.pack(W[p + \"w1.weight\"], W[p + \"w3.weight\"], W[p + \"w2.weight\"])\n\n    def serve(self, W: dict, backend, pool_file=None) -> ExpertServer:\n        \"\"\"The host's expert server on the backend's DRAM (moe.serve).\"\"\"\n        return MO.serve(self.offload, lambda g: self.expert(W, g), backend, pool_file)\n\n    def state_regions(self, slot: int = 0) -> list:\n        \"\"\"The context's state that its KV caches do not hold, as DRAM regions (address,\n        bytes; every slice's): each conv layer's state ring (a rollback restores them from a\n        snapshot: opentpu/llm/snapshot.py).\"\"\"\n        m, out = self.descriptors(0), []\n        for li in range(self.spec.layers):\n            lw = m.layer(li)\n            if lw.kind == CONV:\n                out.append((Affine.of(lw.state.base).static(), 4 * math.prod(lw.state.shape)))\n        return out\n\n    # ---- programs\n    def compile_decode(self, blocks: int, lo: int, block: int = ATTN_BLOCK):\n        \"\"\"(programs, run_args): lfm2_step at a run-time position (qwen3.compile_decode); the\n        convolutions need lo >= conv_k - 1 (every tap of the state ring is a past token).\"\"\"\n        return compile_decode(self, lfm2_step, blocks, lo, block)\n\n    def compile_generate(self, blocks: int, lo: int, block: int = ATTN_BLOCK,\n                         chain: bool = True, samp=None, debug: bool = False,\n                         part: int | None = None) -> list:\n        \"\"\"The decode loop on the device for bucket `blocks` (lfm2_step in it, generate.py).\"\"\"\n        return G.compile_generate(self, lfm2_step, blocks, lo, block, chain, samp, debug, part)\n\n    def compile_step(self, pos: int, block: int = ATTN_BLOCK, tok: int | None = None) -> list:\n        \"\"\"One program per slice: the decode token at position `pos` (lfm2_step).\"\"\"\n        return [trace_fit(lfm2_step, self.cfg, s,\n                          lambda s=s: {\"m\": step_descriptors(self, s), \"pos\": pos,\n                                       \"block\": block, **_tok_arg(self, tok)}).finish()\n                for s in range(self.cfg.S)]\n\n    def compile_rows(self, rows, logit_rows, block: int = ATTN_BLOCK, tokens=None) -> list:\n        \"\"\"One program per slice: consecutive positions of the sequence at once (lfm2_rows).\"\"\"\n        if self.spec.moe is not None and len(rows) > 1:\n            raise ValueError(\"a MoE model runs one row per program (its MoE block routes one \"\n                             \"token)\")\n        if len(rows) > self.rows:\n            raise ValueError(f\"{len(rows)} rows, the image's I/O area holds {self.rows}\")\n        if any(r != (0, rows[0][1] + i) for i, r in enumerate(rows)):\n            raise ValueError(\"LFM2 rows must be consecutive positions of sequence 0\")\n        return [lfm2_rows.trace(self.cfg, s, {\"m\": self.descriptors(s), \"p0\": rows[0][1],\n                                              \"R\": len(rows), \"logit_rows\": list(logit_rows),\n                                              \"block\": block,\n                                              **_tokens_arg(self, tokens, rows)}).finish()\n                for s in range(self.cfg.S)]\n\n    def compile_prompt_run(self, blocks: int, R: int, kind: str, block: int = ATTN_BLOCK,\n                           p0: int | None = None):\n        \"\"\"lfm2_prompt_run's (programs, run_args) (docs/prefill.md), a program per slice: R\n        rows of a prompt at a run-time position of bucket `blocks` (from conv_k - 1: the state's\n        tpos and ring words), or at the compile-time position p0 (the rows before conv_k - 1;\n        no run_args).\"\"\"\n        if self.spec.moe is not None:\n            raise ValueError(\"a MoE model runs one row per program (its MoE block routes one \"\n                             \"token)\")\n        if not self.lookup:\n            raise ValueError(\"a prompt run needs lookup tables (lookup=True)\")\n        if kind not in (\"P\", \"L\"):\n            raise ValueError(f\"prompt run kind {kind!r}\")\n        if R > self.rows:\n            raise ValueError(f\"{R} rows, the image's I/O area holds {self.rows}\")\n        pos = p0 if p0 is not None else \\\n            RunRows(blocks, block, max((blocks - 1) * block, self.spec.conv_k - 1),\n                    self.lookup[\"zmask\"], self.cap, R, 0, _amask(self.lookup))\n        bs = [lfm2_prompt_run.trace(self.cfg, s, {\"m\": self.descriptors(s), \"pos\": pos, \"R\": R,\n                                                  \"kind\": kind, \"block\": block})\n              for s in range(self.cfg.S)]\n        return [b.finish() for b in bs], list(bs[0].run_args)\n\n    # ---- kernel descriptors\n    def descriptors(self, sid: int) -> SimpleNamespace:\n        spec, cfg = self.spec, self.cfg\n        D, d, H, K, n = cfg.D, spec.head_dim, spec.hidden, spec.conv_k, self.h_loc\n\n        def layer(li, it=None, at=None):\n            \"\"\"Descriptors of layer `li` (static), or of element li of its run's unit at\n            iteration `it` (a hardware-loop variable). Its kind (for a MoE model: kind, is a MoE\n            layer; Spec.lkinds) and formats group from self.keys. at (the stack in one loop,\n            self.stack): li's kind and group in the block at the stack's base + the Counter at\n            (compiler.Counter: the bytes of the blocks before it); `it` is not used.\"\"\"\n            kind, g = self.keys[li]\n            moe = False\n            if isinstance(kind, tuple):\n                kind, moe = kind\n            g = self.layouts[g]\n            off = self._off(li, it) if at is None else Affine(self.stack.base) + Affine.of(at)\n            lofs, mf = g.lofs[kind], g.mf\n            ns = SimpleNamespace(g_in=Tensor(off + lofs[\"g_in\"], (H,), (1,)),\n                                 g_post=Tensor(off + lofs[\"g_post\"], (H,), (1,)), moe=moe,\n                                 mlp_loop=self.mlp_loop, kind=kind)\n            for name, (r, k) in self.mats[kind].items():\n                da, sa = lofs[name]\n                fm = mf[name]\n                setattr(ns, name, QTensor.weight(off + da, off + sa, r, k, fm, D))\n            if moe:\n                E = spec.moe.E\n                da, sa = lofs[\"router\"]\n                ns.router = QTensor.weight(off + da, off + sa, E, H, \"int8\", D)\n                ns.ebias = Tensor(off + lofs[\"ebias\"], (E,), (1,))\n                ns.gbase = Tensor(off + lofs[\"gbase\"], (1,), (1,))\n            else:\n                mofs, moff = lofs, off\n                if spec.moe is not None:            # the dense layers' MLP region\n                    mofs = self.mlp_ofs\n                    moff = Affine.of(self.dense0) + self._idx(li, it) * self.DS\n                    for name in (\"wg\", \"wu\"):\n                        da, sa = mofs[name]\n                        fm = mf[name]\n                        setattr(ns, name, QTensor.weight(moff + da, moff + sa, self.f_loc, H,\n                                                         fm, D))\n                C = g.dchunk\n                fm = mf[\"wd\"]\n                parts = tuple(QTensor.weight(moff + da, moff + sa, n, C, fm, D)\n                              for da, sa in mofs[\"wd\"])\n                ns.wd = QTensor(parts[0].data, parts[0].scale, (n, spec.ffn), parts[0].rs,\n                                parts[0].srs, D, parts=parts, pw=C, wf=parts[0].wf)\n            if kind == CONV:\n                ns.taps = Tensor(off + lofs[\"taps\"], (K, n), (n, 1))\n                ns.state = Tensor(off + lofs[\"state\"], (2 * K, n), (n, 1))     # _ring_rows\n            else:\n                ns.qn = Tensor(off + lofs[\"qn\"], (d,), (1,))\n                ns.kn = Tensor(off + lofs[\"kn\"], (d,), (1,))\n                ns.kv = KVDesc({sid + j * cfg.S: {k: off + v for k, v in r.items()}\n                                for j, r in enumerate(lofs[\"kv\"])}, self.cap, self.dk, D, cfg.S,\n                               sid, dv=d)\n                ns.kvs = [ns.kv]\n            return ns\n\n        dev = None\n        if self.offload is not None:\n            L = self.offload\n            dev = SimpleNamespace(mbox=L.mbox, served=L.served, answer=L.answer, dir=L.dir,\n                                  tag=L.tag, fmt=self.fmt, slots=L.slot_bounds,\n                                  ids=L.layers * L.E)\n        return SimpleNamespace(\n            spec=spec, layer=layer, plan=self.plan, moe_dev=dev, stack=self.stack,\n            x=_tdesc(self.io[\"x\"], (1, H)), cos=_tdesc(self.io[\"cos\"], (d // 2,)),\n            sin=_tdesc(self.io[\"sin\"], (d // 2,)), g_final=_tdesc(self.io[\"gf\"], (H,)),\n            logits=_tdesc(self.io[\"logits\"], (1, spec.vocab)),\n            xr=_tdesc(self.io[\"x\"], (self.rows, H)),\n            cosr=_tdesc(self.io[\"cos\"], (self.rows, d // 2)),\n            sinr=_tdesc(self.io[\"sin\"], (self.rows, d // 2)),\n            logitsr=_tdesc(self.io[\"logits\"], (self.rows, spec.vocab)),\n            oscr=_tdesc(self.io[\"o\"], (self.cfg.act_rows, self.nq_loc * d)) if \"o\" in self.io\n            else None,\n            head=_qdesc(*self.head, self.v_loc, H, D, self.head_format), v_loc=self.v_loc,\n            **_lookup_desc(self.lookup, spec, self.cap))\n\n\n# =============================================================================== kernel\ndef _ring_rows(K: int, p):\n    \"\"\"The state ring's rows: (the row holding position p - j, j = 1 .. K-1; the rows B * x of\n    position p is stored to). 2K rows: slot s at rows 1 + s and 1 + s + K (the mirror, not\n    kept for slot K-1), row 0 a scratch row. Rows w + 1 .. w + K, w = (p + 1) mod K, hold\n    positions p-K+1 .. p in order, so at a run-time position (RunPos: its `ring` is w) every\n    row is one register plus a constant; a position given as an int reads the slot rows.\"\"\"\n    if isinstance(p, RunPos):\n        w = p.ring\n        return [w + K - j for j in range(1, K)], [w, w + K]\n    return ([1 + (p - j) % K for j in range(1, K)],\n            [1 + p % K] + ([1 + p % K + K] if p % K < K - 1 else []))\n\n\ndef _conv(x, lw, pos: int, spec: Spec):\n    \"\"\"x + out_proj(C * conv(B * x)) for one token, this slice's channels; returns the new\n    residual (replicated on every slice). B * x is stored to the state ring (_ring_rows); the\n    rows of the K - 1 positions before (those >= 0) are read back from it.\"\"\"\n    K = spec.conv_k\n    n = lw.taps.shape[1]\n    taps = ol.load(lw.taps)                     # [K, n]; row K-1 weighs the current token\n    if isinstance(pos, RunPos) and pos.lo < K - 1:\n        raise ValueError(f\"a run-time position needs p >= {K - 1} (conv taps)\")\n    prev_rows, put = _ring_rows(K, pos)\n    past = K - 1 if isinstance(pos, RunPos) else min(K - 1, pos)\n    prev = [(ol.load(lw.state[r:r + 1, :]), taps[K - 1 - j:K - j, :])\n            for j, r in zip(range(1, past + 1), prev_rows)]  # loaded while in_proj streams\n    xs = ol.quantize(rmsnorm(x, ol.load(lw.g_in), spec.eps))\n    bcx = ol.dot(xs, lw.win)                    # [1, 3n]: B, C, x of this slice's channels\n    bx = bcx[:, 0:n] * bcx[:, 2 * n:3 * n]\n    for r in put:\n        ol.store(lw.state[r:r + 1, :], bx)\n    y = bx * taps[K - 1:K, :]\n    for s, t in prev:\n        y = y + s * t\n    y_all = ol.all_gather(y * bcx[:, n:2 * n])  # [1, H]\n    return x + ol.all_gather(ol.dot(y_all, lw.wout))\n\n\n@ol.jit\ndef lfm2_step(m, pos: int, block: int = ATTN_BLOCK, tok: int | None = None):\n    \"\"\"One decode token at position `pos`: x (the token's embedding) -> logits.\n\n    Each run of m.plan with repeats is a hardware loop over its unit of layers; the others are\n    unrolled. Conv layers update their state ring, attention layers append K/V at `pos` and\n    attend over positions 0..pos. Logits for this slice's vocabulary rows go to m.logits.\n    \"\"\"\n    fill_logits(m)\n    spec = m.spec\n    x, c, s_ = _inputs(m, pos, tok)\n\n    def layer(li, it):\n        lw = m.layer(li, it)\n        if lw.kind == CONV:\n            x.set(_conv(x, lw, pos, spec))\n        else:\n            x.set(_attention(x, lw, c, s_, pos, spec, block))\n        if lw.moe:\n            x.set(MO.moe_ffn(x, lw, spec.moe, m.moe_dev, spec.eps))\n        else:\n            x.set(_mlp(x, lw, spec))\n\n    run_layers(m.plan, layer)\n    _lm_head(x, m, spec)\n\n\ndef _ring_store(lw, last, ringo: int, K: int, n: int) -> None:\n    \"\"\"The state ring's rows 1 .. 2K-1 (_ring_rows) from `last`, the B * x rows of the last K\n    positions q = p'-K .. p'-1 (p' the next position): row y holds slot (y - 1) mod K, its\n    position's row last[(y - 1 - p') mod K]. A run-time p' makes that a rotation: the K rows\n    and again their first K - 1 go to a TMEM window, and row y (and its mirror y + K) is the\n    window's row o + y - 1 (o + y - K - 1), o = -p' mod K (the state word at TMEM `ringo`,\n    prefill.words). One ST per row from a register offset, to fixed DRAM rows; every copy is\n    rewritten as R steps would leave it (row 0, the scratch row, not).\"\"\"\n    b = current()\n    win = ol.empty([2 * K - 1, n])\n    win[0:K, :].set(last)\n    win[K:2 * K - 1, :].set(last[0:K - 1, :])\n    r = b.scratch()\n    b.emit(I.rld(r, ringo, mul=win.rs, comment=\"the ring's rotation\"))\n    for y in range(1, 2 * K):\n        ra, imm = b.addr(Affine.of(lw.state.base) + 4 * n * y)\n        j = y - 1 if y <= K else y - K - 1\n        b.emit(I.st(imm, win.base + j * win.rs, n, ra=ra, rb=r, comment=\"ring row\"))\n    b.unscratch(r)\n    del win\n\n\ndef _conv_rows(x, lw, p0: int, spec: Spec):\n    \"\"\"_conv for R consecutive positions p0 .. p0+R-1 at once: in_proj streams once for the R\n    rows (B and x first, C after the convolution: TMEM would not hold all three), and row r\n    convolves over the rows before it in the chunk and the ring (positions\n    before p0). The same products and sums per row as _conv, in the same order, so the result\n    is bit-identical; the ring ends up holding the chunk's last K rows, each in its slot. p0 a\n    RunRows (a prompt run, docs/prefill.md): the ring's rows by its ring word, and the whole ring\n    stored from the last K rows (_ring_store).\"\"\"\n    K, R = spec.conv_k, x.rows\n    n = lw.taps.shape[1]\n    run = isinstance(p0, RunRows)\n    taps = ol.load(lw.taps)                     # [K, n]; row K-1 weighs the current token\n    E = ol.empty([K - 1 + R, n])                # B * x of positions p0-K+1 .. p0+R-1\n    prev = zip(range(1, K), _ring_rows(K, p0)[0]) if run else \\\n        ((j, 1 + (p0 - j) % K) for j in range(1, min(K, p0 + 1)))\n    for j, row in prev:                         # the ring's rows before the chunk\n        ol.load(lw.state[row, :], out=E[K - 1 - j, :])\n    xs = ol.quantize(rmsnorm(x, ol.load(lw.g_in), spec.eps))\n    bx = E[K - 1:K - 1 + R, :]                  # B * x; B, C, x: this slice's channels\n    bx.set(ol.dot(xs, lw.win[0:n, :]) * ol.dot(xs, lw.win[2 * n:3 * n, :]))\n    if run:\n        _ring_store(lw, E[R - 1:R - 1 + K, :], p0.words[\"ringo\"], K, n)\n    else:\n        for r in range(max(0, R - K), R):\n            for sl in _ring_rows(K, p0 + r)[1]:\n                ol.store(lw.state[sl:sl + 1, :], E[K - 1 + r:K + r, :])\n    full = 0 if run else max(0, K - 1 - p0)     # rows before it lack positions < 0\n    groups = [(r, r + 1) for r in range(min(full, R))] + ([(full, R)] if full < R else [])\n    y = ol.empty([R, n]) if len(groups) > 1 else None\n    for r0, r1 in groups:\n        acc = bx[r0:r1, :] * taps[K - 1, :][None, :]\n        for j in range(1, (K - 1 if run else min(K - 1, p0 + r0)) + 1):\n            acc = acc + E[K - 1 + r0 - j:K - 1 + r1 - j, :] * taps[K - 1 - j, :][None, :]\n        if y is None:\n            y = acc\n        else:\n            y[r0:r1, :].set(acc)\n    del E, bx, acc, taps\n    y_all = ol.all_gather(y * ol.dot(xs, lw.win[n:2 * n, :]))  # [R, H]\n    return x + ol.all_gather(ol.dot(y_all, lw.wout))\n\n\n@ol.jit\ndef lfm2_rows(m, p0: int, R: int, logit_rows, block: int = ATTN_BLOCK, tokens=None):\n    \"\"\"R prompt tokens at positions p0 .. p0+R-1 at once: their embeddings m.xr and RoPE\n    tables m.cosr / m.sinr, or those of `tokens` from the image's tables (qwen3._inputs_rows) ->\n    logits of the rows in `logit_rows` (a contiguous range, or empty). Bit-identical to R\n    lfm2_step runs.\"\"\"\n    spec = m.spec\n    rows = p0 if isinstance(p0, RunRows) else [(0, p0 + r) for r in range(R)]\n    x, c, s_ = _inputs_rows(m, rows, tokens)\n\n    def layer(li, it):\n        lw = m.layer(li, it)\n        if lw.kind == CONV:\n            x.set(_conv_rows(x, lw, p0, spec))\n        else:\n            x.set(_attention_rows(x, lw, c, s_, rows, spec, block))\n        x.set(_mlp(x, lw, spec))\n\n    run_layers(m.plan, layer)\n    _lm_head_rows(x, m, spec, logit_rows)\n\n\n@ol.jit\ndef lfm2_prompt_run(m, pos, R: int, kind: str, block: int = ATTN_BLOCK):\n    \"\"\"A prompt run of R rows (docs/prefill.md), lfm2_rows with its tokens from out[]: kind\n    \"P\", or \"L\" (the prompt's last run: its last row's logits). pos: a RunRows (toks_at 0) at\n    the run-time position (the state's tpos and ring words, RunWords), or the run's first\n    position, a compile-time one (the rows before conv_k - 1).\"\"\"\n    run = isinstance(pos, RunRows)\n    with RunWords(m, pos):\n        lfm2_rows.fn(m, pos, R, [R - 1] if kind == \"L\" else [], block,\n                     None if run else OutTokens(0))\n\n\ndef run_layers(runs, layer, nest: dict | None = None) -> None:\n    \"\"\"Emit the layers of a plan (runs of `plan`) as layer(index, it): a run with repeats is\n    one hardware loop over its unit (the index is the element's layer in the first iteration,\n    `it` the loop variable), the others are unrolled (`it` None). nest (subs' of the runs): a\n    unit's repeated part is a hardware loop inside it, its layers layer(index, it, jt) with\n    jt = (the inner loop variable, the part's layers, its bytes); one copy of the part's\n    layers in the program instead of one a repeat.\"\"\"\n    for first, unit, reps in runs:\n        for it in ([None] if reps == 1 else ol.range(reps)):\n            if nest is None:\n                for e in range(len(unit)):\n                    layer(first + e, it)\n                continue\n            for e0, su, r, nb in nest[first]:\n                if r == 1:\n                    for e in range(len(su)):\n                        layer(first + e0 + e, it)\n                    continue\n                for jt in ol.range(r):\n                    for e in range(len(su)):\n                        layer(first + e0 + e, it, (jt, len(su), nb))\n", "opentpu/llm/llama.py": "\"\"\"Llama-like decoders on openTPU: SmolLM3 (e.g. SmolLM3-3B) and Phi-3 / Phi-4-mini.\n\nThey are Qwen3 (qwen3.py) without the RMSNorm on each q and k head, so they run on Qwen3's\nSpec, DRAM image, kernels and Engine; this module only reads their configs (spec_from_hf).\nWhat differs from Qwen3, all in qwen3.py and off for Qwen3:\n  qk_norm   False: no q_norm / k_norm\n  nope      SmolLM3's layers without RoPE (config no_rope_layers[i] == 0, every 4th layer):\n            one hardware loop still runs every layer, each with a rope gate (qwen3._rope_gate)\n  rotary    partial RoPE (Phi-3 partial_rotary_factor 0.75: 96 of 128 dimensions; the others\n            pass through, as Qwen3.5's)\n  rope_div, rope_scale\n            LongRoPE (Phi-3 rope_scaling type longrope): the short factors divide the\n            frequencies, the attention factor scales cos and sin; the KV capacity stays within\n            original_max_position_embeddings (ctx), where Hugging Face uses the short factors\n  embed     \"int8\": the embedding rows are int8 per 128 (their vocabularies, 128K and 200K,\n            make an fp32 table 1-2.4 GB): the device gathers them from the tied int8 LM head\n            (kernels.gather.gather_row)\nPhi-3's fused qkv_proj and gate_up_proj are read as separate q/k/v and gate/up projections\n(qwen3.Weights).\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport math\nfrom pathlib import Path\n\nfrom . import formats as FM\nfrom . import rope_parameters\nfrom .qwen3 import Spec\n\nMODEL_TYPES = (\"llama\", \"smollm3\", \"phi3\")\n\n\ndef spec_from_hf(model_dir) -> Spec:\n    \"\"\"The qwen3.Spec of a SmolLM3 / Phi-3 / Llama checkpoint, as Hugging Face's modeling code\n    reads its config.json (the RoPE parameters as transformers' standardize_rope_params).\"\"\"\n    c = json.loads((Path(model_dir) / \"config.json\").read_text())\n    mt = c.get(\"model_type\")\n    if mt not in MODEL_TYPES:\n        raise ValueError(f\"{model_dir}: model type {mt!r} is not a Llama-like one {MODEL_TYPES}\")\n    if c.get(\"attention_bias\") or c.get(\"mlp_bias\"):\n        raise ValueError(f\"{model_dir}: attention / MLP biases are not supported\")\n    H, nq = c[\"hidden_size\"], c[\"num_attention_heads\"]\n    d = c.get(\"head_dim\") or H // nq\n    L = c[\"num_hidden_layers\"]\n    rp = rope_parameters(c, model_dir, (\"default\", \"longrope\"))\n    theta = rp.get(\"rope_theta\", c.get(\"rope_theta\", 10000.0))\n    rotary = int(d * rp.get(\"partial_rotary_factor\", c.get(\"partial_rotary_factor\", 1.0)))\n    kind = rp.get(\"rope_type\", rp.get(\"type\", \"default\"))\n    extra: dict = {}\n    if kind == \"longrope\":\n        orig = rp.get(\"original_max_position_embeddings\",\n                      c.get(\"original_max_position_embeddings\"))\n        factor = rp.get(\"factor\") or c[\"max_position_embeddings\"] / orig\n        af = rp.get(\"attention_factor\")\n        if af is None:\n            af = 1.0 if factor <= 1.0 else math.sqrt(1 + math.log(factor) / math.log(orig))\n        extra = dict(rope_div=tuple(float(f) for f in rp[\"short_factor\"]), rope_scale=af,\n                     ctx=orig)\n        if len(extra[\"rope_div\"]) != rotary // 2:\n            raise ValueError(f\"{len(extra['rope_div'])} short factors for {rotary // 2} \"\n                             f\"frequencies\")\n    # Phi-3's sliding window (Hugging Face masks the keys at or before q - window; this code\n    # has none): the KV capacity stays within it, where no key is masked\n    window = c.get(\"sliding_window\")\n    if mt == \"phi3\" and window:\n        extra[\"ctx\"] = min(extra.get(\"ctx\") or window, window)\n    if mt == \"smollm3\":\n        flags = c.get(\"no_rope_layers\")\n        if flags is None:                               # SmolLM3Config's default\n            n = c.get(\"no_rope_layer_interval\", 4)\n            flags = [int((i + 1) % n != 0) for i in range(L)]\n        extra[\"nope\"] = tuple(i for i, f in enumerate(flags) if not f)\n        if c.get(\"use_sliding_window\"):\n            raise ValueError(f\"{model_dir}: sliding-window attention is not supported\")\n    eos = c.get(\"eos_token_id\")\n    g = Path(model_dir) / \"generation_config.json\"\n    if g.exists():\n        eos = json.loads(g.read_text()).get(\"eos_token_id\", eos)\n    return Spec(hidden=H, layers=L, n_q=nq, n_kv=c[\"num_key_value_heads\"], head_dim=d,\n                ffn=c[\"intermediate_size\"], vocab=c[\"vocab_size\"], eps=c[\"rms_norm_eps\"],\n                theta=theta, tied=c.get(\"tie_word_embeddings\", False),\n                bos=c.get(\"bos_token_id\"), eos=tuple(eos) if isinstance(eos, list) else (eos,),\n                qk_norm=False, rotary=0 if rotary == d else rotary, embed=\"int8\",\n                mix=FM.mix_for(c), **extra)\n", "opentpu/llm/minicpmv.py": "\"\"\"MiniCPM-V 4.7 (openbmb/MiniCPM-V-4.7-35B-A3B) on openTPU: docs/minicpmv.md.\n\nThe language model is Qwen3.5-MoE (qwen35.Spec, streamed experts). This module holds what is\nMiniCPM-V's own:\n  VisionSpec        the vision tower's and projector's dimensions and the image token ids\n  host side         what the host does to an image, as a tokenizer does to text (no model\n                    math): decode, the slice grid, bicubic resizes, normalization, 14 x 14\n                    patches; the NaViT position ids; the placeholder text; the canvas M-RoPE\n                    positions (integer index arithmetic). Ports of transformers v5.18.0's\n                    MiniCPMV4_6ImageProcessor, MiniCPMV4_6Processor and\n                    MiniCPMV4_7Model.get_rope_index (Apache-2.0)\n  vision_reference  the SigLIP2 tower, its window merger and the projector, fp32 numpy (HF's\n                    math): the reference the card's runs are checked against\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport itertools\nimport json\nimport math\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom .. import quant as Q\n\nTOWER, MERGER = \"model.vision_tower.\", \"model.merger.\"\n\n\n# =============================================================================== the spec\n@dataclass(frozen=True)\nclass VisionSpec:\n    hidden: int = 1152              # SigLIP2 so400m\n    heads: int = 16                 # of 72\n    ffn: int = 4304\n    layers: int = 27\n    patch: int = 14\n    side: int = 70                  # the position table's side: image_size 980 / patch 14\n    eps: float = 1e-6               # every LayerNorm's (the projector's too)\n    insert: int = 6                 # the window merger after this layer (insert_layer_id)\n    window: int = 2                 # its window and the projector's merge: 2 x 2\n    out: int = 2048                 # the language model's hidden size\n    scale: int = 448                # the processor's scale_resolution\n    max_slices: int = 9             # its max_slice_nums (preprocessor_config.json)\n    image_token: int = 248056       # <|image_pad|>\n    image_start: int = 248078       # <image>\n    image_end: int = 248079\n    slice_start: int = 248088       # <slice>\n    slice_end: int = 248089\n    newline: int = 198              # \"\\n\"\n\n    @property\n    def head_dim(self) -> int:\n        return self.hidden // self.heads\n\n    @property\n    def merged(self) -> int:\n        \"\"\"The patches per language-model token: two 2 x 2 merges (16x mode).\"\"\"\n        return (self.window * self.window) ** 2\n\n    @staticmethod\n    def from_hf(model_dir) -> \"VisionSpec\":\n        top = json.loads((Path(model_dir) / \"config.json\").read_text())\n        if top.get(\"downsample_mode\", \"16x\") != \"16x\" or top.get(\"merger_times\", 1) != 1:\n            raise ValueError(f\"{model_dir}: only downsample_mode 16x, merger_times 1\")\n        v = top[\"vision_config\"]\n        if v.get(\"hidden_act\", \"gelu_pytorch_tanh\") != \"gelu_pytorch_tanh\":\n            raise ValueError(f\"{model_dir}: vision activation {v['hidden_act']}\")\n        pre = Path(model_dir) / \"preprocessor_config.json\"\n        p = json.loads(pre.read_text()) if pre.exists() else {}\n        if any(x != 0.5 for x in p.get(\"image_mean\", [0.5]) + p.get(\"image_std\", [0.5])):\n            raise ValueError(f\"{model_dir}: image mean / std other than 0.5\")\n        return VisionSpec(hidden=v[\"hidden_size\"], heads=v[\"num_attention_heads\"],\n                          ffn=v[\"intermediate_size\"], layers=v[\"num_hidden_layers\"],\n                          patch=v[\"patch_size\"], side=v[\"image_size\"] // v[\"patch_size\"],\n                          eps=v.get(\"layer_norm_eps\", 1e-6),\n                          insert=top.get(\"insert_layer_id\", 6),\n                          out=top[\"text_config\"][\"hidden_size\"],\n                          scale=p.get(\"scale_resolution\", 448),\n                          max_slices=p.get(\"max_slice_nums\", 9),\n                          image_token=top[\"image_token_id\"], image_start=top[\"image_start_id\"],\n                          image_end=top[\"image_end_id\"], slice_start=top[\"slice_start_id\"],\n                          slice_end=top[\"slice_end_id\"], newline=top[\"newline_id\"])\n\n\n# =============================================================================== host side\ndef ensure_divide(length, divisor: int) -> int:\n    return max(round(length / divisor) * divisor, divisor)\n\n\ndef best_resize(h, w, scale: int, patch: int, upscale: bool = False) -> tuple:\n    \"\"\"find_best_resize: (h, w) of about scale^2 pixels at the aspect ratio when the image is\n    larger (or upscale), each a multiple of 4 patches (the two 2 x 2 merges).\"\"\"\n    if h * w > scale * scale or upscale:\n        ar = w / h\n        h = int(scale / math.sqrt(ar))\n        w = int(h * ar)\n    return ensure_divide(h, patch * 4), ensure_divide(w, patch * 4)\n\n\ndef slice_grid(h: int, w: int, max_slices: int, scale: int):\n    \"\"\"get_sliced_grid: (rows, cols) of the slices, or None (the thumbnail alone).\"\"\"\n    log_ratio = math.log(w / h)\n    multiple = min(math.ceil(w * h / (scale * scale)), max_slices)\n    if multiple <= 1:\n        return None\n    best, err = [1, 1], float(\"inf\")\n    for n in (multiple - 1, multiple, multiple + 1):\n        if n == 1 or n > max_slices:\n            continue\n        for rows in range(1, n + 1):\n            if n % rows == 0:\n                e = abs(log_ratio - math.log((n // rows) / rows))\n                if e < err:\n                    best, err = [rows, n // rows], e\n                elif e == err and rows > best[0]:\n                    best = [rows, n // rows]\n    return tuple(best)\n\n\ndef refine_size(h: int, w: int, grid, scale: int, patch: int) -> tuple:\n    \"\"\"get_refine_size: the size the image is resized to before it is cut into the grid.\"\"\"\n    rows, cols = grid\n    bh, bw = best_resize(ensure_divide(h, rows) / rows, ensure_divide(w, cols) / cols, scale,\n                         patch, upscale=True)\n    return bh * rows, bw * cols\n\n\ndef decode(src):\n    \"\"\"An image as HF's processor reads it: a path, a data: URL or base64 string, or the file's\n    bytes (torchvision's decode_image, RGB; its EXIF orientation is not applied, as HF's for a\n    path), or a PIL image (EXIF-transposed, RGB) -> uint8 [3, H, W] (a torch tensor).\"\"\"\n    import torch\n    try:\n        from torchvision.io import ImageReadMode, decode_image\n    except ImportError:                     # (no torchvision: PIL's decoder, RGB)\n        decode_image = None\n    if isinstance(src, (bytes, bytearray)):\n        src, raw = None, bytes(src)\n    elif not isinstance(src, (str, Path)):\n        from PIL import ImageOps\n        im = ImageOps.exif_transpose(src).convert(\"RGB\")\n        return torch.from_numpy(np.asarray(im).copy()).permute(2, 0, 1).contiguous()\n    s = None if src is None else str(src)\n    if s is None:\n        pass\n    elif not s.startswith(\"data:\") and len(s) < 4096 and Path(s).is_file():\n        raw = Path(s).read_bytes()\n    else:\n        import base64\n        raw = base64.decodebytes((s.split(\",\", 1)[1] if s.startswith(\"data:image/\") else s)\n                                 .encode())\n    if decode_image is not None:\n        return decode_image(torch.frombuffer(bytearray(raw), dtype=torch.uint8),\n                            mode=ImageReadMode.RGB)\n    import io\n    from PIL import Image\n    im = Image.open(io.BytesIO(raw)).convert(\"RGB\")\n    return torch.from_numpy(np.asarray(im).copy()).permute(2, 0, 1).contiguous()\n\n\ndef _resize(img, h: int, w: int):\n    \"\"\"torchvision's bicubic resize with antialiasing of a uint8 [3, H, W] tensor (uint8), as\n    HF's TorchvisionBackend; without torchvision, torch's own (the same kernel in float, rounded\n    and clamped: not checked bit for bit).\"\"\"\n    try:\n        from torchvision.transforms import InterpolationMode\n        from torchvision.transforms.v2 import functional as tvF\n        return tvF.resize(img, [h, w], interpolation=InterpolationMode.BICUBIC, antialias=True)\n    except ImportError:\n        import torch\n        y = torch.nn.functional.interpolate(img[None].float(), size=(h, w), mode=\"bicubic\",\n                                            antialias=True, align_corners=False)[0]\n        return y.round().clamp(0, 255).to(torch.uint8)\n\n\ndef crops(img, vs: VisionSpec, max_slices: int | None = None):\n    \"\"\"An image (uint8 [3, H, W]) as the processor cuts it: ([the thumbnail, slices...] as\n    uint8 tensors, the grid (rows, cols) or None).\"\"\"\n    max_slices = vs.max_slices if max_slices is None else max_slices\n    H, W = img.shape[-2:]\n    grid = slice_grid(H, W, max_slices, vs.scale) if max_slices >= 1 else None\n    th, tw = best_resize(H, W, vs.scale, vs.patch, upscale=grid is None)\n    out = [_resize(img, th, tw)]\n    if grid is not None:\n        rh, rw = refine_size(H, W, grid, vs.scale, vs.patch)\n        ref = _resize(img, rh, rw)\n        ph, pw = rh // grid[0], rw // grid[1]\n        out += [ref[:, i:i + ph, j:j + pw] for i in range(0, rh, ph) for j in range(0, rw, pw)]\n    return out, grid\n\n\ndef patches(crop, patch: int = 14) -> np.ndarray:\n    \"\"\"A crop's patch rows [h w, 3 patch^2] (fp32): its patch x patch blocks row-major, each\n    (channel, row, column), normalized (x - 127.5) / 127.5 as HF's fused rescale and\n    normalize (mean = std = 0.5): the patch embedding is then a matrix product.\"\"\"\n    x = np.asarray(crop, np.float32)\n    x = (x - np.float32(127.5)) / np.float32(127.5)\n    C, H, W = x.shape\n    h, w = H // patch, W // patch\n    return np.ascontiguousarray(x.reshape(C, h, patch, w, patch).transpose(1, 3, 0, 2, 4)\n                                .reshape(h * w, C * patch * patch))\n\n\ndef position_ids(h: int, w: int, side: int) -> np.ndarray:\n    \"\"\"The NaViT position ids of an h x w patch grid in the side x side table\n    (get_vision_nearest_position_ids: float32 bucketize, as torch computes it).\"\"\"\n    import torch\n    b = torch.arange(1 / side, 1.0, 1 / side)\n    bh = torch.bucketize(torch.arange(h) / h, b, right=True)\n    bw = torch.bucketize(torch.arange(w) / w, b, right=True)\n    return (bh[:, None] * side + bw).flatten().numpy()\n\n\n@dataclass\nclass ImageInput:\n    \"\"\"One image as the host prepares it: its crops' patch rows and (h, w) in patches (the\n    thumbnail first), the slice grid, the placeholder text that replaces its <|image_pad|> in\n    the prompt, and its content's key (sha256 of the crops' sizes and patch rows: token_keys).\"\"\"\n    patches: list\n    sizes: list\n    grid: tuple | None\n    text: str\n    key: str = \"\"\n\n    @property\n    def tokens(self) -> int:\n        \"\"\"Its language-model rows (the <|image_pad|> tokens of its placeholder).\"\"\"\n        return sum(h * w for h, w in self.sizes) // 16\n\n\ndef prepare(src, vs: VisionSpec, max_slices: int | None = None, image_id: int | None = 0,\n            pad: str = \"<|image_pad|>\") -> ImageInput:\n    \"\"\"An image (path, data URL, base64 or PIL) -> ImageInput: replace_image_token's text with\n    use_image_id's <image_id>N</image_id> prefix (image_id None: none).\"\"\"\n    cs, grid = crops(decode(src), vs, max_slices)\n    ps = [patches(c, vs.patch) for c in cs]\n    sizes = [(c.shape[-2] // vs.patch, c.shape[-1] // vs.patch) for c in cs]\n    n = [h * w // vs.merged for h, w in sizes]\n    text = \"<image>\" + pad * n[0] + \"</image>\"\n    if grid is not None:\n        row = (\"<slice>\" + pad * n[1] + \"</slice>\") * grid[1]\n        text += \"\\n\".join([row] * grid[0])\n    if image_id is not None:\n        text = f\"<image_id>{image_id}</image_id>\" + text\n    h = hashlib.sha256(repr(sizes).encode())\n    for p in ps:\n        h.update(np.ascontiguousarray(p).tobytes())\n    return ImageInput(ps, sizes, grid, text, h.hexdigest())\n\n\ndef expand(text: str, images: list, pad: str = \"<|image_pad|>\") -> str:\n    \"\"\"The chat template's text with its i-th `pad` replaced by images[i].text (one per image,\n    in order: get_text_with_replacements).\"\"\"\n    parts = text.split(pad)\n    if len(parts) - 1 != len(images):\n        raise ValueError(f\"{len(parts) - 1} image placeholders for {len(images)} images\")\n    return parts[0] + \"\".join(im.text + p for im, p in zip(images, parts[1:]))\n\n\ndef token_keys(im: ImageInput) -> list[int]:\n    \"\"\"Stand-ins for an image's <|image_pad|> tokens in a context's key (otpu-serve's prefix\n    matching and KV store compare token ids, and every image's pads are the one id): negative\n    int32s, the k-th a hash of the image's content key and k, so the keys of two contexts part\n    at their first differing image's first token.\"\"\"\n    h = bytes.fromhex(im.key)\n    return [-1 - int.from_bytes(hashlib.blake2b(h + k.to_bytes(4, \"little\"),\n                                                digest_size=4).digest(), \"little\") % (2**31 - 1)\n            for k in range(im.tokens)]\n\n\ndef keyed(ids, images: list, image_token: int) -> list[int]:\n    \"\"\"A prompt's key: its token ids with each image's pads its token_keys, in order.\"\"\"\n    keys = [k for im in images for k in token_keys(im)]\n    out, i = [], 0\n    for t in ids:\n        if t == image_token:\n            if i == len(keys):\n                raise ValueError(f\"more image tokens than the {len(images)} images' {len(keys)}\")\n            out.append(keys[i])\n            i += 1\n        else:\n            out.append(int(t))\n    if i != len(keys):\n        raise ValueError(f\"{i} image tokens for the {len(images)} images' {len(keys)}\")\n    return out\n\n\ndef unkeyed(keys, image_token: int) -> list[int]:\n    \"\"\"The token ids of a key (keyed's inverse).\"\"\"\n    return [image_token if t < 0 else t for t in keys]\n\n\ndef _frame_end(last: int, ids: list, markers: tuple, limit: int) -> int:\n    e = last\n    while e < limit and ids[e] in markers:\n        e += 1\n    return e\n\n\ndef _groups(ids: list, mm: list, vs: VisionSpec):\n    \"\"\"_group_visual_frames: [(group start, group end, [(thumb start, thumb end, frame end,\n    slices [(start, end)])])] of one sequence; mm 1 on the image tokens.\"\"\"\n    markers = (vs.slice_start, vs.slice_end, vs.image_start, vs.image_end, vs.newline)\n    groups, open_slices, prev_end = [], None, 0\n    for modality, run in itertools.groupby(enumerate(mm), lambda t: t[1]):\n        if modality == 0:\n            continue\n        run = list(run)\n        crop = (run[0][0], run[-1][0] + 1)\n        if open_slices is not None and ids[crop[0] - 1] == vs.slice_start:\n            open_slices.append(crop)\n        else:\n            open_slices = []\n            frame = (crop[0], crop[1], open_slices)\n            gap = ids[prev_end:crop[0] - 1]\n            if groups and all(t in markers for t in gap):\n                groups[-1][1].append(frame)\n            else:\n                groups.append((crop[0] - 1, [frame]))\n        prev_end = crop[1]\n    out = []\n    for g0, frames in groups:\n        fr = [(a, b, _frame_end(sl[-1][1] if sl else b, ids, markers, len(ids)), sl)\n              for a, b, sl in frames]\n        out.append((g0, fr[-1][2], fr))\n    return out\n\n\ndef _grid_positions(o: int, grid, canvas_h: int = 0, canvas_w: int = 0, h_off: int = 0,\n                    w_off: int = 0, merge: int = 4):\n    \"\"\"get_vision_position_ids: [3, n] (t, h, w) of a crop placed on the canvas.\"\"\"\n    import torch\n    gh, gw = int(grid[0]) // merge, int(grid[1]) // merge\n    ch, cw = canvas_h or gh, canvas_w or gw\n    hc = torch.linspace(0, ch - 1, gh).round().long() + h_off\n    wc = torch.linspace(0, cw - 1, gw).round().long() + w_off\n    H, W = torch.meshgrid(hc, wc, indexing=\"ij\")\n    return (torch.stack([torch.zeros_like(H), H, W]).reshape(3, -1) + o).numpy()\n\n\ndef rope_index(ids, sizes, vs: VisionSpec, merge: int = 4) -> tuple:\n    \"\"\"Canvas M-RoPE (get_rope_index for one unpadded sequence): (positions [3, T] of (t, h,\n    w), delta), delta = max position + 1 - T (decode: slot s is at position s + delta). sizes:\n    every crop's (h, w) in patches, in order (thumbnail, slices; image after image). A text-only\n    sequence is arange(T) in each row, delta 0.\"\"\"\n    ids = [int(t) for t in ids]\n    mm = [1 if t == vs.image_token else 0 for t in ids]\n    T = len(ids)\n    pos = np.tile(np.arange(T, dtype=np.int64), (3, 1))\n    it = iter([tuple(int(v) for v in s) for s in sizes])\n    cur, idx = 0, 0\n    for g0, g1, frames in _groups(ids, mm, vs):\n        if g0 > idx:\n            pos[:, idx:g0] = np.arange(g0 - idx) + cur\n            cur += g0 - idx\n        cursor = g0\n        for t0, t1, fend, slices in frames:\n            thumb = next(it)\n            fstart = t0 - 1\n            if fstart > cursor:\n                n = fstart - cursor\n                pos[:, cursor:fstart] = np.arange(n) + cur\n                cur += n + 1\n            fend = min(fend, g1)\n            o = cur\n            halo = max(o - 1, 0)\n            sh = sw = rows = cols = 0\n            ch, cw = thumb[0] // merge, thumb[1] // merge\n            if slices:\n                cols = len(slices)\n                for k in range(len(slices) - 1):\n                    if slices[k + 1][0] - slices[k][1] > 2:\n                        cols = k + 1\n                        break\n                rows = len(slices) // cols if cols > 0 else 1\n                if rows * cols != len(slices):\n                    rows, cols = 1, len(slices)\n                first = next(it)\n                sh, sw = first[0] // merge, first[1] // merge\n                ch, cw = rows * sh, cols * sw\n            pos[:, fstart:fend] = o\n            pos[1:, fstart] = halo\n            if t1 < fend:\n                pos[1, t1], pos[2, t1] = o + ch, o + cw\n            pos[:, t0:t1] = _grid_positions(o, thumb, ch, cw, merge=merge)\n            for k, (s0, s1) in enumerate(slices):\n                ho, wo = (k // cols) * sh, (k % cols) * sw\n                sz = first if k == 0 else next(it)\n                gh, gw = sz[0] // merge, sz[1] // merge\n                if s0 - 1 >= fstart:\n                    pos[1, s0 - 1], pos[2, s0 - 1] = o + ho, o + wo\n                if s1 < fend:\n                    pos[1, s1], pos[2, s1] = o + ho + gh - 1, o + wo + gw - 1\n                pos[:, s0:s1] = _grid_positions(o, sz, h_off=ho, w_off=wo, merge=merge)\n            for k in range(len(slices) - 1):\n                a, b = slices[k][1], slices[k + 1][0]\n                if b - a <= 2:\n                    continue\n                for nl in range(a + 1, b - 1):\n                    pos[1, nl] = o + (k // cols + 1) * sh - 1\n                    pos[2, nl] = o + cols * sw\n            cur = o + max(ch, cw) + 1\n            cursor = fend\n        if cursor < g1:\n            pos[:, cursor:g1] = np.arange(g1 - cursor) + cur\n            cur += g1 - cursor\n        idx = g1\n    if idx < T:\n        pos[:, idx:T] = np.arange(T - idx) + cur\n    return pos, int(pos.max()) + 1 - T if T else 0\n\n\n# =============================================================================== reference\ndef load_vision(model_dir) -> dict:\n    \"\"\"The vision tower's and projector's tensors (fp32 numpy), by their checkpoint names.\"\"\"\n    import torch\n    from safetensors import safe_open\n    W = {}\n    for f in sorted(Path(model_dir).glob(\"*.safetensors\")):\n        with safe_open(str(f), \"pt\") as h:\n            for k in h.keys():\n                if k.startswith((TOWER, MERGER)):\n                    W[k] = h.get_tensor(k).to(torch.float32).numpy()\n    return W\n\n\nclass VisionWeights:\n    \"\"\"load_vision's tensors read from the checkpoint as they are asked for, none kept (the\n    staged pieces' packing and the vectors of a staged image's build).\"\"\"\n\n    def __init__(self, model_dir):\n        from safetensors import safe_open\n        self.model_dir = Path(model_dir)\n        self._at = {}\n        for f in sorted(self.model_dir.glob(\"*.safetensors\")):\n            with safe_open(str(f), \"pt\") as h:\n                for k in h.keys():\n                    if k.startswith((TOWER, MERGER)):\n                        self._at[k] = str(f)\n\n    def __contains__(self, k) -> bool:\n        return k in self._at\n\n    def keys(self):\n        return self._at.keys()\n\n    def __getitem__(self, k) -> np.ndarray:\n        import torch\n        from safetensors import safe_open\n        with safe_open(self._at[k], \"pt\") as h:\n            return h.get_tensor(k).to(torch.float32).numpy()\n\n\ndef _ln(x, w, b, eps):\n    m = x.mean(-1, keepdims=True)\n    xc = x - m\n    return xc / np.sqrt((xc * xc).mean(-1, keepdims=True) + eps) * w + b\n\n\ndef _gelu_tanh(x):\n    return 0.5 * x * (1 + np.tanh(np.float32(math.sqrt(2 / math.pi)) * (x + 0.044715 * x ** 3)))\n\n\ndef gelu_erf(x):\n    \"\"\"nn.GELU(): x Phi(x), the exact erf form (the projector's).\"\"\"\n    import torch\n    t = torch.from_numpy(np.ascontiguousarray(x, np.float32))\n    return torch.nn.functional.gelu(t).numpy()\n\n\ndef _lin(x, W, n):\n    return x @ W[n + \".weight\"].T + W[n + \".bias\"]\n\n\ndef _attention(x, W, p, vs: VisionSpec, groups):\n    \"\"\"Bidirectional attention of x's rows within each group of row indices.\"\"\"\n    q, k, v = (_lin(x, W, p + n) for n in (\"q_proj\", \"k_proj\", \"v_proj\"))\n    d = vs.head_dim\n    o = np.zeros_like(q)\n    for g in groups:\n        for h in range(vs.heads):\n            c = slice(h * d, (h + 1) * d)\n            s = q[g, c] @ k[g, c].T * np.float32(d ** -0.5)\n            s = np.exp(s - s.max(axis=1, keepdims=True))\n            o[g, c] = (s / s.sum(axis=1, keepdims=True)) @ v[g, c]\n    return _lin(o, W, p + \"out_proj\")\n\n\ndef windows(h: int, w: int, k: int = 2) -> np.ndarray:\n    \"\"\"[h w / k^2, k^2]: each k x k window's row indices of the h x w grid (row-major), windows\n    row-major: the merges' order (the window merger's attention groups and concatenation, the\n    projector's 2 x 2).\"\"\"\n    i = np.arange(h * w).reshape(h // k, k, w // k, k).transpose(0, 2, 1, 3)\n    return i.reshape(-1, k * k)\n\n\ndef card_order(h: int, w: int) -> np.ndarray:\n    \"\"\"[h w]: the raster indices of an h x w crop's patches in the card's window order (h, w\n    multiples of 4): each 4 x 4 block row-major, within it its 2 x 2 windows row-major, within\n    those their 4 patches (opentpu/kernels/vit.py: both merges' windows are then consecutive\n    rows; the projector's output rows come out row-major over the blocks, HF's order).\"\"\"\n    i = np.arange(h * w).reshape(h // 4, 2, 2, w // 4, 2, 2)\n    return i.transpose(0, 3, 1, 4, 2, 5).reshape(-1)\n\n\ndef _layer(x, W, i, vs, groups):\n    p = f\"{TOWER}encoder.layers.{i}.\"\n    x = x + _attention(_ln(x, W[p + \"layer_norm1.weight\"], W[p + \"layer_norm1.bias\"], vs.eps),\n                       W, p + \"self_attn.\", vs, groups)\n    y = _ln(x, W[p + \"layer_norm2.weight\"], W[p + \"layer_norm2.bias\"], vs.eps)\n    return x + _lin(_gelu_tanh(_lin(y, W, p + \"mlp.fc1\")), W, p + \"mlp.fc2\")\n\n\ndef vision_reference(vs: VisionSpec, W: dict, P: np.ndarray, size, capture=None,\n                     gelu=gelu_erf) -> np.ndarray:\n    \"\"\"One crop's language-model rows [h w / 16, out] (fp32): P its patch rows [h w, 3 p^2],\n    size its (h, w) in patches. capture: a dict that gets the stages' rows (\"embed\",\n    \"layer6\" .. the input of the window merger, \"merged\" its output, \"post\" after\n    post_layernorm, \"out\"). gelu: the projector's (nn.GELU's erf; lib's tanh for the\n    measurement of docs/minicpmv.md 4.2).\"\"\"\n    h, w = size\n    cap = capture if capture is not None else {}\n    f32 = np.float32\n    Wp = W[TOWER + \"embeddings.patch_embedding.weight\"].reshape(vs.hidden, -1)\n    x = (np.asarray(P, f32) @ Wp.T + W[TOWER + \"embeddings.patch_embedding.bias\"]\n         + W[TOWER + \"embeddings.position_embedding.weight\"][position_ids(h, w, vs.side)])\n    cap[\"embed\"] = x\n    every = [np.arange(h * w)]\n    for i in range(vs.insert + 1):\n        x = _layer(x, W, i, vs, every)\n    cap[f\"layer{vs.insert}\"] = x\n    m = TOWER + \"vit_merger.\"\n    win = windows(h, w, vs.window)\n    x = x + _attention(_ln(x, W[m + \"layer_norm1.weight\"], W[m + \"layer_norm1.bias\"], vs.eps),\n                       W, m + \"self_attn.\", vs, list(win))\n    z = x[win].reshape(len(win), -1)                        # [h w / 4, 4 C]\n    y = _ln(z, W[m + \"pre_norm.weight\"], W[m + \"pre_norm.bias\"], vs.eps)\n    x = _lin(_gelu_tanh(_lin(y, W, m + \"linear_1\")), W, m + \"linear_2\") + x[win].mean(axis=1)\n    cap[\"merged\"] = x\n    h2, w2 = h // 2, w // 2\n    every = [np.arange(h2 * w2)]\n    for i in range(vs.insert + 1, vs.layers):\n        x = _layer(x, W, i, vs, every)\n    x = _ln(x, W[TOWER + \"post_layernorm.weight\"], W[TOWER + \"post_layernorm.bias\"], vs.eps)\n    cap[\"post\"] = x\n    z = x[windows(h2, w2, vs.window)].reshape(h2 * w2 // 4, -1)\n    p = MERGER + \"mlp.0.\"\n    y = _ln(z, W[p + \"pre_norm.weight\"], W[p + \"pre_norm.bias\"], vs.eps)\n    out = _lin(gelu(_lin(y, W, p + \"linear_1\")), W, p + \"linear_2\")\n    cap[\"out\"] = out\n    return out\n\n\n# =============================================================================== on the card\ndef _up(n: int, q: int) -> int:\n    return -(-n // q) * q\n\n\nclass VisionImage:\n    \"\"\"The vision tower's and projector's part of a MiniCPM-V image in one slice's DRAM\n    (docs/minicpmv.md 4.2): the weights in MXU formats (the checkpoint's shapes, but the MLPs'\n    widths padded to their chunks with zero rows and columns and the patch rows' 588 to 640;\n    each LayerNorm's bias folded into the next linear's; `fmt`: their formats, formats()), in\n    pieces of at most `max_piece` bytes (kernels/pieces.py: an expert slot's, so the host can\n    stage them into slots); the vectors (gains, biases) in a block a layer (block `layers` is\n    the window merger's attention), `lstride` bytes apart; the work area of a crop of up to\n    `nmax` patches (the host's patch rows P and position-table rows E, the residual rows X and\n    X2, the Q and O scratch, the KV scratch) and the projector's output rows `vis`\n    (`out_rows`: the prompt's image rows). `b`: the image's allocator (qwen3._Bump), from its\n    next byte.\n\n    The pieces' addresses: `table` (the default) has the kernels read them from a table in\n    DRAM (`pieces()` order: each layer block's PL, then the window merger's, the projector's\n    and the patch embedding's), so the same programs run with the pieces resident (`resident`:\n    laid out after each layer's vectors, the table holding their addresses, written at build)\n    or staged into expert slots by the host (resident False: the pieces' bytes are the pool's\n    entries, the table written per image). table False: static addresses, the resident\n    pieces' (the reference the table runs are checked against, bit for bit).\"\"\"\n\n    CHUNK = 256         # the MLPs' F chunk (a 4-bit W2's column slices: whole 2D)\n    WCHUNK = 512        # the window merger's (17216 -> 17408)\n    WUNIT = 256         # its W1 rows a piece holds at least (a chunk then spans two pieces)\n    PARTS = (768, 512, 256, 128)    # vit_merge's pieces: the widest that splits 4C (1152: 768,\n    #                                 6 blocks: an even first block for a 4-bit W1)\n    MAX_PIECE = 1712128             # a piece's bytes by default: qwen35-35b's fp4 expert slot\n    LMATS = (\"wq\", \"wk\", \"wv\", \"wo\", \"w1\", \"w2\")\n\n    def __init__(self, vs: VisionSpec, cfg, b, nmax: int = 2048, out_rows: int = 2048,\n                 fmt: str = \"int8\", max_piece: int | None = None, resident: bool = True,\n                 table: bool = True):\n        from ..kernels import pieces as PC\n        D = cfg.D\n        self.vs, self.cfg = vs, cfg\n        self.tables = {}                # the host's tables (build: \"pos\", the position table)\n        self.fmts = self.formats(fmt)\n        F_ = self.fmts\n        C, H = vs.hidden, vs.heads\n        self.C, self.heads, self.dv = C, H, vs.head_dim\n        self.dp = _up(vs.head_dim, D)\n        self.F = _up(vs.ffn, self.CHUNK)\n        self.FW = _up(4 * vs.ffn, self.WCHUNK)\n        self.KP = _up(3 * vs.patch ** 2, D)\n        self.part = next(p for p in self.PARTS if (4 * C) % p == 0)\n        self.nmax, self.out_rows = _up(nmax, D), out_rows     # V^T rows: whole D stretches\n        if not (resident or table):\n            raise ValueError(\"staged pieces are read from the table\")\n        self.resident, self.use_table = resident, table\n        self.max_piece = mp = max_piece or self.MAX_PIECE\n        HP = H * self.dp\n\n        def mat(n, k, f, unit, parts=False):\n            return PC.plan(n, k, f, D, unit, mp, parts)\n        dh = vs.head_dim\n        # the matrices in pieces of whole units: a head's rows (q, k, v), D rows (out, the\n        # embedding: a piece's output columns an MM), MLP chunks of rows (W1), column parts (W2)\n        self.lmats = dict(wq=mat(C, C, F_[\"attn\"], dh), wk=mat(C, C, F_[\"attn\"], dh),\n                          wv=mat(C, C, F_[\"attn\"], dh), wo=mat(C, C, F_[\"attn\"], D),\n                          w1=mat(self.F, C, F_[\"mlp\"], self.CHUNK),\n                          w2=mat(C, self.F, F_[\"mlp\"], self.CHUNK, parts=True))\n        self.mmats = {\"wm\": dict(w1=mat(self.FW, 4 * C, F_[\"wm\"], self.WUNIT),\n                                 w2=mat(C, self.FW, F_[\"wm\"], self.WCHUNK, parts=True)),\n                      \"proj\": dict(w1=mat(4 * C, 4 * C, F_[\"proj\"], self.CHUNK),\n                                   w2=mat(vs.out, 4 * C, F_[\"proj\"], self.CHUNK, parts=True))}\n        self.emat = mat(C, self.KP, F_[\"embed\"], D)\n        # the table's order: per layer block its matrices' pieces (PL words), then the window\n        # merger's, the projector's, the embedding's\n        self.lfirst, a = {}, 0\n        for n in self.LMATS:\n            self.lfirst[n], a = a, a + len(self.lmats[n].groups)\n        self.PL = a\n        self.mfirst, a = {}, (vs.layers + 1) * self.PL\n        for m in (\"wm\", \"proj\"):\n            for n in (\"w1\", \"w2\"):\n                self.mfirst[m, n], a = a, a + len(self.mmats[m][n].groups)\n        self.efirst, self.npieces = a, a + len(self.emat.groups)\n        # a layer block: its vectors, then (resident) its pieces\n        from .qwen3 import _Bump\n        lb = _Bump()\n        self.lofs = dict(ln1w=lb.alloc(4 * C), ln2w=lb.alloc(4 * C), bq=lb.alloc(4 * C),\n                         bk=lb.alloc(4 * C), bv=lb.alloc(4 * C), bo=lb.alloc(4 * C),\n                         b1=lb.alloc(4 * self.F), b2=lb.alloc(4 * C))\n        self.lpiece = {}                # (matrix, piece) -> offset in the block (resident)\n        if resident:\n            lb.next = _up(lb.next, 4096)\n            for n in self.LMATS:\n                for i in range(len(self.lmats[n].groups)):\n                    self.lpiece[n, i] = lb.alloc(_up(self.lmats[n].piece_bytes(i), 128))\n        self.lstride = _up(lb.next, 4096)\n        self.layer0 = _up(b.next, 4096)\n        b.next = self.layer0 + (vs.layers + 1) * self.lstride\n        self.start = self.layer0\n        self.wm = dict(pre_w=b.alloc(16 * C), pre_b=b.alloc(16 * C), b1=b.alloc(4 * self.FW),\n                       b2=b.alloc(4 * C))\n        self.post = (b.alloc(4 * C), b.alloc(4 * C))\n        self.proj = dict(pre_w=b.alloc(16 * C), pre_b=b.alloc(16 * C), b1=b.alloc(16 * C),\n                         b2=b.alloc(4 * vs.out))\n        self.emb = dict(bp=b.alloc(4 * C))\n        self.table = b.alloc(4 * self.npieces)\n        self.mpiece = {}                # (merge, matrix, piece) / (\"emb\", piece) -> address\n        if resident:\n            b.next = _up(b.next, 4096)\n            for m in (\"wm\", \"proj\"):\n                for n in (\"w1\", \"w2\"):\n                    for i in range(len(self.mmats[m][n].groups)):\n                        self.mpiece[m, n, i] = b.alloc(_up(self.mmats[m][n].piece_bytes(i),\n                                                           128))\n            for i in range(len(self.emat.groups)):\n                self.mpiece[\"emb\", i] = b.alloc(_up(self.emat.piece_bytes(i), 128))\n        self.weights_end = b.next\n        # the RLD bound of a piece's address: the resident pieces' span (set_bound: the slots')\n        self.bound = (self.layer0, max(self.weights_end - 1, self.layer0))\n        n = self.nmax\n        self.work = dict(P=b.alloc(4 * n * self.KP), E=b.alloc(4 * n * C),\n                         X=b.alloc(4 * n * C), X2=b.alloc(4 * n // 4 * C),\n                         Q=b.alloc(4 * n * HP), O=b.alloc(4 * n * C),\n                         vis=b.alloc(4 * out_rows * vs.out))\n        self.kvh = {h: {\"k\": b.alloc(n * self.dp), \"ks\": b.alloc(4 * n),\n                        \"vt\": b.alloc(self.dp * n), \"vs\": b.alloc(4 * n)} for h in range(H)}\n        self.end = b.next\n\n    KINDS = (\"attn\", \"mlp\", \"wm\", \"proj\", \"embed\")\n\n    @classmethod\n    def formats(cls, fmt: str) -> dict:\n        \"\"\"The weights' MXU formats by kind: \"int8\" (every kind), or \"kind=fmt,...\" over the\n        others' int8 (attn: the encoder layers' and the window merger's attention; mlp: the\n        encoder layers' MLPs; wm: the window merger's MLP; proj: the projector; embed: the\n        patch embedding).\"\"\"\n        if \"=\" not in fmt:\n            return dict.fromkeys(cls.KINDS, fmt)\n        out = dict.fromkeys(cls.KINDS, \"int8\")\n        for part in fmt.split(\",\"):\n            k, f = part.split(\"=\")\n            if k not in out:\n                raise ValueError(f\"vision format kind {k!r}: one of {cls.KINDS}\")\n            out[k] = f\n        return out\n\n    def set_bound(self, lo: int, hi: int) -> None:\n        \"\"\"Staged pieces: the addresses a piece may be at (the slot region's), RLD's bound.\"\"\"\n        self.bound = (int(lo), int(hi))\n\n    # ---- the pieces\n    def pieces(self) -> list:\n        \"\"\"Every piece in the table's order: (key, Layout, piece index), key (\"l\", layer,\n        matrix), (\"m\", \"wm\" / \"proj\", matrix) or (\"emb\",).\"\"\"\n        out = []\n        for li in range(self.vs.layers + 1):\n            for n in self.LMATS:\n                lay = self.lmats[n]\n                out += [((\"l\", li, n), lay, i) for i in range(len(lay.groups))]\n        for m in (\"wm\", \"proj\"):\n            for n in (\"w1\", \"w2\"):\n                lay = self.mmats[m][n]\n                out += [((\"m\", m, n), lay, i) for i in range(len(lay.groups))]\n        out += [((\"emb\",), self.emat, i) for i in range(len(self.emat.groups))]\n        return out\n\n    def resident_addresses(self) -> np.ndarray:\n        \"\"\"The table of the resident pieces' addresses (uint32, pieces() order).\"\"\"\n        if not self.resident:\n            raise ValueError(\"the pieces are not resident\")\n        out = []\n        for li in range(self.vs.layers + 1):\n            for n in self.LMATS:\n                out += [self.layer0 + li * self.lstride + self.lpiece[n, i]\n                        for i in range(len(self.lmats[n].groups))]\n        for m in (\"wm\", \"proj\"):\n            for n in (\"w1\", \"w2\"):\n                out += [self.mpiece[m, n, i] for i in range(len(self.mmats[m][n].groups))]\n        out += [self.mpiece[\"emb\", i] for i in range(len(self.emat.groups))]\n        return np.array(out, np.uint32)\n\n    # ---- descriptors\n    @staticmethod\n    def _v(base, a, n):\n        from ..compiler import Affine, Tensor\n        return Tensor(Affine.of(base) + a, (n,), (1,))\n\n    def _table(self, first: int, n: int, li=None):\n        from ..compiler import Affine, Tensor\n        from ..kernels import pieces as PC\n        at = Affine(self.table + 4 * first)\n        if li is not None:\n            at = at + Affine.of(li) * (4 * self.PL)\n        return PC.Table(Tensor(at, (n,), (1,)), n, self.bound)\n\n    def layer(self, li):\n        \"\"\"Encoder layer li's weights (li an int or a run-time value; vs.layers: the window\n        merger's attention, whose block has the layers' layout).\"\"\"\n        from types import SimpleNamespace\n        from ..compiler import Affine\n        from ..kernels import pieces as PC\n        base = Affine(self.layer0) + Affine.of(li) * self.lstride\n        o, C = self.lofs, self.C\n        if self.use_table:\n            t = self._table(0, self.PL, li)\n            ws = {n: PC.PQ(self.lmats[n], table=t, first=self.lfirst[n]) for n in self.LMATS}\n        else:\n            ws = {n: PC.PQ(self.lmats[n], bases=[base + self.lpiece[n, i] for i in\n                                                 range(len(self.lmats[n].groups))])\n                  for n in self.LMATS}\n        return SimpleNamespace(\n            ln1w=self._v(base, o[\"ln1w\"], C), ln2w=self._v(base, o[\"ln2w\"], C),\n            bq=self._v(base, o[\"bq\"], C), bk=self._v(base, o[\"bk\"], C),\n            bv=self._v(base, o[\"bv\"], C), bo=self._v(base, o[\"bo\"], C),\n            b1=self._v(base, o[\"b1\"], self.F), b2=self._v(base, o[\"b2\"], C), **ws)\n\n    def _mat(self, m, n, lay):\n        from ..kernels import pieces as PC\n        if self.use_table:\n            first = self.efirst if m == \"emb\" else self.mfirst[m, n]\n            return PC.PQ(lay, table=self._table(first, len(lay.groups)), first=0)\n        return PC.PQ(lay, bases=[self.mpiece[(m, i) if m == \"emb\" else (m, n, i)]\n                                 for i in range(len(lay.groups))])\n\n    def merge_weights(self, which: str):\n        \"\"\"The window merger's MLP (\"wm\") or the projector's (\"proj\") for vit_merge.\"\"\"\n        from types import SimpleNamespace\n        m, C, mm = getattr(self, which), self.C, self.mmats[which]\n        return SimpleNamespace(pre_w=self._v(0, m[\"pre_w\"], 4 * C),\n                               pre_b=self._v(0, m[\"pre_b\"], 4 * C),\n                               w1=self._mat(which, \"w1\", mm[\"w1\"]),\n                               b1=self._v(0, m[\"b1\"], mm[\"w1\"].n),\n                               w2=self._mat(which, \"w2\", mm[\"w2\"]),\n                               b2=self._v(0, m[\"b2\"], mm[\"w2\"].n))\n\n    def descriptors(self):\n        \"\"\"The phases' `v`: the work area, the embedding's weights, the post norm.\"\"\"\n        from types import SimpleNamespace\n        from ..kernels.vit import VitKV\n        from .qwen3 import _tdesc as t\n        w, n, C = self.work, self.nmax, self.C\n        return SimpleNamespace(\n            C=C, heads=self.heads, dp=self.dp, dv=self.dv,\n            P=t(w[\"P\"], (n, self.KP)), E=t(w[\"E\"], (n, C)), X=t(w[\"X\"], (n, C)),\n            X2=t(w[\"X2\"], (n // 4, C)),\n            Q=[t(w[\"Q\"] + 4 * h * n * self.dp, (n, self.dp)) for h in range(self.heads)],\n            O=t(w[\"O\"], (n, C)), vis=t(w[\"vis\"], (self.out_rows, self.vs.out)),\n            kv=VitKV(self.kvh, n, self.dp, self.cfg.D, 1, 0, dv=self.dv),\n            emb=SimpleNamespace(wp=self._mat(\"emb\", None, self.emat),\n                                bp=self._v(0, self.emb[\"bp\"], C)),\n            post=(self._v(0, self.post[0], C), self._v(0, self.post[1], C)))\n\n    # ---- contents\n    def _matrix(self, W, key) -> np.ndarray:\n        \"\"\"The float matrix of piece key `key` (pieces()), padded as laid out, from the\n        checkpoint's tensors W (load_vision's, or a mapping that reads each when asked).\"\"\"\n        vs, C = self.vs, self.C\n        f32 = np.float32\n\n        def pad(a, shape):\n            a = np.asarray(a, f32)\n            out = np.zeros(shape, f32)\n            out[tuple(slice(0, n) for n in a.shape)] = a\n            return out\n        if key[0] == \"l\":\n            _, li, n = key\n            p = f\"{TOWER}vit_merger.\" if li == vs.layers else f\"{TOWER}encoder.layers.{li}.\"\n            if n in (\"wq\", \"wk\", \"wv\"):\n                return W[p + f\"self_attn.{n[1]}_proj.weight\"]\n            if n == \"wo\":\n                return W[p + \"self_attn.out_proj.weight\"]\n            shape = (self.F, C) if n == \"w1\" else (C, self.F)\n            if li == vs.layers:         # (the window merger's block has no MLP: zeros)\n                return np.zeros(shape, f32)\n            return pad(W[p + (\"mlp.fc1.weight\" if n == \"w1\" else \"mlp.fc2.weight\")], shape)\n        if key[0] == \"m\":\n            _, m, n = key\n            p, F = (TOWER + \"vit_merger.\", self.FW) if m == \"wm\" else (MERGER + \"mlp.0.\", 4 * C)\n            if n == \"w1\":\n                return pad(W[p + \"linear_1.weight\"], (F, 4 * C))\n            return pad(W[p + \"linear_2.weight\"], (self.mmats[m][\"w2\"].n, F))\n        wp = np.asarray(W[TOWER + \"embeddings.patch_embedding.weight\"], f32).reshape(C, -1)\n        return pad(wp, (C, self.KP))\n\n    def _vectors(self, W: dict) -> list:\n        \"\"\"The vectors (address, values): the checkpoint's tensors (load_vision's), each\n        LayerNorm's bias folded into the next linear's bias (float64).\"\"\"\n        vs = self.vs\n\n        def pad(a, n):\n            out = np.zeros(n, np.float32)\n            out[:len(a)] = a\n            return out\n\n        def folded(p, ln):      # the linear's bias with the LayerNorm's before it folded in\n            return W[p + \".bias\"] + W[p + \".weight\"].astype(np.float64) @ W[ln + \".bias\"]\n        vecs = []\n        o = self.lofs\n        for li in range(vs.layers + 1):\n            base = self.layer0 + li * self.lstride\n            merger = li == vs.layers\n            p = f\"{TOWER}vit_merger.\" if merger else f\"{TOWER}encoder.layers.{li}.\"\n            for n in \"qkv\":\n                vecs.append((base + o[\"b\" + n],\n                             folded(p + f\"self_attn.{n}_proj\", p + \"layer_norm1\")))\n            vecs += [(base + o[\"bo\"], W[p + \"self_attn.out_proj.bias\"]),\n                     (base + o[\"ln1w\"], W[p + \"layer_norm1.weight\"])]\n            if merger:\n                continue\n            vecs += [(base + o[\"ln2w\"], W[p + \"layer_norm2.weight\"]),\n                     (base + o[\"b1\"], pad(folded(p + \"mlp.fc1\", p + \"layer_norm2\"), self.F)),\n                     (base + o[\"b2\"], W[p + \"mlp.fc2.bias\"])]\n        for m, p, F in ((\"wm\", TOWER + \"vit_merger.\", self.FW),\n                        (\"proj\", MERGER + \"mlp.0.\", 4 * self.C)):\n            d = getattr(self, m)\n            vecs += [(d[\"pre_w\"], W[p + \"pre_norm.weight\"]), (d[\"pre_b\"], W[p + \"pre_norm.bias\"]),\n                     (d[\"b1\"], pad(W[p + \"linear_1.bias\"], F)),\n                     (d[\"b2\"], W[p + \"linear_2.bias\"])]\n        vecs += [(self.post[0], W[TOWER + \"post_layernorm.weight\"]),\n                 (self.post[1], W[TOWER + \"post_layernorm.bias\"]),\n                 (self.emb[\"bp\"], W[TOWER + \"embeddings.patch_embedding.bias\"])]\n        return vecs\n\n    def used(self) -> list:\n        \"\"\"The pieces (pieces() indices) the programs read: all but the window merger's block's\n        MLP (its attention block has the layers' layout; vit_out_mlp runs it without the MLP).\"\"\"\n        return [i for i, (key, _, _) in enumerate(self.pieces())\n                if not (key[0] == \"l\" and key[1] == self.vs.layers and key[2] in (\"w1\", \"w2\"))]\n\n    def piece_sizes(self) -> list:\n        \"\"\"Each piece's bytes (pieces() order).\"\"\"\n        return [lay.piece_bytes(i) for _, lay, i in self.pieces()]\n\n    def piece(self, W, i: int) -> np.ndarray:\n        \"\"\"Piece i's bytes (uint8, pieces() order): its matrix quantized (the last one's kept\n        for the next piece of it).\"\"\"\n        from ..kernels import pieces as PC\n        key, lay, pi = self.pieces()[i]\n        c = getattr(self, \"_packed\", None)\n        if c is None or c[0] != key:\n            q, s = Q.quantize_mxu(np.asarray(self._matrix(W, key), np.float32), lay.fmt,\n                                  self.cfg.D)\n            c = self._packed = (key, PC.pack(lay, q, s))\n        return c[1][pi]\n\n    def piece_bytes(self, W: dict) -> list:\n        \"\"\"Every piece's bytes in pieces() order (uint8, each its Layout's piece_bytes): the\n        pool's vision entries, or the resident pieces.\"\"\"\n        out = [self.piece(W, i) for i in range(self.npieces)]\n        self._packed = None\n        return out\n\n    def build(self, W: dict, put) -> None:\n        \"\"\"Write the vectors and (resident) the pieces and their table (W: load_vision's\n        tensors) with put(addr, array); keep the position table for the host's rows\n        (host_rows).\"\"\"\n        for addr, v in self._vectors(W):\n            put(addr, np.asarray(v, np.float32))\n        if self.resident:\n            for a, p in zip(self.resident_addresses(), self.piece_bytes(W)):\n                put(int(a), p)\n            put(self.table, self.resident_addresses())\n        self.tables[\"pos\"] = np.asarray(W[TOWER + \"embeddings.position_embedding.weight\"],\n                                        np.float32)\n\n    # ---- the runs\n    def programs(self, N: int, block: int = 256, R: int | None = None,\n                 proj_gelu=None) -> tuple:\n        \"\"\"One crop of N patches (h x w, both multiples of 4, its rows in card_order): ({phase:\n        (program, run_args)}, the runs in order [(phase, run argument values)]): a program per\n        phase and patch count (not grid: the order makes the merges' windows consecutive), the\n        encoder layers' at a run-time layer index (\"layer\"), the projector's at a run-time\n        output row (\"vis_row\").\"\"\"\n        from ..compiler import Affine, RunVar, Tensor\n        from ..kernels import vit as VK\n        from ..kernels.lib import gelu_tanh\n        vs, cfg = self.vs, self.cfg\n        R = R or min(16, cfg.act_rows)\n        RM = max(1, R // 2)          # the merges' windows a group: their [R, chunk] MLP tiles\n        G = min(16, cfg.act_rows) // 4 * 4  # the window attention's rows an MM (G / 4 windows)\n        N2 = N // 4\n        if N > self.nmax:\n            raise ValueError(f\"a crop of {N} patches: the image's work area holds {self.nmax}\")\n        if N % 16:\n            raise ValueError(f\"a crop of {N} patches: h and w multiples of 4 (two merges)\")\n        eps, sc = vs.eps, 1.0 / math.log(2.0) / math.sqrt(vs.head_dim)\n        v = self.descriptors()\n        lw = self.layer(RunVar(\"layer\", bound=vs.layers))\n        mlw = self.layer(vs.layers)\n\n        def tr(kernel, **kw):\n            b = kernel.trace(cfg, 0, {\"v\": v, **kw})\n            return b.finish(), list(b.run_args)\n        row = RunVar(\"vis_row\", bound=self.out_rows)\n        vis = Tensor(Affine.of(v.vis.base) + row * (4 * vs.out), v.vis.shape, v.vis.strides)\n        P = {\"embed\": tr(VK.vit_embed, N=N, R=R),\n             \"qkv\": tr(VK.vit_qkv, lw=lw, src=v.X, N=N, R=R, eps=eps),\n             \"attend\": tr(VK.vit_attend, N=N, scale=sc, block=block),\n             \"out\": tr(VK.vit_out_mlp, lw=lw, dst=v.X, N=N, R=R, eps=eps, chunk=self.CHUNK),\n             \"mqkv\": tr(VK.vit_qkv, lw=mlw, src=v.X, N=N, R=R, eps=eps),\n             \"wattend\": tr(VK.vit_window_attend, N=N, G=G, scale=sc),\n             \"mout\": tr(VK.vit_out_mlp, lw=mlw, dst=v.X, N=N, R=R, eps=eps, chunk=self.CHUNK,\n                        mlp=False),\n             \"wmerge\": tr(VK.vit_merge, mw=self.merge_weights(\"wm\"), src=v.X, dst=v.X2,\n                          N4=N2, R=RM, eps=eps, chunk=self.WCHUNK, mean=True, part=self.part),\n             \"qkv2\": tr(VK.vit_qkv, lw=lw, src=v.X2, N=N2, R=R, eps=eps),\n             \"attend2\": tr(VK.vit_attend, N=N2, scale=sc, block=block),\n             \"out2\": tr(VK.vit_out_mlp, lw=lw, dst=v.X2, N=N2, R=R, eps=eps, chunk=self.CHUNK),\n             \"last\": tr(VK.vit_out_mlp, lw=lw, dst=v.X2, N=N2, R=R, eps=eps, chunk=self.CHUNK,\n                        post=v.post),\n             \"proj\": tr(VK.vit_merge, mw=self.merge_weights(\"proj\"), src=v.X2, dst=vis,\n                        N4=N2 // 4, R=RM, eps=eps, chunk=self.CHUNK, mean=False,\n                        part=self.part, act=proj_gelu or gelu_tanh)}\n        runs = [(\"embed\", {})]\n        for i in range(vs.insert + 1):\n            runs += [(\"qkv\", {\"layer\": i}), (\"attend\", {}), (\"out\", {\"layer\": i})]\n        runs += [(\"mqkv\", {}), (\"wattend\", {}), (\"mout\", {}), (\"wmerge\", {})]\n        for i in range(vs.insert + 1, vs.layers):\n            runs += [(\"qkv2\", {\"layer\": i}), (\"attend2\", {}),\n                     (\"last\" if i == vs.layers - 1 else \"out2\", {\"layer\": i})]\n        runs.append((\"proj\", {\"vis_row\": 0}))\n        return P, runs\n\n    def host_rows(self, P: np.ndarray, size) -> tuple:\n        \"\"\"The host's rows of a crop (P raster order): its patch rows padded to KP columns, and\n        its position rows (the position table's rows at its NaViT ids: a table lookup, no\n        arithmetic), both in card_order.\"\"\"\n        h, w = size\n        o = card_order(h, w)\n        p = np.zeros((h * w, self.KP), np.float32)\n        p[:, :P.shape[1]] = P[o]\n        return p, self.tables[\"pos\"][position_ids(h, w, self.vs.side)[o]]\n\n    def encode(self, backend, P: np.ndarray, size, vis_row: int = 0, proj_gelu=None,\n               cache: dict | None = None, s: int = 0) -> np.ndarray:\n        \"\"\"One crop through the tower and projector on `backend` (a qwen3 backend: write, run\n        or start / wait, read; one that runs words gets each program assembled once); its\n        rows go to vis[vis_row:]; returns them ([h w / 16, out] fp32). cache: the programs by\n        patch count (and the projector's GELU).\"\"\"\n        from ..compiler import Words, arg_words\n        from .. import isa as I\n        h, w = size\n        key = (h * w, proj_gelu)\n        progs = None if cache is None else cache.get(key)\n        if progs is None:\n            P_, runs = self.programs(h * w, proj_gelu=proj_gelu)\n            if getattr(backend, \"runs_words\", False):\n                P_ = {k: (Words.of(I.assemble(p), ra), ra) for k, (p, ra) in P_.items()}\n            else:\n                P_ = {k: ([p], ra) for k, (p, ra) in P_.items()}\n            progs = (P_, runs)\n            if cache is not None:\n                cache[key] = progs\n        P_, runs = progs\n        p, e = self.host_rows(P, size)\n        backend.write(s, self.work[\"P\"], p)\n        backend.write(s, self.work[\"E\"], e)\n        start = getattr(backend, \"start\", None)\n        for name, vals in runs:\n            prog, ra = P_[name]\n            if \"vis_row\" in vals:\n                vals = {\"vis_row\": vis_row}\n            if start is None:\n                backend.run(prog, args=arg_words(ra, vals))\n            else:\n                start(prog, args=arg_words(ra, vals))\n                backend.wait()\n        n = h * w // 16\n        return backend.read(s, self.work[\"vis\"] + 4 * vis_row * self.vs.out,\n                            4 * n * self.vs.out).view(np.float32).reshape(n, self.vs.out)\n\n\n# =============================================================================== the model's image\nfrom . import qwen35 as QW              # noqa: E402  (qwen35 does not import this module)\nfrom .. import language as ol           # noqa: E402\n# the family's module-level names, which tools and tiled.py look up by the image's module\nfrom .qwen35 import ATTN_BLOCK, RUN_ROWS, emulated_logits, reference_logits  # noqa: E402\nFAMILY = (ATTN_BLOCK, RUN_ROWS, emulated_logits, reference_logits)\n\n\n@dataclass(frozen=True)\nclass Spec(QW.Spec):\n    \"\"\"MiniCPM-V 4.7: its language model qwen35's Spec (Qwen3.5-MoE), its vision side\n    `vision` (VisionSpec) in the model's image before the expert slots (Image): the tower's\n    weights in `vision_fmt` (VisionImage.formats), a crop's work area of `vision_patches`\n    patches, `vision_rows` rows of image tokens (the projector's output rows a prompt's\n    images take, docs/minicpmv.md 4.3). `vision_staged` (a MoE's; the default since session\n    mcpv2, docs/minicpmv.md 6: decode +8.4%, an image +0.3-0.9 s): the tower's weights are the\n    expert pool's entries past the experts, placed in expert slots for an image's runs (the\n    expert server's place) instead of resident (docs/minicpmv.md 4.2).\"\"\"\n    vision: VisionSpec | None = VisionSpec()   # None: the language model alone\n    vision_fmt: str = \"int8\"\n    vision_patches: int = 2048\n    vision_rows: int = 2048\n    vision_staged: bool = True\n\n    @staticmethod\n    def from_hf(model_dir) -> \"Spec\":\n        from dataclasses import fields\n        base = QW.Spec.from_hf(model_dir)\n        return Spec(**{f.name: getattr(base, f.name) for f in fields(QW.Spec)},\n                    vision=VisionSpec.from_hf(model_dir))\n\n    def image(self, cfg, cap: int, batch: int = 1, rows: int = 1, wformat: str = \"int8\",\n              head_format: str | None = None, lookup: bool | str = False,\n              experts: int | None = None, embed_host: bool | None = None,\n              formats: str | None = None, prefill_rows: int | None = None) -> \"Image\":\n        return Image(self, cfg, cap, batch, rows, wformat, head_format, lookup, experts,\n                     embed_host, formats, prefill_rows)\n\n\nclass Image(QW.Image):\n    \"\"\"qwen35's image with MiniCPM-V's vision side (`vision`: a VisionImage, its weights and a\n    crop's work area) after the model's DRAM and before the expert slots; its `vis` rows are\n    the prompt's image rows, which vis_copy_run puts in a prefill chunk's residual rows\n    (layer 0's input, qwen35_layer_run embedded). The text path's programs are qwen35's: a\n    text-only prompt runs exactly qwen35-35b's.\"\"\"\n\n    def __init__(self, *a, **kw):\n        super().__init__(*a, **kw)\n        v = self.vision\n        if v is not None and not v.resident:        # staged: the pieces in expert slots\n            L = self.offload\n            if L is None:\n                raise ValueError(\"staged vision weights need the expert slots (a MoE model)\")\n            if max(v.piece_sizes()) > L.slot_bytes:\n                raise ValueError(f\"vision pieces of up to {max(v.piece_sizes())} bytes, slots \"\n                                 f\"of {L.slot_bytes}\")\n            v.set_bound(*L.slot_bounds)\n\n    def check_room(self) -> None:\n        \"\"\"Staged vision's pieces against the expert slots past k a layer (ExpertServer.place's\n        room): a ValueError when they do not fit. An engine's image is checked (streamed.engine\n        after it opens, Vision); not every image: streamed.probe's has k slots a layer, the\n        layout alone (session mcpv3's first run, 2026-10-13: the check in __init__ refused the\n        probe, 438 pieces against 0 slots, before the engine's 36 a layer).\"\"\"\n        v, L = self.vision, self.offload\n        if v is None or v.resident:\n            return\n        free = sum(max(0, n - L.k) for _, n in L.slots)\n        if len(v.used()) > free:\n            raise ValueError(f\"staged vision: {len(v.used())} pieces, {free} expert slots past \"\n                             f\"k = {L.k} a layer (more slots, or vision_staged False)\")\n\n    def before_slots(self, b) -> None:\n        sp = self.spec\n        mp = None                       # staged: pieces of at most an expert slot's bytes\n        staged = sp.vision is not None and sp.vision_staged and sp.moe is not None\n        if staged:\n            from . import moe as MO\n            mp = min(VisionImage.MAX_PIECE,\n                     MO.ExpertFormat(sp.hidden, sp.moe.ffn, self.cfg.D, self.wformat).nbytes)\n        self.vision = None if sp.vision is None else \\\n            VisionImage(sp.vision, self.cfg, b, nmax=sp.vision_patches, out_rows=sp.vision_rows,\n                        fmt=sp.vision_fmt, resident=not staged, max_piece=mp)\n        if self.vision is not None:     # (an attribute of the image's own: the image cache keeps\n            self.vis_tables = self.vision.tables    # its entries, opentpu/imgcache.py)\n\n    @property\n    def pool_extra(self):\n        \"\"\"Staged vision: (the pool's entries past the experts, their key: moe.pool_key's\n        \"vision\"), else None. Entry layers x E + i is piece i (VisionImage.pieces()).\"\"\"\n        v = self.vision\n        if v is None or v.resident:\n            return None\n        h = hashlib.blake2b(digest_size=16)\n        h.update(json.dumps([v.fmts, v.max_piece, v.piece_sizes(),\n                             [[list(k), lay.n, lay.k, i] for k, lay, i in v.pieces()]]).encode())\n        return v.npieces, {\"entries\": v.npieces, \"format\": self.spec.vision_fmt,\n                           \"pieces\": h.hexdigest()}\n\n    def expert(self, W, g: int) -> np.ndarray:\n        \"\"\"Global expert g in its slot's bytes; past the experts (staged vision), piece\n        g - layers x E zero-padded to a slot (the vision tensors read as asked for).\"\"\"\n        L = self.offload\n        G = L.layers * L.E\n        if g < G:\n            return super().expert(W, g)\n        if getattr(self, \"_vis_w\", None) is None:\n            self._vis_w = VisionWeights(W.model_dir) if hasattr(W, \"model_dir\") else W\n        out = np.zeros(L.slot_bytes, np.uint8)\n        p = self.vision.piece(self._vis_w, g - G)\n        out[:p.size] = p\n        return out\n\n    def build(self, W: dict) -> list:\n        \"\"\"qwen35's DRAM image, then the vision side's weights: load_vision's tensors of the\n        checkpoint W reads (LazyWeights' model_dir), or W's own under their names.\"\"\"\n        imgs = super().build(W)\n        if self.vision is None:\n            return imgs\n        Wv = (load_vision(W.model_dir) if self.vision.resident else\n              VisionWeights(W.model_dir)) if hasattr(W, \"model_dir\") else W\n\n        def put(addr, a):\n            v = np.ascontiguousarray(a).view(np.uint8).reshape(-1)\n            imgs[0][addr:addr + v.size] = v\n        self.vision.build(Wv, put)\n        return imgs\n\n    def descriptors(self, sid: int, slot: int = 0):\n        m = super().descriptors(sid, slot)\n        if self.vision is not None:\n            m.vis = self.vision.descriptors().vis\n        return m\n\n    def compile_vis_run(self, n: int, em: bool = False):\n        \"\"\"(programs, run_args): vis_copy_run of n rows, the chunk's row (\"row\") and the vis\n        row (\"src\") run arguments.\"\"\"\n        from ..compiler import RunVar\n        b = vis_copy_run.trace(self.cfg, 0, {\"m\": self.descriptors(0), \"n\": n,\n                                             \"row\": RunVar(\"row\", self.prefill_rows),\n                                             \"src\": RunVar(\"src\", self.spec.vision_rows),\n                                             \"em\": em})\n        return [b.finish()], list(b.run_args)\n\n    def rope_table(self) -> tuple:\n        \"\"\"The image's RoPE tables as the host built them (qwen3.rope_tables at slots 0 .. cap\n        - 1): cos, sin [cap, rope_dim / 2].\"\"\"\n        if not hasattr(self, \"_rope\"):\n            from .qwen3 import rope_tables\n            cs = [rope_tables(self.spec, p) for p in range(self.cap)]\n            self._rope = (np.stack([c for c, _ in cs]), np.stack([x for _, x in cs]))\n        return self._rope\n\n\n@ol.jit\ndef vis_copy_run(m, n: int, row, src, em: bool = False):\n    \"\"\"n image rows of a layer-major prefill chunk: the projector's rows m.vis[src:src + n] ->\n    the chunk's residual rows m.xbuf[row:row + n] (em: their records' X, moe.em_x), layer 0's\n    input (qwen35_layer_run with embedded): a DMA through TMEM, no arithmetic.\"\"\"\n    from . import moe as MO\n    X = MO.em_x(m.moe_dev, row, n, m.spec.hidden) if em else m.xbuf[row:row + n, :]\n    ol.store(X, ol.load(m.vis[src:src + n, :]))\n\n\ndef mrope_rows(table: tuple, pos: np.ndarray) -> tuple:\n    \"\"\"The RoPE rows of positions pos [3, n] (t, h, w; rope_index's) from the image's tables\n    (Image.rope_table): Qwen3.5's interleaved M-RoPE (mrope_section [11, 11, 10]) takes\n    frequency i from h's position where i % 3 == 1, w's where i % 3 == 2, t's else, so each\n    entry is the table's entry of that position and frequency: a gather, no arithmetic. A text\n    position (t = h = w) gives the table's row itself, bit for bit.\"\"\"\n    cos, sin = table\n    half = cos.shape[1]\n    sec = np.arange(half) % 3\n    rows = np.asarray(pos)[sec]                     # [half, n]: each frequency's position\n    if rows.min() < 0 or rows.max() >= len(cos):\n        raise ValueError(f\"M-RoPE positions {rows.min()} .. {rows.max()} outside the table \"\n                         f\"({len(cos)})\")\n    cols = np.arange(half)[:, None]\n    return np.ascontiguousarray(cos[rows, cols].T), np.ascontiguousarray(sin[rows, cols].T)\n\n\n# =============================================================================== the host's images\nclass Vision:\n    \"\"\"MiniCPM-V's images on an Engine whose image is a minicpmv.Image (docs/minicpmv.md 4.3):\n    each image's crops through the card's tower and projector into the image's vis rows\n    (encode), each prompt token's vis row (rows), and the RoPE table's rows at every slot's\n    M-RoPE positions (positions). The host only moves data: the patch rows it cut, the vis\n    rows the card computed (by their index), the table entries the image was built with.\"\"\"\n\n    def __init__(self, eng):\n        img = eng.image\n        if getattr(img, \"vision\", None) is None:\n            raise ValueError(\"the engine's image has no vision side (minicpmv.Spec.vision)\")\n        img.check_room()\n        self.eng, self.img, self.vs = eng, img, eng.spec.vision\n        self.table = img.rope_table()\n        self.cache = {}                     # VisionImage's programs by patch count\n        self.dev = np.tile(np.arange(img.cap), (3, 1))  # the device table's positions, a slot\n        self.seconds = 0.0                  # the encodes' wall time\n\n    def encode(self, images: list, row: int = 0) -> int:\n        \"\"\"Each ImageInput's crops in order (thumbnail, slices) into vis rows from `row`: their\n        rows follow one another as the prompt's image tokens do. Returns the rows.\"\"\"\n        import time\n        t, r = time.time(), row\n        n = sum(im.tokens for im in images)\n        v = self.img.vision\n        if row + n > v.out_rows:\n            raise ValueError(f\"{n} image rows from {row}: the image holds \"\n                             f\"{v.out_rows} (Spec.vision_rows)\")\n        if not images:\n            return 0\n        if not v.resident:\n            self.stage()\n        try:\n            for im in images:\n                for P, size in zip(im.patches, im.sizes):\n                    v.encode(self.eng.backend, P, size, vis_row=r, cache=self.cache)\n                    r += size[0] * size[1] // 16\n        finally:\n            if not v.resident:\n                self.eng.server.release()\n        self.seconds += time.time() - t\n        return r - row\n\n    def stage(self) -> None:\n        \"\"\"Staged weights (Spec.vision_staged): the pieces the programs read placed in expert\n        slots by the expert server (the pool's entries layers x E + i, place), and their table\n        written: the address of each (the first's for a piece the programs never read).\"\"\"\n        v, srv = self.img.vision, self.eng.server\n        G = srv.L.layers * srv.L.E\n        used, sizes = v.used(), v.piece_sizes()\n        at = srv.place([G + i for i in used], {G + i: sizes[i] for i in used})\n        table = np.full(v.npieces, at[0], np.uint32)\n        table[used] = at\n        self.eng.backend.write(0, v.table, table)\n\n    def prompt(self, ids, images: list, n: int = 0) -> list | None:\n        \"\"\"A prompt's image side (ids: the whole sequence's token ids, its images in order):\n        the RoPE table's rows at its positions (positions), the images with tokens in ids[n:]\n        (what is fed) through the tower into vis rows from 0 (an image that started before n\n        whole), and each of ids[n:]'s vis row (-1: text): prefill_layers' vis. Without images\n        the table's own rows (pristine) and None.\"\"\"\n        if not images:\n            self.pristine()\n            return None\n        self.positions(ids, [s for im in images for s in im.sizes])\n        at, j, k = [], 0, 0                 # each image token's (image, its k-th row)\n        for t in ids:\n            if int(t) == self.vs.image_token:\n                if k == images[j].tokens:\n                    j, k = j + 1, 0\n                at.append((j, k))\n                k += 1\n            else:\n                at.append(None)\n        new = sorted({a[0] for a in at[n:] if a is not None})\n        base, row = {}, 0\n        for j in new:\n            base[j], row = row, row + images[j].tokens\n        self.encode([images[j] for j in new])\n        return [-1 if a is None else base[a[0]] + a[1] for a in at[n:]]\n\n    def rows(self, ids, row: int = 0) -> list:\n        \"\"\"Each token's vis row (prefill_layers' vis): the image tokens' in order from `row`,\n        -1 for the others.\"\"\"\n        out, r = [], row\n        for t in ids:\n            if int(t) == self.vs.image_token:\n                out.append(r)\n                r += 1\n            else:\n                out.append(-1)\n        return out\n\n    def positions(self, ids, sizes) -> int:\n        \"\"\"The RoPE table's rows for a sequence (every token since slot 0, every crop's (h, w)\n        in order): slot s < T at rope_index's position, s >= T at s + delta (the decode's).\n        Writes the rows that differ from what the table holds (none for text after text: the\n        image's own rows); returns delta.\"\"\"\n        pos, delta = rope_index(ids, sizes, self.vs)\n        cap = self.img.cap\n        T = pos.shape[1]\n        if T > cap:\n            raise ValueError(f\"{T} tokens: the cache holds {cap}\")\n        self._write(np.concatenate([pos, np.tile(np.arange(T, cap) + delta, (3, 1))], axis=1))\n        return int(delta)\n\n    def pristine(self) -> None:\n        \"\"\"The table's own rows back at every slot (a text-only sequence: a chat's reset).\"\"\"\n        self._write(np.tile(np.arange(self.img.cap), (3, 1)))\n\n    def _write(self, want: np.ndarray) -> None:\n        cap = self.img.cap\n        diff = (want != self.dev).any(0)\n        lk = self.img.lookup\n        half = lk[\"half\"]\n        i = 0\n        while i < cap:\n            if not diff[i]:\n                i += 1\n                continue\n            j = i\n            while j < cap and diff[j]:\n                j += 1\n            c, s_ = mrope_rows(self.table, want[:, i:j])\n            for sl in range(self.eng.cfg.S):\n                self.eng.backend.write(sl, lk[\"cos_t\"] + 4 * half * i, c)\n                self.eng.backend.write(sl, lk[\"sin_t\"] + 4 * half * i, s_)\n            i = j\n        self.dev = want\n", "opentpu/llm/moe.py": "\"\"\"Mixture-of-experts FFN with its experts streamed into a DRAM cache: path (a) of\ndocs/offload.md. The card routes and computes every expert; opentpu.host.offload's server only\nmoves experts into per-layer LRU slots in the card's DRAM and keeps the directory.\n\nA MoE layer on the device (`moe_ffn`), one token:\n\n1. the router: an MM of the normalized residual -> E logits (and, with a shared expert, its\n   gate's logit as row E of the same matrix), and the model's rule (MoESpec.rule);\n2. the k best by ARGMAX with knock-out (in order, ties to the first), their global ids\n   (the layer's base j * E + index) and weights: LFM2's sigmoid scores, chosen with the\n   expert bias, renormalized and scaled; Qwen's softmax of the k largest logits;\n3. the fence, WAITW served >= seq (the host has finished every earlier request: none of this\n   layer's slots is being replaced, and the one request row and answer are free), then the\n   ids and seq + 1 to the mailbox; then what needs no routed expert, while the host streams\n   the missing ones: a shared expert (a dense SwiGLU of the layer block, times sigmoid of its\n   gate's logit; docs/offload.md 15) and beside()'s work;\n4. the directory: each id's present flag;\n5. the experts present (a LOOP over the k ids, a LOOP R[present] inside), then the others\n   (LOOP R[1 - present]). A present one takes its slot address from its directory entry, a\n   missing one from its word of the request's answer (docs/offload.md 10.11), each by WAITW\n   (!= 0: at once for an expert present; for the others once the host has written the\n   answer) to a TMEM word and RLD (raw) into a register; a missing one then waits for its\n   slot's tag word (WAITW != 0: the host writes it in its expert's DMA's last beat). Each\n   zeroes its slot's tag (the next nonzero tag there is a later expert's), runs\n   kernels.mlp.swiglu_down there and writes its weighted output to its row of a [k, H] tile;\n   then the answer's words are zeroed (the host writes the next request's answer only after\n   its post);\n6. the rows summed in the router's order (the result does not depend on what the cache held),\n   then the shared expert's output added (last, as before it was computed early: bit for bit\n   the same sum), and the whole to the residual.\n\nIt holds one register (the resident decode's run arguments and the layer loops hold the\nrest): the per-expert values are the columns of a small tile that each loop rotates, so\nexpert i is always at column 0 in iteration i.\n\nWith MoESpec.hint the layer also posts a prefetch hint before its mixer (`moe_hint`,\ndocs/offload.md section 12): its router on the layer's input, the k best as a request whose\nids are offset by layers x E; the host replaces their slots' victims at once and moves the\nmissing experts in the link's idle time, and the route's own request finds them landed or on\ntheir way.\n\n`moe_ffn_rows` is the layer on R rows at once (layer-major prefill, docs/offload.md section 13):\neach row routes as moe_ffn's; one request carries the rows' R x k ids (the count at mbox + 4);\nthe card finds their union (each id's first place among them) and runs each union expert once\non all R rows, storing each row's unweighted output to its (row, rank) place in a DRAM scratch\nof [R k + 1, H] (R k <= 16, the request's one line; the last row a sink for the outputs no row\nchose); each row then sums its own k in its router's order, so a row's result is moe_ffn's bit\nfor bit. `moe_hint_rows` is moe_hint on R rows: a layer-major run's hint for the next layer, its\nrouter on the run's output rows (section 13.9).\n\nExpert-major (sections 13.11, 13.13) splits a layer-major MoE layer over a chunk's runs: each\nrun's `moe_prologue_rows` routes its rows, keeps their ids, weights and norm in the rows' records\nof a scratch (em_record; the server carves it from the first expert slots for the prefill), and\nposts the experts as a need line; then one `moe_expert_run` a layer runs each expert its rows\nchose once, in passes of up to C rows (em_pass_rows, docs/offload.md 13.18; ld-memch's\nbucketing), each pass waiting on its directory entry; the next layer's runs end the layer (`moe_combine_rows`). A row's arithmetic is\nmoe_ffn_rows', bit for bit.\n\n`ExpertFormat` is one expert's slot: gate and up [F, H] and W_down's column parts, laid out as a\nlayer block's MLP (lfm2.Image), so the FFN is kernels.mlp.swiglu_down at the slot's address\n(a compiler.DevVar: the register RLD sets). One slice (S = 1, the board's).\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport numpy as np\n\nfrom .. import isa as I\nfrom .. import language as ol\nfrom .. import quant as Q\nfrom ..compiler import Affine, CompileError, DevVar, QTensor, Tensor, current\nfrom ..host.offload import LINE, SPLIT, ExpertServer, Layout, PoolFile, dram_of, to_split\nfrom ..kernels import mailbox as MB\nfrom ..kernels.lib import gelu_tanh, rmsnorm, sigmoid, silu\nfrom ..kernels.mlp import _chunk, swiglu_down\n\nNEG = -3.0e38                       # knocked out (below every score)\nACTS = {\"silu\": silu, \"gelu_tanh\": gelu_tanh}\n\n\n@dataclass(frozen=True)\nclass MoESpec:\n    E: int                 # experts per layer\n    k: int                 # experts per token\n    ffn: int               # an expert's width\n    first: int = 0         # the first MoE layer (the ones before it have a dense MLP)\n    rule: str = \"sigmoid_bias\"       # LFM2: sigmoid scores, the choice on score + expert bias;\n                                     # \"softmax\": Qwen, the k largest logits' softmax\n    norm: bool = True                # renormalize the chosen weights (softmax: always)\n    scale: float = 1.0               # then multiply them by this\n    shared: int = 0                  # a shared expert's width (Qwen: the layer's dense MLP,\n                                     # times sigmoid(x . w_gate)), 0: none\n    act: str = \"silu\"                # the experts' gate: SiLU, or \"gelu_tanh\" (Gemma 4)\n    hint: bool = False               # each layer posts its router's k best on its input as a\n                                     # prefetch hint before its mixer (moe_hint; Qwen3.5)\n\n    def __post_init__(self):\n        if self.rule not in (\"sigmoid_bias\", \"softmax\"):\n            raise ValueError(f\"MoE router rule {self.rule!r}\")\n        if self.act not in ACTS:\n            raise ValueError(f\"MoE expert activation {self.act!r}\")\n        if self.rule == \"softmax\" and not self.norm:\n            raise ValueError(\"a softmax router over all experts is not supported (norm=False)\")\n\n\nclass ExpertFormat:\n    \"\"\"One expert in its slot: W_gate, W_up [F, H] (rows, then their scale rows) and W_down\n    [H, F] in column parts of `C` (swiglu_down's chunks; its rows quantized whole, each part's\n    scale rows the row's Sw and its blocks': quant.column_parts), each D-byte aligned. A width\n    that is not a whole number of the format's chunks (Gemma 4's 704) is padded with zero rows\n    of W_gate and W_up and zero columns of W_down to `F` (768): exact, act(0) * 0 = 0.\"\"\"\n\n    def __init__(self, H: int, F: int, D: int, wformat: str):\n        rb = lambda k: Q.row_bytes(k, wformat, D)                       # noqa: E731\n        q = D if wformat == \"int8\" else 2 * D\n        self.F0, F = F, -(-F // q) * q       # the expert's own width, the slot's\n        self.H, self.F, self.D, self.wformat = H, F, D, wformat\n        self.C = _chunk(F, D, q)\n        a, align = 0, max(LINE, D)          # the MXU streams whole D-byte chunks\n\n        def take(n):\n            nonlocal a\n            at, a = a, a + -(-n // align) * align\n            return at\n        sb = lambda k: Q.scale_bytes(k, wformat, D)                     # noqa: E731\n        self.wg = (take(F * rb(H)), take(F * sb(H)))\n        self.wu = (take(F * rb(H)), take(F * sb(H)))\n        self.wd = [(take(H * rb(self.C)), take(H * sb(self.C))) for _ in range(F // self.C)]\n        self.nbytes = a\n\n    def ranges(self) -> list[int]:\n        \"\"\"The down projection's QACT ranges over the expert's own width F0, for an emulation\n        of the unpadded expert: a chunk of C each, the last cut at F0 (the slot's zero columns\n        change no range's amax).\"\"\"\n        return [min(self.C, self.F0 - c) for c in range(0, self.F0, self.C)]\n\n    def pack(self, wg: np.ndarray, wu: np.ndarray, wd: np.ndarray) -> np.ndarray:\n        \"\"\"The slot's bytes for W_gate, W_up [F0, H] and W_down [H, F0] (float).\"\"\"\n        out = np.zeros(self.nbytes, np.uint8)\n        if self.F != self.F0:                   # the zero padding\n            pad = self.F - self.F0\n            wg, wu = (np.pad(np.asarray(w, np.float32), ((0, pad), (0, 0))) for w in (wg, wu))\n            wd = np.pad(np.asarray(wd, np.float32), ((0, 0), (0, pad)))\n\n        def put(pair, qs):\n            for at, v in zip(pair, qs):\n                v = np.ascontiguousarray(v).view(np.uint8).reshape(-1)\n                out[at:at + v.size] = v\n        fm, D = self.wformat, self.D\n        put(self.wg, Q.quantize_mxu(wg, fm, D))\n        put(self.wu, Q.quantize_mxu(wu, fm, D))\n        # W_down's rows quantized whole (one Sw a row), stored in column parts of C\n        q, s = Q.quantize_mxu(np.asarray(wd, np.float32), fm, D)\n        for pair, qs in zip(self.wd, Q.column_parts(q, s, fm, self.F, self.C, D)):\n            put(pair, qs)\n        return out\n\n    def descs(self, base) -> SimpleNamespace:\n        \"\"\"wg, wu, wd QTensors of the expert whose slot starts at `base` (an address\n        expression: a DevVar for a slot found at run time).\"\"\"\n        H, F, D, C, fm = self.H, self.F, self.D, self.C, self.wformat\n        base = Affine.of(base)\n\n        def q(pair, n, k):\n            return QTensor.weight(base + pair[0], base + pair[1], n, k, fm, D)\n        parts = tuple(q(p, H, C) for p in self.wd)\n        wd = QTensor(parts[0].data, parts[0].scale, (H, F), parts[0].rs, parts[0].srs, D,\n                     parts=parts, pw=C, wf=parts[0].wf)\n        return SimpleNamespace(wg=q(self.wg, F, H), wu=q(self.wu, F, H), wd=wd)\n\n\ndef gemma_expert(W, p: str, e: int):\n    \"\"\"Gemma 4's routed expert e of the layer at prefix p (`p + \"experts.gate_up_proj\"` [E, 2F,\n    H], gate rows first; `p + \"experts.down_proj\"` [E, H, F]) as W_gate, W_up [F, H] and W_down\n    [H, F] for ExpertFormat.pack, router.per_expert_scale[e] folded into W_down (it multiplies\n    the expert's output). pre_feedforward_layernorm_2's gain stays out: moe_ffn applies it to\n    the experts' input before quantizing it (lw.g_exp; docs/offload.md 11.2). A lazy W with\n    `part` reads the one expert.\"\"\"\n    k = p + \"experts.\"\n    get = getattr(W, \"part\", None)\n    gu, dn = ((get(k + \"gate_up_proj\", e), get(k + \"down_proj\", e)) if get is not None else\n              (W[k + \"gate_up_proj\"][e], W[k + \"down_proj\"][e]))\n    gu, dn = np.asarray(gu, np.float32), np.asarray(dn, np.float32)\n    F = gu.shape[0] // 2\n    s = np.asarray(W[p + \"router.per_expert_scale\"], np.float32)[e]\n    return gu[:F], gu[F:], dn * s\n\n\ndef gemma_router(W, p: str) -> np.ndarray:\n    \"\"\"Gemma 4's router [E, H] on the residual's unit RMSNorm (moe_ffn's input): router.proj\n    with router.scale and H^-0.5 folded into its columns.\"\"\"\n    w = np.asarray(W[p + \"router.proj.weight\"], np.float32)\n    return w * (np.asarray(W[p + \"router.scale\"], np.float32) * np.float32(w.shape[1] ** -0.5))\n\n\n# ---------------------------------------------------------------------------- the pool's key\ndef quant_source(wformat: str) -> str:\n    \"\"\"The quantizer's code an expert's bytes depend on: quant.py and fp32.py (int8x's\n    quantize_mx, the 4-bit formats' scale arithmetic). Not numpy's version (qcache._source's):\n    a pool is packed on one host and read on another.\"\"\"\n    from .. import fp32 as F\n    h = hashlib.blake2b(digest_size=16)\n    for f in (Q.__file__, F.__file__):\n        h.update(Path(f).read_bytes())\n    return h.hexdigest()\n\n\ndef checkpoint_id(model_dir) -> str | None:\n    \"\"\"A checkpoint's identity: its config.json's hash (strip_experts.py copies the file as it\n    is, so the card host's checkpoint without the experts has the packing host's); None\n    without one.\"\"\"\n    f = Path(model_dir) / \"config.json\" if model_dir is not None else None\n    if f is None or not f.exists():\n        return None\n    return hashlib.blake2b(f.read_bytes(), digest_size=16).hexdigest()\n\n\ndef pool_key(image, model_dir=None, mtp_from=None) -> dict:\n    \"\"\"The key of `image`'s expert pool (`<pool>.key`, JSON): what decides its experts' bytes,\n    the MXU's numerics (quant.MX_NUMERICS: key 2 and on; a key 1 pool holds the scale words of\n    the MXU before MX, docs/mx_mxu.md), the quantizer's code (quant_source), the format, D, the\n    layout (the pool's and the slot's: ExpertFormat's parts) and the checkpoint\n    (checkpoint_id); \"numpy\" and \"model\" are notes, not compared. mtp_from: the checkpoint an\n    MTP image's MTP layer (its experts the pool's last layer) comes from when not the model's\n    (LazyWeights.mtp_from: MiniCPM-V 4.7's, docs/offload.md 15.6), its checkpoint_id as\n    \"mtp_from\". An image with entries past the experts (`pool_extra`: (their count, their key),\n    MiniCPM-V's vision pieces staged through the slots, docs/minicpmv.md 4.2) adds \"vision\":\n    their key, which open_pool compares on its own (key_diff does not: the experts' part of a\n    pool is the same).\"\"\"\n    f, L = image.fmt, image.offload\n    key = {\"key\": 2, \"numerics\": Q.MX_NUMERICS, \"quant\": quant_source(f.wformat),\n           \"format\": f.wformat, \"D\": f.D,\n           \"layout\": {\"layers\": L.layers, \"E\": L.E, \"slot_bytes\": L.slot_bytes, \"H\": f.H,\n                      \"F\": f.F0, \"C\": f.C, \"wg\": list(f.wg), \"wu\": list(f.wu),\n                      \"wd\": [list(x) for x in f.wd]},\n           \"checkpoint\": checkpoint_id(model_dir), \"numpy\": np.__version__,\n           \"model\": None if model_dir is None else Path(model_dir).name}\n    if mtp_from is not None:\n        key[\"mtp_from\"] = checkpoint_id(mtp_from)\n    if getattr(image, \"pool_extra\", None) is not None:\n        key[\"vision\"] = image.pool_extra[1]\n    return key\n\n\ndef key_diff(have: dict, want: dict) -> list:\n    \"\"\"The fields in which a pool's key `have` differs from `want` (the checkpoint only when\n    both know it; the MTP layer's checkpoint, mtp_from, whenever either names one).\"\"\"\n    out = [k for k in (\"key\", \"numerics\", \"quant\", \"format\", \"D\", \"layout\")\n           if have.get(k) != want.get(k)]\n    if have.get(\"mtp_from\") != want.get(\"mtp_from\"):\n        out.append(\"mtp_from\")\n    if None not in (have.get(\"checkpoint\"), want.get(\"checkpoint\")) and \\\n            have[\"checkpoint\"] != want[\"checkpoint\"]:\n        out.append(\"checkpoint\")\n    return out\n\n\ndef check_pool_key(pool_file, want: dict) -> None:\n    \"\"\"Refuse an expert pool whose key (`<pool>.key`) is not `want`: its experts were packed by\n    another quantizer, for the MXU before MX, in another format or layout, or from another\n    checkpoint. A pool without a key is refused too: it was packed before keys, so before the\n    MX numerics (its scale words are the former MXU's); pack_pool stamp gives one its key once\n    `sums` shows it holds this tree's bytes.\"\"\"\n    kf = Path(str(pool_file) + \".key\")\n    if not kf.exists():\n        raise ValueError(\n            f\"{pool_file} has no key file: a pool packed before keys, for the MXU before MX \"\n            f\"(docs/mx_mxu.md), whose experts' bytes are not this image's. Repack it: remove \"\n            f\"{pool_file} and its .packed and .format, then python3 tools/offload/pack_pool.py \"\n            f\"MODEL {pool_file} init and its pack workers (or let the run pack the experts it \"\n            f\"asks for); a pool known to hold this tree's bytes (pack_pool.py ... sums) gets \"\n            f\"its key by pack_pool.py MODEL {pool_file} stamp\")\n    have = json.loads(kf.read_text())\n    diff = key_diff(have, want)\n    if diff:\n        note = {k: (have.get(k), want.get(k)) for k in diff if k != \"layout\"}\n        raise ValueError(\n            f\"{pool_file} was packed for another model image ({', '.join(diff)} differ\"\n            f\"{': ' + str(note) if note else ''}; {have.get('format')} D {have.get('D')} of \"\n            f\"{have.get('model')}, this run is {want['format']} D {want['D']} of \"\n            f\"{want.get('model')}): its experts' bytes are not this image's. Repack it: remove \"\n            f\"{pool_file} and its .packed, .format and .key, then python3 \"\n            f\"tools/offload/pack_pool.py MODEL {pool_file} init and its pack workers (or let \"\n            f\"the run pack the experts it asks for)\")\n\n\ndef pool_entries(path: Path, n: int) -> int:\n    \"\"\"The entries a pool file holds by its key: n experts and its \"vision\" key's entries.\"\"\"\n    kf = Path(str(path) + \".key\")\n    have = json.loads(kf.read_text()) if kf.exists() else {}\n    return n + int((have.get(\"vision\") or {}).get(\"entries\", 0))\n\n\ndef open_pool(layout: Layout, pool_file, mapped: bool = True,\n              key: dict | None = None, extra: int = 0) -> PoolFile:\n    \"\"\"The expert pool file for `layout`, opened, and its packed experts' read into the page\n    cache started (PoolFile.warm: the host's RAM tier; the Engine opens it before it builds the\n    image, so the read runs during the build). The file is the whole pool's size (sparse until\n    packed), and `<pool_file>.packed` marks the experts in it (a file of the right size without\n    one is a pool packed whole). A new file is in the split format\n    (opentpu.host.offload.split_order), as `<pool_file>.format` says; a file without it holds\n    the slot format. With `key` (pool_key) a new file gets it as `<pool_file>.key`, and an\n    existing one must have it (check_pool_key; one without a key file is refused).\n    The page cache stays the kernel's to reclaim: nothing is pinned. mapped: PoolFile's (its\n    reads touched through a read-only map: docs/offload.md 10.7).\n\n    extra: entries past the experts (layers x E on; key[\"vision\"] their key: pool_key), each a\n    slot's bytes. A pool whose own extra entries are not these (none, or another key's) keeps\n    its experts and gets these, not packed yet (the file grown or cut past its experts, its\n    key's \"vision\" replaced); a run without extra opens a pool with them as its experts'.\"\"\"\n    L = layout\n    n = L.layers * L.E\n    N = n + extra\n    path = Path(pool_file)\n    done = Path(str(path) + \".packed\")\n    kf = Path(str(path) + \".key\")\n    fresh = not path.exists() or path.stat().st_size != pool_entries(path, n) * L.slot_bytes\n    if not fresh and key is not None:\n        check_pool_key(path, key)\n    want_x = (key or {}).get(\"vision\") if extra else None\n    have_x = json.loads(kf.read_text()).get(\"vision\") if not fresh and kf.exists() else None\n    if fresh:\n        with open(path, \"wb\") as f:\n            f.truncate(N * L.slot_bytes)\n    elif extra and have_x != want_x:    # its extra entries replaced, its experts kept\n        with open(path, \"r+b\") as f:\n            f.truncate(n * L.slot_bytes)\n            f.truncate(N * L.slot_bytes)\n        pk = np.fromfile(done, np.uint8)[:n] if done.exists() else np.ones(n, np.uint8)\n        done.write_bytes(np.concatenate([pk, np.zeros(N - n, np.uint8)]).tobytes())\n        have = json.loads(kf.read_text()) if kf.exists() else dict(key)\n        have[\"vision\"] = want_x\n        kf.write_text(json.dumps(have, indent=1) + \"\\n\")\n    M = pool_entries(path, n) if not fresh else N      # (the file's entries)\n    if fresh or not done.exists() or done.stat().st_size != M:\n        done.write_bytes(bytes(M) if fresh else bytes([1]) * M)\n    fmt = Path(str(path) + \".format\")\n    if fresh:\n        fmt.write_text(SPLIT + \"\\n\")\n        if key is not None:\n            kf.write_text(json.dumps(key, indent=1) + \"\\n\")\n        elif kf.exists():\n            kf.unlink()\n    pf = PoolFile(path, L.slot_bytes, fmt.exists() and fmt.read_text().strip() == SPLIT,\n                  mapped=mapped)\n    pf.arr = np.memmap(path, np.uint8, \"r+\", shape=(N, L.slot_bytes))\n    pf.packed = np.memmap(done, np.uint8, \"r+\", shape=(N,))\n    pf.ids = np.nonzero(np.asarray(pf.packed))[0]\n    pf.resident_at_open = pf.resident(pf.ids)\n    pf.warm(pf.ids)\n    return pf\n\n\ndef rewarm(pf: PoolFile):\n    \"\"\"The pool's experts that left the page cache since the open's read began, read into it\n    again; the Engine calls it once the image is built and the build's memory freed. A 35B\n    MoE image's build peaks at 28-30 GB of the card host's 31 and takes the pool out of the\n    page cache again (docs/minicpmv.md 6, pooldisk: its turns then read their experts from the\n    disk, ~15-32 ms each against 0.5 ms). The open's read is stopped (it may still run: an\n    image from the image cache), then those of the packed experts with bytes out of the page\n    cache (mincore) are read in file order on a new thread. Returns the warm thread now: the\n    open's when it had ended and nothing left the page cache, or where the host cannot tell\n    (no mincore: the open's read is left to run).\"\"\"\n    t = pf.warm_t\n    if pf._pages() is None:                 # (no mincore here; and no map of its own made:\n        return t                            # pool_map False keeps none)\n    stopped = t is not None and t.is_alive()\n    if stopped:\n        t.stop.set()\n        t.join()\n    gone = pf.absent(pf.ids)\n    if gone is None and stopped:            # (mincore failed: all of them again)\n        gone = pf.ids\n    # (a stopped read with nothing left out: an empty one, so the record says done)\n    return t if gone is None or not (len(gone) or stopped) else pf.warm(gone)\n\n\ndef serve(layout: Layout, expert, backend, pool_file=None, warm=True,\n          policy: str = \"lfu\") -> ExpertServer:\n    \"\"\"The host's expert server on the backend's DRAM (slice 0); with `warm`, the slots filled\n    with each layer's first experts. expert(g): global expert g's slot bytes. An expert is\n    packed when it is first asked for and kept in host RAM, or, with `pool_file` (a path, or\n    open_pool's PoolFile), in that file (the page cache, or the SSD tier), which keeps it for\n    later runs (`server.pool`: the PoolFile). `policy`: the slots' replacement (ExpertServer's;\n    least decayed use, docs/offload.md 5.5).\"\"\"\n    L = layout\n    pf = None\n    if pool_file is None:\n        cache: dict = {}\n\n        def pool(g):\n            if g not in cache:\n                cache[g] = expert(g).tobytes()\n            return cache[g]\n    else:\n        pf = pool_file if isinstance(pool_file, PoolFile) else open_pool(L, pool_file)\n\n        def pool(g):                    # read from the file (the memmap's writes are in the\n            if not pf.packed[g]:        # page cache preadv reads)\n                pf.arr[g] = to_split(expert(g)) if pf.split else expert(g)\n                pf.packed[g] = 1\n            return pf.get(g)\n    srv = ExpertServer(dram_of(backend, L), L, pool, policy=policy)\n    srv.pool_file = pf\n    if pf is not None:                  # (its reads' touches after each request is served)\n        pf.defer_touch = True\n    srv.pool_warm = None if pf is None else pf.warm_t\n    srv.load([j * L.E + e for j in range(L.layers) for e in range(L.E)] if warm else ())\n    return srv\n\n\n# ---------------------------------------------------------------------------- reference\ndef route(logits: np.ndarray, bias: np.ndarray | None, mo: MoESpec):\n    \"\"\"The model's choice for one token's router logits [E]: (ids in the device's order, their\n    weights). The k largest (ties: the first) of: LFM2, sigmoid scores + bias, the chosen\n    scores renormalized (+ 1e-6, as Hugging Face) and scaled; softmax (Qwen), the logits, the\n    chosen ones' softmax (Hugging Face's softmax over all, renormalized over the k).\"\"\"\n    lg = np.asarray(logits, np.float64)\n    if mo.rule == \"softmax\":\n        s, sel = lg, lg.copy()\n    else:\n        s = 1.0 / (1.0 + np.exp(-lg))\n        sel = s + bias\n    ids = []\n    for _ in range(mo.k):\n        i = int(np.argmax(sel))\n        ids.append(i)\n        sel[i] = -np.inf\n    w = s[ids]\n    if mo.rule == \"softmax\":\n        w = np.exp(w - w[0])\n        w = w / w.sum()\n    elif mo.norm:\n        w = w / (w.sum() + 1e-6)\n    return ids, w * mo.scale\n\n\n# ---------------------------------------------------------------------------- the device\ndef moe_hint(x, lw, mo: MoESpec, dev: SimpleNamespace, eps: float) -> None:\n    \"\"\"Path (a)'s prefetch hint (docs/offload.md section 12), before the layer's mixer: its\n    router on the layer's input x through moe_ffn's norm, the k best by the model's rule (no\n    weights), posted as a request whose global ids are offset by dev.hint_off (layers x E: the\n    host's mark of a hint). The host writes served once it has replaced the hinted experts'\n    victims, before their transfers, so the route's fence (moe_ffn) waits for no expert; an\n    expert still on its way reads as missing there and is waited for by its answer word and\n    its tag. lw and dev as moe_ffn's. One register.\"\"\"\n    b = current()\n    E, k = mo.E, mo.k\n    xs = ol.quantize(rmsnorm(x, ol.load(lw.g_post), eps))\n    lg = ol.dot(xs, lw.router)\n    del xs\n    sel, pr, ids, tmp = ol.empty((E,)), ol.empty((2,)), ol.empty((k,)), ol.empty((k,))\n    if mo.rule == \"softmax\":\n        sel.set(lg[0, 0:E])\n    else:\n        sel.set(sigmoid(lg[0, 0:E]) + ol.load(lw.ebias))\n    del lg\n    r = b.scratch()\n    lp = b.begin_loop(k)                # the k best, as the route picks them\n    b.emit(I.argmax(pr.base, sel.base, 1, E, comment=\"hint: best\"))\n    b.emit(I.rld(r, pr.base + 1, bound=(0, E - 1), comment=\"its index\"))\n    b.emit(I.vop(I.V_FILL, sel.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, NEG, ra=r,\n                 comment=\"knock out\"))\n    if k > 1:\n        tmp[0:k - 1].set(ids[1:k])\n        ids[0:k - 1].set(tmp[0:k - 1])\n    b.emit(I.vop(I.V_COPY, ids.base + k - 1, pr.base + 1, 0, 1, 1, 0, 0, 0, comment=\"id\"))\n    b.end_loop(lp)\n    b.unscratch(r)\n    ids.set(ids + ol.load(lw.gbase) + float(dev.hint_off))\n    seq = MB.wait_served(dev.mbox)                  # MB.post, with the request's count\n    ol.store(Tensor(Affine(dev.mbox + LINE), (k,), (1,)), ids)\n    ol.store(Tensor(Affine(dev.mbox + 4), (1,), (1,)), ol.full((1,), float(k)))\n    seq.set(seq + 1.0)\n    ol.store(Tensor(Affine(dev.mbox), (1,), (1,)), seq)\n\n\ndef moe_hint_rows(x, lw, mo: MoESpec, dev: SimpleNamespace, eps: float) -> None:\n    \"\"\"moe_hint on R rows at once (x [R, H], R * k <= LINE / 4: one request row): each row's k\n    best by the router of lw's layer, through its norm (moe_ffn's route), posted as one hint\n    of the rows' R * k ids (repeats included) and their count. A layer-major prefill run's\n    hint for the next layer (docs/offload.md 13.9): layer j's run on its output rows, with\n    layer j + 1's lw, ahead of layer j + 1's runs. One register.\"\"\"\n    b = current()\n    R, E, k = x.rows, mo.E, mo.k\n    N = R * k\n    if N > LINE // 4:\n        raise CompileError(f\"{R} rows of {k} experts: more ids than a request row holds\")\n    xs = ol.quantize(rmsnorm(x, ol.load(lw.g_post), eps))\n    lg = ol.dot(xs, lw.router)                          # [R, E] (+ the shared expert's gate)\n    del xs\n    gid = ol.empty((R, k), dense=True)\n    pr, tmp, ids = ol.empty((2,)), ol.empty((k,)), ol.empty((k,))\n    off = ol.load(lw.gbase) + float(dev.hint_off)\n    r = b.scratch()\n    for q in range(R):                                  # each row's k best, as the route's\n        sel = ol.empty((E,))\n        if mo.rule == \"softmax\":\n            sel.set(lg[q, 0:E])\n        else:\n            sel.set(sigmoid(lg[q, 0:E]) + ol.load(lw.ebias))\n        lp = b.begin_loop(k)\n        b.emit(I.argmax(pr.base, sel.base, 1, E, comment=\"hint: best\"))\n        b.emit(I.rld(r, pr.base + 1, bound=(0, E - 1), comment=\"its index\"))\n        b.emit(I.vop(I.V_FILL, sel.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, NEG, ra=r,\n                     comment=\"knock out\"))\n        if k > 1:\n            tmp[0:k - 1].set(ids[1:k])\n            ids[0:k - 1].set(tmp[0:k - 1])\n        b.emit(I.vop(I.V_COPY, ids.base + k - 1, pr.base + 1, 0, 1, 1, 0, 0, 0, comment=\"id\"))\n        b.end_loop(lp)\n        del sel\n        gid[q, :].set(ids + off)\n    b.unscratch(r)\n    del lg, ids, tmp, off\n    seq = MB.wait_served(dev.mbox)                  # MB.post, with the request's count\n    ol.store(Tensor(Affine(dev.mbox + LINE), (N,), (1,)), gid.reshape(1, N)[0, :])\n    ol.store(Tensor(Affine(dev.mbox + 4), (1,), (1,)), ol.full((1,), float(N)))\n    seq.set(seq + 1.0)\n    ol.store(Tensor(Affine(dev.mbox), (1,), (1,)), seq)\n\n\ndef _ebound(dev):\n    \"\"\"A directory entry's byte offset (8 a global id): its RLD bound, if the device says how\n    many ids there are.\"\"\"\n    n = getattr(dev, \"ids\", None)\n    return (0, 8 * (n - 1)) if n else None\n\n\ndef slot_of(r: int, word, off: int, dev: SimpleNamespace, missing: bool,\n            off_bound=None) -> None:\n    \"\"\"R[r] = the slot of the expert whose offset (TMEM word `off`: its directory entry's, or\n    for a missing one its answer word's) the loop has at column 0, its data landed, and the\n    slot's tag zeroed. Present: WAITW on its entry (at once). Missing: WAITW on its answer\n    word (once the host has written the answer), then on the slot's tag (once the expert's\n    DMA has landed: the host writes the tag in its last beat). The tag is zeroed for every\n    expert the card uses, so a nonzero tag is always a later expert's (docs/offload.md 10.11).\n    word: a one-word TMEM tile; off_bound: the offset's RLD bound (isa.rld); the slot's is the\n    pool's (dev.slots).\"\"\"\n    b = current()\n    b.emit(I.rld(r, off, bound=off_bound, comment=\"answer word\" if missing else \"entry offset\"))\n    b.waitw(word, dev.answer if missing else dev.dir, 0, I.C_NE, ra=r,\n            comment=\"wait: its slot (the answer)\" if missing else \"its slot\")\n    b.rld(r, word, raw=True, bound=getattr(dev, \"slots\", None), comment=\"its slot\")\n    if missing:\n        b.waitw(word, dev.tag, 0, I.C_NE, ra=r, comment=\"wait: its data (the slot's tag)\")\n    ol.store(Tensor(Affine(dev.tag) + DevVar(\"expert slot\", r), (1,), (1,)), ol.zeros((1,)))\n\n\ndef moe_ffn(x, lw, mo: MoESpec, dev: SimpleNamespace, eps: float, beside=None,\n            residual: bool = True, y_first: bool = False):\n    \"\"\"x + the MoE FFN of one token (module docstring). lw: the layer's g_post [H], router\n    QTensor [E, H] ([E + 1, H] with a shared expert: its gate is row E), ebias Tensor [E]\n    (sigmoid_bias), gbase Tensor [1] (j * E as fp32), and with a shared expert its SwiGLU\n    wg, wu, wd; with g_exp [H] (Gemma 4: pre_feedforward_layernorm_2's gain) the routed\n    experts read their own quantized input, the norm times g_exp, and the router the norm (the\n    norm alone, quantized, has its blocks scaled by the residual's outlier channels, which the\n    gain zeroes: docs/offload.md 11.2). dev: the offload words (mbox, served, answer, dir:\n    static DRAM addresses), `tag` (a slot's tag word, from the slot) and `fmt`, the\n    ExpertFormat.\n\n    beside(): emits work that needs no expert (Gemma 4's dense MLP) right after the request is\n    posted, so that it runs while the host streams the missing experts (docs/offload.md 5.3);\n    moe_ffn's register is free during it. A shared expert runs there too, before beside()'s\n    work (docs/offload.md 15: the card waits for its misses in most MoE layers, and a shared\n    expert computed after them lengthened every wait by its time). residual=False: the FFN's\n    output without x (Gemma 4 norms the experts' sum before its residual). y_first: the experts' [k, H] outputs take\n    their TMEM before the router's input does (Gemma 4 26B-A4B: 22,544 words, which only the\n    free space before the step's later tiles holds).\"\"\"\n    b = current()\n    if ol.num_programs() != 1:\n        raise CompileError(\"moe_ffn runs on one slice\")\n    E, k, H = mo.E, mo.k, x.cols\n    y = ol.empty((k, H)) if y_first else None\n    if getattr(lw, \"g_exp\", None) is None:\n        xs = xe = ol.quantize(rmsnorm(x, ol.load(lw.g_post), eps))\n    else:\n        xn = rmsnorm(x, ol.load(lw.g_post), eps)\n        xs, xe = ol.quantize(xn), ol.quantize(xn * ol.load(lw.g_exp)[None, :])   # (QACT\n        del xn                                                                   # CSCALE)\n    lg = ol.dot(xs, lw.router)\n    sc, sel = ol.empty((E,)), ol.empty((E,))\n    if mo.rule == \"softmax\":\n        sc.set(lg[0, 0:E])\n        sel.set(sc)\n    else:\n        sc.set(sigmoid(lg[0, 0:E]))\n        sel.set(sc + ol.load(lw.ebias))\n    gate = sigmoid(lg[0, E:E + 1]) if mo.shared else None\n    # One register in all (the resident decode's arguments and the layer loops hold the\n    # rest): r holds one value at a time (an index, the seq bits, an offset, a count, a slot\n    # address, a row). The k experts' values are the columns of pe, a [5, k] tile that every\n    # loop over the experts rotates left by one at the end of its body: expert i is at column\n    # 0 in iteration i, and after k iterations every row is back in order. (A slot address\n    # never passes through the VPU, which would flush it as a denormal: WAITW copies it from\n    # the directory to the word `word`, at once for an expert present, and RLD raw takes its\n    # bits into r.)\n    EP, MISS, OFF, WT, ROW, ANS = range(6)          # pe's rows\n    pe, tmp, ids, pr = ol.empty((6, k)), ol.empty((6, k)), ol.empty((k,)), ol.empty((2,))\n    word = ol.empty((1,))\n    wt = pe[WT, :]\n\n    def rotate(rows=slice(0, 6)):\n        a, e = rows.start, rows.stop\n        if k > 1:\n            tmp[a:e, 0:k - 1].set(pe[a:e, 1:k])\n        tmp[a:e, k - 1:k].set(pe[a:e, 0:1])\n        pe[a:e, :].set(tmp[a:e, :])\n\n    r = b.scratch()\n    # the k best: ARGMAX, knock-out; in the router's order, the new one to column k - 1\n    lp = b.begin_loop(k)\n    b.emit(I.argmax(pr.base, sel.base, 1, E, comment=\"moe: best\"))\n    b.emit(I.rld(r, pr.base + 1, bound=(0, E - 1), comment=\"its index\"))\n    b.emit(I.vop(I.V_FILL, sel.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, NEG, ra=r,\n                 comment=\"knock out\"))\n    rotate(slice(WT, WT + 1))\n    b.emit(I.vop(I.V_COPY, wt.base + k - 1, sc.base, 0, 1, 1, 0, 0, 0, rb=r, comment=\"weight\"))\n    if k > 1:\n        tmp[0, 0:k - 1].set(ids[1:k])\n        ids[0:k - 1].set(tmp[0, 0:k - 1])\n    b.emit(I.vop(I.V_COPY, ids.base + k - 1, pr.base + 1, 0, 1, 1, 0, 0, 0, comment=\"id\"))\n    b.end_loop(lp)\n    if mo.rule == \"softmax\":                            # column 0 holds the largest\n        e = ol.exp2((wt - wt[0:1]) * ol.LOG2E)\n        wt.set(e * ol.recip(ol.sum(e)))\n    elif mo.norm:\n        wt.set(wt * ol.recip(ol.sum(wt) + 1e-6))\n    if mo.scale != 1.0:\n        wt.set(wt * float(mo.scale))\n    gid = ol.empty((k,))\n    gid.set(ids + ol.load(lw.gbase))                    # global ids: j * E + index\n    pe[OFF, :].set(gid * 8.0)                           # their directory entries' offsets\n    if y is None:\n        y = ol.empty((k, H))\n    for i in range(k):              # y's rows (ol.empty may pad them), the answer's words\n        pe[ROW, i:i + 1].set(float(i * y.rs))\n        pe[ANS, i:i + 1].set(float(4 * i))\n    # the fence, then the request: seq + 1 and the ids\n    seq = ol.load(Tensor(Affine(dev.mbox), (1,), (1,)))\n    b.rld(r, seq, raw=True, comment=\"seq (bits)\")\n    b.waitw(word, dev.served, 0, I.C_GE, rc=r, comment=\"fence: served >= seq\")\n    ol.store(Tensor(Affine(dev.mbox + LINE), (k,), (1,)), gid)\n    ol.store(Tensor(Affine(dev.mbox + 4), (1,), (1,)), ol.full((1,), float(k)))  # (its count)\n    seq.set(seq + 1.0)\n    ol.store(Tensor(Affine(dev.mbox), (1,), (1,)), seq)\n    sh = None\n    if mo.shared or beside is not None:                 # while the host streams: the work\n        b.unscratch(r)                                  # that needs no routed expert\n        if mo.shared:                                   # (the shared expert, added last)\n            sh = swiglu_down(xs, lw.wg, lw.wu, lw.wd) * gate[:, None]\n            del gate\n        if beside is not None:\n            beside()\n        r = b.scratch()\n    # the directory: each entry's present flag\n    col = lambda row: pe.base + row * pe.rs                       # noqa: E731 (column 0)\n    lp = b.begin_loop(k)\n    b.emit(I.rld(r, col(OFF), bound=_ebound(dev), comment=\"entry offset\"))\n    b.emit(I.ld(dev.dir + 4, col(EP), 1, ra=r, comment=\"entry: present\"))\n    rotate()\n    b.end_loop(lp)\n    pe[MISS, :].set(pe[EP, :] * -1.0 + 1.0)\n    ex = dev.fmt.descs(DevVar(\"expert slot\", r, align=LINE))   # (slots: LINE-aligned)\n\n    def expert():\n        \"\"\"The expert whose slot is R[r], weighted, into its row of y.\"\"\"\n        o = swiglu_down(xe, ex.wg, ex.wu, ex.wd, act=ACTS[mo.act])\n        b.check_live(o)\n        b.emit(I.rld(r, col(ROW), bound=(0, (k - 1) * y.rs), comment=\"its row\"))\n        b.emit(I.vop(I.V_MUL, y.base, o.base, col(WT), 1, H, 0, 0, 0, I.B_ROW, ra=r,\n                     comment=\"weighted, to its row\"))\n\n    for flag, wait in ((EP, False), (MISS, True)):\n        lp = b.begin_loop(k)\n        b.emit(I.rld(r, col(flag), bound=(0, 1), comment=\"missing\" if wait else \"present\"))\n        inner = b.begin_loop(0, rcount=r)               # (the count is read here: r is free)\n        slot_of(r, word, col(ANS) if wait else col(OFF), dev, wait,\n                (0, 4 * (k - 1)) if wait else _ebound(dev))\n        expert()\n        b.end_loop(inner)\n        rotate()\n        b.end_loop(lp)\n    b.unscratch(r)\n    ol.store(Tensor(Affine(dev.answer), (k,), (1,)), ol.zeros((k,)))   # (for the next request)\n    acc = y[0:1, :]\n    for i in range(1, k):\n        acc = acc + y[i:i + 1, :]\n    if sh is not None:\n        acc = acc + sh\n    return x + acc if residual else acc\n\n\ndef moe_ffn_rows(x, lw, mo: MoESpec, dev: SimpleNamespace, eps: float, beside=None,\n                 residual: bool = True):\n    \"\"\"x + the MoE FFN of R token rows at once (x [R, H], R * k <= LINE / 4: one request row):\n    a layer-major prefill run's (docs/offload.md 13). Every row routes as moe_ffn's; one\n    request names the rows' R * k ids (repeats included: the host serves each once) and their\n    count (the word after seq); each expert of the rows' union runs once, on every row (one MM\n    of R rows: with PAIR, R <= 2 cost what one does), and each row that chose it stores its\n    output, unweighted, to its place (row, rank) of dev.scratch [R * k + 1, H] (the last row a\n    sink for the rows that did not); then each row sums its experts' outputs, weighted, in its\n    router's order. So a row's result is moe_ffn's on that row alone, bit for bit, whatever\n    the cache held. lw, dev (and dev.scratch), beside and residual as moe_ffn's.\n\n    The union: for each row q, eq[n, j] = 1 - min(1, |id_n - id_q,j|) over every entry n of\n    the request (the ids are integers: 1 where equal); its row sums say whether row q chose\n    entry n's expert (found) and at which rank (the sum of j eq[n, j]), which gives the byte\n    offset of entry n's output for row q in the scratch; an entry whose expert an earlier row\n    chose is not computed again. One register, as moe_ffn's.\"\"\"\n    b = current()\n    if ol.num_programs() != 1:\n        raise CompileError(\"moe_ffn_rows runs on one slice\")\n    R, H, E, k = x.rows, x.cols, mo.E, mo.k\n    N = R * k\n    if N > LINE // 4:\n        raise CompileError(f\"{R} rows of {k} experts: more ids than a request row holds\")\n    if getattr(lw, \"g_exp\", None) is None:\n        xs = xe = ol.quantize(rmsnorm(x, ol.load(lw.g_post), eps))\n    else:\n        xn = rmsnorm(x, ol.load(lw.g_post), eps)\n        xs, xe = ol.quantize(xn), ol.quantize(xn * ol.load(lw.g_exp)[None, :])\n        del xn\n    lg = ol.dot(xs, lw.router)                          # [R, E] (+ the shared expert's gate)\n    gid, wts = ol.empty((R, k), dense=True), ol.empty((R, k), dense=True)\n    pr, tmp, ids = ol.empty((2,)), ol.empty((k,)), ol.empty((k,))\n    gb = ol.load(lw.gbase)\n    r = b.scratch()\n    for q in range(R):                                  # each row's k best, as moe_ffn's\n        sc, sel = ol.empty((E,)), ol.empty((E,))\n        if mo.rule == \"softmax\":\n            sc.set(lg[q, 0:E])\n            sel.set(sc)\n        else:\n            sc.set(sigmoid(lg[q, 0:E]))\n            sel.set(sc + ol.load(lw.ebias))\n        wt = wts[q, :]\n        lp = b.begin_loop(k)\n        b.emit(I.argmax(pr.base, sel.base, 1, E, comment=\"moe: best\"))\n        b.emit(I.rld(r, pr.base + 1, bound=(0, E - 1), comment=\"its index\"))\n        b.emit(I.vop(I.V_FILL, sel.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, NEG, ra=r,\n                     comment=\"knock out\"))\n        if k > 1:\n            tmp[0:k - 1].set(wt[1:k])\n            wt[0:k - 1].set(tmp[0:k - 1])\n            tmp[0:k - 1].set(ids[1:k])\n            ids[0:k - 1].set(tmp[0:k - 1])\n        b.emit(I.vop(I.V_COPY, wt.base + k - 1, sc.base, 0, 1, 1, 0, 0, 0, rb=r,\n                     comment=\"weight\"))\n        b.emit(I.vop(I.V_COPY, ids.base + k - 1, pr.base + 1, 0, 1, 1, 0, 0, 0, comment=\"id\"))\n        b.end_loop(lp)\n        del sc, sel\n        if mo.rule == \"softmax\":                        # column 0 holds the largest\n            e = ol.exp2((wt - wt[0:1]) * ol.LOG2E)\n            wt.set(e * ol.recip(ol.sum(e)))\n            del e\n        elif mo.norm:\n            wt.set(wt * ol.recip(ol.sum(wt) + 1e-6))\n        if mo.scale != 1.0:\n            wt.set(wt * float(mo.scale))\n        gid[q, :].set(ids + gb)                         # global ids: j * E + index\n    del ids, tmp\n    gf = gid.reshape(1, N)[0, :]                        # the request's entries, row by row\n    # pe's rows (columns: the entries; every loop over them rotates pe left by one, so entry\n    # n is at column 0 in iteration n): present and computed here, missing, the directory\n    # offset, and per row q the byte offset of the entry's output for q in the scratch\n    EP, MISS, OFF, ANS, TG = 0, 1, 2, 3, 4\n    RB, SINK = 4 * H, N * 4 * H\n    pe, tpe = ol.empty((TG + R, N)), ol.empty((TG + R, N))\n    rank = ol.empty((k,))\n    for j in range(k):\n        rank[j:j + 1].set(float(j))\n    dup = ol.zeros((N,))\n    for q in range(R):\n        d = ol.empty((N, k))\n        d.set(gf[:, None])\n        eq = 1.0 - ol.minimum(ol.abs(d - gid[q, :][None, :]), 1.0)\n        del d\n        found = ol.sum(eq)                              # [N]: row q chose entry n's expert\n        at = ol.sum(eq * rank[None, :])                 # its rank in row q\n        del eq\n        pe[TG + q, :].set(found * ((at + float(q * k)) * float(RB) - float(SINK)) + float(SINK))\n        if q + 1 < R:                                   # later rows' entries chosen before\n            dup[(q + 1) * k:N].set(dup[(q + 1) * k:N] + found[(q + 1) * k:N])\n        del found, at\n    pe[OFF, :].set(gf * 8.0)\n    for n in range(N):                                  # each entry's word of the answer\n        pe[ANS, n:n + 1].set(float(4 * n))\n\n    def rotate():\n        tpe[:, 0:N - 1].set(pe[:, 1:N])\n        tpe[:, N - 1:N].set(pe[:, 0:1])\n        pe[:, :].set(tpe[:, :])\n\n    # the fence, then the request: the ids, their count, seq + 1\n    word = ol.empty((1,))\n    seq = ol.load(Tensor(Affine(dev.mbox), (1,), (1,)))\n    b.rld(r, seq, raw=True, comment=\"seq (bits)\")\n    b.waitw(word, dev.served, 0, I.C_GE, rc=r, comment=\"fence: served >= seq\")\n    ol.store(Tensor(Affine(dev.mbox + LINE), (N,), (1,)), gf)\n    ol.store(Tensor(Affine(dev.mbox + 4), (1,), (1,)), ol.full((1,), float(N)))\n    seq.set(seq + 1.0)\n    ol.store(Tensor(Affine(dev.mbox), (1,), (1,)), seq)\n    sh = None\n    if mo.shared or beside is not None:                 # while the host streams: the work\n        b.unscratch(r)                                  # that needs no routed expert\n        if mo.shared:                                   # (the shared expert, added last)\n            g = ol.empty((R,))\n            g.column().set(lg[:, E:E + 1])\n            gate = sigmoid(g)\n            del g\n            sh = swiglu_down(xs, lw.wg, lw.wu, lw.wd) * gate[:, None]\n            del gate, lg\n        if beside is not None:\n            beside()\n        r = b.scratch()\n    col = lambda row: pe.base + row * pe.rs                       # noqa: E731 (column 0)\n    lp = b.begin_loop(N)                                # the directory: present flags\n    b.emit(I.rld(r, col(OFF), bound=_ebound(dev), comment=\"entry offset\"))\n    b.emit(I.ld(dev.dir + 4, col(EP), 1, ra=r, comment=\"entry: present\"))\n    rotate()\n    b.end_loop(lp)\n    keep = 1.0 - ol.minimum(dup, 1.0)                   # entries computed here: the union\n    pe[MISS, :].set((pe[EP, :] * -1.0 + 1.0) * keep)\n    pe[EP, :].set(pe[EP, :] * keep)\n    del keep, dup\n    ex = dev.fmt.descs(DevVar(\"expert slot\", r, align=LINE))      # (slots: LINE-aligned)\n\n    def expert():\n        \"\"\"The expert whose slot is R[r] on every row; each row's output to its place.\"\"\"\n        o = swiglu_down(xe, ex.wg, ex.wu, ex.wd, act=ACTS[mo.act])\n        b.check_live(o)\n        for q in range(R):\n            b.emit(I.rld(r, col(TG + q), bound=(0, SINK), comment=\"its place for this row\"))\n            ol.store(Tensor(Affine(dev.scratch) + DevVar(\"place\", r), (H,), (1,)), o[q, :])\n\n    for flag, wait in ((EP, False), (MISS, True)):\n        lp = b.begin_loop(N)\n        b.emit(I.rld(r, col(flag), bound=(0, 1), comment=\"missing\" if wait else \"present\"))\n        inner = b.begin_loop(0, rcount=r)               # (the count is read here: r is free)\n        slot_of(r, word, col(ANS) if wait else col(OFF), dev, wait,\n                (0, 4 * (N - 1)) if wait else _ebound(dev))\n        expert()\n        b.end_loop(inner)\n        rotate()\n        b.end_loop(lp)\n    b.unscratch(r)\n    ol.store(Tensor(Affine(dev.answer), (N,), (1,)), ol.zeros((N,)))   # (for the next request)\n    out = ol.empty((R, H))\n    for q in range(R):                                  # each row's sum in its router's order\n        acc = None\n        for i in range(k):\n            y = ol.load(Tensor(Affine(dev.scratch + (q * k + i) * RB), (1, H), (H, 1))) * \\\n                wts[q, i:i + 1]\n            acc = y if acc is None else acc + y\n        out[q:q + 1, :].set(acc)\n        del acc, y\n    if sh is not None:\n        out = out + sh\n    return x + out if residual else out\n\n\n# ---------------------------------------------------------------------------- expert-major\nEM_RHO = 1.12               # an expert's stream from DRAM, MXU cycles a chunk (the card: 17.07 / 15.2\n                            # GB/s); any value in (1, 2) orders the pass sizes alike (em_pass_order)\n_TWO23 = float(1 << 23)     # FILL's immediate plus a register: the float 2^23 + R (0 <= R < 2^23)\n\n\ndef em_meta(k: int) -> int:\n    \"\"\"Words of a record's tail: the row's k ids and k weights and its norm's 1 / rms, in whole\n    lines.\"\"\"\n    w = LINE // 4\n    return -(-(2 * k + 1) // w) * w\n\n\ndef em_record(H: int, k: int) -> int:\n    \"\"\"Bytes of a chunk row's record in the expert-major scratch (docs/offload.md 13.11): the\n    row's residual X [H], its k experts' outputs OUT [k, H] (rank order), the shared expert's\n    output or the normed dense MLP's SH [H], then its tail (em_meta): global ids [k], weights\n    [k] and the 1 / rms of the norm before the router and the experts (fp32).\"\"\"\n    return 4 * ((k + 2) * H + em_meta(k))\n\n\ndef em_slots(layout: Layout, nbytes: int) -> list:\n    \"\"\"The slots a scratch of nbytes covers: the slot area's first ones, from the first slot on\n    (the slots follow one another, layer after layer). The server takes them for the prefill\n    and hands them back after it, with their tag beats zeroed.\"\"\"\n    s = layout.all_slots()\n    n = -(-nbytes // layout.pitch)\n    if n > len(s):\n        raise ValueError(f\"a scratch of {nbytes} bytes: {n} slots, the image has {len(s)}\")\n    return s[:n]\n\n\ndef em_row(dev: SimpleNamespace, row, r: int = 0) -> Affine:\n    \"\"\"The byte address of the record of chunk row row + r (row: a run argument or an int).\"\"\"\n    return Affine(dev.em_base + r * dev.em_rec) + row * dev.em_rec\n\n\ndef em_x(dev: SimpleNamespace, row, R: int, H: int) -> Tensor:\n    \"\"\"The residual rows X of chunk rows row .. row + R - 1, [R, H] (expert-major's residual\n    stream: the records' first words).\"\"\"\n    return Tensor(em_row(dev, row), (R, H), (dev.em_rec // 4, 1))\n\n\ndef need_rows(k: int) -> int:\n    \"\"\"The rows a need line holds: LINE / 4 ids, k a row (0: not one).\"\"\"\n    return (LINE // 4) // max(1, k)\n\n\ndef moe_prologue_rows(x, lw, mo: MoESpec, dev: SimpleNamespace, eps: float, row,\n                      beside=None) -> None:\n    \"\"\"Expert-major's MoE prologue (docs/offload.md 13.11) of a layer-major run's R rows x [R,\n    H] (chunk rows from `row`, a run argument): each row's norm and route as moe_ffn_rows'; to\n    each row's record tail its k global ids and weights and the norm's 1 / rms (the expert run\n    norms the row again from X and it: bit for bit); then the rows' ids, offset by\n    dev.need_off (2 x layers x E), posted as need lines of need_rows(k) rows each (a hint's\n    post: the server streams the experts no slot holds and answers nothing; the layer's expert\n    run waits on their directory entries); then to each row's SH the shared expert's output\n    (SwiGLU of the layer block times sigmoid of its gate's logit), or beside()'s ([R, H]:\n    Gemma 4's normed dense MLP, while the host streams). The router's and the shared expert's\n    MMs take the R rows at once (a tile's: tiled.qwen35_layer_tile); of more need lines than\n    one, the first goes out before the shared expert and the others as its chunks begin (each\n    post waits for the host to serve the one before: the MXU works meanwhile), the rest after\n    it. The caller stores x itself to the records' X (em_x). One register.\"\"\"\n    b = current()\n    if ol.num_programs() != 1:\n        raise CompileError(\"moe_prologue_rows runs on one slice\")\n    R, H, E, k = x.rows, x.cols, mo.E, mo.k\n    per = need_rows(k)                                  # rows a need line\n    if per < 1:\n        raise CompileError(f\"{k} experts a row: more ids than a need line holds\")\n    ss = ol.sum(x * x, axis=1)                          # rmsnorm's, its 1 / rms kept\n    rinv = ol.rsqrt(ss * (1.0 / H) + eps)\n    del ss\n    g = ol.load(lw.g_post)\n\n    def normed(r0, n):                                  # rows r0 .. r0 + n, normed, quantized\n        xr, rr = (x, rinv) if n == R else (x[r0:r0 + n, :], rinv[r0:r0 + n])\n        if getattr(lw, \"g_exp\", None) is None:          # (as moe_ffn_rows' quantize(rmsnorm))\n            return ol.quantize((xr * rr[:, None]) * g[None, :])\n        xn = (xr * rr[:, None]) * g[None, :]\n        return ol.quantize(xn)\n\n    G = min(R, current().cfg.MCOLS) if mo.shared else R  # rows a shared expert pass: whole\n    xs = normed(0, R)                                   # column groups (its outputs' TMEM)\n    if G == R:\n        del g\n    lg = ol.dot(xs, lw.router)                          # [R, E] (+ the shared expert's gate)\n    gid, wts = ol.empty((R, k), dense=True), ol.empty((R, k), dense=True)\n    pr, tmp, ids = ol.empty((2,)), ol.empty((k,)), ol.empty((k,))\n    gb = ol.load(lw.gbase)\n    r = b.scratch()\n    for q in range(R):                                  # each row's k best, as moe_ffn_rows'\n        sc, sel = ol.empty((E,)), ol.empty((E,))\n        if mo.rule == \"softmax\":\n            sc.set(lg[q, 0:E])\n            sel.set(sc)\n        else:\n            sc.set(sigmoid(lg[q, 0:E]))\n            sel.set(sc + ol.load(lw.ebias))\n        wt = wts[q, :]\n        lp = b.begin_loop(k)\n        b.emit(I.argmax(pr.base, sel.base, 1, E, comment=\"moe: best\"))\n        b.emit(I.rld(r, pr.base + 1, bound=(0, E - 1), comment=\"its index\"))\n        b.emit(I.vop(I.V_FILL, sel.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, NEG, ra=r,\n                     comment=\"knock out\"))\n        if k > 1:\n            tmp[0:k - 1].set(wt[1:k])\n            wt[0:k - 1].set(tmp[0:k - 1])\n            tmp[0:k - 1].set(ids[1:k])\n            ids[0:k - 1].set(tmp[0:k - 1])\n        b.emit(I.vop(I.V_COPY, wt.base + k - 1, sc.base, 0, 1, 1, 0, 0, 0, rb=r,\n                     comment=\"weight\"))\n        b.emit(I.vop(I.V_COPY, ids.base + k - 1, pr.base + 1, 0, 1, 1, 0, 0, 0, comment=\"id\"))\n        b.end_loop(lp)\n        del sc, sel\n        if mo.rule == \"softmax\":                        # column 0 holds the largest\n            e = ol.exp2((wt - wt[0:1]) * ol.LOG2E)\n            wt.set(e * ol.recip(ol.sum(e)))\n            del e\n        elif mo.norm:\n            wt.set(wt * ol.recip(ol.sum(wt) + 1e-6))\n        if mo.scale != 1.0:\n            wt.set(wt * float(mo.scale))\n        gid[q, :].set(ids + gb)                         # global ids: j * E + index\n    b.unscratch(r)\n    del ids, tmp, pr, gb\n    tail = 4 * H * (k + 2)\n    for q in range(R):                                  # the record tails\n        t = em_row(dev, row, q) + tail\n        ol.store(Tensor(t, (k,), (1,)), gid[q, :])\n        ol.store(Tensor(t + 4 * k, (k,), (1,)), wts[q, :])\n        ol.store(Tensor(t + 8 * k, (1,), (1,)), rinv[q:q + 1])\n    del wts\n    if G == R:\n        del rinv\n    lines, held = list(range(0, R, per)), [gid]         # each need line's first row; the ids\n    del gid                                             # (freed after the last line)\n\n    def post(i=None):                                   # the next need line (MB.post, its count)\n        if not lines:\n            return\n        r0 = lines.pop(0)\n        N = min(per, R - r0) * k\n        seq = MB.wait_served(dev.mbox)\n        ol.store(Tensor(Affine(dev.mbox + LINE), (N,), (1,)),\n                 held[0][r0:r0 + N // k, :].reshape(1, N)[0, :] + float(dev.need_off))\n        ol.store(Tensor(Affine(dev.mbox + 4), (1,), (1,)), ol.full((1,), float(N)))\n        seq.set(seq + 1.0)\n        ol.store(Tensor(Affine(dev.mbox), (1,), (1,)), seq)\n        del seq\n        if not lines:\n            held.clear()\n\n    post()\n    if mo.shared:\n        gs = ol.empty((R,))\n        gs.column().set(lg[:, E:E + 1])\n        gate = sigmoid(gs)\n        del gs\n        if G < R:\n            del xs\n        for r0 in range(0, R, G):                       # each row's SH\n            n = min(G, R - r0)\n            xg = xs if G == R else normed(r0, n)\n            sh = swiglu_down(xg, lw.wg, lw.wu, lw.wd, each=post if lines else None) * \\\n                (gate if G == R else gate[r0:r0 + n])[:, None]\n            del xg\n            for q in range(n):\n                ol.store(Tensor(em_row(dev, row, r0 + q) + 4 * H * (k + 1), (1, H), (H, 1)),\n                         sh[q:q + 1, :])\n            del sh\n        if G < R:\n            del g, rinv\n    elif beside is not None:\n        del lg\n        sh = beside()\n        for q in range(R):\n            ol.store(Tensor(em_row(dev, row, q) + 4 * H * (k + 1), (1, H), (H, 1)),\n                     sh[q:q + 1, :])\n    while lines:\n        post()\n\n\ndef moe_combine_rows(x, mo: MoESpec, dev: SimpleNamespace, row, residual: bool = True):\n    \"\"\"Expert-major's end of a MoE layer (docs/offload.md 13.11), in the next layer's run (or\n    the prefill's head): for each of the R rows x [R, H] from chunk row `row`, its experts'\n    outputs weighted and summed in its router's order, from its record (OUT, the tail's\n    weights), then the shared expert's output (SH) added, and x + that: moe_ffn_rows' sums,\n    bit for bit. residual=False: the routed sum alone (Gemma 4 norms it beside the dense MLP's,\n    which SH holds).\"\"\"\n    R, H, k = x.rows, x.cols, mo.k\n    out = ol.empty((R, H))\n    for q in range(R):                                  # each row's sum in its router's order\n        t = em_row(dev, row, q)\n        wt = ol.load(Tensor(t + 4 * H * (k + 2) + 4 * k, (k,), (1,)))\n        acc = None\n        for i in range(k):\n            y = ol.load(Tensor(t + 4 * H * (1 + i), (1, H), (H, 1))) * wt[i:i + 1]\n            acc = y if acc is None else acc + y\n        out[q:q + 1, :].set(acc)\n        del acc, y, wt\n    if not residual:\n        return out\n    if mo.shared:\n        out = out + ol.load(Tensor(em_row(dev, row) + 4 * H * (k + 1), (R, H),\n                                   (dev.em_rec // 4, 1)))\n    return x + out\n\n\ndef em_mxu_cost(cfg, wformat: str, m: int) -> int:\n    \"\"\"An expert pass's MXU time on m rows, in cycles a chunk of its weights (docs/isa.md MM):\n    4-bit weights a chunk a cycle with PAIR (2 m <= MCOLS), half a chunk without; int8 a chunk a\n    cycle; the ACT RAM's rows past MCOLS replay each chunk, ceil(m / MCOLS) groups.\"\"\"\n    g = -(-m // cfg.MCOLS)\n    if Q.mxu_wf(wformat) == 0:\n        return g\n    return 1 if cfg.PAIR and 2 * m <= cfg.MCOLS else 2 * g\n\n\ndef em_pass_order(cfg, wformat: str) -> list:\n    \"\"\"Every pass size m <= ACT_ROWS, the best first: the least time an entry,\n    max(EM_RHO, em_mxu_cost(m)) / m, the fewest rows on a tie (docs/offload.md 13.17). A pass\n    streams its expert's weights once, so it costs the stream until the MXU takes longer; the\n    stream is a little under a chunk a cycle (EM_RHO), and any value in (1, 2) orders them the\n    same.\"\"\"\n    act = cfg.act_rows\n    return sorted(range(1, act + 1),\n                  key=lambda m: (max(EM_RHO, em_mxu_cost(cfg, wformat, m)) / m, m))\n\n\ndef em_pass_rows(cfg, wformat: str) -> int:\n    \"\"\"C, the entries of one expert an expert-major pass takes: em_pass_order's first. 4 on the\n    card (MCOLS 4, PAIR: 2 rows at the stream's rate, 4 at twice its MXU time), 16 at MCOLS 16\n    with ACT_ROWS >= 16, 4 for int8 at MCOLS 4 (a chunk a cycle for every row).\"\"\"\n    return em_pass_order(cfg, wformat)[0]\n\n\ndef em_short_rows(cfg, wformat: str, c: int) -> int:\n    \"\"\"The most rows a pass of C entries computes for less MXU time than C's (0: none): an\n    expert's last pass, if it holds no more entries, computes only that many (on the card 2 of\n    C = 4).\"\"\"\n    cost = em_mxu_cost(cfg, wformat, c)\n    return max([m for m in range(1, c) if em_mxu_cost(cfg, wformat, m) < cost], default=0)\n\n\ndef moe_expert_run(lw, mo: MoESpec, dev: SimpleNamespace, rows, entries, C: int = 2,\n                   S: int = 0) -> None:\n    \"\"\"Expert-major's expert run of one MoE layer (docs/offload.md 13.11, 13.17), after the\n    layer's mixer runs over a chunk's `rows` rows (run arguments: rows, and entries = rows x k):\n    every (row, rank) entry's expert once on its row, each expert in passes of up to C of its\n    entries, each pass streaming the expert's weights once (C: em_pass_rows).\n\n    1. The tables: per row (a loop of `rows`) its k ids from its record tail, and for each of\n       its entries its row and its output's place (the record's OUT row of its rank, in lines).\n    2. The bucketing (a loop of `entries`): an entry joins its expert's open pass while it has\n       room, else opens one (expert, a short flag 0, and the entry in all C places: a pass of\n       fewer entries computes its first row again and stores the same output again); the\n       expert's free places, next place and room flag (min(free, 1)) count it, and LOOPs\n       counted by the flag and 1 - flag are the branches. Registers reach the tables as\n       FILL's 2^23 + R, made exact after. The pass table holds entries / C + E passes at most.\n       With S (em_short_rows: a smaller pass's MXU costs less) a loop over the experts then\n       flags each one's last pass that holds at most S entries (free >= C - S); the others'\n       flags go to a sink row.\n    3. The passes (a loop of the passes counted): WAITW on the expert's directory entry (its\n       slot word != 0: the server writes an entry after its expert's data and tag, and keeps\n       a needed expert's slot until this run has read it), its slot's tag zeroed (as slot_of),\n       then the pass's C rows (S for a flagged pass, a LOOP of count flag and one of 1 - flag)\n       normed again from their X and 1 / rms and quantized (moe_ffn_rows' expression),\n       swiglu_down at the slot, each output row to its place. Each row's quantization and MM\n       outputs are its own (docs/isa.md: one exact integer an output), so the outputs are\n       C = 2's bit for bit.\n\n    The entry wait stops at MB.TIMEOUT with an error the host sees: the prefill never runs on\n    without an expert.\"\"\"\n    b = current()\n    if ol.num_programs() != 1:\n        raise CompileError(\"moe_expert_run runs on one slice\")\n    if not 1 <= C or not 0 <= S < C:\n        raise CompileError(f\"expert run passes of {C} entries, short ones of {S}\")\n    E, k, H = mo.E, mo.k, dev.fmt.H\n    N, REC, PW = dev.em_rows * k, dev.em_rec, C + 2\n    PM = N // C + E\n    tail = 4 * H * (k + 2)\n    # 1. the tables: ids (global), each entry's row, each entry's place (lines from the base)\n    L, QR, PL = ol.empty((N,)), ol.empty((N,)), ol.empty((N,))\n    rr = b.arg_reg(rows, 1)\n    rd, rt, rq, rpl = (b.scratch() for _ in range(4))\n    lp = b.begin_loop(0, rcount=rr)\n    b.emit(I.ld(dev.em_base + tail, L.base, k, ra=rd, rb=rt, comment=\"the row's ids\"))\n    b.emit(I.vop(I.V_FILL, QR.base, 0, 0, 1, k, 0, 0, 0, I.B_SCALAR, _TWO23, ra=rt, rd=rq,\n                 comment=\"its entries' row\"))\n    for i in range(k):\n        b.emit(I.vop(I.V_FILL, PL.base + i, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR,\n                     _TWO23 + (1 + i) * H // 16, ra=rt, rd=rpl, comment=\"its place (lines)\"))\n    b.emit(I.addi(rd, rd, REC, comment=\"next record\"))\n    b.emit(I.addi(rt, rt, k, comment=\"its entries\"))\n    b.emit(I.addi(rq, rq, 1, comment=\"next row\"))\n    b.emit(I.addi(rpl, rpl, REC // LINE, comment=\"its record (lines)\"))\n    b.end_loop(lp)\n    for r in (rd, rt, rq, rpl):\n        b.unscratch(r)\n    b.release_arg(rows)\n    QR.set(QR - _TWO23)\n    PL.set(PL - _TWO23)\n    gb = ol.load(lw.gbase)\n    L.set(L - gb)                                       # the layer's own indices\n    # 2. the bucketing\n    FREE, ROOM, POS = ol.zeros((E,)), ol.zeros((E,)), ol.zeros((E,))\n    BASE = ol.full((E,), _TWO23 + PM * PW)              # (the sink row, for the unused)\n    PT = ol.empty((PM + 1, PW), dense=True)\n    re = b.arg_reg(entries, 1)\n    rp, rnp, r1, r2, r3, r4 = (b.scratch() for _ in range(6))\n    lp = b.begin_loop(0, rcount=re)\n    b.emit(I.rld(r1, L.base, ra=rp, comment=\"its expert\"))\n    b.emit(I.rld(r2, ROOM.base, ra=r1, comment=\"room in its open pass\"))\n    b.emit(I.rld(r3, ROOM.base, ra=r1, mul=-1, comment=\"-room\"))\n    join = b.begin_loop(0, rcount=r2)\n    b.emit(I.rld(r4, POS.base, ra=r1, comment=\"its next place (2^23 + word)\"))\n    b.emit(I.vop(I.V_FILL, PT.base - (1 << 23), 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, _TWO23,\n                 ra=r4, rd=rp, comment=\"join: the entry\"))\n    b.emit(I.vop(I.V_ADD, POS.base, POS.base, 0, 1, 1, 0, 0, 0, I.B_SCALAR, 1.0, ra=r1, rb=r1,\n                 comment=\"next place\"))\n    b.emit(I.vop(I.V_ADD, FREE.base, FREE.base, 0, 1, 1, 0, 0, 0, I.B_SCALAR, -1.0, ra=r1,\n                 rb=r1, comment=\"free - 1\"))\n    b.emit(I.vop(I.V_MIN, ROOM.base, FREE.base, 0, 1, 1, 0, 0, 0, I.B_SCALAR, 1.0, ra=r1,\n                 rb=r1, comment=\"room = min(free, 1)\"))\n    b.end_loop(join)\n    opn = b.begin_loop(1, rcount=r3)                    # 1 - room\n    b.emit(I.vop(I.V_FILL, PT.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, _TWO23, ra=rnp, rd=r1,\n                 comment=\"open: its expert\"))\n    b.emit(I.vop(I.V_FILL, PT.base + 1, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, _TWO23, ra=rnp,\n                 comment=\"open: not short\"))\n    b.emit(I.vop(I.V_FILL, PT.base + 2, 0, 0, 1, C, 0, 0, 0, I.B_SCALAR, _TWO23, ra=rnp,\n                 rd=rp, comment=\"open: the entry in every place\"))\n    b.emit(I.vop(I.V_FILL, BASE.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, _TWO23, ra=r1, rd=rnp,\n                 comment=\"its open pass\"))\n    b.emit(I.vop(I.V_FILL, POS.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, _TWO23 + 3, ra=r1,\n                 rd=rnp, comment=\"its next place\"))\n    b.emit(I.vop(I.V_FILL, FREE.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, float(C - 1), ra=r1,\n                 comment=\"free\"))\n    b.emit(I.vop(I.V_FILL, ROOM.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, float(min(C - 1, 1)),\n                 ra=r1, comment=\"room\"))\n    b.emit(I.addi(rnp, rnp, PW, comment=\"next pass\"))\n    b.end_loop(opn)\n    b.emit(I.addi(rp, rp, 1, comment=\"next entry\"))\n    b.end_loop(lp)\n    NP = ol.full((1,), _TWO23)\n    b.emit(I.vop(I.V_FILL, NP.base, 0, 0, 1, 1, 0, 0, 0, I.B_SCALAR, _TWO23, rd=rnp,\n                 comment=\"passes x PW\"))\n    for r in (rp, rnp, r1, r2, r3, r4):\n        b.unscratch(r)\n    b.release_arg(entries)\n    del L, ROOM, POS\n    if S:                                               # each expert's last pass: short?\n        SH = ol.empty((E,))\n        b.emit(I.vop(I.V_SUB, SH.base, FREE.base, 0, 1, E, 0, 0, 0, I.B_SCALAR,\n                     float(C - S - 1), comment=\"free - (C - S - 1)\"))\n        b.emit(I.vop(I.V_MAX, SH.base, SH.base, 0, 1, E, 0, 0, 0, I.B_SCALAR, 0.0))\n        b.emit(I.vop(I.V_MIN, SH.base, SH.base, 0, 1, E, 0, 0, 0, I.B_SCALAR, 1.0,\n                     comment=\"short: free >= C - S\"))\n        re, r4 = b.scratch(), b.scratch()\n        lp = b.begin_loop(E)\n        b.emit(I.rld(r4, BASE.base, ra=re, comment=\"its last pass (2^23 + word)\"))\n        b.emit(I.vop(I.V_ADD, PT.base + 1 - (1 << 23), SH.base, 0, 1, 1, 0, 0, 0, I.B_SCALAR,\n                     _TWO23, ra=r4, rb=re, comment=\"its short flag\"))\n        b.emit(I.addi(re, re, 1, comment=\"next expert\"))\n        b.end_loop(lp)\n        b.unscratch(re)\n        b.unscratch(r4)\n        del SH\n    del FREE, BASE\n    PT.set(PT - _TWO23)\n    PT[:, 0:1].set(PT[:, 0:1] + gb)                     # global ids\n    NP.set((NP - _TWO23) * (1.0 / PW))\n    del gb\n    # 3. the passes\n    g = ol.load(lw.g_post)\n    ge = ol.load(lw.g_exp) if getattr(lw, \"g_exp\", None) is not None else None\n    word = ol.empty((1,))\n    rq, rs, rn = b.scratch(), b.scratch(), b.scratch()\n\n    def rows_of_pass(M: int) -> None:\n        \"\"\"The pass's first M places: their rows normed, quantized, through the expert, out.\"\"\"\n        xr = ol.empty((M, H), dense=True)\n        rec = DevVar(\"record\", rn, align=LINE)\n        for j in range(M):                              # (moe_ffn_rows' expressions, a row at a\n            b.emit(I.rld(rn, PT.base + 2 + j, ra=rq, comment=\"entry\"))      # time: TMEM for C\n            b.emit(I.rld(rn, QR.base, ra=rn, mul=REC, comment=\"its row's record\"))  # rows of\n            x = ol.load(Tensor(Affine(dev.em_base) + rec, (1, H), (H, 1)))       # the 26B's)\n            ri = ol.load(Tensor(Affine(dev.em_base + tail + 8 * k) + rec, (1,), (1,)))\n            xr[j:j + 1, :].set((x * ri[:, None]) * g[None, :])\n            del x, ri\n            if ge is not None:\n                xr[j:j + 1, :].set(xr[j:j + 1, :] * ge[None, :])\n        xe = ol.quantize(xr)\n        del xr\n        ex = dev.fmt.descs(DevVar(\"expert slot\", rs, align=LINE))\n        o = swiglu_down(xe, ex.wg, ex.wu, ex.wd, act=ACTS[mo.act])\n        b.check_live(o)\n        for j in range(M):\n            b.emit(I.rld(rn, PT.base + 2 + j, ra=rq, comment=\"entry\"))\n            b.emit(I.rld(rn, PL.base, ra=rn, mul=LINE, comment=\"its place\"))\n            ol.store(Tensor(Affine(dev.em_base) + DevVar(\"place\", rn, align=LINE), (1, H),\n                            (H, 1)), o[j:j + 1, :])\n        del o, xe\n\n    b.rld(rs, NP, comment=\"passes\")\n    lp = b.begin_loop(0, rcount=rs)                     # (the count is read here: rs is free)\n    b.emit(I.rld(rs, PT.base, ra=rq, mul=8, comment=\"its directory entry\"))\n    b.waitw(word, dev.dir, 0, I.C_NE, ra=rs, timeout=MB.TIMEOUT,\n            comment=\"wait: its slot (the entry)\")\n    b.rld(rs, word, raw=True, bound=getattr(dev, \"slots\", None), comment=\"its slot\")\n    ol.store(Tensor(Affine(dev.tag) + DevVar(\"expert slot\", rs), (1,), (1,)), ol.zeros((1,)))\n    if S:\n        rf, rg = b.scratch(), b.scratch()\n        b.emit(I.rld(rf, PT.base + 1, ra=rq, comment=\"short\"))\n        b.emit(I.rld(rg, PT.base + 1, ra=rq, mul=-1, comment=\"-short\"))\n        short = b.begin_loop(0, rcount=rf)\n        rows_of_pass(S)\n        b.end_loop(short)\n        full = b.begin_loop(1, rcount=rg)               # 1 - short\n        rows_of_pass(C)\n        b.end_loop(full)\n        b.unscratch(rf)\n        b.unscratch(rg)\n    else:\n        rows_of_pass(C)\n    b.emit(I.addi(rq, rq, PW, comment=\"next pass\"))\n    b.end_loop(lp)\n    for r in (rq, rs, rn):\n        b.unscratch(r)\n", "opentpu/llm/mtp.py": "\"\"\"Speculative decoding with Qwen3.5's MTP drafter, k = 1, on an openTPU backend (docs/mtp.md 9).\n\nPhase 2 drives the loop from the host, one program per run, compiled at its position as\nEngine.step's are; phase 3 runs the same kernels per attention bucket at a run-time position\nwith the loop on the card (docs/mtp.md 2, 3). Each iteration at position p, with the token t\n(at p) and the draft d (for p + 1):\n\n    verify   qwen35_rows over (t, d) at p, p + 1 (fork, hidden): logits of both rows, a0 and a1\n             their argmax; the final norm's rows to `hid`; the DeltaNet states and conv\n             windows after row 0 stay in slot c, those after row 1 go to slot 1 - c\n    accept   n = (d == a0); a0 is emitted, and a1 when n = 1 (a stop id ends the loop)\n    draft    qwen35_mtp over (hid[0], a0), (hid[1], a1) at p, p + 1: the next draft is row n's\n    commit   c ^= n, p += 1 + n, t = a_n\n\nGreedy, the tokens are those of plain greedy decode bit for bit: every emitted token is the\nargmax of a logits row the decode step would compute on the committed state (the rows\nkernel is bit-identical to decode steps; with PAIR and 4-bit weights where its MMs pair as\nthe steps' do: 2 rows at MCOLS >= 4, qwen35_rows). Rejected rows leave nothing behind: the\nKV caches (the model's and the MTP layer's) are positional and are overwritten before they\nare read, and the recurrent state and windows of a rejected row sit in the uncommitted\nslot.\n\nSampled (the loop on the card, docs/mtp.md 11), a0 and a1 are generate.Sampler's picks with\nthe uniforms of positions p + 1 and p + 2, and the draft is accepted iff a0 == d: speculative\nsampling for a one-hot draft. The tokens are plain sampled decode's for the same uniforms;\nrow 1's repetition penalty counts d (_penalize_draft).\n\nThe prompt's prefill takes plain prefill's runs (qwen3.fit_chunk: the same rows, so its\nMMs pair as plain prefill's do), stores `hid` for every row and runs the MTP layer over the\nprompt's rows (h_i, x_(i+1)), which fills its KV cache; its last row (h_(P-1), a0) gives the\nfirst draft.\n\"\"\"\nfrom __future__ import annotations\n\nimport time\nfrom dataclasses import dataclass, field, replace\n\nimport numpy as np\n\nfrom .. import isa as I\nfrom .. import language as ol\nfrom ..compiler import CompileError, current\nfrom . import generate as G\nfrom . import prefill as PF\nfrom ..host.offload import LINE\nfrom ..kernels import mailbox as MB\nfrom .qwen3 import ATTN_BLOCK, Engine, RunRows, fit_chunk, head_rows_chunk\n\nMTP_ROWS = 4            # the MTP layer's rows per run in the prefill (its TMEM: [R, 2H] input)\n\n\n@dataclass\nclass MTPStats:\n    \"\"\"One generation: the prompt, the tokens, and per iteration the drafts accepted (0, 1).\"\"\"\n    prompt: int = 0\n    tokens: list = field(default_factory=list)\n    accepted: list = field(default_factory=list)\n    runs: list = field(default_factory=list)        # (kind, rows, stats of the backend's run)\n    slots: list = field(default_factory=list)       # each verify run's committed slot (parity)\n    compile_s: float = 0.0                          # host seconds compiling the programs\n    prefill_s: float = 0.0                          # host seconds of the prefill (wall)\n    prefill_compile_s: float = 0.0                  # ... compiling its programs\n    timed_out: bool = False                         # loop_card: the deadline wrote the stop word\n\n    @property\n    def iterations(self) -> int:\n        return len(self.accepted)\n\n    @property\n    def acceptance(self) -> float:\n        return sum(self.accepted) / max(1, len(self.accepted))\n\n\ndef mtp_engine(spec, W, cap: int = 4096, **kw) -> Engine:\n    \"\"\"An Engine whose image holds the MTP drafter and the state slots (Spec.mtp) and the\n    resident decode's tables (its runs read their inputs from the image). W must hold the\n    checkpoint's mtp.* tensors (load_weights(path, mtp=True)).\"\"\"\n    return Engine(replace(spec, mtp=True), W, cap=cap, resident=True, **kw)\n\n\nclass MTPDecoder:\n    \"\"\"Speculative decoding with the MTP drafter on an Engine made by mtp_engine: greedy, and\n    sampled with the loop on the card (generate_card(sampling=)). slot: the DeltaNet states'\n    and windows' committed slot (DeltaNetParts).\"\"\"\n\n    def __init__(self, engine: Engine):\n        img = engine.image\n        if not getattr(img.spec, \"mtp\", False) or not img.lookup:\n            raise ValueError(\"MTPDecoder needs an Engine made by mtp_engine (Spec.mtp, lookup)\")\n        if engine.cfg.S != 1:\n            raise ValueError(\"MTP decoding runs on one slice\")\n        fmts = {img.wformat, img.head_format, *getattr(img, \"mf\", {}).values()}\n        if engine.cfg.PAIR and fmts - {\"int8\", None} and 2 * 2 > engine.cfg.MCOLS:\n            raise ValueError(\"with PAIR and 4-bit weights a 2-row verify run pairs its MMs as \"\n                             \"the decode steps do only at MCOLS >= 4 (qwen35_rows): its tokens \"\n                             \"would not be plain decode's bit for bit\")\n        mo = getattr(img.spec, \"moe\", None)\n        if mo is not None and (img.rows < 2 or 2 * mo.k > LINE // 4):\n            raise ValueError(\"MTP decoding of a MoE model needs an image of 2 rows and a \"\n                             \"request row for both rows' experts (2 k ids)\")\n        self.eng, self.img = engine, img\n        self.slot = 0\n        self.draft = None           # the draft after the token at Engine.pos (prefill, the loop)\n        self.pending = None         # (p, a0): a lazy prefill's last row, its draft not run yet\n                                    # (the loop's first run drafts it: loop_card; else _settle)\n        self.held = {}              # a snapshot's position t -> the residual row of t - 1 (holds)\n        self.refill = None          # (t - 1, that row): the next prefill's first K / V row again\n        self.split = None           # the loop's V and E in two parts: None when over IMEM (tests:\n                                    # True always, False never; _gen_programs)\n        # the MTP layer's rows a prefill run (a MoE's: its experts' request names R k ids)\n        self.mtp_rows = MTP_ROWS if mo is None else max(1, min(MTP_ROWS, LINE // 4 // mo.k))\n\n    # ---- runs\n    def _run(self, progs, kind: str, rows: int, st: MTPStats, tokens=None) -> None:\n        \"\"\"A run; `tokens`: its rows' tokens, whose embedding rows the host writes first when\n        the int8 table is on the host (embed_host: a MoE's).\"\"\"\n        if tokens is not None and getattr(self.img, \"embed_host\", False):\n            self.eng._write_host_rows(tokens)\n        r = self.eng.backend.run(progs)\n        st.runs.append((kind, rows, r))\n\n    def _logits(self, n: int) -> np.ndarray:\n        io, v = self.img.io, self.img.spec.vocab\n        return self.eng.backend.read(0, io[\"logits\"], 4 * n * v).view(np.float32).reshape(n, v)\n\n    def _drafts(self, n: int) -> list:\n        w = self.eng.backend.read(0, self.img.io[\"draft\"], 4 * n).view(np.float32)\n        return [int(x) for x in w]\n\n    def _verify(self, p: int, toks, logit_rows, fork: bool, st: MTPStats, kind: str):\n        rows = [(0, p + j) for j in range(len(toks))]\n        t0 = time.perf_counter()\n        progs = self.img.compile_rows(rows, logit_rows, self.eng.block, tokens=toks,\n                                      slot=self.slot, fork=fork, hidden=True, nest=False)\n        st.compile_s += time.perf_counter() - t0\n        if fork:\n            st.slots.append(self.slot)\n        self._run(progs, kind, len(toks), st, toks)\n\n    def _draft(self, p: int, toks, st: MTPStats, kind: str, h0: int = 0) -> list:\n        t0 = time.perf_counter()\n        progs = self.img.compile_mtp(p, len(toks), toks, self.eng.block, h0=h0)\n        st.compile_s += time.perf_counter() - t0\n        self._run(progs, kind, len(toks), st, toks)\n        return self._drafts(len(toks))\n\n    # ---- generation\n    def prefill(self, tokens, st: MTPStats, chunk: int | None = None, pick=None, on_run=None,\n                follow: int | None = None, vis=None, lazy: bool = False):\n        \"\"\"Feed `tokens` from Engine.pos in plain prefill's runs (qwen3.fit_chunk,\n        Engine.prefill's: their rows and so their MMs' pairing are its), each storing its rows'\n        hidden, then the MTP layer over them, (h_q, x_(q + 1)), in runs of up to `chunk` rows;\n        returns (a0, the first draft), also in self.draft. pick(logits) -> a0 (default the\n        argmax). From Engine.pos 0 a new context; from a later one, the context this decoder\n        left (its prefill, or the loop's run: the MTP layer's KV cache holds every position\n        before Engine.pos, the committed slot the states). on_run(tokens): after each prefill\n        run (Engine.pos past it); a true return stops the prefill there (-> None, None; a later\n        prefill feeds the rest). follow: the token after `tokens` (a part of a prompt, the rest\n        fed later): the last row's MTP input, no logits, a0 None. vis: each token's image row\n        or -1 (Engine.prefill_layers': MiniCPM-V's images, a layer-by-layer prompt's only; the\n        MTP layer's input of an image token is its placeholder's embedding row). lazy (a\n        layer-by-layer prompt's, by_layers: the others draft in their last run): the last row's\n        draft is left to the loop's first run (loop_card: a D1 before the first verify, served\n        in the loop's run), a0 returned at once with no draft (self.pending; a prefill or a\n        rollback before any loop settles it: _settle).\"\"\"\n        self._settle(st)\n        toks = [int(t) for t in tokens]\n        vis = None if vis is None or max(vis, default=-1) < 0 else [int(v) for v in vis]\n        if vis is not None and len(vis) != len(toks):\n            raise ValueError(f\"vis: {len(vis)} rows for {len(toks)} tokens\")\n        chunk = self.mtp_rows if chunk is None else chunk\n        p0 = p = self.eng.pos\n        P = p0 + len(toks)\n        if not toks or P > self.img.cap - 1:\n            raise ValueError(f\"{len(toks)} tokens at position {p0}: the cache holds \"\n                             f\"{self.img.cap}, and the next token needs a position\")\n        if p0 == 0:\n            self.slot = 0\n        if vis is not None and not (self.by_layers and P > self.img.spec.conv_k - 1):\n            raise ValueError(\"image rows go in a layer-by-layer prompt (a streamed MoE's)\")\n        if self.eng.prompt_runs and PF.supported(self.eng) and PF.covers(self.eng, p0, P):\n            a0, draft = PF.mtp(self, toks, st, pick, on_run, follow)    # docs/prefill.md\n            self.draft = draft\n            return a0, draft\n        K = self.img.spec.conv_k\n        if self.by_layers and P > K - 1:    # a streamed MoE's prompt layer by layer: the rows\n            n = max(0, K - 1 - p0)          # before conv_k - 1 in the rows kernel's runs first\n            stop = []                       # (their runs reported too: on_run, e.g. Chat.fed)\n\n            def first(part):\n                stop.append(bool(on_run(part)))\n                return stop[-1]\n            if n:\n                if vis is not None and max(vis[:n]) >= 0:\n                    raise ValueError(f\"an image row before position {K - 1}\")\n                self.prefill(toks[:n], st, chunk, on_run=None if on_run is None else first,\n                             follow=toks[n])\n            if any(stop):\n                self.draft = None\n                return None, None\n            return self._prefill_layers(toks[n:], st, pick, on_run, follow,\n                                        None if vis is None else vis[n:], lazy)\n        a0 = draft = None\n        fit = self.img.rows\n        head = follow is None\n        while p < P:\n            left, i = P - p, p - p0\n            t0 = time.perf_counter()\n            n, progs, fit = fit_chunk(self.img, self.eng.block, 0, p, self.img.rows, left, fit,\n                                      toks[i:], logits=head, hidden=True, slot=self.slot)\n            if progs is None:           # one row: the rows kernel (plain prefill's decode step)\n                progs = self.img.compile_rows([(0, p)], [0] if head and n == left else [],\n                                              self.eng.block, tokens=toks[i:i + 1],\n                                              slot=self.slot, hidden=True)\n            st.compile_s += time.perf_counter() - t0\n            self._run(progs, \"prefill\", n, st, toks[i:i + n])\n            nxt = toks[i + 1:i + n + 1]\n            if n == left and head:\n                lg = self._logits(n)[n - 1]\n                a0 = int(np.argmax(lg)) if pick is None else int(pick(lg))\n                nxt = nxt + [a0]\n            elif n == left:\n                nxt = nxt + [int(follow)]\n            for j in range(0, n, chunk):\n                k = min(chunk, n - j)\n                draft = self._draft(p + j, nxt[j:j + k], st, \"mtp prefill\", h0=j)[k - 1]\n            p += n\n            self.eng.pos = p\n            if on_run is not None and on_run(toks[i:i + n]) and p < P:\n                self.draft = None\n                return None, None\n        self.eng.pos = P\n        self.draft = draft\n        return a0, draft\n\n    @property\n    def by_layers(self) -> bool:\n        \"\"\"The prompt goes layer by layer (a streamed MoE's Engine with layer_major and its\n        embedding rows from the host, _prefill_layers).\"\"\"\n        return (getattr(self.img.spec, \"moe\", None) is not None and bool(self.eng.layer_major)\n                and bool(getattr(self.img, \"embed_host\", False)))\n\n    @property\n    def holds(self) -> bool:\n        \"\"\"A snapshot keeps the residual row before it (by_layers: Engine.prefill_layers'\n        keep), so a rollback to it takes the context back to the snapshot itself, and the next\n        prefill appends the MTP layer's row before it from that row with the new token\n        (Engine.prefill_layers' fix) instead of running that position through the model again.\n        Without, a rollback goes a token further back (rollback).\"\"\"\n        return self.by_layers\n\n    def _prefill_layers(self, toks, st: MTPStats, pick, on_run, follow, vis=None,\n                        lazy: bool = False):\n        \"\"\"prefill on a streamed MoE whose Engine runs the prompt layer by layer\n        (Engine.prefill_layers with the MTP layer's K / V, docs/mtp.md 12), from conv_k - 1\n        on: each chunk's rows through the model a layer at a time (the expert slots pooled),\n        then the MTP layer's K / V of its rows that have their next token (the prompt's, or\n        `follow`); then, the slots back to decode's, the last row's draft: qwen35_mtp over the\n        head's hidden row and a0 (its MoE a request in the MTP layer's slots; lazy: left to\n        the loop, self.pending). The states in the committed slot. on_run(tokens) once, after\n        it. vis: the tokens' image rows. A part before a snapshot (follow) keeps its last\n        row's residual (holds); after a rollback to one, the MTP layer's row before it comes\n        first (self.refill).\"\"\"\n        eng = self.eng\n        head = follow is None\n        P, n0 = eng.pos + len(toks), len(eng.stats)\n        kw = {} if vis is None else {\"vis\": vis}\n        if self.refill is not None:\n            kw[\"fix\"], self.refill = self.refill, None\n        lg = eng.prefill_layers(toks, logits=head, mtp=toks[1:] + [follow], slot=self.slot,\n                                keep=not head, **kw)\n        st.runs.append((\"prefill\", len(toks),\n                        {\"cycles\": sum((s or {}).get(\"cycles\", 0) for s in eng.stats[n0:])}))\n        if on_run is not None:\n            on_run(toks)\n        if not head:\n            self.draft = None\n            return None, None\n        a0 = int(np.argmax(lg)) if pick is None else int(pick(lg))\n        if lazy:\n            self.draft, self.pending = None, (P - 1, a0)\n            return a0, None\n        draft = self._draft(P - 1, [a0], st, \"mtp prefill\")[0]\n        self.draft = draft\n        return a0, draft\n\n    def _settle(self, st: MTPStats | None = None) -> None:\n        \"\"\"A lazy prefill's pending draft run on its own (the 1-row MTP run an eager prefill\n        takes), when no loop came to take it: the MTP layer's K / V row at its position and\n        self.draft as an eager prefill leaves them.\"\"\"\n        if self.pending is None:\n            return\n        (q, a0), self.pending = self.pending, None\n        self.draft = self._draft(q, [a0], MTPStats() if st is None else st, \"mtp prefill\")[0]\n\n    def kept_row(self) -> np.ndarray | None:\n        \"\"\"The residual row before Engine.pos, when the last prefill kept it (holds: a part\n        before a snapshot, Engine.kept), read back; else None.\"\"\"\n        eng = self.eng\n        kept = getattr(eng, \"kept\", None)\n        if not self.holds or kept is None or kept[0] != eng.pos - 1:\n            return None\n        H = self.img.spec.hidden\n        return eng.backend.read(0, self.img.io[\"xbuf\"] + 4 * H * kept[1],\n                                4 * H).view(np.float32).copy()\n\n    def snapshot(self) -> bool:\n        \"\"\"Engine.snapshot of the committed slot's states and windows; with the residual row\n        before its position, read back (holds: the last prefill kept it, kept_row).\"\"\"\n        eng = self.eng\n        ok = eng.snapshot(self.slot)\n        h = self.kept_row() if ok else None\n        if h is not None:\n            self.held[eng.pos] = h\n        at = set(eng._snaps.at.values()) if getattr(eng, \"_snaps\", None) is not None else set()\n        self.held = {t: h for t, h in self.held.items() if t in at}\n        return ok\n\n    def rollback(self, k: int) -> int:\n        \"\"\"Engine.rollback for this decoder's context (into the committed slot): the MTP\n        layer's row at q took the token at q + 1 (h_q, x_(q + 1)), so a context going back\n        because the token at k changes must append the row at k - 1 again with the new token.\n        With a snapshot at k that holds the residual row of k - 1 (holds), the context goes\n        back to k and the next prefill appends that row from it first (self.refill); else it\n        goes back to k - 1 at most, where the next prefill's first row computes that row\n        again. Returns the position.\"\"\"\n        if k >= self.eng.pos:\n            return self.eng.pos\n        h = self.held.get(k)\n        t = self.eng.rollback(k if h is not None else max(0, k - 1), self.slot)\n        self.draft = self.pending = None    # (the next prefill computes the rows from t on)\n        self.refill = (t - 1, h) if h is not None and t == k else None\n        self.held = {p: v for p, v in self.held.items() if p <= t}\n        if t == 0:\n            self.slot = 0\n        return t\n\n    def generate(self, prompt, max_new: int = 32, stop=None, drafts=None) -> MTPStats:\n        \"\"\"Greedy generation from an empty context; stops after a stop id (default the\n        model's EOS ids) or max_new tokens, leaving the context as plain decode would (the\n        last token not fed: Engine.pos is its position). drafts (tests): drafts(position,\n        tokens so far) -> the draft for that position instead of the MTP's.\"\"\"\n        stop = set(self.img.spec.eos if stop is None else stop)\n        st = MTPStats(prompt=len(prompt))\n        t0 = time.perf_counter()\n        a0, d = self.prefill(prompt, st)\n        st.prefill_s, st.prefill_compile_s = time.perf_counter() - t0, st.compile_s\n        out, p, t = st.tokens, self.eng.pos, a0\n        out.append(a0)\n        while len(out) < max_new and out[-1] not in stop and p + 1 < self.img.cap:\n            if drafts is not None:\n                d = int(drafts(p + 1, out))\n            self._verify(p, [t, d], [0, 1], True, st, \"verify\")\n            lg = self._logits(2)\n            a = [int(np.argmax(lg[0])), int(np.argmax(lg[1]))]\n            n = int(d == a[0])\n            st.accepted.append(n)\n            # a0, and a1 when the draft holds; cut after a stop id or at max_new, and then the\n            # committed state is row 0's (as plain decode's: the last token not fed)\n            keep = 1 if a[0] in stop or len(out) + 1 >= max_new else 1 + n\n            out += a[:keep]\n            if keep - 1 < n or out[-1] in stop or len(out) >= max_new:\n                self.slot ^= keep - 1\n                p += keep\n                break\n            nd = self._draft(p, a, st, \"mtp\")\n            self.slot ^= n\n            p, t, d = p + 1 + n, a[n], nd[n]\n        self.eng.pos = p\n        return st\n\n    # ---- the loop on the card\n    def _gen_programs(self, b0: int, b1: int, st: MTPStats | None = None,\n                      forced: bool = False, samp: G.Sampling | None = None) -> dict:\n        \"\"\"Buckets b0 .. b1's programs of the MTP loop in the chain area and their table\n        entries (each compiled and written once per engine, `forced` and sampler); returns\n        {(bucket, kind): programs} (a split kind's first part; its second at (bucket, kind,\n        1)). A V or E over IMEM (or any, self.split True) goes in two parts (compile_gen's\n        split form, cut at the first of plan_cuts whose parts fit): the first in its slot and\n        table entry, the second in the slot's second half, its entry at the first half's end\n        (ptab2_addr).\"\"\"\n        eng, img = self.eng, self.img\n        a = img.lookup[\"mtpgen\"]\n        mode = (forced, None if samp is None else samp.key)\n        if eng.__dict__.get(\"_mtp_forced\", mode) != mode:\n            eng.__dict__.pop(\"_mtp_gen\", None)      # the chain area holds another kind\n        eng._mtp_forced = mode\n        done = eng.__dict__.setdefault(\"_mtp_gen\", {})\n\n        def over(k, progs):\n            return CompileError(f\"MTP loop program {KINDS[k]} of bucket {blk}: \"\n                                f\"{max(map(len, progs))} instructions, IMEM \"\n                                f\"{img.cfg.IMEM_WORDS // 8}\")\n        for blk in range(b0, b1 + 1):\n            if (blk, V0) in done:\n                continue\n            t0 = time.perf_counter()\n            tab = np.zeros(2 * NK, np.uint32)\n            for k in range(NK):\n                sk = samp if KINDS[k][0] in \"VE\" else None      # (D, D1: either mode's)\n                what = (\"mtpgen\", blk, k, eng.block, forced, None if sk is None else sk.key)\n                splits = KINDS[k][0] in \"VE\" and self.split is not False\n                progs = None\n                if not (splits and self.split):\n                    progs = eng.cached(what, lambda: (compile_gen(img, blk, k, eng.block,\n                                                                  forced, sk), None))[0]\n                    if progs is None:\n                        continue\n                    if not G.fits(img, progs):\n                        if not splits:\n                            raise over(k, progs)\n                        progs = None\n                parts = None\n                if progs is None:           # the split form\n                    for cut in plan_cuts(img):\n                        parts = [eng.cached(what + (\"part\", j, cut), lambda j=j: (\n                            compile_gen(img, blk, k, eng.block, forced, sk, j, cut), None))[0]\n                            for j in (0, 1)]\n                        if parts[0] is None or (all(G.fits(img, p) for p in parts) and all(\n                                4 * len(G.slot_words(eng.backend, p)) <= a[\"slot\"] // 2 - 8\n                                for p in parts[0])):    # (room for the second's entry)\n                            break\n                    else:\n                        raise over(k, parts[1] if parts else [[]])\n                    if parts[0] is None:\n                        continue\n                    progs, p2 = parts[0], prog_addr(a, blk, k) + a[\"slot\"] // 2\n                    ent = np.array([p2, len(I.assemble(parts[1][0])) // 8], np.uint32)\n                    for s_, prog in enumerate(parts[1]):\n                        eng.backend.write(s_, p2, G.slot_words(eng.backend, prog))\n                        eng.backend.write(s_, ptab2_addr(a, blk, k), ent)\n                for s_, prog in enumerate(progs):     # (with its wait entries: chained)\n                    eng.backend.write(s_, prog_addr(a, blk, k), G.slot_words(eng.backend, prog))\n                tab[2 * k], tab[2 * k + 1] = prog_addr(a, blk, k), len(I.assemble(progs[0])) // 8\n                done[(blk, k)] = progs              # (a split kind's first part: the entry)\n                if parts is not None:\n                    done[(blk, k, 1)] = parts[1]\n            for s_ in range(img.cfg.S):\n                eng.backend.write(s_, ptab_addr(a, blk), tab)\n            if st is not None:\n                st.compile_s += time.perf_counter() - t0\n        return done\n\n    def generate_card(self, prompt, max_new: int = 32, stop=None, on_token=None,\n                      drafts=None, deadline: float | None = None,\n                      sampling: G.Sampling | None = None, context=None,\n                      rng=None) -> MTPStats:\n        \"\"\"Greedy MTP decoding with the loop on the device (docs/mtp.md 10): the prefill as\n        generate()'s (its last logits' argmax on the host, as Engine.generate_card's callers\n        take it), then one device run that verifies, drafts and chains through the buckets'\n        programs until a stop id (default the model's EOS ids), the host's stop word or\n        max_new tokens; the tokens are read from out[] as they land (on_token). The context\n        is left as plain decode leaves it (the last token not fed: Engine.pos its position,\n        the committed state slot read back). st.runs: the run's counters (CYCLES), st.accepted\n        the iterations' accepted drafts (their count, from the device's counters). drafts\n        (tests): the draft of each position q (drafts[q], q < cap + 2) instead of the MTP's,\n        from the first iteration's on. deadline (seconds, a card's run_generate): past it the\n        host writes the stop word (st.timed_out; the card halts at its next verify), and 10 s\n        later a run still going raises TimeoutError.\n\n        sampling (generate.Sampling) with rng (a numpy Generator): sampled, as\n        Engine.generate_card(sampling=...) (docs/mtp.md 11): a0 is the sampler's pick from\n        the prefill's logits (generate.reference_pick, the device's arithmetic) with the\n        generator's first uniform, then the run's tokens with its next n, one per position\n        (Engine._generate_inputs); the repetition penalty over `context` (default the prompt)\n        and the tokens. The tokens equal the plain sampled loop's for the same uniforms.\"\"\"\n        samp = sampling\n        if samp is not None and rng is None:\n            raise ValueError(\"a sampled generate_card needs rng (the uniforms)\")\n        st = MTPStats(prompt=len(prompt))\n        t0 = time.perf_counter()\n        ctx = [int(t) for t in (prompt if context is None else context)]\n\n        def pick(lg):\n            u = np.minimum(np.float32(rng.random()), np.float32(1 - 2.0 ** -24))\n            return G.reference_pick(lg, samp, ctx, u, self.img.cfg.S,\n                                    getattr(self.img.spec, \"softcap\", None))\n        a0, d = self.prefill(prompt, st, pick=None if samp is None else pick, lazy=True)\n        st.prefill_s, st.prefill_compile_s = time.perf_counter() - t0, st.compile_s\n        return self.loop_card(a0, d, max_new, stop, on_token, drafts, st, deadline,\n                              samp, ctx + [a0], rng)\n\n    def loop_card(self, a0: int, d: int, max_new: int = 32, stop=None, on_token=None,\n                  drafts=None, st: MTPStats | None = None,\n                  deadline: float | None = None, samp: G.Sampling | None = None,\n                  context=(), rng=None, halt=None) -> MTPStats:\n        \"\"\"generate_card after its prefill: a0 (the token at Engine.pos, emitted) and d (the\n        draft of the next position: self.draft after a prefill or a run) -> the device's run\n        of the MTP loop from the committed slot (see generate_card); sampled with samp, the\n        uniforms from rng and the penalty's context (the ids so far, a0 with them). halt()\n        (polled while a card runs): true writes the host's stop word, as the deadline does.\n        d None after a lazy prefill (self.pending, the prompt's last row at P - 1 and a0): the\n        run starts with that bucket's D1 over (hid[0], a0) at P - 1, as an E's iteration would\n        leave it (n = 0), which drafts d, appends the MTP layer's row and chains to the first\n        verify; its MoE request is served in the run. No run (a0 a stop id, no tokens left):\n        the draft runs on its own (_settle).\"\"\"\n        eng, img = self.eng, self.img\n        spec, block = img.spec, eng.block\n        ids = list(spec.eos if stop is None else stop)\n        st = MTPStats(prompt=eng.pos) if st is None else st\n        st.tokens.append(a0)\n        if on_token is not None:\n            on_token(a0)\n        P = eng.pos\n        n = min(max_new - 1, img.cap - P - 2)\n        lazy = d is None and self.pending is not None\n        if lazy and self.pending != (P - 1, a0):\n            raise ValueError(f\"the pending draft is {self.pending}'s, not ({P - 1}, {a0})'s\")\n        if a0 in ids or n <= 0:\n            self._settle(st)\n            return st\n        if d is None and not lazy:\n            raise ValueError(\"loop_card needs the draft (a prefill's or a run's: self.draft)\")\n        b0, b1 = (P - lazy) // block + 1, (P + n) // block + 1\n        progs = self._gen_programs(b0, b1, st, drafts is not None, samp)\n        g = img.lookup[\"gen\"]\n        if samp is not None:        # u[P + 1 .. P + n], then a stand-in for row 1 of the\n            eng._generate_inputs(samp, P, n, context, rng)      # last verify (not emitted)\n            for s_ in range(img.cfg.S):\n                eng.backend.write(s_, g[\"uni\"] + 4 * (P + n + 1), np.full(1, 0.5, np.float32))\n        if drafts is not None:\n            dt = np.zeros(img.cap + 2, np.float32)\n            dt[:len(drafts)] = np.asarray(drafts, np.float32)[:img.cap + 2]\n            eng.backend.write(0, img.lookup[\"mtpgen\"][\"dtab\"], dt)\n            d = int(dt[P + 1])\n        words = G.state_words(spec, a0, P, n, ids, block, samp)\n        words[S_PAR] = self.slot\n        if lazy:                    # the D1 of P - 1's bucket: an E's iteration there (n = 0),\n            q = P - 1               # the next position P (tpos block: the next bucket's first)\n            words[G.S_TPOS], words[S_TPOS0] = q % block + 1, q % block\n            words[S_A0], words[S_A1], words[S_N] = a0, a0, 0\n            first = progs[(b0, D1)]\n        else:\n            words[S_DRAFT] = d\n            first = progs[(b0, (E0 if P % block == block - 1 else V0) + self.slot)]\n        if getattr(img, \"embed_host\", False):   # the first program's rows: the V's (the E's\n            eng._write_host_rows([a0] if lazy else [a0, d])     # row 0), the D1's a0; then\n        for s_ in range(img.cfg.S):                             # each program posts the next\n            eng.backend.write(s_, g[\"state\"], words)            # one's\n            eng.backend.write(s_, g[\"out\"] + 4 * (P + 1), np.full(n, G.OUT_MARK, np.uint32))\n        self.pending = None\n        run = getattr(eng.backend, \"run_generate\", None)\n        if run is not None:\n            end = None if deadline is None else time.perf_counter() + deadline\n\n            def late() -> bool:\n                if end is not None:\n                    now = time.perf_counter()\n                    if now > end + 10.0:\n                        raise TimeoutError(f\"the MTP loop runs {deadline + 10:.0f} s, its \"\n                                           f\"stop word unanswered\")\n                    st.timed_out = st.timed_out or now > end\n                return st.timed_out or (halt is not None and bool(halt()))\n            stats, got = run(first, g[\"out\"] + 4 * (P + 1), n, on_token,\n                             None if end is None and halt is None else late, g[\"state\"])\n        else:\n            stats = eng.backend.run(first)\n            w = eng.backend.read(0, g[\"out\"] + 4 * (P + 1), 4 * n).view(np.uint32)\n            k = int(np.argmax(w == G.OUT_MARK)) if (w == G.OUT_MARK).any() else n\n            got = [int(x) for x in w[:k].view(np.float32)]\n            if on_token is not None:\n                for t in got:\n                    on_token(t)\n        st.runs.append((\"generate\", len(got), stats))\n        st.tokens += got\n        sw = eng.backend.read(0, g[\"state\"], 4 * G.STATE_WORDS).view(np.float32)\n        self.slot, self.draft = int(sw[S_PAR]), int(sw[S_DRAFT])\n        it, acc = int(sw[S_ITER]), int(sw[S_ACC])\n        st.accepted = [1] * acc + [0] * (it - acc)\n        eng.pos = P + len(got)\n        return st\n\n\n# ---- the loop on the card (docs/mtp.md 10)\n# the state block: generate.py's words, and the iteration's, which the card stores in its own\n# 64-byte beat (words 32..47): not in the host's stop word's (16..31), which the host writes\n# during the run (BoardBackend.run_generate: the beat alone, its words read just before)\nS_DRAFT, S_A0, S_A1, S_N, S_PAR, S_TPOS0, S_ITER, S_ACC = 32, 33, 34, 35, 36, 37, 38, 39\nS_END = 40          # 1.0: the iteration's D halts (a stop id, the host's word, no tokens left)\n# a bucket's programs, in its chain table's order: the verify (V) and the bucket's last\n# position (E) per parity, the MTP layer over two rows (D) and over one (D1)\nKINDS = (\"V0\", \"V1\", \"E0\", \"E1\", \"D\", \"D1\")\nNK = len(KINDS)\nV0, E0, D2, D1 = 0, 2, 4, 5\n\n\ndef gen_alloc(b, cap: int, spec, block: int = ATTN_BLOCK,\n              imem_words: int = 1 << 15, waitc: bool = False) -> dict:\n    \"\"\"DRAM of the MTP loop: a program slot per bucket and kind (with its wait entries on a\n    WAITC device: generate.prog_bytes; a split V's or E's second part in its second half, the\n    part's chain entry at the first half's end: ptab2_addr), and the chain table ([address,\n    instructions] per bucket and kind); the sampled verify's row 1 logits (the generate loop's\n    lg holds row 0's: generate.Sampler).\"\"\"\n    nb, slot = G.buckets(cap, block), G.prog_bytes(imem_words, waitc)\n    return {\"progs\": b.alloc(slot * NK * nb), \"ptab\": b.alloc(8 * NK * nb), \"nb\": nb,\n            \"slot\": slot,\n            \"dtab\": b.alloc(4 * (cap + 2)),     # tests: the draft of each position\n            \"lg\": b.alloc(4 * G._vpad(spec))}\n\n\ndef gen_build(put, s: int, S: int, spec, a: dict) -> None:\n    \"\"\"The row 1 logits' padding: -inf after this slice's rows to a whole block (as\n    generate.build's lg).\"\"\"\n    v_loc = spec.vocab // S\n    put(s, a[\"lg\"], np.full(-(-v_loc // G.BLK) * G.BLK, -np.inf, np.float32))\n\n\ndef prog_addr(a: dict, blocks: int, kind: int) -> int:\n    return a[\"progs\"] + a[\"slot\"] * (NK * (blocks - 1) + kind)\n\n\ndef ptab_addr(a: dict, blocks: int, kind: int = 0) -> int:\n    return a[\"ptab\"] + 8 * (NK * (blocks - 1) + kind)\n\n\ndef ptab2_addr(a: dict, blocks: int, kind: int) -> int:\n    \"\"\"A split kind's second part's [address, instructions] (its first part's HALT CHAIN): the\n    last 8 bytes of the slot's first half, past the first part's words and wait entries (a\n    program of IMEM's instructions with all its entries fills the half: the first part has\n    fewer, _gen_programs). No DRAM of its own: an MTP image's layout is the same, split or\n    not.\"\"\"\n    return prog_addr(a, blocks, kind) + a[\"slot\"] // 2 - 8\n\n\ndef plan_cuts(image) -> list:\n    \"\"\"The layers at which a split V or E may cut (the first layer of each run of the plan but\n    the first: qwen35.plan_span), the most even first (by the runs' count on either side).\"\"\"\n    firsts = [f for f, _, _ in image.plan[1:]]\n    n = len(image.plan)\n    return [f for _, f in sorted((abs(2 * (i + 1) - n), f) for i, f in enumerate(firsts))]\n\n\ndef _flag(x):\n    \"\"\"1.0 where the small integer x is >= 1, else 0.0.\"\"\"\n    return ol.minimum(ol.maximum(x, 0.0), 1.0)\n\n\ndef _hit(st, tok):\n    \"\"\"1.0 when tok is one of the state block's stop ids (integers).\"\"\"\n    ids = st[G.S_STOP:G.S_STOP + G.N_STOP]\n    return ol.max(ol.minimum(ol.abs(ids - tok), 1.0) * -1.0 + 1.0)\n\n\ndef _load_state(b, g):\n    \"\"\"The state block into TMEM, and its LD (the run-time arguments load right after it:\n    the compiler puts its prologue before the program's first instruction, so an index into\n    the program would not stay put).\"\"\"\n    st = ol.load(g.state)\n    return st, b.stack[-1][-1]\n\n\ndef _args(b, at, words: dict) -> None:\n    \"\"\"The run-time arguments (c * var alone in an address) loaded from their state words\n    right after the instruction `at` (the state's LD), now that the program has named them\n    all.\"\"\"\n    body = b.stack[-1]\n    i = next(j for j, x in enumerate(body) if x is at) + 1\n    body[i:i] = [I.rld(15 - k, words[v.name], mul=int(c), comment=f\"argument {c}*{v.name}\")\n                 for k, (v, c) in enumerate(b.run_args)]\n    b.run_words = None\n\n\ndef _post_rows(m, toks) -> None:\n    \"\"\"With the int8 embedding table on the host (embed_host: a MoE's), the post of the next\n    program's tokens (one request of their ids and count: RowServer writes their rows to the\n    slot's rows 0 .. n - 1, which the next program's rows gather once served). The verify's\n    (a0, a1) for the D (a0 for the D1), the draft's (t, d) for the next V (row 0 the E's).\"\"\"\n    mbox = getattr(m, \"embed_mbox\", None)\n    if mbox is None:\n        return\n    ids = ol.empty((len(toks),))\n    for r, t in enumerate(toks):\n        ids[r:r + 1].set(t)\n    MB.post(mbox, ids, count=True)\n    del ids\n\n\ndef _store_state(g, st) -> None:\n    \"\"\"The state block to DRAM, but the host's stop word and the sampler's.\"\"\"\n    ol.store(g.state[:G.S_HALT], st[:G.S_HALT])\n    ol.store(g.state[S_DRAFT:S_END + 1], st[S_DRAFT:S_END + 1])\n\n\ndef _verify_gen(m, pos, block: int, c: int, R: int, samp: G.Sampling | None = None,\n                part: int | None = None, cut: int = 0):\n    \"\"\"V (R = 2: rows t, d at p, p + 1) or E (R = 1: t at the bucket's last position) of\n    parity c: the rows kernel (fork, hidden) with an ARGMAX per row, or with samp the sampled\n    loop's pick (generate.Sampler: row r with the uniform of position p + 1 + r, row 1's\n    logits in the MTP area's lg); a0 -> out[p + 1], and with the draft accepted (d == a0,\n    tokens left, a0 not a stop id) a1 -> out[p + 2]; the iteration's words and the commit (the\n    penalty's context gets the emitted ids); S_END at a stop id, the host's stop word or no\n    tokens left; then HALT CHAIN to the bucket's D or D1 (which halts at S_END). Sampled,\n    accepting d iff the pick a0 equals it is speculative sampling for the one-hot draft\n    (docs/mtp.md 11.1).\n\n    part 0 / 1 (a V or E over IMEM: compile_gen's split form): part 0 the layers before `cut`\n    (the rows' embedding rows gathered), their residual to m.hid (the hidden rows, which part\n    1 writes at its end), then HALT CHAIN to part 1 through its entry (ptab2_addr); part 1 the\n    layers from `cut` on (the residual from m.hid), the head and the rest as above. The same\n    operations: the residual's fp32 rows only pass through DRAM.\"\"\"\n    from .qwen35 import qwen35_rows\n    b = current()\n    g, a = m.gen, m.mtpgen\n    st, at = _load_state(b, g)\n    words = {\"tok\": st.base + G.S_TOK, \"tok1\": st.base + S_DRAFT, \"tpos\": st.base + G.S_TPOS}\n    b.run_words = words\n    span = xs = None\n    if part is not None:\n        span = (0, cut) if part == 0 else (cut, m.spec.layers)\n        xs = m.hid\n    if part == 0:\n        qwen35_rows.fn(m, pos, R, [], block, None, R > 1, False, span, xs, False)  # (not nested)\n        _args(b, at, words)\n        G._chain(b, ptab2_addr(a, pos.blocks, (V0 if R > 1 else E0) + c),\n                 what=\"the verify's second part\")\n        return\n    if samp is None:\n        m.lm_sinks = [G.Greedy(b, m.v_loc, head_rows_chunk(R)) for _ in range(R)]\n    else:\n        if b.S != 1:\n            raise CompileError(\"the sampled MTP loop runs on one slice\")\n        consts = G.Sampler.constants(b, g, samp)\n        m.lm_sinks = []\n        for r in range(R):          # row 1 takes row 0's penalty factors of each chunk\n            m.lm_sinks.append(G.Sampler(b, m, g, samp, st, pos, consts,\n                                        lg=a[\"lg\"] if r else None, u_at=pos.pos + 1 + r,\n                                        pen_from=m.lm_sinks[0] if r else None))\n    qwen35_rows.fn(m, pos, R, list(range(R)), block, None, R > 1, True, span, xs,\n                   False)                                               # (not nested)\n    if samp is not None and samp.pen and R > 1:\n        _penalize_draft(b, g, st, m.lm_sinks[1])\n    toks = [sk.token() for sk in m.lm_sinks]\n    sinks, m.lm_sinks = m.lm_sinks, None\n    a0, a1 = toks[0], toks[-1]\n    _post_rows(m, toks)                 # embed_host: the D's rows (a0, a1), D1's (a0)\n    left, tpos = st[G.S_LEFT:G.S_LEFT + 1], st[G.S_TPOS:G.S_TPOS + 1]\n    stop = _hit(st, a0)\n    ol.store(g.out[pos.pos + 1:pos.pos + 2], a0)\n    if samp is not None:\n        sinks[0].after(a0)\n    if R > 1:\n        d = st[S_DRAFT:S_DRAFT + 1]\n        n = (ol.minimum(ol.abs(d - a0), 1.0) * -1.0 + 1.0) * _flag(left - 1.0) * \\\n            (stop * -1.0 + 1.0)\n        r = b.scratch()\n        b.rld(r, n, comment=\"accepted\")\n        lp = b.begin_loop(0, rcount=r)\n        b.unscratch(r)\n        ol.store(g.out[pos.pos + 2:pos.pos + 3], a1)\n        if samp is not None:\n            sinks[1].after(a1)\n        b.end_loop(lp)\n        stop = ol.maximum(stop, _hit(st, a1) * n)\n        st[G.S_TOK:G.S_TOK + 1].set(a0 + n * (a1 - a0))\n        st[S_PAR:S_PAR + 1].set(n if c == 0 else n * -1.0 + 1.0)\n    else:\n        n = ol.zeros([1])\n        st[G.S_TOK:G.S_TOK + 1].set(a0)\n        st[S_PAR:S_PAR + 1].set(float(c))\n    st[S_A0:S_A0 + 1].set(a0)\n    st[S_A1:S_A1 + 1].set(a1)\n    st[S_N:S_N + 1].set(n)\n    st[S_TPOS0:S_TPOS0 + 1].set(tpos)\n    tpos.set(tpos + n + 1.0)\n    left.set(left - n - 1.0)\n    st[S_ITER:S_ITER + 1].set(st[S_ITER:S_ITER + 1] + 1.0)\n    st[S_ACC:S_ACC + 1].set(st[S_ACC:S_ACC + 1] + n)\n    st[S_END:S_END + 1].set(ol.maximum(ol.maximum(stop, ol.load(g.state[G.S_HALT:G.S_HALT + 1])),\n                                       _flag(left * -1.0 + 1.0)))\n    _args(b, at, words)\n    _store_state(g, st)\n    G._chain(b, ptab_addr(a, pos.blocks, D2 if R > 1 else D1), what=\"the draft\")\n\n\ndef _penalize_draft(b, g, st, sk) -> None:\n    \"\"\"Row 1 follows the draft d, so its repetition penalty counts d as in the context (row 0's\n    must not: both rows' chunks took the context's factors pa, pb). Row 1's stored logit x of\n    d stays when d is in the context already (pb[d] = R > 1), else (x the raw logit then)\n    becomes min(x / R, x * R), as Sampler.after's factors would give; a select by min/max with\n    +-2^127, exact for finite logits (x * R / R would round). Then the maximum of d's block\n    again (one slice: the row is d).\"\"\"\n    d = st[S_DRAFT:S_DRAFT + 1]\n    t = b.alloc((2,))\n    blk = b.alloc((G.BLK,))\n    r, rk, rb_ = b.scratch(), b.scratch(), b.scratch()\n    b.rld(r, d * 4.0, comment=\"the draft's bytes\")\n    b.emit(I.ld(g.addr[\"pb\"], t.base, 1, ra=r, comment=\"pb[d]\"))\n    b.emit(I.ld(sk.lg, t.base + 1, 1, ra=r, comment=\"row 1's logit of d\"))\n    pb, x = t[0:1], t[1:2]\n    z = ol.minimum(x * st[G.S_PENINV:G.S_PENINV + 1], x * st[G.S_PEN:G.S_PEN + 1])\n    s = (G._step(pb - 1.0) * 2.0 - 1.0) * 2.0 ** 127        # +2^127: d in the context\n    y = ol.maximum(ol.minimum(z, s * -1.0), ol.minimum(x, s))\n    b.emit(I.st(sk.lg, y.base, 1, ra=r, comment=\"penalized\"))\n    k = d * (1.0 / G.BLK)                                   # d's block (f2i: the floor)\n    b.emit(I.rld(rk, k.base, mul=4 * G.BLK, comment=\"its bytes\"))\n    b.emit(I.rld(rb_, k.base, comment=\"its index\"))\n    b.emit(I.ld(sk.lg, blk.base, G.BLK, ra=rk, comment=\"d's block\"))\n    b.emit(I.vop(I.V_RMAX, sk.bm.base, blk.base, 0, 1, G.BLK, 1, G.BLK, 0, ra=rb_,\n                 comment=\"its maximum\"))\n    for x_ in (r, rk, rb_):\n        b.unscratch(x_)\n\n\ndef _draft_gen(m, pos, block: int, R: int, forced: bool = False):\n    \"\"\"D (R = 2) or D1 (R = 1): the MTP layer over the iteration's rows (hid_r, a_r) at p ..\n    (qwen35_mtp), the next draft d = draft[n]; the position moves on (to the next bucket at\n    its end), then HALT CHAIN to the next iteration's program: V or E (tpos = block - 1) of\n    the committed parity, in this bucket or the next; HALT when the verify ended the loop\n    (S_END): the MTP layer's KV cache then holds every position before the last token's, and\n    S_DRAFT the draft after it, so a later run or prefill continues from there. forced\n    (tests): the draft of the next iteration's row 1 (position p + 2 + n) from the host's\n    table (dtab) instead.\"\"\"\n    from .qwen35 import qwen35_mtp\n    b = current()\n    g, a = m.gen, m.mtpgen\n    st, at = _load_state(b, g)\n    words = {\"tok\": st.base + S_A0, \"tok1\": st.base + S_A1, \"tpos\": st.base + S_TPOS0}\n    b.run_words = words\n    drafts = qwen35_mtp.fn(m, pos, R, block)\n    _args(b, at, words)\n    n = st[S_N:S_N + 1]\n    st[S_DRAFT:S_DRAFT + 1].set(drafts[0] if R == 1 else drafts[0] + n * (drafts[1] - drafts[0]))\n    if forced:\n        r = b.scratch()\n        b.rld(r, (st[S_TPOS0:S_TPOS0 + 1] + n) * 4.0, comment=\"the draft's position\")\n        b.emit(I.ld(a[\"dtab\"] + 4 * (pos.t0 + 2), st.base + S_DRAFT, 1, ra=r,\n                    comment=\"the host's draft\"))\n        b.unscratch(r)\n    _post_rows(m, [st[G.S_TOK:G.S_TOK + 1], st[S_DRAFT:S_DRAFT + 1]])   # the next V's (E's)\n    tp = st[G.S_TPOS:G.S_TPOS + 1]                      # the next position's: 1 .. block\n    wrap = _flag(tp - float(block - 1))                 # block: the next bucket's first\n    tp.set(tp - wrap * float(block))\n    end = _flag(tp - float(block - 2))                  # block - 1: the bucket's E\n    off = (wrap * float(NK) + end * 2.0 + st[S_PAR:S_PAR + 1]) * 8.0\n    _store_state(g, st)\n    G._chain(b, ptab_addr(a, pos.blocks), cond=st[S_END:S_END + 1] * -1.0 + 1.0, off=off,\n             what=\"the next iteration\")\n    b.emit(I.halt())\n\n\ndef compile_gen(image, blocks: int, kind: int, block: int = ATTN_BLOCK,\n                forced: bool = False, samp: G.Sampling | None = None,\n                part: int | None = None, cut: int = 0) -> list | None:\n    \"\"\"Program KINDS[kind] of bucket `blocks` of the MTP loop (docs/mtp.md 10), one per slice;\n    None when the bucket has no such position (E and D1 past the KV cache's end). forced\n    (tests): D and D1 take the drafts from the host's table (_draft_gen). samp: V and E\n    sample (docs/mtp.md 11), D and D1 are the same either way. part 0 / 1: a V's or E's\n    split form, cut at layer `cut` (a run's first: plan_cuts).\"\"\"\n    name = KINDS[kind]\n    if part is not None and (name[0] not in \"VE\" or cut not in plan_cuts(image)):\n        raise ValueError(f\"a split {name}: a V or E cut at a run of the plan\")\n    R = 1 if name in (\"E0\", \"E1\", \"D1\") else 2\n    t0 = (blocks - 1) * block\n    lo = t0 + block - 1 if R == 1 else max(t0, image.spec.conv_k - 1)\n    if lo + R > image.cap or \"mtpgen\" not in image.lookup:\n        if \"mtpgen\" not in image.lookup:\n            raise ValueError(\"the MTP loop needs an MTP image with lookup tables\")\n        return None\n    rp = RunRows(blocks, block, lo, image.lookup[\"zmask\"], image.cap, R)\n    c = int(name[1]) if name[0] in \"VE\" else 0\n    fn, kw = ((_verify_gen, {\"c\": c, \"R\": R, \"samp\": samp, \"part\": part, \"cut\": cut})\n              if name[0] in \"VE\" else (_draft_gen, {\"R\": R, \"forced\": forced}))\n    return [ol.jit(fn).trace(image.cfg, s, {\"m\": image.descriptors(s, c), \"pos\": rp,\n                                            \"block\": block, **kw}).finish()\n            for s in range(image.cfg.S)]\n", "opentpu/llm/prefill.py": "\"\"\"A prompt's prefill from programs at run-time positions (docs/prefill.md).\n\nThe host writes the prompt's tokens to the generate area's out[] (the token at each position),\nthen runs one program per run of up to R_max rows: P (rows), L (the prompt's last run: its last\nrow's logits) and, on an MTP image, M (the MTP layer over the run's rows) after each. A program\ntakes its position from the generate state's tpos word and its tokens from out[], so it serves\nevery run of its bucket and kind, and the engine keeps it (and the program cache across\nprocesses): the host compiles nothing per prompt. The rows before conv_k - 1 (a new context's\nfirst run) are at compile-time positions, cached the same way.\n\nThe runs' split depends only on the first position, the prompt's length, R_max and the attention\nblock: R_max rows a run, cut where a run would cross a bucket's end (a run-time run's rows stay in\nits bucket). R_max, per bucket: the most rows in fit_chunk's sizes (one MXU pass of MCOLS rows,\nthen whole passes, at most the image's rows; Qwen3.5: one pass) whose L program in that bucket\ncompiles and fits IMEM (a later bucket's attention makes a longer\nprogram: Phi-4-mini's mix takes 3 rows in bucket 1, 1 in bucket 16). Plain and MTP engines of a\nmodel take the same split, so their logits are the same bit for bit. Where today's prefill\n(compile_rows) would fit more rows in a bucket than its prompt run, a prompt that reaches the\nbucket takes today's route (covers).\n\nTiled runs (opentpu/llm/tiled.py, docs/tiled_prefill.md), on by default (off with the engine's\ntile_runs False, or OTPU_TILE=0 where the engine does not say: tile_flag): a bucket's P and L\nruns are tile_run's programs of up to T rows (_probe_tile: whole passes of MCOLS up to ACT_ROWS\nand the image's rows, every run a prompt can ask for in the bucket fitting TMEM and IMEM), each\nweight streamed once a run; a bucket where no tile fits, or where today's prompt runs (covering\nit) take more rows than the tile (tiled), takes today's prompt runs. MTP's M runs stay today's.\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nimport threading\nimport time\n\nimport numpy as np\n\nfrom .. import progcache as PC\nfrom ..compiler import CompileError\nfrom . import generate as G\nfrom . import tiled as TL\nfrom .qwen3 import RUN_WORDS\n\n\ndef split(p0: int, P: int, R_max, block: int, K: int) -> list[tuple[int, int, str]]:\n    \"\"\"The runs (first position, rows, kind) of the prompt positions [p0, P). R_max: the most\n    rows of a run, an int, or R_max(blocks) for bucket `blocks` (0: the first run of a new\n    context, before conv_k - 1).\"\"\"\n    rm = R_max if callable(R_max) else (lambda blocks: R_max)\n    runs, p = [], p0\n    while p < P:\n        if p >= K - 1:                      # a run-time run: its rows in one bucket\n            n = min(rm(p // block + 1), P - p, block - p % block)\n        else:                               # a new context's first run (R_max(0))\n            n = min(rm(0), P - p)\n        runs.append((p, n, \"L\" if p + n == P else \"P\"))\n        p += n\n    return runs\n\n\ndef conv_k(eng) -> int:\n    \"\"\"The model's convolution taps (Qwen3.5's DeltaNet, LFM2's): its first conv_k - 1\n    positions run at compile-time positions; 1 without.\"\"\"\n    return getattr(eng.spec, \"conv_k\", 1)\n\n\ndef supported(eng) -> bool:\n    \"\"\"The engine's image runs prompts this way: a dense model's resident image, without\n    rows the host writes before each run unless its prompt runs read them (prompt_host_rows:\n    Gemma 4's PLE records on the host, written before each run).\"\"\"\n    img = eng.image\n    host = (eng._host_rows is not None and bool(eng._host_rows([0]))) or \\\n        getattr(eng, \"row_server\", None) is not None\n    return (hasattr(img, \"compile_prompt_run\") and bool(getattr(img, \"lookup\", None))\n            and getattr(eng.spec, \"moe\", None) is None and not getattr(eng.spec, \"experts\", 0)\n            and (not host or getattr(img, \"prompt_host_rows\", False)))\n\n\ndef tile_flag(t) -> bool:\n    \"\"\"Tiled prompt runs asked for: t (an engine's tile_runs), or where it is None OTPU_TILE:\n    on unless it is 0 (unset or empty: the default, on; in the reference cache's key as it is\n    set: tools/qual/refs.py env_key). Their bits are today's prompt runs' (docs/tiled_prefill.md\n    11).\"\"\"\n    if t is None:\n        t = os.environ.get(\"OTPU_TILE\", \"\").strip() != \"0\"\n    return bool(t)\n\n\ndef layer_tile_flag(t, default: bool = False) -> bool:\n    \"\"\"A MoE model's tiled expert-major layer runs asked for (Engine.layer_tile, with\n    expert_major), and so its image's mask tiles as it is built. t (an engine's tile_runs) True,\n    or where it is None OTPU_TILE: for a family whose tiles are on by default (`default`:\n    Qwen3.5-MoE's, tiled.LAYER_ROWS: their whole forms are today's bits, docs/tiled_prefill.md\n    14) on unless it is 0, as the prompt runs' tile_flag; for the others (Gemma 4's: opt-in)\n    set and not 0.\"\"\"\n    if t is None:\n        v = os.environ.get(\"OTPU_TILE\", \"\").strip()\n        t = v != \"0\" if default else v not in (\"\", \"0\")\n    return bool(t)\n\n\ndef tile_scratch(spec, layer_runs: bool, default: bool = False) -> bool:\n    \"\"\"An image holds the tiled runs' I/O scratch (io \"o\": the attention's outputs a part at a\n    time, loaded back whole: tiled.py): a dense model's (its tiled prompt runs, the default);\n    a MoE model's only where its family has tiled layer runs (layer_runs) and they are asked for\n    as the image is built (layer_tile_flag, the family's `default`), so a MoE image's layout and\n    expert slots without them stay as they were.\"\"\"\n    moe = getattr(spec, \"moe\", None) is not None or bool(getattr(spec, \"experts\", 0))\n    return not moe or (layer_runs and layer_tile_flag(None, default))\n\n\ndef tiling(eng) -> bool:\n    \"\"\"Tiled prompt runs on (opentpu/llm/tiled.py): tile_flag of the engine's tile_runs, for\n    an image whose family has a tile kernel, on one slice (tiled.check: a configuration of\n    more, the design point's two, takes today's runs).\"\"\"\n    img = eng.image\n    return tile_flag(getattr(eng, \"tile_runs\", None)) and TL.family(img) is not None \\\n        and img.cfg.S == 1\n\n\ndef programs(eng, p: int, R: int, kind: str, hidden: bool = False, slot: int = 0,\n             tile: bool | None = None):\n    \"\"\"The run's (programs, the state words it reads) (kept by the engine; through its\n    program cache): the programs, or on the card (runs_words) the program assembled once, so\n    a run of another program loads its words, not an assembly of them (3-5 ms a run; MTP's\n    rows and M runs alternate). hidden, slot: MTP's rows (their hidden stored, the states'\n    slot); M's take neither. tile: a tiled run (True), today's (False), or the bucket's\n    choice (None: tiled).\"\"\"\n    done = eng.__dict__.setdefault(\"_prompt_progs\", {})\n    what, blocks, compile = _what(eng, p, R, kind, hidden, slot, tile)\n    with _lock(eng):\n        if what not in done:\n            done[what] = _prepared(eng, what, blocks, *eng.cached(what, compile))\n    return done[what]\n\n\ndef _what(eng, p: int, R: int, kind: str, hidden: bool = False, slot: int = 0,\n          tile: bool | None = None):\n    \"\"\"A run's (program cache key, bucket (0: compile-time positions), compile()); tile as\n    programs'.\"\"\"\n    img, block = eng.image, eng.block\n    if kind == \"M\":\n        hidden, slot = False, 0\n    kw = dict(hidden=hidden, slot=slot) if hidden or slot else {}\n    if p < conv_k(eng) - 1:\n        blocks, kw[\"p0\"] = 0, p\n        what = (\"prompt\", kind, R, \"at\", p, hidden, slot)\n    else:\n        blocks = p // block + 1\n        if tile is None:\n            tile = kind != \"M\" and tiled(eng, blocks)\n        if tile and kind != \"M\":\n            what = (\"prompt tile\", kind, R, blocks, hidden, slot)\n            return what, blocks, lambda: TL.compile_tile_run(img, blocks, R, kind, block, **kw)\n        what = (\"prompt\", kind, R, blocks, hidden, slot)\n    return what, blocks, lambda: img.compile_prompt_run(blocks, R, kind, block, **kw)\n\n\ndef _prepared(eng, what, blocks: int, progs, ra):\n    \"\"\"programs()' entry of a compiled run (blocks 0: a compile-time one).\"\"\"\n    img = eng.image\n    if not G.fits(img, progs):\n        raise CompileError(f\"prompt run {what}: {max(map(len, progs))} instructions, \"\n                           f\"IMEM {img.cfg.IMEM_WORDS // 8}\")\n    # the words the run reads: its arguments', and those its addresses add with a loop's\n    # step (Program.run_seen: a register loaded from the word before the loop, no argument)\n    names = {v.name for v, _ in ra or ()} | \\\n        {v.name for p in progs for v, _ in getattr(p, \"run_seen\", ())}\n    prep = getattr(eng.backend, \"prepare\", None)\n    if getattr(eng.backend, \"runs_words\", False) and len(progs) == 1:   # (Words: run_args;\n        from .qwen3 import worker_words                                 # WAITC: the entries)\n        progs = worker_words(img, progs[0], ra or getattr(progs[0], \"run_args\", ()))\n    elif prep is not None:\n        prep(progs)\n    if blocks:                      # a run-time run: and the words its kernel reads itself\n        names |= set(getattr(img, \"prompt_words\", ()))\n    return progs, sorted(names)\n\n\ndef r_max(eng, blocks: int = 1) -> int:\n    \"\"\"The most rows of a run in bucket `blocks`: fit_chunk's sizes (one MXU pass, then whole\n    passes) up to the image's rows (Qwen3.5: one pass), the bucket's (plain) L program\n    compiled and fitting IMEM (kept by the engine). MTP's runs take the same R_max (their\n    programs must fit it), so plain and MTP prefills of a model split alike. With the engine's program cache the answer is kept there\n    too (progcache.fact), so a new process does not try the larger R again (the 4B's R = 4,\n    traced until TMEM runs out). Tiled runs (tiled): the bucket's tile rows.\"\"\"\n    if tiled(eng, blocks):\n        return _tile_fit(eng, blocks)\n    return _fit(eng, blocks)[0]\n\n\ndef tiled(eng, blocks: int) -> bool:\n    \"\"\"Bucket `blocks`'s P and L runs tiled: tiling on, a tile fits the bucket, and today's\n    prompt runs (which cover it) take fewer rows there. Each run is a pass of the weights, so\n    the form with more rows a run streams them less often (release r2: LFM2-2.6B's tile took 1\n    row at MCOLS 4 and 2 at 8 where today's runs take 4, and its chat prefill ran at half the\n    speed of the untiled one); on a tie today's runs, which were 0.4-1.2% faster at equal rows\n    and bytes on every production dense model (docs/tiled_prefill.md 12.4). Where a tile takes\n    as many rows as today's runs could (Qwen3-0.6B's 16) nothing more is compiled to know it:\n    no production model's today's runs reach those rows.\"\"\"\n    if not (blocks and tiling(eng)):\n        return False\n    T = _tile_fit(eng, blocks)\n    if not T:\n        return False\n    if T >= _probe_top(eng, blocks):\n        return True\n    try:\n        R, covered = _fit(eng, blocks)\n    except CompileError:                # (no prompt run of today's fits the bucket)\n        return True\n    return not (covered and R >= T)\n\n\ndef _probe_top(eng, blocks: int) -> int:\n    \"\"\"The largest of _probe's run sizes in bucket `blocks` (blocks > 0).\"\"\"\n    from .qwen3 import _whole_passes\n    img, mc = eng.image, eng.image.cfg.MCOLS\n    p = max((blocks - 1) * eng.block, conv_k(eng) - 1)\n    return _whole_passes(min(img.rows, img.cap - p,\n                             mc if hasattr(eng.spec, \"mtp\") else img.rows), mc)\n\n\ndef covers(eng, p0: int, P: int) -> bool:\n    \"\"\"Prompt runs take the positions [p0, P): in every bucket they touch a run takes today's\n    rows (compile_rows, fit_chunk's; Qwen3.5's up to one MXU pass), so they stream no weight\n    more often and run no more often (docs/prefill.md 7); else Engine.prefill_chunks and\n    MTPDecoder.prefill take today's route for the prompt.\"\"\"\n    P = min(P, eng.cap)                 # (past the cache: the route's own error)\n    return all(tiled(eng, b) or _fit(eng, b)[1]\n               for b in range(p0 // eng.block + 1, (P - 1) // eng.block + 2))\n\n\ndef _fit(eng, blocks: int):\n    \"\"\"(R_max, covered) of bucket `blocks` (_probe), kept by the engine and the program\n    cache.\"\"\"\n    done = eng.__dict__.setdefault(\"_prompt_rmax\", {})\n    with _lock(eng):\n        if blocks not in done:\n            what = (\"prompt fit\", blocks)\n            done[blocks] = tuple(PC.fact(eng.layout, what, lambda: _probe(eng, blocks))\n                                 if eng.prog_cache else _probe(eng, blocks))\n        return done[blocks]\n\n\ndef _probe(eng, blocks: int) -> list:\n    \"\"\"[R_max, covered] of bucket `blocks`: the largest of fit_chunk's run sizes (up to MCOLS\n    rows, then whole passes of MCOLS up to the image's rows; Qwen3.5's, whose MTP runs take\n    R_max too, one pass at most) at which every run a prompt can ask for in the bucket fits\n    (_kinds: P and L, MTP's rows and M, at every R' <= R: the split cuts a run at the prompt's\n    and the bucket's end), then prefer_rows' choice (an odd R's R - 1 where PAIR makes it\n    cheaper per row); covered when compile_rows (today's prefill) does not fit the next larger\n    size there either, or would take no more rows by the same choice (a prompt program larger\n    than today's would run fewer rows). blocks 0: a new context's first run, at compile-time\n    positions 0 .. conv_k - 2 (convolutions), sized on its own (LFM2.5-230M's fits 8 rows at a\n    run-time position, 4 from position 0; LFM2-2.6B's 4 from 0, not from 1), covered.\"\"\"\n    from .qwen3 import _whole_passes, prefer_rows\n    img, block, mc, K = eng.image, eng.block, eng.image.cfg.MCOLS, conv_k(eng)\n    ps = range(K - 1) if not blocks else [max((blocks - 1) * block, K - 1)]\n    n = _whole_passes(min(img.rows, img.cap - ps[-1],\n                          mc if hasattr(eng.spec, \"mtp\") else img.rows), mc)\n    sizes = []\n    while n:\n        sizes.append(n)\n        n = _whole_passes(n - 1, mc)\n    kinds = _kinds(eng)\n    for i, R in enumerate(sizes):\n        if all(_fits(lambda: programs(eng, p, r, k, h, tile=False)) for r in range(R, 0, -1)\n               for k, h in kinds for p in ps):\n            break\n    else:\n        raise CompileError(f\"no prompt run fits bucket {blocks}\")\n\n    def cost(r):                    # a run of r rows without logits, its programs\n        what, _, compile = _what(eng, ps[0], r, \"P\", tile=False)\n        return eng.cached(what, compile)[0]\n    R = prefer_rows(img, R, cost)\n    if i == 0 or not blocks:\n        return [R, True]\n    up = sizes[i - 1]               # today's next larger size: fits, and would take more rows?\n    return [R, not _fits(lambda: _today(eng, ps[0], up)) or\n            prefer_rows(img, up, lambda r: _today(eng, ps[0], r, logits=False)) <= R]\n\n\ndef _tile_fit(eng, blocks: int) -> int:\n    \"\"\"The tile rows of bucket `blocks` (_probe_tile; 0: none fits), kept by the engine and\n    the program cache.\"\"\"\n    done = eng.__dict__.setdefault(\"_prompt_tile\", {})\n    with _lock(eng):\n        if blocks not in done:\n            what = (\"prompt tile fit\", blocks)\n            done[blocks] = int(PC.fact(eng.layout, what, lambda: _probe_tile(eng, blocks))\n                               if eng.prog_cache else _probe_tile(eng, blocks))\n        return done[blocks]\n\n\ndef _probe_tile(eng, blocks: int) -> int:\n    \"\"\"The rows T of a tiled run in bucket `blocks` (from conv_k - 1): the largest of the sizes\n    up to ACT_ROWS, the image's rows and the bucket's room (whole passes of MCOLS above\n    MCOLS rows, as _probe's) at which every run a prompt can ask for in the bucket fits (_kinds\n    at every R <= T: tiled P and L, today's M), then an odd T's T - 1 where PAIR makes it\n    cheaper a row (prefer_rows' rule: PREFER_MARGIN less MXU time a row); 0 where none fits.\"\"\"\n    from .qwen3 import PREFER_MARGIN, _whole_passes, mxu_time\n    img, block, mc = eng.image, eng.block, eng.image.cfg.MCOLS\n    p = max((blocks - 1) * block, conv_k(eng) - 1)\n    room = min(img.rows, img.cfg.act_rows, img.cap - p, block - p % block)\n    if room <= 0:\n        return 0\n    n, sizes = _whole_passes(room, mc), []\n    while n:\n        sizes.append(n)\n        n = _whole_passes(n - 1, mc)\n    kinds = _kinds(eng)\n    for T in sizes:\n        if all(_fits(lambda: programs(eng, p, r, k, h, tile=k != \"M\")) for r in range(T, 0, -1)\n               for k, h in kinds):\n            break\n    else:\n        return 0\n    if T >= 3 and T % 2:\n        def cost(r):\n            what, _, compile = _what(eng, p, r, \"P\", tile=True)\n            return mxu_time(eng.cached(what, compile)[0]) / r\n        if cost(T - 1) <= (1 - PREFER_MARGIN) * cost(T):\n            T -= 1\n    return T\n\n\ndef _kinds(eng) -> list:\n    \"\"\"The (kind, hidden) of the runs a prompt asks for: P and L; an MTP engine's rows (their\n    hidden) and its MTP layer's M.\"\"\"\n    if getattr(eng.spec, \"mtp\", False):\n        return [(\"L\", True), (\"P\", True), (\"M\", False)]\n    return [(\"L\", False), (\"P\", False)]\n\n\ndef _fits(compile) -> bool:\n    \"\"\"compile() compiles and fits IMEM; False where TMEM, ACT RAM or IMEM do not hold it.\"\"\"\n    try:\n        compile()\n    except CompileError as e:\n        if not any(w in str(e) for w in (\"TMEM\", \"ACT RAM\", \"IMEM\")):\n            raise\n        return False\n    return True\n\n\ndef _today(eng, p: int, n: int, logits: bool = True):\n    \"\"\"Today's run of n rows at p (compile_rows), the prompt's last with logits; its programs,\n    CompileError where they do not fit.\"\"\"\n    img = eng.image\n    progs = img.compile_rows([(0, p + j) for j in range(n)], [n - 1] if logits else [],\n                             eng.block, **eng._tokens_kw([0] * n))\n    if not G.fits(img, progs):\n        raise CompileError(f\"rows at {p}: {max(map(len, progs))} instructions, IMEM\")\n    return progs\n\n\ndef _lock(eng):\n    \"\"\"The engine's lock over its prompt programs (warm's thread compiles them too).\"\"\"\n    return eng.__dict__.setdefault(\"_prompt_lock\", threading.RLock())\n\n\ndef warm(eng) -> None:\n    \"\"\"Bucket 1's prompt programs ahead, on a thread, when the engine starts: R_max, a new\n    context's first (compile-time) run, and the bucket's P and L runs, MTP's (hidden rows, the\n    MTP layer) on an MTP image, from the program cache or compiled, while the host waits for\n    a prompt (a chat). A prompt that comes first takes the lock in turn: none is compiled\n    twice. Engines without the pipeline (the simulators' tests) warm nothing.\"\"\"\n    if not (eng.prompt_runs and eng.pipeline and supported(eng)):\n        return\n\n    def go():\n        try:\n            R, K = r_max(eng, 1), conv_k(eng)\n            mtp = bool(getattr(eng.spec, \"mtp\", False))\n            todo = [(0, r_max(eng, 0), \"P\")] if K > 1 else []\n            todo += [(K - 1 if K > 1 else 0, r, k) for r in range(R, 0, -1)\n                     for k in ((\"P\", \"L\") if r == R else (\"L\",))]\n            for p, r, k in todo:\n                programs(eng, p, r, k, mtp, 0)\n                if mtp:\n                    programs(eng, p, r, \"M\")\n        except Exception:           # (the prompt meets the same error and reports it)\n            pass\n    eng._prompt_warm = threading.Thread(target=go, daemon=True, name=\"otpu-prompt-warm\")\n    eng._prompt_warm.start()\n\n\ndef write_tokens(eng, p0: int, tokens) -> None:\n    \"\"\"The prompt's tokens to out[p0 ..] (every slice's).\"\"\"\n    g = eng.image.lookup[\"gen\"]\n    t = np.asarray(tokens, np.float32)\n    for s in range(eng.cfg.S):\n        eng.backend.write(s, g[\"out\"] + 4 * p0, t)\n\n\ndef words(eng, names, p: int, R: int) -> dict:\n    \"\"\"The state words (qwen3.RUN_WORDS) of a run of R rows at p: tpos; LFM2's ring, the\n    first row of the last K in its state ring ((p + 1) mod K), and ringo, the rotation of the\n    ring after the run (-(p + R) mod K, lfm2._ring_store).\"\"\"\n    K = conv_k(eng)\n    v = {\"tpos\": p % eng.block, \"ring\": (p + 1) % K, \"ringo\": -(p + R) % K}\n    return {RUN_WORDS[n]: v[n] for n in names}\n\n\ndef run(eng, entry, p: int, R: int, tokens=()) -> dict:\n    \"\"\"One run at position p (programs' entry): the state words it reads written first, and\n    on an image whose prompt runs read host rows (prompt_host_rows) the run's tokens' rows.\"\"\"\n    progs, names = entry\n    if getattr(eng.image, \"prompt_host_rows\", False):\n        eng._write_host_rows(tokens)\n    if names:\n        g, w = eng.image.lookup[\"gen\"], words(eng, names, p, R)\n        for a, b in _ranges(sorted(w)):\n            x = np.array([w[i] for i in range(a, b)], np.float32)\n            for s in range(eng.cfg.S):\n                eng.backend.write(s, g[\"state\"] + 4 * a, x)\n    st = eng.backend.run(progs)\n    st[\"rows\"] = R\n    return st\n\n\ndef _ranges(ws):\n    \"\"\"Runs [a, b) of consecutive word indices.\"\"\"\n    out = []\n    for i in ws:\n        if out and out[-1][1] == i:\n            out[-1][1] = i + 1\n        else:\n            out.append([i, i + 1])\n    return out\n\n\ndef logits(eng, R: int) -> np.ndarray:\n    \"\"\"The L run's last row's logits.\"\"\"\n    io, S, v, v_loc = eng.image.io, eng.cfg.S, eng.spec.vocab, eng.image.v_loc\n    return np.concatenate([eng.backend.read(s, io[\"logits\"] + 4 * ((R - 1) * v + s * v_loc),\n                                            4 * v_loc).view(np.float32) for s in range(S)])\n\n\ndef chunks(eng, tokens, head: bool = True):\n    \"\"\"Engine.prefill_chunks's runs this way: yields (the run's tokens, logits after the\n    prompt's last token with the last run, else None; without `head` every run is a P).\"\"\"\n    tokens = [int(t) for t in tokens]\n    p0 = eng.poss[0]\n    P = p0 + len(tokens)\n    if P > eng.cap:\n        raise RuntimeError(\"KV cache full\")\n    if not tokens:\n        return\n    write_tokens(eng, p0, tokens)\n    for p, R, kind in split(p0, P, lambda b: r_max(eng, b), eng.block, conv_k(eng)):\n        kind = kind if head else \"P\"\n        progs = programs(eng, p, R, kind)\n        if kind == \"L\":\n            eng._prefetch(P)            # the first decode step's, while the device runs\n        eng.stats.append(run(eng, progs, p, R, tokens[p - p0:p - p0 + R]))\n        eng.poss[0] = p + R\n        yield tokens[p - p0:p - p0 + R], logits(eng, R) if kind == \"L\" else None\n\n\ndef mtp(dec, tokens, st, pick=None, on_run=None, follow: int | None = None):\n    \"\"\"MTPDecoder.prefill's runs this way: each run's rows (their hidden stored, the states in\n    the decoder's slot), then the MTP layer over them (M: the tokens after the rows, out[P] the\n    prompt's last logits' pick a0, or `follow`: a part of a prompt, every run a P). Returns\n    (a0, the first draft); on_run as the decoder's.\"\"\"\n    eng = dec.eng\n    toks = [int(t) for t in tokens]\n    p0 = eng.pos\n    P = p0 + len(toks)\n    a0 = draft = None\n    t0 = time.perf_counter()\n    runs = split(p0, P, lambda b: r_max(eng, b), eng.block, conv_k(eng))\n    if follow is not None:\n        runs = [(p, R, \"P\") for p, R, _ in runs]\n    st.compile_s += time.perf_counter() - t0\n    write_tokens(eng, p0, toks if follow is None else toks + [int(follow)])\n    for p, R, kind in runs:\n        t0 = time.perf_counter()\n        rows, mp = programs(eng, p, R, kind, True, dec.slot), programs(eng, p, R, \"M\")\n        st.compile_s += time.perf_counter() - t0\n        st.runs.append((\"prefill\", R, run(eng, rows, p, R)))\n        if kind == \"L\":\n            lg = logits(eng, R)\n            a0 = int(np.argmax(lg)) if pick is None else int(pick(lg))\n            write_tokens(eng, P, [a0])\n        st.runs.append((\"mtp prefill\", R, run(eng, mp, p, R)))\n        draft = dec._drafts(R)[R - 1]\n        eng.pos = p + R\n        if on_run is not None and on_run(toks[p - p0:p - p0 + R]) and p + R < P:\n            return None, None\n    return a0, draft\n", "opentpu/llm/qwen3.py": "\"\"\"Qwen3 dense decoder (e.g. Qwen3-0.6B / 1.7B) on openTPU.\n\nPieces:\n  Spec              model dimensions (from a Hugging Face config.json)\n  load_weights      Hugging Face safetensors -> fp32 numpy arrays (HF parameter names)\n  reference_logits  plain numpy forward pass (the math, fp32), for debugging\n  Image             the per-slice DRAM layout: every layer's weights, norms and KV cache in one\n                    fixed-size block (so a hardware loop walks the layers with one address\n                    register), the tied LM head, and a small I/O area\n  qwen3_step        the ol kernel for one decode token: 28 layers, final norm, LM head\n  qwen3_rows        R token rows at once, each row (sequence, position): batched decode (b\n                    sequences, one KV cache each) and chunked prefill (consecutive positions\n                    of one sequence; causal because each token attends over its own prefix)\n  Engine            runs tokens on a backend (ISA simulator, RTL simulation or the board) and\n                    keeps the KV caches in device DRAM between tokens\n\nWeights are in an MXU format (int8 or 4-bit: an fp32 scale per row and power-of-two offsets per\n128 inputs under it, opentpu/quant.py); activations are quantized on the fly to int8 with an\nfp32 scale per row and a power-of-two offset per 32 (QACT), and every MM sums each output as one\nexact integer (docs/mx_mxu.md). The residual stream, norms, RoPE and softmax are fp32.\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport math\nfrom collections.abc import Mapping\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport numpy as np\n\nfrom .. import fp32 as F\nfrom .. import imgcache as IC\nfrom .. import isa as I\nfrom .. import progcache as PC\nfrom .. import qcache as QC\nfrom .. import quant as Q\nfrom .. import waits as WC\nfrom .. import language as ol\nfrom ..compiler import (Affine, CompileError, DevVar, KVDesc, QTensor, RunVar, Tensor, arg_words,\n                        Words, current, k_scale_bytes, trace_fit)\nfrom . import formats as FM\nfrom . import generate as G\nfrom . import rope_parameters\nfrom . import snapshot as SN\nfrom ..isasim import Config, Machine, design_config\nfrom ..kernels.attention import Additive, Bucket, _attend_heads\nfrom ..kernels.layouts import head_parallel_attention_weights\nfrom ..host.offload import BackendDram, RowLayout, RowServer\nfrom ..kernels import mailbox as MB\nfrom ..kernels import gather as GA\nfrom ..kernels.gather import gather_row, onehot, onehot_blocks\nfrom ..kernels.gather import operand as gather_operand\nfrom ..kernels.lib import rmsnorm, rope, rope_rows, sigmoid, softcap\nfrom ..kernels.mlp import _chunk, down_chunk, swiglu_down\nfrom ..runtime import ALIGN\n\n\n# =============================================================================== model spec\n@dataclass(frozen=True)\nclass Spec:\n    hidden: int\n    layers: int\n    n_q: int\n    n_kv: int\n    head_dim: int\n    ffn: int\n    vocab: int\n    eps: float = 1e-6\n    theta: float = 1e6\n    tied: bool = True\n    bos: int = 151643\n    eos: tuple = (151645, 151643)\n    # the Llama-like models of llama.py (SmolLM3, Phi-3 / Phi-4-mini) run on this code too:\n    qk_norm: bool = True      # RMSNorm on each q and k head (Qwen3); Llama-likes have none\n    qk_smooth: bool = True    # with qk_norm: K's channels smoothed into the gains (qk_gains)\n    nope: tuple = ()          # layers without RoPE (SmolLM3: every 4th)\n    rotary: int = 0           # RoPE dimensions of a head, the first ones (0: all; Phi-4-mini 96)\n    rope_div: tuple = ()      # per-frequency divisors of the angle (LongRoPE's short factors)\n    rope_scale: float = 1.0   # factor on cos and sin (LongRoPE's attention factor)\n    ctx: int = 0              # the most positions the model takes (LongRoPE: its short\n    #                           factors' range; Phi-3: its sliding window; 0: no limit)\n    embed: str = \"f32\"        # the embedding rows: fp32, or \"int8\" (the MXU's int8, as the\n    #                           tied int8 LM head holds them: the device gathers them from it,\n    #                           kernels.gather.gather_row)\n    formats: str = \"\"         # weight formats per kind over the image's wformat (KINDS)\n    mix: str = \"\"             # the recommended mix (wformat \"mix\": formats.named, MIXES)\n\n    @property\n    def rope_dim(self) -> int:\n        \"\"\"RoPE rotates the first `rotary` dimensions of each head (default all of them).\"\"\"\n        return self.rotary or self.head_dim\n\n    @staticmethod\n    def from_hf(model_dir) -> \"Spec\":\n        c = json.loads((Path(model_dir) / \"config.json\").read_text())\n        rp = rope_parameters(c, model_dir)          # (Qwen3's YaRN: not supported)\n        if c.get(\"use_sliding_window\"):\n            raise ValueError(f\"{model_dir}: sliding-window attention is not supported\")\n        if c.get(\"attention_bias\"):\n            raise ValueError(f\"{model_dir}: attention biases are not supported\")\n        eos = c.get(\"eos_token_id\", 151645)\n        g = Path(model_dir) / \"generation_config.json\"\n        if g.exists():\n            eos = json.loads(g.read_text()).get(\"eos_token_id\", eos)\n        return Spec(hidden=c[\"hidden_size\"], layers=c[\"num_hidden_layers\"],\n                    n_q=c[\"num_attention_heads\"], n_kv=c[\"num_key_value_heads\"],\n                    head_dim=c.get(\"head_dim\") or c[\"hidden_size\"] // c[\"num_attention_heads\"],\n                    ffn=c[\"intermediate_size\"], vocab=c[\"vocab_size\"], eps=c[\"rms_norm_eps\"],\n                    theta=rp.get(\"rope_theta\") or c.get(\"rope_theta\") or 10000.0,\n                    tied=c.get(\"tie_word_embeddings\", True),\n                    bos=c.get(\"bos_token_id\", 151643),\n                    eos=tuple(eos) if isinstance(eos, list) else (eos,), mix=FM.mix_for(c))\n\n    def check(self, cfg: Config) -> None:\n        S, D = cfg.S, cfg.D\n        need = [(self.head_dim % D == 0, f\"head_dim {self.head_dim} % D {D}\"),\n                (self.hidden % (S * D) == 0, f\"hidden {self.hidden} % S*D\"),\n                (self.ffn % (S * D) == 0, f\"ffn {self.ffn} % S*D\"),\n                (self.n_kv % S == 0, f\"n_kv {self.n_kv} % S\"),\n                (self.n_q % self.n_kv == 0, \"n_q % n_kv\"),\n                (self.n_q // self.n_kv <= cfg.MCOLS, \"query group larger than MXU columns\"),\n                (self.vocab % S == 0, f\"vocab {self.vocab} % S\"),\n                (max(self.ffn, self.n_q * self.head_dim, self.hidden) <= cfg.ACT_BLOCKS * D,\n                 \"an inner dimension exceeds ACT RAM\")]\n        bad = [m for ok, m in need if not ok]\n        if bad:\n            raise ValueError(\"model does not map onto this openTPU config: \" + \"; \".join(bad))\n\n    def image(self, cfg: Config, cap: int, batch: int = 1, rows: int = 1,\n              wformat: str = \"int8\", head_format: str | None = None,\n              lookup: bool = False, embed_host: bool | None = None,\n              formats: str | None = None) -> \"Image\":\n        return Image(self, cfg, cap, batch, rows, wformat, head_format, lookup, embed_host,\n                     formats)\n\n\ndef finite(v: np.ndarray, name: str) -> np.ndarray:\n    \"\"\"v, a tensor converted from a checkpoint, or a ValueError naming it when it holds a NaN or\n    an infinity (a corrupt or mis-converted checkpoint): the quantizers would turn its block\n    into a NaN or infinite scale, and the model image would hold garbage. One float64 sum (no\n    finite fp32 values sum to an infinity there).\"\"\"\n    if np.isfinite(np.sum(v, dtype=np.float64)):\n        return v\n    bad = ~np.isfinite(v)\n    at = tuple(int(i) for i in np.unravel_index(int(np.argmax(bad)), v.shape))\n    raise ValueError(f\"{name}: {int(bad.sum())} of its {v.size} values are not finite (NaN or \"\n                     f\"inf; the first at {at}): the checkpoint is corrupt or was converted wrong\")\n\n\n# a multimodal checkpoint's vision tower and projector: Qwen3.5's model.visual, MiniCPM-V's\n# model.vision_tower and model.merger (docs/minicpmv.md; their loader is minicpmv's)\nVISION = (\"model.visual.\", \"model.vision_tower.\", \"model.merger.\")\n\n\nclass Weights(Mapping):\n    \"\"\"The tensors of a HF safetensors checkpoint, read and converted to fp32 numpy arrays\n    when first used (load_weights): a multi-billion-parameter model is never all in memory in\n    fp32 (LFM2-2.6B: 10 GB), the image build converts one tensor at a time. Tensors of at most\n    CACHE bytes stay cached (norms, conv taps: read per token by the references), and the\n    last larger one (the embedding table a reference indexes per token). A tensor with a NaN or\n    an infinity is refused (finite).\"\"\"\n\n    CACHE = 16 << 20\n\n    def __init__(self, model_dir, mtp: bool = False):\n        from safetensors import safe_open\n        self.model_dir = Path(model_dir)\n        self._files, self._where = [], {}\n        skip = VISION if mtp else VISION + (\"mtp.\",)\n        for f in sorted(Path(model_dir).glob(\"*.safetensors\")):\n            h = safe_open(str(f), framework=\"pt\")\n            self._files.append(h)\n            for k in h.keys():\n                if k.startswith(skip):\n                    continue\n                self._where[k.replace(\"model.language_model.\", \"model.\", 1)] = (h, k, None)\n        self._split_fused(Path(model_dir))\n        self._small: dict = {}\n        self._big: tuple | None = None\n\n    def _split_fused(self, model_dir: Path) -> None:\n        \"\"\"Phi-3's fused projections also under the names of separate ones: qkv_proj's rows\n        are q, k and v (num_attention_heads, num_key_value_heads, num_key_value_heads heads),\n        gate_up_proj's the gate's, then the up projection's (Phi3MLP: chunk(2)).\"\"\"\n        fused = [n for n in self._where if n.endswith((\"self_attn.qkv_proj.weight\",\n                                                        \"mlp.gate_up_proj.weight\"))]\n        if not fused:\n            return\n        c = json.loads((model_dir / \"config.json\").read_text())\n        d = c.get(\"head_dim\") or c[\"hidden_size\"] // c[\"num_attention_heads\"]\n        nq, nkv = c[\"num_attention_heads\"] * d, c[\"num_key_value_heads\"] * d\n        ff = c[\"intermediate_size\"]\n        for n in fused:\n            h, k, _ = self._where[n]\n            if n.endswith(\"qkv_proj.weight\"):\n                p = n[:-len(\"qkv_proj.weight\")]\n                parts = ((\"q_proj\", 0, nq), (\"k_proj\", nq, nq + nkv),\n                         (\"v_proj\", nq + nkv, nq + 2 * nkv))\n            else:\n                p = n[:-len(\"gate_up_proj.weight\")]\n                parts = ((\"gate_proj\", 0, ff), (\"up_proj\", ff, 2 * ff))\n            for name, a, b in parts:\n                self._where[p + name + \".weight\"] = (h, k, (a, b))\n\n    def __getitem__(self, name) -> np.ndarray:\n        if name in self._small:\n            return self._small[name]\n        if self._big is not None and self._big[0] == name:\n            return self._big[1]\n        import torch\n        h, k, rows = self._where[name]\n        t = h.get_tensor(k) if rows is None else h.get_slice(k)[rows[0]:rows[1]]\n        v = finite(t.to(torch.float32).numpy(), name)\n        if v.nbytes <= self.CACHE:\n            self._small[name] = v\n        else:\n            self._big = (name, v)\n        return v\n\n    def __iter__(self):\n        return iter(self._where)\n\n    def __len__(self) -> int:\n        return len(self._where)\n\n    def __contains__(self, name) -> bool:\n        return name in self._where\n\n\ndef load_weights(model_dir, mtp: bool = False) -> Weights:\n    \"\"\"All tensors of a HF safetensors checkpoint as fp32 numpy arrays, converted when first\n    used (Weights). Of a multimodal checkpoint (Qwen3.5, MiniCPM-V) only the language model is\n    loaded, under the names of a text-only one (model.language_model.* -> model.*): not the\n    vision tower and projector (VISION), nor the multi-token prediction layers (mtp.*) unless\n    `mtp` (Qwen3.5's drafter,\n    opentpu/llm/mtp.py). Gemma 4: gemma4.load_weights (its PLE table read by rows).\"\"\"\n    cfg = Path(model_dir) / \"config.json\"\n    if cfg.exists() and json.loads(cfg.read_text()).get(\"model_type\") in (\"gemma4\",\n                                                                          \"gemma4_text\"):\n        from .gemma4 import load_weights as gemma4_weights\n        return gemma4_weights(model_dir)\n    return Weights(model_dir, mtp)\n\n\nclass LazyWeights(dict):\n    \"\"\"load_weights' names over a checkpoint's safetensors files, each tensor read as fp32 when\n    it is asked for and not kept: for a model whose fp32 weights would not fit host RAM (a\n    MoE; its experts are packed one at a time, opentpu.llm.moe). release() gives the files'\n    pages back once the image is built (a later read reopens its file). A tensor with a NaN or\n    an infinity is refused (finite). mtp: the multi-token prediction layers' tensors (mtp.*,\n    Qwen3.5's drafter) too, from `mtp_from` when given (another checkpoint's: MiniCPM-V 4.7\n    has none, its backbone's base Qwen3.5-35B-A3B's are transplanted, docs/offload.md 15.6).\"\"\"\n\n    def __init__(self, model_dir, mtp: bool = False, mtp_from=None):\n        super().__init__()\n        from safetensors import safe_open\n        self.model_dir = Path(model_dir)    # (moe.pool_key: the checkpoint's identity)\n        self.mtp_from = None if mtp_from is None else Path(mtp_from)\n        self._at, self._h = {}, {}          # name -> (file, its name there); file -> handle\n        own = mtp and mtp_from is None\n        for f in sorted(Path(model_dir).glob(\"*.safetensors\")):\n            h = self._h[str(f)] = safe_open(str(f), \"pt\")\n            for k in h.keys():\n                if not k.startswith(VISION + (() if own else (\"mtp.\",))):\n                    self._at[k.replace(\"model.language_model.\", \"model.\", 1)] = (str(f), k)\n        for f in sorted(Path(mtp_from).glob(\"*.safetensors\")) if mtp and mtp_from else ():\n            h = safe_open(str(f), \"pt\")\n            keys = [k for k in h.keys() if k.startswith(\"mtp.\")]\n            if keys:\n                self._h[str(f)] = h\n                self._at.update((k, (str(f), k)) for k in keys)\n        if mtp and not any(k.startswith(\"mtp.\") for k in self._at):\n            raise ValueError(f\"{mtp_from or model_dir}: no mtp.* tensors (the MTP drafter)\")\n\n    def _open(self, k):\n        from safetensors import safe_open\n        f, name = self._at[k]\n        if f not in self._h:\n            self._h[f] = safe_open(f, \"pt\")\n        return self._h[f], name\n\n    def __getitem__(self, k):\n        import torch\n        h, name = self._open(k)\n        return finite(h.get_tensor(name).to(torch.float32).numpy(), k)\n\n    def part(self, k, i):\n        \"\"\"Tensor k's i-th entry along its first axis (one expert of a fused expert tensor),\n        read alone.\"\"\"\n        import torch\n        h, name = self._open(k)\n        return finite(h.get_slice(name)[i].to(torch.float32).numpy(), f\"{k}[{i}]\")\n\n    def release(self) -> None:\n        \"\"\"Close the files (safe_open maps each whole: the pages a read touched stay mapped,\n        and the kernel keeps them over other page cache, a pool file's) and drop their pages\n        (POSIX_FADV_DONTNEED, where the host has it). A tensor read after reopens its file.\"\"\"\n        import gc\n        import os\n        files = list(self._h)\n        self._h.clear()\n        gc.collect()                        # (a handle in a cycle would keep its map)\n        for f in files if hasattr(os, \"posix_fadvise\") else ():\n            fd = os.open(f, os.O_RDONLY)\n            try:\n                os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n            finally:\n                os.close(fd)\n\n    def __contains__(self, k):\n        return k in self._at\n\n    def __iter__(self):\n        return iter(self._at)\n\n    def __len__(self):\n        return len(self._at)\n\n    def keys(self):\n        return self._at.keys()\n\n    def items(self):\n        return ((k, self[k]) for k in self._at)\n\n\ndef rope_tables(spec: Spec, pos: int) -> tuple[np.ndarray, np.ndarray]:\n    \"\"\"cos, sin [rope_dim/2] for one position (HF rotate-half convention); with LongRoPE's\n    (spec.rope_div, spec.rope_scale) each frequency divided by its factor and both tables\n    scaled by the attention factor.\"\"\"\n    half = spec.rope_dim // 2\n    inv = 1.0 / (spec.theta ** (np.arange(half, dtype=np.float64) * 2 / spec.rope_dim))\n    div = getattr(spec, \"rope_div\", ())\n    if div:\n        inv = inv / np.asarray(div, np.float64)\n    ang = pos * inv\n    sc = getattr(spec, \"rope_scale\", 1.0)\n    return (np.cos(ang) * sc).astype(np.float32), (np.sin(ang) * sc).astype(np.float32)\n\n\n# =============================================================================== K smoothing\ndef qk_sigma(spec: Spec, wq, wk, gq, gk) -> np.ndarray:\n    \"\"\"sigma [head_dim]: the factors K's channels are divided by and q's multiplied by (q . K\n    unchanged), so that K's int8 rounding (one scale per token and head block) does not lose\n    the small channels to a few large ones (docs/quant.md, \"K smoothing\"). Qwen3's k_norm\n    gains have outlier channels (Qwen3-0.6B: up to 42 times their median in a layer); K's\n    rounding cost Qwen3-0.6B a KL of 0.048 nats a token, the int8 weights 0.0023.\n\n    sigma = sqrt(kmag / qmag) (SmoothQuant's balance between q and K), from the weights alone\n    (wq [n_q d, H], wk [n_kv d, H], the gains gq, gk [d]): a channel's magnitude is its gain\n    times its projection row's norm over its head's RMS row norm, the largest over the heads,\n    as the heads share the gains; the same within each RoPE pair (c, c + rope_dim / 2), so it\n    commutes with RoPE; and a power of two, so that it scales q and K exactly and changes only\n    how they round.\"\"\"\n    d = spec.head_dim\n\n    def mag(w, g, heads):\n        r = np.linalg.norm(np.asarray(w, np.float64).reshape(heads, d, -1), axis=-1)\n        r = r / np.sqrt(np.mean(r * r, -1, keepdims=True))\n        m = np.abs(np.asarray(g, np.float64)) * r.max(0)\n        h = spec.rope_dim // 2\n        m[:h] = m[h:2 * h] = np.maximum(m[:h], m[h:2 * h])\n        return m\n\n    km, qm = mag(wk, gk, spec.n_kv), mag(wq, gq, spec.n_q)\n    ok = (km > 0) & (qm > 0)\n    s = np.sqrt(np.where(ok, km, 1) / np.where(ok, qm, 1))\n    return np.exp2(np.round(np.log2(s)))\n\n\ndef qk_gains(spec: Spec, W, p: str) -> tuple[np.ndarray, np.ndarray]:\n    \"\"\"Layer p's q_norm and k_norm gains (fp32) as the device applies them: times and divided\n    by qk_sigma with spec.qk_smooth, else the checkpoint's.\"\"\"\n    gq = np.asarray(W[p + \"self_attn.q_norm.weight\"], np.float32)\n    gk = np.asarray(W[p + \"self_attn.k_norm.weight\"], np.float32)\n    if not spec.qk_smooth:\n        return gq, gk\n    s = qk_sigma(spec, W[p + \"self_attn.q_proj.weight\"], W[p + \"self_attn.k_proj.weight\"], gq,\n                 gk)\n    return (gq * s).astype(np.float32), (gk / s).astype(np.float32)\n\n\n# =============================================================================== lookup tables\ndef _lookup_alloc(b: \"_Bump\", spec, cap: int, block: int = None, D: int = 128,\n                  head: tuple | None = None, M: int = 4, embed_host: bool = False,\n                  rows: int = 1, imem: int = 1 << 15, masks: bool = False,\n                  waitc: bool = False) -> dict:\n    \"\"\"DRAM for the device-side inputs of a run-time position (RunPos): every token's embedding\n    row, the RoPE cos / sin rows of every position, and the attention mask table\n    (attention.Bucket: cap entries +inf, then a block of -inf). The embedding rows are fp32\n    (flushed, as the host writes them), or with spec.embed \"int8\" the MXU's int8 rows and their\n    gather scales, an fp32 per D block (kernels.gather.gather_row, with its one-hot operand for\n    M MXU columns): the LM head's rows when `head` (its data and scale addresses) is given -- a\n    tied int8 head whole on one slice; its gather scales beside its scale rows -- else a table\n    of their own, or with `embed_host` a slot of `rows` of them that the host fills from the\n    table it keeps (embed_record: each row's int8 data, then its gather scales) and a mailbox\n    for the generate loop's requests (opentpu.host.offload.RowLayout). A dense model's image\n    also holds the prompt runs' additive mask tiles (amask_table); a MoE model's with `masks` (its\n    tiled layer runs: tiled.compile_layer_tile).\"\"\"\n    block = block or ATTN_BLOCK\n    half = len(rope_tables(spec, 0)[0])\n    V, H = spec.vocab, spec.hidden\n    if embed_host and (getattr(spec, \"embed\", \"f32\") != \"int8\" or head is not None):\n        raise ValueError(\"embed_host: the model's int8 embedding table of its own (Spec.embed \"\n                         \"int8, not the tied int8 head's rows)\")\n    if getattr(spec, \"embed\", \"f32\") == \"int8\":\n        if head is not None:            # the head's rows, gather scales of their own\n            emb = {\"embed_q\": (head[0], b.alloc(V * Q.gather_scale_bytes(H, \"int8\", D))),\n                   \"own\": False, \"head_gsc\": True}\n        elif embed_host:\n            rec = embed_record(H, D)\n            slot = b.alloc(rows * rec)\n            emb = {\"embed_q\": (slot, slot + H), \"own\": False, \"host\": True, \"rec\": rec,\n                   \"rows\": rows, \"mbox\": b.alloc(RowLayout.WORDS)}\n        else:\n            emb = {\"embed_q\": (b.alloc(V * H), b.alloc(V * Q.gather_scale_bytes(H, \"int8\", D))),\n                   \"own\": True}\n        emb.update(onehot=b.alloc(4 * M * onehot_blocks(D, M, \"int8\") * D), M=M)\n    else:\n        emb = {\"embed\": b.alloc(4 * V * H)}\n    if masks or (getattr(spec, \"moe\", None) is None and not getattr(spec, \"experts\", 0)):\n        emb.update(amask=b.alloc(amask_bytes(block, M)), amask_M=M)\n    return {**emb, \"cos_t\": b.alloc(4 * cap * half), \"sin_t\": b.alloc(4 * cap * half),\n            \"zmask\": b.alloc(4 * (cap + block)), \"half\": half, \"block\": block, \"D\": D,\n            \"gen\": G.alloc(b, spec, cap, block, imem, waitc)}\n\n\ndef amask_bytes(block: int, M: int, tables: int = 1) -> int:\n    \"\"\"The bytes of `tables` mask tables (amask_table's, one after the other) and AMASK_PAD\n    positions after them: a looped attention's last packed tile reads the next one's mask tiles,\n    at most MCOLS (M) rows past the table (tiled._heads_loop), from the image's own words.\"\"\"\n    return (tables * block + AMASK_PAD * M) * M * (block + 1) * 4\n\n\nAMASK_PAD = 1       # amask_bytes' padding, in MCOLS positions\n\n\ndef amask_table(block: int, M: int, start: bool = False) -> np.ndarray:\n    \"\"\"attention.Additive's mask tiles for a prompt run's rows (docs/prefill.md 9), one a\n    position q in an attention block: M rows (MCOLS: a score buffer's) of the block's entries c\n    and a pad word (the buffer's row stride), -0 for c <= q (the row's own token and those\n    before it) and -inf after; [block, M, block + 1] fp32, 1 MiB at 256 and MCOLS 4. start:\n    the opposite (a sliding window's first block: -inf for c <= q, -0 after).\"\"\"\n    c = np.arange(block + 1)[None, :]\n    keep = ((c > np.arange(block)[:, None]) if start else (c <= np.arange(block)[:, None])) | \\\n        (c == block)\n    tile = np.where(keep, np.float32(-0.0), np.float32(-np.inf)).astype(np.float32)\n    return np.ascontiguousarray(np.broadcast_to(tile[:, None, :], (block, M, block + 1)))\n\n\ndef _amask(lk: dict):\n    \"\"\"RunRows' amask: the table's address and its bytes a position, or None (no table).\"\"\"\n    if \"amask\" not in lk:\n        return None\n    return lk[\"amask\"], 4 * lk[\"amask_M\"] * (lk[\"block\"] + 1)\n\n\ndef put_head(img, W, qb, put, put_q, rows) -> None:\n    \"\"\"An image build's LM head (put_q of its slices' rows), and where the resident decode's\n    int8 embedding rows are the tied int8 head's (_lookup_alloc: head_gsc, one slice) their\n    gather scales beside it (quant.gather_scales of the head's scale rows).\"\"\"\n    spec, D = img.spec, img.cfg.D\n    head = W[\"model.embed_tokens.weight\"] if spec.tied else W[\"lm_head.weight\"]\n    lk = img.lookup\n    if lk.get(\"head_gsc\"):\n        qb.submit(head, img.head_format, D, lambda q, sc: (\n            put(0, img.head[0], q), put(0, img.head[1], sc),\n            put(0, lk[\"embed_q\"][1], Q.gather_scales(sc, \"int8\", spec.hidden, D))))\n    else:\n        put_q(img.head, rows(head, img.v_loc), img.head_format)\n\n\ndef _lookup_build(put, S: int, W: dict, spec, cap: int, lk: dict) -> None:\n    cs = [rope_tables(spec, p) for p in range(cap)]\n    z = np.concatenate([np.full(cap, np.inf, np.float32), np.full(lk[\"block\"], -np.inf,\n                                                                  np.float32)])\n    if \"embed\" in lk:\n        e = F.ftz(np.asarray(W[\"model.embed_tokens.weight\"], np.float32))\n    elif lk[\"own\"]:\n        tab = W[\"model.embed_tokens.weight\"]\n        eq, es = Q.quantize_mxu(tab, \"int8\", lk[\"D\"])\n        es = Q.gather_scales(es, \"int8\", tab.shape[1], lk[\"D\"])\n    elif lk.get(\"host\"):                    # the host's table, in the slot's record format\n        lk[\"store\"] = embed_store(W[\"model.embed_tokens.weight\"], lk[\"D\"])\n    for s in range(S):\n        if \"embed\" in lk:\n            put(s, lk[\"embed\"], e)\n        elif lk[\"own\"]:\n            put(s, lk[\"embed_q\"][0], eq)\n            put(s, lk[\"embed_q\"][1], es)\n        put(s, lk[\"cos_t\"], np.stack([c for c, _ in cs]))\n        put(s, lk[\"sin_t\"], np.stack([x for _, x in cs]))\n        put(s, lk[\"zmask\"], z)\n        if \"amask\" in lk:\n            put(s, lk[\"amask\"], amask_table(lk[\"block\"], lk[\"amask_M\"]))\n        if \"onehot\" in lk:\n            put(s, lk[\"onehot\"], onehot(lk[\"D\"], lk[\"M\"], \"int8\"))\n        G.build(put, s, S, spec, cap, lk[\"gen\"])\n\n\ndef _lookup_desc(lk: dict, spec, cap: int) -> dict:\n    if not lk:\n        return {}\n    d = {\"cos_t\": _tdesc(lk[\"cos_t\"], (cap, lk[\"half\"])),\n         \"sin_t\": _tdesc(lk[\"sin_t\"], (cap, lk[\"half\"])), \"zmask\": lk[\"zmask\"]}\n    if \"embed\" in lk:\n        d[\"embed\"] = _tdesc(lk[\"embed\"], (spec.vocab, spec.hidden))\n    elif lk.get(\"host\"):        # the slot: rows of records (the int8 row, its gather scales)\n        a, sa = lk[\"embed_q\"]\n        d[\"embed_q\"] = QTensor(Affine(a), Affine(sa), (lk[\"rows\"], spec.hidden), lk[\"rec\"],\n                               lk[\"rec\"], lk[\"D\"], wf=Q.mxu_wf(\"int8\"))\n        d[\"embed_mbox\"] = mbox = lk[\"mbox\"]\n        d[\"post_token\"] = lambda tok: MB.post(mbox, tok)    # the generate loop's request\n    else:                       # the table's rows and their gather scales (kernels.gather)\n        d[\"embed_q\"] = GA.table(*lk[\"embed_q\"], spec.vocab, spec.hidden, \"int8\", lk[\"D\"])\n    if \"embed\" not in lk:\n        M, D = lk[\"M\"], lk[\"D\"]\n        d[\"onehot\"] = _tdesc(lk[\"onehot\"], (M, onehot_blocks(D, M, \"int8\") * D))\n    d[\"gen\"] = G.desc(lk[\"gen\"], spec, cap)\n    return d\n\n\ndef embed_record(H: int, D: int) -> int:\n    \"\"\"Bytes of one int8 embedding row in a host-filled slot (embed_host): its H int8 values\n    (the MXU's int8, quant.quantize_mxu), then its gather scales (an fp32 per D block,\n    quant.gather_scales), whole MXU chunks.\"\"\"\n    return -(-(H + Q.gather_scale_bytes(H, \"int8\", D)) // ALIGN) * ALIGN\n\n\ndef embed_store(table, D: int) -> np.ndarray:\n    \"\"\"The int8 embedding table [V, H] the host keeps (embed_host), in the slot's record format\n    (embed_record): [V, record bytes] uint8, quantized as the on-card table would be.\"\"\"\n    V, H = table.shape\n    out = np.zeros((V, embed_record(H, D)), np.uint8)\n    gb = Q.gather_scale_bytes(H, \"int8\", D)\n    for r0 in range(0, V, Q.QUANT_ROWS):\n        q, sc = Q.quantize_mxu(np.asarray(table[r0:r0 + Q.QUANT_ROWS], np.float32), \"int8\", D)\n        n = len(q)\n        out[r0:r0 + n, :H] = np.asarray(q).view(np.uint8).reshape(n, H)\n        out[r0:r0 + n, H:H + gb] = Q.gather_scales(sc, \"int8\", H, D).view(np.uint8).reshape(n, gb)\n    return out\n\n\nclass EmbedHost:\n    \"\"\"An Image's side of embed_host (its int8 embedding table on the host, the card holding a\n    slot of the run's rows: _lookup_alloc): the rows the host writes before a run, and the\n    server of the generate loop's requests (each sampled token's row into slot row 0). Data\n    movement only, as Gemma 4 E4B's PLE records (docs/offload.md 5.9).\"\"\"\n\n    @property\n    def embed_host(self) -> bool:\n        return bool(getattr(self, \"lookup\", None) and self.lookup.get(\"host\"))\n\n    def host_rows(self, tokens) -> list:\n        \"\"\"[(slot address, the tokens' records)] before a run of these token rows ([] with the\n        table on the card).\"\"\"\n        if not self.embed_host:\n            return []\n        lk = self.lookup\n        if len(tokens) > lk[\"rows\"]:\n            raise ValueError(f\"{len(tokens)} tokens, the embedding slot holds {lk['rows']}\")\n        return [(lk[\"embed_q\"][0], lk[\"store\"][[int(t) for t in tokens]].reshape(-1))]\n\n    def row_server(self, backend) -> RowServer | None:\n        \"\"\"The host's server of the generate loop's requests, on the backend's DRAM (the\n        Engine gives it the expert server's memory when there is one); None with the table on\n        the card.\"\"\"\n        if not self.embed_host:\n            return None\n        lk = self.lookup\n        return RowServer(BackendDram(backend), RowLayout(lk[\"mbox\"], lk[\"embed_q\"][0],\n                                                         lk[\"rec\"]),\n                         lambda t: lk[\"store\"][t])\n\n\nclass Embedding:\n    \"\"\"The embedding rows the device computes with, on the host: the checkpoint's fp32 rows\n    (Engine.embed: the inputs the host writes for an image without lookup tables), or with\n    spec.embed \"int8\" their int8 quantization as the device's gather dequantizes it, bit for bit\n    (the reference; an Engine of such a model reads them from the image, batch 1).\"\"\"\n\n    def __init__(self, spec, W, D: int):\n        self.W, self.table = W, None        # read at the first row (never with device inputs)\n        self.int8, self.D = getattr(spec, \"embed\", \"f32\") == \"int8\", D\n\n    def __getitem__(self, idx) -> np.ndarray:\n        if self.table is None:\n            self.table = self.W[\"model.embed_tokens.weight\"]\n        rows = np.asarray(self.table[idx], np.float32)\n        if not self.int8:\n            return rows\n        return gathered_rows(rows, self.D).reshape(rows.shape)\n\n\ndef gathered_rows(rows, D: int) -> np.ndarray:\n    \"\"\"The values kernels.gather.gather_row gives for these fp32 rows [n, K] held in the MXU's\n    int8 (quant.quantize_mxu, as the LM head is stored): [n, K], bit for bit.\"\"\"\n    return GA.gathered(rows, \"int8\", D)\n\n\ndef _tok_arg(image, tok) -> dict:\n    \"\"\"The kernel argument of a compile-time token (none without one: the program is the\n    host-input one).\"\"\"\n    if tok is None:\n        return {}\n    if not image.lookup:\n        raise ValueError(\"a program with its token's inputs from the image needs lookup tables\")\n    return {\"tok\": int(tok)}\n\n\ndef _tokens_arg(image, tokens, rows) -> dict:\n    if tokens is None:\n        return {}\n    if not image.lookup:\n        raise ValueError(\"rows with their inputs from the image need lookup tables\")\n    if len(tokens) != len(rows):\n        raise ValueError(f\"{len(tokens)} tokens for {len(rows)} rows\")\n    return {\"tokens\": [int(t) for t in tokens]}\n\n\ndef has_embed_host(spec) -> bool:\n    \"\"\"The model's image can keep its int8 embedding table on the host (embed_host).\"\"\"\n    import inspect\n    return \"embed_host\" in inspect.signature(spec.image).parameters\n\n\ndef has_lookup(spec) -> bool:\n    \"\"\"The model's image can hold the resident decode's tables (Spec.image(lookup=True)) and\n    compile_decode: Qwen3, LFM2, Qwen3.5.\"\"\"\n    import inspect\n    return \"lookup\" in inspect.signature(spec.image).parameters\n\n\ndef compile_decode(image, kernel, blocks: int, lo: int, block: int | None = None):\n    \"\"\"The decode program of every position p in [lo, blocks * block), lo >= (blocks - 1) *\n    block, at a run-time position (RunPos; the image needs lookup=True): (programs, run_args),\n    run_args the programs' arguments (RunVar, coefficient) (compiler.arg_words gives the ARG\n    register words of RunPos.values).\"\"\"\n    if not image.lookup:\n        raise ValueError(\"compile_decode needs an image with lookup tables (lookup=True)\")\n    block = block or ATTN_BLOCK\n    if not (blocks - 1) * block <= lo < min(blocks * block, image.cap):\n        raise ValueError(f\"lo {lo} is not in bucket {blocks}\")\n    rp = RunPos(blocks, block, lo, image.lookup[\"zmask\"], image.cap)\n    bs = [trace_fit(kernel, image.cfg, s, lambda s=s: {\"m\": step_descriptors(image, s),\n                                                       \"pos\": rp, \"block\": block})\n          for s in range(image.cfg.S)]\n    progs = [b.finish() for b in bs]\n    if any(b.run_args != bs[0].run_args for b in bs):\n        raise CompileError(\"the slices' programs take different run-time arguments\")\n    return progs, list(bs[0].run_args)\n\n\n# =============================================================================== reference\ndef reference_logits(spec: Spec, W: dict, tokens) -> np.ndarray:\n    \"\"\"fp32 numpy forward of the whole sequence (causal); returns logits [T, vocab].\"\"\"\n    tokens = list(tokens)\n    T, d, G = len(tokens), spec.head_dim, spec.n_q // spec.n_kv\n    x = W[\"model.embed_tokens.weight\"][tokens].astype(np.float32)\n\n    def norm(v, g):\n        return (v / np.sqrt(np.mean(v * v, axis=-1, keepdims=True) + spec.eps)) * g\n\n    cs = [rope_tables(spec, p) for p in range(T)]\n    cos = np.stack([c for c, _ in cs])[:, None, :]\n    sin = np.stack([s for _, s in cs])[:, None, :]\n\n    def rot(v):\n        h, rd = spec.rope_dim // 2, spec.rope_dim\n        v1, v2 = v[..., :h], v[..., h:rd]\n        return np.concatenate([v1 * cos - v2 * sin, v2 * cos + v1 * sin, v[..., rd:]], axis=-1)\n\n    mask = np.triu(np.full((T, T), -np.inf, np.float32), 1)\n    for i in range(spec.layers):\n        p = f\"model.layers.{i}.\"\n        h = norm(x, W[p + \"input_layernorm.weight\"])\n        q = (h @ W[p + \"self_attn.q_proj.weight\"].T).reshape(T, spec.n_q, d)\n        k = (h @ W[p + \"self_attn.k_proj.weight\"].T).reshape(T, spec.n_kv, d)\n        v = (h @ W[p + \"self_attn.v_proj.weight\"].T).reshape(T, spec.n_kv, d)\n        if spec.qk_norm:\n            q = norm(q, W[p + \"self_attn.q_norm.weight\"])\n            k = norm(k, W[p + \"self_attn.k_norm.weight\"])\n        if i not in spec.nope:\n            q, k = rot(q), rot(k)\n        o = np.zeros((T, spec.n_q, d), np.float32)\n        for hq in range(spec.n_q):\n            s = q[:, hq] @ k[:, hq // G].T / math.sqrt(d) + mask\n            s = np.exp(s - s.max(axis=1, keepdims=True))\n            o[:, hq] = (s / s.sum(axis=1, keepdims=True)) @ v[:, hq // G]\n        x = x + o.reshape(T, -1) @ W[p + \"self_attn.o_proj.weight\"].T\n        h = norm(x, W[p + \"post_attention_layernorm.weight\"])\n        g = h @ W[p + \"mlp.gate_proj.weight\"].T\n        u = h @ W[p + \"mlp.up_proj.weight\"].T\n        x = x + ((g / (1 + np.exp(-g))) * u) @ W[p + \"mlp.down_proj.weight\"].T\n    x = norm(x, W[\"model.norm.weight\"])\n    head = W[\"model.embed_tokens.weight\"] if spec.tied else W[\"lm_head.weight\"]\n    return x @ head.T\n\n\ndef _fake_q(x, D: int = 128, n: int | None = None):\n    \"\"\"QACT's quantization of the rows of x (the last axis), in float64: per row an fp32 scale\n    and a power-of-two offset per D/4 (quant.fake_act), over ranges of n columns (one QACT\n    each; default the whole row: the down projection's chunks are ranges of their own). An\n    MXAct: a weight's @ (an MXW, _fake_w) leaves out what MM's window drops. A value within\n    2^-31 of a rounding tie rounds as the device's quantizer rounds it in fp32, not as float64\n    noise has it: a row whose values have exact ratios has exact ties (a 4-bit row: codes 3 and\n    6 make 63.5; a flash block's attention output is an integer vector times a scalar, _pv).\"\"\"\n    return Q.fake_act(x, D, n)\n\n\ndef _fake_k(k, D: int = 128):\n    \"\"\"K rows [..., d] as the KV cache holds them (QST, compiler.KVDesc.k): at d = D one fp32\n    scale a row (ROW, read by MM RSC), else an int8 scale row (an offset per D-block). (values,\n    the groups' offsets dw per D/8 or None) -- q.K^T's streamed operand, mx_matmul's.\"\"\"\n    if k.shape[-1] == D:\n        return np.asarray(Q.fake_act(k, D, row=True)).view(np.ndarray), None\n    a = Q.fake_act(k, D, g=D)\n    return np.asarray(a).view(np.ndarray), a.da\n\n\ndef _qk(qq, K, dw, D: int = 128):\n    \"\"\"The scores q.K^T of a query row qq (an MXAct, _fake_q) against K rows [T, d] (_fake_k's\n    values, dw [T, d / (D/8)] or None): MM's sums with the int8 window's drops.\"\"\"\n    return Q.mx_matmul(qq, K, None if dw is None else np.asarray(dw).reshape(len(K), -1),\n                       I.MX_W[I.W8], D)\n\n\ndef _v_parts(v):\n    \"\"\"V rows [..., d] as the KV cache holds them: int8 values and one scale per row (an all-zero\n    row's scale is 0, as the device's).\"\"\"\n    a = np.abs(v).max(-1, keepdims=True)\n    return np.clip(np.rint(v / np.where(a == 0, 1, a / 127)), -127, 127), a[..., 0] / 127\n\n\ndef _pv(pp, Vq, vs, D: int = 128, block: int | None = None, start: int = 0):\n    \"\"\"P.V as the device's flash attention takes it (kernels/attention.py _attend_heads): per\n    attention block of `block` tokens (ATTN_BLOCK) the softmax numerators pp [T] times V's row\n    scales vs [T] (folded in by QACT CSCALE), quantized as one QACT (the last block padded with\n    zeros to whole D blocks), against V's int8 values Vq [T, d] (V^T streamed UNIT: MM's drops\n    of P's groups more than 16 octaves below the block's largest). start: the first key's\n    position (a sliding window's: the blocks are the cache's, from position 0, its first one\n    masked before the window: zeros there, the QACT's groups at the block's offsets).\"\"\"\n    block = block or ATTN_BLOCK\n    T = len(pp)\n    out = 0.0\n    t0 = 0\n    while t0 < T:\n        o = (start + t0) % block                    # the segment's place in its block\n        n = min(block - o, T - t0)\n        npad = -(-(o + n) // D) * D\n        seg = np.zeros(npad)\n        seg[o:o + n] = pp[t0:t0 + n] * vs[t0:t0 + n]\n        vt = np.zeros((npad, Vq.shape[-1]))\n        vt[o:o + n] = Vq[t0:t0 + n]\n        out = out + Q.mx_matmul(_fake_q(seg, D), vt.T, None, I.MX_W[I.W8], D)\n        t0 += n\n    return out\n\n\ndef _fake_w(a, D: int, fmt: str = \"int8\"):\n    \"\"\"A weight matrix as the device holds it, in float64 (quant.quantize_mxu in format fmt,\n    dequantized): an MXW, whose @ with an MXAct (_fake_q) sums as MM does.\"\"\"\n    return Q.fake_w(np.asarray(a, np.float32), fmt, D)\n\n\nKINDS = (\"attn\", \"mlp\", \"gateup\", \"down\", \"head\")     # the weight kinds of a formats string\n\n\ndef _formats(spec, formats: str | None) -> str:\n    \"\"\"An image's formats string: `formats`, else OTPU_FORMATS, else spec.formats.\"\"\"\n    import os\n    return formats if formats is not None else os.environ.get(\"OTPU_FORMATS\", spec.formats)\n\n\ndef weight_kind(n: str) -> tuple:\n    \"\"\"(kind, layer) of checkpoint weight `n` (KINDS: the head, or a layer's attention, MLP\n    gate / up or down projection).\"\"\"\n    if not n.startswith(\"model.layers.\"):\n        return \"head\", 0\n    return (\"attn\" if \".self_attn.\" in n else \"down\" if \".down_proj.\" in n else \"gateup\",\n            int(n.split(\".\")[2]))\n\n\ndef emulated_logits(spec: Spec, W: dict, tokens, D: int = 128, wformat: str = \"int8\",\n                    head_format: str | None = None, formats: str | None = None,\n                    S: int = 1) -> np.ndarray:\n    \"\"\"float64 decode that applies openTPU's quantization points but none of its rounding: the\n    weights in their MXU formats (`wformat`, `head_format`, `formats` as in Image), every MM\n    input quantized as QACT does on S slices (the card's 1; the design's 2: a row scale and\n    offsets per D/4; the down projection's in its F chunks, kernels.mlp.down_chunk of a slice's\n    F), int8 K (per token: ROW at d = D, else an offset per D-block) and V (per token), P per\n    attention block with V's per-token scales folded in (_pv), and MM's window's drops.\n    Separates quantization error from kernel bugs.\"\"\"\n    d, G = spec.head_dim, spec.n_q // spec.n_kv\n    Wq: dict = {}\n    head = \"model.embed_tokens.weight\" if spec.tied else \"lm_head.weight\"\n    wformat, formats = FM.named(spec, wformat, formats)\n    fmt = FM.resolver(formats, KINDS, spec.formats, wformat, head_format)\n\n    def w(n):\n        if n not in Wq:\n            Wq[n] = _fake_w(W[n], D, fmt(*weight_kind(n)))\n        return Wq[n]\n\n    def chunk(i):\n        return down_chunk(spec.ffn // S, D, fmt(\"down\", i))\n\n    def norm(v, g):\n        return (v / np.sqrt(np.mean(v * v, -1, keepdims=True) + spec.eps)) * g\n\n    qk = [qk_gains(spec, W, f\"model.layers.{i}.\") if spec.qk_norm else None\n          for i in range(spec.layers)]\n    Kc = [[] for _ in range(spec.layers)]\n    Vc = [[] for _ in range(spec.layers)]\n    out = []\n    for pos, tk in enumerate(tokens):\n        x = np.asarray(W[\"model.embed_tokens.weight\"][tk], np.float64)\n        if spec.embed == \"int8\":                    # the int8 embedding rows (Spec.embed)\n            x = gathered_rows(x, D)[0].astype(np.float64)\n        c, s = rope_tables(spec, pos)\n\n        def rot(v):\n            h, rd = spec.rope_dim // 2, spec.rope_dim\n            v1, v2 = v[..., :h], v[..., h:rd]\n            return np.concatenate([v1 * c - v2 * s, v2 * c + v1 * s, v[..., rd:]], -1)\n\n        for i in range(spec.layers):\n            p = f\"model.layers.{i}.\"\n            h = _fake_q(norm(x, W[p + \"input_layernorm.weight\"]), D)\n            q = (w(p + \"self_attn.q_proj.weight\") @ h).reshape(spec.n_q, d)\n            k = (w(p + \"self_attn.k_proj.weight\") @ h).reshape(spec.n_kv, d)\n            v = (w(p + \"self_attn.v_proj.weight\") @ h).reshape(spec.n_kv, d)\n            if spec.qk_norm:\n                q, k = norm(q, qk[i][0]), norm(k, qk[i][1])\n            if i not in spec.nope:\n                q, k = rot(q), rot(k)\n            Kc[i].append(_fake_k(k, D))\n            Vc[i].append(_v_parts(v))\n            K = np.stack([a for a, _ in Kc[i]], 1)\n            dK = None if Kc[i][0][1] is None else np.stack([b for _, b in Kc[i]], 1)\n            Vq, Vs = (np.stack(z, 1) for z in zip(*Vc[i]))\n            o = np.zeros((spec.n_q, d))\n            for hq in range(spec.n_q):\n                sc = _qk(_fake_q(q[hq] / math.sqrt(d), D), K[hq // G], None if dK is None\n                         else dK[hq // G], D)\n                pp = np.exp(sc - sc.max())\n                o[hq] = _pv(pp, Vq[hq // G], Vs[hq // G], D) / pp.sum()\n            x = x + w(p + \"self_attn.o_proj.weight\") @ _fake_q(o.reshape(-1), D)\n            h = _fake_q(norm(x, W[p + \"post_attention_layernorm.weight\"]), D)\n            g = w(p + \"mlp.gate_proj.weight\") @ h\n            u = w(p + \"mlp.up_proj.weight\") @ h\n            x = x + w(p + \"mlp.down_proj.weight\") @ _fake_q((g / (1 + np.exp(-g))) * u, D,\n                                                             chunk(i))\n        out.append(w(head) @ _fake_q(norm(x, W[\"model.norm.weight\"]), D))\n    return np.array(out)\n\n\n# =============================================================================== DRAM image\n# Attention: tokens per flash block (256 halves the per-block vector-unit latency overhead of\n# 128 at long contexts) and score blocks in flight per head.\nATTN_BLOCK = 256\nATTN_DEPTH = 3\n\n\nclass _Bump:\n    def __init__(self, start: int = 0):\n        self.next = start\n\n    def alloc(self, nbytes: int) -> int:\n        a = self.next\n        self.next = (a + nbytes + ALIGN - 1) // ALIGN * ALIGN\n        return a\n\n\ndef _qdesc(daddr: int, saddr: int, n: int, k: int, D: int, fmt: str = \"int8\") -> QTensor:\n    return QTensor.weight(daddr, saddr, n, k, fmt, D)\n\n\ndef _tdesc(addr: int, shape) -> Tensor:\n    shape = tuple(shape)\n    strides, st = [], 1\n    for n in reversed(shape):\n        strides.append(st)\n        st *= n\n    return Tensor(Affine(addr), shape, tuple(reversed(strides)))\n\n\nclass Image(EmbedHost):\n    \"\"\"Per-slice DRAM layout of a Qwen3 model. Every slice uses the same addresses.\n\n    [ I/O: x_in, cos, sin | final norm | logits ] [ layer 0 block ] ... [ layer L-1 block ]\n    [ LM head rows of this slice ]. A layer block holds the norms, this slice's rows of every\n    projection (quantized + scales) and this slice's KV heads with room for `cap` tokens, for\n    each of `batch` sequences; its layout follows the layer's weight formats. The layers run\n    as `runs` (first layer, (layout,), layers): each range of one layout a hardware loop over\n    its blocks, contiguous with their stride. The I/O area holds `rows` token rows (x, cos,\n    sin, logits).\n    A model with layers without RoPE (spec.nope) has a rope gate per layer block: (1, 0) or\n    (0, 1), and each layer rotates with cos * g0 + g1 and sin * g0 (_rope_gate).\n\n    Weight formats (opentpu/quant.py): `wformat` for the layers' projections, `head_format`\n    (default: the same) for the LM head: \"int8\", or 4-bit \"int4\" / \"fp4\". `formats` sets a\n    kind's format over wformat per layer range (opentpu/llm/formats.py, KINDS; None:\n    OTPU_FORMATS, else spec.formats): a layer block layout per combination, a run (a loop)\n    per range of one layout. The KV cache and the activations stay int8.\n    \"\"\"\n\n    def __init__(self, spec: Spec, cfg: Config, cap: int, batch: int = 1, rows: int = 1,\n                 wformat: str = \"int8\", head_format: str | None = None, lookup: bool = False,\n                 embed_host: bool | None = None, formats: str | None = None):\n        spec.check(cfg)\n        if cap % cfg.D:\n            raise ValueError(\"KV capacity must be a multiple of D\")\n        if spec.ctx and cap > spec.ctx:\n            raise ValueError(f\"KV capacity {cap} above the model's range ({spec.ctx}: RoPE, \"\n                             f\"a sliding window)\")\n        S, D = cfg.S, cfg.D\n        H, d, F_ = spec.hidden, spec.head_dim, spec.ffn\n        self.spec, self.cfg, self.cap = spec, cfg, cap\n        wformat, formats = FM.named(spec, wformat, formats)\n        fmt = FM.resolver(formats, KINDS, spec.formats, wformat, head_format)\n        # each layer's formats (attention, gate / up, down: its block's layout), the head's,\n        # and the formats string (for the compile worker)\n        self.lf = tuple((fmt(\"attn\", i), fmt(\"gateup\", i), fmt(\"down\", i))\n                        for i in range(spec.layers))\n        self.wformat, self.head_format = wformat, fmt(\"head\")\n        self.mf = self.mats_formats(self.lf[0])     # layer 0's projections' formats\n        self.formats = _formats(spec, formats)\n        rb = lambda k, f: Q.row_bytes(k, f, D)                          # noqa: E731\n        self.batch, self.rows = batch, rows\n        self.nq_loc, self.nkv_loc = spec.n_q // S, spec.n_kv // S\n        self.h_loc, self.f_loc, self.v_loc = H // S, F_ // S, spec.vocab // S\n        b = _Bump()\n        R = rows\n        rd = spec.rope_dim\n        self.io = {\"x\": b.alloc(4 * H * R), \"cos\": b.alloc(2 * rd * R),\n                   \"sin\": b.alloc(2 * rd * R), \"gf\": b.alloc(4 * H),\n                   \"logits\": b.alloc(4 * spec.vocab * R)}\n        from .prefill import tile_scratch   # a tiled run's attention outputs, a part at a time\n        if tile_scratch(spec, layer_runs=False):    # (tiled.py; a dense image's)\n            self.io[\"o\"] = b.alloc(4 * cfg.act_rows * self.nq_loc * d)\n        self.layer0 = b.next\n        self.mats = {\"wq\": (self.nq_loc * d, H), \"wk\": (self.nkv_loc * d, H),\n                     \"wv\": (self.nkv_loc * d, H), \"wo\": (self.h_loc, spec.n_q * d),\n                     \"wg\": (self.f_loc, H), \"wu\": (self.f_loc, H)}\n        # W_down in column parts of the MLP's F chunk: each down MM streams one part, whose\n        # scales are then contiguous (with row-major scales every row would cost a DRAM beat);\n        # the chunk by W_down's format\n        self.dchunks = {fd: _chunk(self.f_loc, D, D if fd == \"int8\" else 2 * D)\n                        for fd in sorted({f[2] for f in self.lf})}\n        self.dchunk = self.dchunks[self.lf[0][2]]\n        self.bofs, self.bsize = {}, {}                  # per layout: offsets inside its block\n        for key in dict.fromkeys(self.lf):\n            mf, C = self.mats_formats(key), self.dchunks[key[2]]\n            lb = _Bump()\n            L = {\"g_in\": lb.alloc(4 * H), \"g_post\": lb.alloc(4 * H)}\n            if spec.qk_norm:\n                L.update(qn=lb.alloc(4 * d), kn=lb.alloc(4 * d))\n            if spec.nope:\n                L[\"rg\"] = lb.alloc(8)\n            for name, (n, k) in self.mats.items():\n                L[name] = (lb.alloc(n * rb(k, mf[name])),\n                           lb.alloc(n * Q.scale_bytes(k, mf[name], D)))\n            L[\"wd\"] = [(lb.alloc(self.h_loc * rb(C, mf[\"wd\"])),\n                        lb.alloc(self.h_loc * Q.scale_bytes(C, mf[\"wd\"], D)))\n                       for _ in range(F_ // C)]\n            L[\"kvs\"] = [[{\"k\": lb.alloc(cap * d), \"ks\": lb.alloc(cap * k_scale_bytes(d, D)),\n                          \"vt\": lb.alloc(d * cap), \"vs\": lb.alloc(4 * cap)}\n                         for _ in range(self.nkv_loc)] for _ in range(batch)]\n            L[\"kv\"] = L[\"kvs\"][0]\n            self.bofs[key], self.bsize[key] = L, (lb.next + 4095) // 4096 * 4096\n        self.lofs, self.LS = self.bofs[self.lf[0]], self.bsize[self.lf[0]]   # layer 0's\n        # the runs: each range of layers of one layout a hardware loop (one layer body in the\n        # program per run: a pattern repeated in units, lfm2.plan's, would unroll each unit)\n        self.runs = []\n        for i, key in enumerate(self.lf):\n            if self.runs and self.runs[-1][1] == (key,):\n                first, unit, reps = self.runs[-1]\n                self.runs[-1] = (first, unit, reps + 1)\n            else:\n                self.runs.append((i, (key,), 1))\n        self.loc = {}                   # layer -> (run base, unit stride, iteration, offset)\n        b.next = self.layer0\n        for first, unit, reps in self.runs:\n            offs = np.cumsum([0] + [self.bsize[k] for k in unit]).tolist()\n            us, base = offs[-1], b.next\n            for it in range(reps):\n                for e in range(len(unit)):\n                    self.loc[first + it * len(unit) + e] = (base, us, it, offs[e])\n            b.next = base + reps * us\n        head = cap * d + cap * k_scale_bytes(d, D) + d * cap + 4 * cap   # k, k scales, v^T, v's\n        self.kv_bytes = spec.layers * self.nkv_loc * head         # per sequence\n        self.head = (b.alloc(self.v_loc * Q.row_bytes(H, self.head_format, D)),\n                     b.alloc(self.v_loc * Q.scale_bytes(H, self.head_format, D)))\n        # the int8 embedding rows of the resident decode are the tied int8 head's (S = 1)\n        shared = spec.tied and self.head_format == \"int8\" and S == 1\n        if embed_host is None:      # dense: the int8 table stays on the card (the Engine moves\n            embed_host = False      # it to the host when the image does not fit otherwise)\n        if embed_host and not lookup:\n            raise ValueError(\"embed_host needs the image's lookup tables (lookup=True)\")\n        self.lookup = _lookup_alloc(b, spec, cap, D=D, head=self.head if shared else None,\n                                    M=cfg.MCOLS, embed_host=bool(embed_host),\n                                    rows=rows, imem=cfg.IMEM_WORDS,\n                                    waitc=cfg.SEQ_WC) if lookup else {}\n        self.choices = {\"embed_host\": self.embed_host,          # (the compile worker's\n                        \"formats\": self.formats}                # image)\n        self.nbytes = b.next\n        if self.nbytes > cfg.DRAM_BYTES:\n            raise MemoryError(f\"model image needs {self.nbytes / 2**20:.0f} MiB per slice, \"\n                              f\"DRAM_BYTES is {cfg.DRAM_BYTES / 2**20:.0f} MiB\")\n\n    # ---- contents\n    def build(self, W: dict) -> list[np.ndarray]:\n        \"\"\"DRAM images (one per slice) with every weight quantized in place, KV cache empty.\"\"\"\n        spec, cfg = self.spec, self.cfg\n        S, D, d = cfg.S, cfg.D, spec.head_dim\n        imgs = [np.zeros(self.nbytes, np.uint8) for _ in range(S)]\n\n        def put(s, addr, a):\n            v = np.ascontiguousarray(a).view(np.uint8).reshape(-1)\n            imgs[s][addr:addr + v.size] = v\n\n        qb = QC.Batch()                 # the matrices, quantized in worker processes\n\n        def put_q(addr_pair, parts, fmt):\n            for s, p in enumerate(parts):\n                qb.submit(p, fmt, D, lambda q, sc, s=s: (put(s, addr_pair[0], q),\n                                                         put(s, addr_pair[1], sc)))\n\n        def put_parts(addrs, parts, fmt, C):\n            \"\"\"Each slice's rows quantized whole and stored in column parts of C (compiler\n            QTensor parts: each part's scale rows the rows' Sw and its blocks' offsets).\"\"\"\n            for s, p in enumerate(parts):\n                qb.submit(p, fmt, D, lambda q, sc, s=s: [\n                    (put(s, a0, pq), put(s, a1, ps))\n                    for (a0, a1), (pq, ps) in zip(addrs, Q.column_parts(q, sc, fmt, p.shape[1],\n                                                                         C, D))])\n\n        def rows(a, n):\n            return [a[s * n:(s + 1) * n] for s in range(S)]\n\n        def f32(a):\n            return F.ftz(np.asarray(a, np.float32))\n\n        for s in range(S):\n            put(s, self.io[\"gf\"], f32(W[\"model.norm.weight\"]))\n        for i in range(spec.layers):\n            p, base, lofs = f\"model.layers.{i}.\", self._off(i).const, self.bofs[self.lf[i]]\n            mf = self.mats_formats(self.lf[i])\n            Lo = {k: (tuple(base + x for x in v) if isinstance(v, tuple) else\n                      (base + v if isinstance(v, int) else v)) for k, v in lofs.items()}\n            qk = qk_gains(spec, W, p) if spec.qk_norm else None\n            for s in range(S):\n                put(s, Lo[\"g_in\"], f32(W[p + \"input_layernorm.weight\"]))\n                put(s, Lo[\"g_post\"], f32(W[p + \"post_attention_layernorm.weight\"]))\n                if spec.qk_norm:\n                    put(s, Lo[\"qn\"], f32(qk[0]))\n                    put(s, Lo[\"kn\"], f32(qk[1]))\n                if spec.nope:\n                    put(s, Lo[\"rg\"], np.array([0, 1] if i in spec.nope else [1, 0], np.float32))\n            wq, wk, wv, wo = head_parallel_attention_weights(\n                W[p + \"self_attn.q_proj.weight\"], W[p + \"self_attn.k_proj.weight\"],\n                W[p + \"self_attn.v_proj.weight\"], W[p + \"self_attn.o_proj.weight\"],\n                spec.n_q, spec.n_kv, d, S)\n            put_q(Lo[\"wq\"], rows(wq, self.nq_loc * d), mf[\"wq\"])\n            put_q(Lo[\"wk\"], rows(wk, self.nkv_loc * d), mf[\"wk\"])\n            put_q(Lo[\"wv\"], rows(wv, self.nkv_loc * d), mf[\"wv\"])\n            put_q(Lo[\"wo\"], rows(wo, self.h_loc), mf[\"wo\"])\n            put_q(Lo[\"wg\"], rows(W[p + \"mlp.gate_proj.weight\"], self.f_loc), mf[\"wg\"])\n            put_q(Lo[\"wu\"], rows(W[p + \"mlp.up_proj.weight\"], self.f_loc), mf[\"wu\"])\n            put_parts([(base + x, base + y) for x, y in lofs[\"wd\"]],\n                      rows(W[p + \"mlp.down_proj.weight\"], self.h_loc), mf[\"wd\"],\n                      self.dchunks[mf[\"wd\"]])\n        put_head(self, W, qb, put, put_q, rows)\n        qb.wait()\n        if self.lookup:\n            _lookup_build(put, S, W, spec, self.cap, self.lookup)\n        return imgs\n\n    @staticmethod\n    def mats_formats(key) -> dict:\n        \"\"\"The projections' formats of a layer block of formats `key` (attention, gate / up,\n        down).\"\"\"\n        fa, fg, fd = key\n        return {\"wq\": fa, \"wk\": fa, \"wv\": fa, \"wo\": fa, \"wg\": fg, \"wu\": fg, \"wd\": fd}\n\n    def _off(self, li, it=None) -> Affine:\n        \"\"\"The block address of layer li (static), or of element li of its run's unit at\n        iteration `it` (a loop variable).\"\"\"\n        base, us, i, o = self.loc[li]\n        return Affine(base + o) + Affine.of(i if it is None else it) * us\n\n    # ---- programs\n    def compile_decode(self, blocks: int, lo: int, block: int = ATTN_BLOCK):\n        \"\"\"(programs, run_args): qwen3_step at a run-time position (compile_decode).\"\"\"\n        return compile_decode(self, qwen3_step, blocks, lo, block)\n\n    def compile_generate(self, blocks: int, lo: int, block: int = ATTN_BLOCK,\n                         chain: bool = True, samp=None, debug: bool = False,\n                         part: int | None = None) -> list:\n        \"\"\"The decode loop on the device for bucket `blocks` (qwen3_step in it, generate.py).\"\"\"\n        return G.compile_generate(self, qwen3_step, blocks, lo, block, chain, samp, debug, part)\n\n    def compile_step(self, pos: int, block: int = ATTN_BLOCK, tok: int | None = None) -> list:\n        \"\"\"One program per slice: the decode token at position `pos` (qwen3_step); with `tok`\n        (an image with lookup tables) its inputs come from the tables, not the host.\"\"\"\n        return [trace_fit(qwen3_step, self.cfg, s,\n                          lambda s=s: {\"m\": step_descriptors(self, s), \"pos\": pos,\n                                       \"block\": block, **_tok_arg(self, tok)}).finish()\n                for s in range(self.cfg.S)]\n\n    def compile_rows(self, rows, logit_rows, block: int = ATTN_BLOCK, tokens=None) -> list:\n        \"\"\"One program per slice: token rows (sequence, position) at once (qwen3_rows); with\n        `tokens` (an image with lookup tables) their inputs come from the tables.\"\"\"\n        if len(rows) > self.rows:\n            raise ValueError(f\"{len(rows)} rows, the image's I/O area holds {self.rows}\")\n        return [qwen3_rows.trace(self.cfg, s, {\"m\": self.descriptors(s), \"rows\": list(rows),\n                                               \"logit_rows\": list(logit_rows), \"block\": block,\n                                               **_tokens_arg(self, tokens, rows)}).finish()\n                for s in range(self.cfg.S)]\n\n    def compile_prompt_run(self, blocks: int, R: int, kind: str, block: int = ATTN_BLOCK):\n        \"\"\"qwen3_prompt_run's (programs, run_args) (docs/prefill.md), a program per slice: R\n        rows of a prompt at a run-time position of bucket `blocks` (the position in the state's\n        tpos word; run_args name the words, RunWords).\"\"\"\n        if not self.lookup:\n            raise ValueError(\"a prompt run needs lookup tables (lookup=True)\")\n        if kind not in (\"P\", \"L\"):\n            raise ValueError(f\"prompt run kind {kind!r}\")\n        pos = RunRows(blocks, block, (blocks - 1) * block, self.lookup[\"zmask\"], self.cap, R, 0,\n                      _amask(self.lookup))\n        bs = [qwen3_prompt_run.trace(self.cfg, s, {\"m\": self.descriptors(s), \"pos\": pos, \"R\": R,\n                                                   \"kind\": kind, \"block\": block})\n              for s in range(self.cfg.S)]\n        return [b.finish() for b in bs], list(bs[0].run_args)\n\n    # ---- kernel descriptors\n    def descriptors(self, sid: int) -> SimpleNamespace:\n        spec, cfg = self.spec, self.cfg\n        D, d, H = cfg.D, spec.head_dim, spec.hidden\n        rh = spec.rope_dim // 2\n\n        def layer(li, it=None):\n            \"\"\"Descriptors of layer `li` (static), or of element li of its run's unit at\n            iteration `it` (a hardware-loop variable).\"\"\"\n            off = self._off(li, it)\n            lofs, mf = self.bofs[self.lf[li]], self.mats_formats(self.lf[li])\n            ns = SimpleNamespace(\n                g_in=Tensor(off + lofs[\"g_in\"], (H,), (1,)),\n                g_post=Tensor(off + lofs[\"g_post\"], (H,), (1,)),\n                qn=Tensor(off + lofs[\"qn\"], (d,), (1,)) if spec.qk_norm else None,\n                kn=Tensor(off + lofs[\"kn\"], (d,), (1,)) if spec.qk_norm else None,\n                rg=Tensor(off + lofs[\"rg\"], (2,), (1,)) if spec.nope else None)\n            for name, (n, k) in self.mats.items():\n                da, sa = lofs[name]\n                fm = mf[name]\n                setattr(ns, name, QTensor.weight(off + da, off + sa, n, k, fm, D))\n            fm = mf[\"wd\"]\n            C, n = self.dchunks[fm], self.h_loc\n            parts = tuple(QTensor.weight(off + da, off + sa, n, C, fm, D)\n                          for da, sa in lofs[\"wd\"])\n            ns.wd = QTensor(parts[0].data, parts[0].scale, (n, spec.ffn), parts[0].rs,\n                            parts[0].srs, D, parts=parts, pw=C, wf=parts[0].wf)\n            ns.kvs = [KVDesc({sid + j * cfg.S: {k: off + v for k, v in r.items()}\n                              for j, r in enumerate(heads)}, self.cap, d, D, cfg.S, sid)\n                      for heads in lofs[\"kvs\"]]\n            ns.kv = ns.kvs[0]\n            return ns\n\n        return SimpleNamespace(\n            spec=spec, layer=layer, runs=self.runs,\n            x=_tdesc(self.io[\"x\"], (1, H)), cos=_tdesc(self.io[\"cos\"], (rh,)),\n            sin=_tdesc(self.io[\"sin\"], (rh,)), g_final=_tdesc(self.io[\"gf\"], (H,)),\n            logits=_tdesc(self.io[\"logits\"], (1, spec.vocab)),\n            xr=_tdesc(self.io[\"x\"], (self.rows, H)),\n            cosr=_tdesc(self.io[\"cos\"], (self.rows, rh)),\n            sinr=_tdesc(self.io[\"sin\"], (self.rows, rh)),\n            logitsr=_tdesc(self.io[\"logits\"], (self.rows, spec.vocab)),\n            oscr=_tdesc(self.io[\"o\"], (cfg.act_rows, self.nq_loc * d)) if \"o\" in self.io\n            else None,\n            head=_qdesc(*self.head, self.v_loc, H, D, self.head_format), v_loc=self.v_loc,\n            **_lookup_desc(self.lookup, spec, self.cap))\n\n\n# =============================================================================== kernel\ndef _padded(x):\n    \"\"\"Rows of one head each, as the KV cache stores them: with head_dim < D (LFM2: 64) padded\n    with zeros to a whole MXU block. q.K^T contracts over D, so the cached K rows and the\n    queries carry zeros beyond head_dim (the scores are unchanged); a quantized store writes\n    whole blocks, so V's zero rows are stored too, but P.V reads only its head_dim rows.\"\"\"\n    d, D = x.cols, ol.block_size()\n    if d % D == 0:\n        return x\n    out = ol.zeros([x.rows, -(-d // D) * D])\n    out[:, :d].set(x)\n    return out\n\n\ndef _rope_padded(x, c, s_, out=None):\n    \"\"\"rope(x) on the first 2 * len(c) dimensions of each row (the others pass through:\n    Qwen3.5's partial RoPE), padded like _padded (RoPE writes straight into the padded tile),\n    or into `out` (a view whose columns beyond x.cols are already zero).\"\"\"\n    d, D, rd = x.cols, ol.block_size(), 2 * c.cols\n    if out is None and d % D == 0 and rd == d:\n        return rope(x, c, s_)\n    if out is None:\n        out = ol.zeros([x.rows, -(-d // D) * D]) if d % D else ol.empty(x.shape)\n    rope(x[:, :rd], c, s_, out=out[:, :rd])\n    if rd < d:\n        out[:, rd:d].set(x[:, rd:])\n    return out\n\n\ndef _norm_heads(x, g, eps):\n    \"\"\"RMSNorm on each row (one head) with gamma `g` (a loaded q_norm / k_norm), or x itself\n    for a model without them (g None: the Llama-likes).\"\"\"\n    return x if g is None else rmsnorm(x, g, eps)\n\n\ndef _rope_gate(lw, c, s_):\n    \"\"\"The layer's RoPE tables: (c, s_) themselves, or with a rope gate (spec.nope: a model\n    with layers without RoPE) c * g0 + g1 and s_ * g0 -- (c, s_) bit for bit where g = (1, 0),\n    the identity rotation (1, +-0) where g = (0, 1). One loop body then serves both kinds.\"\"\"\n    if getattr(lw, \"rg\", None) is None:\n        return c, s_\n    g = ol.load(lw.rg)\n    return c * g[0:1] + g[1:2], s_ * g[0:1]\n\n\ndef _load_opt(desc):\n    return None if desc is None else ol.load(desc)\n\n\nclass RunPos:\n    \"\"\"The decode position as a run-time value (docs/isa.md \"Arguments\"): one program serves\n    every position p of a bucket, lo <= p < blocks * block, whose attention spans `blocks`\n    blocks (the last one masked: attention.Bucket). The program sees p as t0 + tpos, t0 =\n    (blocks - 1) * block the bucket's first position and tpos = p - t0 < block the run-time\n    value (so the V^T append stays in its 256-token tile: compiler.tile_split). The token's\n    embedding and RoPE rows come from the image's tables (Image(lookup=True)) at the token id\n    and the position; the KV cache appends at the position; ring is (p + 1) mod K, the first\n    row of the last K in a mirrored K-row state ring (LFM2's convolutions: lfm2._ring_rows).\n    values(token, p, K, block) and compiler.arg_words give the argument words of a program's\n    run_args.\"\"\"\n\n    tok, ring = RunVar(\"tok\"), RunVar(\"ring\")\n\n    def __init__(self, blocks: int, block: int, lo: int, zmask: int, cap: int):\n        self.blocks, self.block, self.lo = blocks, block, lo\n        self.t0 = (blocks - 1) * block\n        self.tpos = RunVar(\"tpos\", bound=min(block, cap - self.t0))\n        self.pos = self.tpos + self.t0\n        # the mask row of a block at t0' starts at entry cap - 1 - p + t0' of the table\n        self.bucket = Bucket(blocks, Affine(zmask + 4 * (cap - 1 - self.t0)) + self.tpos * -4)\n\n    @staticmethod\n    def values(token: int, p: int, K: int = 1, block: int = ATTN_BLOCK) -> dict:\n        return {\"tpos\": p % block, \"tok\": token, \"ring\": (p + 1) % K}\n\n    def offset(self, r: int) -> \"RunPos\":\n        \"\"\"Row r of a run of rows from this position, in its attention block (a layer-major\n        prefill run, Engine.prefill_layers): position p + r, its mask row r entries on (the\n        same run-time values).\"\"\"\n        q = object.__new__(type(self))\n        q.__dict__.update(self.__dict__)\n        q.tpos, q.pos = self.tpos + r, self.pos + r\n        q.bucket = Bucket(self.blocks, self.bucket.z - 4 * r)\n        return q\n\n\nclass RunRows(RunPos):\n    \"\"\"R consecutive rows at a run-time position (MTP's verify and draft runs, docs/mtp.md 10):\n    row r is position t0 + tpos + r, every row in the bucket (tpos <= block - R), its token the\n    run-time value toks[r] (tok, tok1, ...); row r attends over the bucket with the mask row\n    of its own position (bucket_row). values(tokens, p) gives the run's argument values.\n    toks_at k (a prefill run, docs/prefill.md): the tokens from the generate area's out[]\n    instead, row r's at out[p + k + r], loaded once by the run: no argument per token. amask\n    (a prompt run's: the image's _amask): row r's masked block takes the additive tile of its\n    position in the block (attention.Additive, docs/prefill.md 9) instead of a mask row.\"\"\"\n\n    def __init__(self, blocks: int, block: int, lo: int, zmask: int, cap: int, R: int,\n                 toks_at: int | None = None, amask: tuple | None = None):\n        super().__init__(blocks, block, lo, zmask, cap)\n        if not 0 < R <= min(block, cap - self.t0):\n            raise ValueError(f\"{R} rows do not fit bucket {blocks}\")\n        self.R, self.toks_at, self.amask = R, toks_at, amask\n        self.tpos.bound = min(block, cap - self.t0) - R + 1\n        self.toks = [] if toks_at is not None else \\\n            [self.tok] + [RunVar(f\"tok{r}\") for r in range(1, R)]\n\n    def bucket_row(self, r: int) -> Bucket:\n        if self.amask is None:\n            return Bucket(self.blocks, self.bucket.z - 4 * r)\n        base, step = self.amask\n        return Bucket(self.blocks, self.bucket.z - 4 * r,\n                      Additive(Affine(base + step * r) + self.tpos * step, self.block))\n\n    @staticmethod\n    def values(tokens, p: int, K: int = 1, block: int = ATTN_BLOCK) -> dict:\n        v = RunPos.values(tokens[0], p, K, block)\n        v.update({f\"tok{r}\": t for r, t in enumerate(tokens) if r})\n        return v\n\n\ndef _attention(x, lw, c, s_, pos: int, spec: Spec, block: int, gated: bool = False):\n    \"\"\"x + W_o . attention(x) for one token, this slice's heads; returns the new residual\n    (replicated on every slice).\n\n    Schedule (the MXU streams weights in program order, so what sits between two MMs in the\n    stream overlaps them): K, V and then Q (one MM per KV head's query group) are projected\n    first, back to back, and the K / V norms, RoPE and K appends run while Q streams. Each\n    head's V^T append and query preparation follow in the attention pipeline (_attend_heads),\n    so the quantizer's slow V^T appends (a byte into each of d cache rows) overlap the heads\n    before it instead of holding all queries back. The Q MMs come before the appends and\n    queries in program order so that the sequencer's window, which the appends fill, never\n    holds the MXU's next MM back.\n\n    A query group of more heads than the MXU has columns attends in parts of MCOLS heads, each\n    streaming the KV head again. `gated` (Qwen3.5): lw.wgate projects a gate per query\n    dimension, and the attention output is multiplied by sigmoid(gate) before W_o.\"\"\"\n    d, G, eps = spec.head_dim, spec.n_q // spec.n_kv, spec.eps\n    kv = lw.kv\n    kpos = pos.pos if isinstance(pos, RunPos) else pos\n    xs = ol.quantize(rmsnorm(x, ol.load(lw.g_in), eps))\n    k = ol.dot(xs, lw.wk)                       # [1, nkv_loc*d]\n    v = ol.dot(xs, lw.wv)\n    sg = sigmoid(ol.dot(xs, lw.wgate)) if gated else None       # [1, nq_loc*d]\n    qn, kn = _load_opt(lw.qn), _load_opt(lw.kn)\n    c, s_ = _rope_gate(lw, c, s_)\n    scale = ol.LOG2E / math.sqrt(d)\n    heads = list(kv.owned_heads(spec.n_kv))\n    nh = len(heads)\n    qps = [ol.dot(xs, lw.wq[j * G * d:(j + 1) * G * d, :]) for j in range(nh)]  # [1, G*d]\n    kh = _rope_padded(_norm_heads(k.reshape(nh, d), kn, eps), c, s_)  # [nkv_loc, d or D]\n    vh = _padded(v.reshape(nh, d))\n    for j, hh in enumerate(heads):\n        ol.kv_append(kv, hh, kpos, kh[j:j + 1, :], None)\n\n    def queries(j):\n        def emit():\n            # the head's V^T append (byte-strided, the quantizer's slowest store) just ahead of\n            # its queries: head j's scores start after K and V_0..V_j, not after all V appends\n            ol.kv_append(kv, heads[j], kpos, None, vh[j:j + 1, :])\n            return _rope_padded(_norm_heads(qps[j].reshape(G, d), qn, eps), c, s_)\n        return emit\n\n    mc = min(G, ol.mxu_columns())\n    parts = [(j, g0, min(G, g0 + mc)) for j in range(nh) for g0 in range(0, G, mc)]\n    if mc == G:\n        qhs = [queries(j) for j in range(nh)]\n    else:\n        groups = {}\n\n        def part(j, g0, g1):\n            def emit():                         # the group's queries, made for its first part\n                if j not in groups:\n                    groups[j] = queries(j)()\n                qg = groups.pop(j) if g1 == G else groups[j]\n                return qg[g0:g1, :]\n            return emit\n        qhs = [part(*p) for p in parts]\n    seq = pos.bucket if isinstance(pos, RunPos) else pos + 1\n    outs = _attend_heads(qhs, kv, [heads[j] for j, _, _ in parts], seq, block, scale,\n                         depth=ATTN_DEPTH, ahead=2)\n    o_row = ol.empty([1, G * nh * d])\n    o_loc = o_row.reshape(G * nh, d)            # the heads' outputs, written in place\n    for (j, g0, g1), (acc, l) in zip(parts, outs):\n        r0, r1 = j * G + g0, j * G + g1\n        if sg is None:\n            o_loc[r0:r1, :].set(acc / l[:, None])\n        else:\n            o_loc[r0:r1, :].set((acc / l[:, None]) * sg.reshape(G * nh, d)[r0:r1, :])\n    o_all = ol.all_gather(o_row)                # [1, n_q*d], slice-major head order\n    y = ol.all_gather(ol.dot(o_all, lw.wo))     # [1, H]\n    return x + y\n\n\ndef _mlp(x, lw, spec: Spec):\n    sid = ol.program_id()\n    xs = ol.quantize(rmsnorm(x, ol.load(lw.g_post), spec.eps))\n    y = swiglu_down(xs, lw.wg, lw.wu, lw.wd, loop=getattr(lw, \"mlp_loop\", False))\n    h_loc = lw.wd.shape[0]\n    mine = slice(sid * h_loc, (sid + 1) * h_loc)\n    return ol.all_gather(x[:, mine] + y)\n\n\n# Token rows per device run of a prefill: the I/O area holds this many, and TMEM (64K words)\n# holds the activations of 8 rows of Qwen3-0.6B (Engine.prefill_chunks shrinks a run that does\n# not fit).\nPREFILL_ROWS = 8\nCOMPILE_AHEAD = 3    # decode programs compiled ahead by the worker processes (Engine)\nDECODE_LEAD = 16     # resident decode: the next bucket's program is compiled from this many\n                     # positions before the current bucket ends (Engine)\nHEAD_CHUNK = 8192     # LM head rows per MM (the fp32 logits of one chunk must fit TMEM)\nAHEAD_PART = 1 << 20  # layer_ahead \"hint\" and expert_major: an idle poll's part of a queued expert\n                      # (docs/offload.md 13.9: 1 MiB parts against 13.8's 512 KiB, the per-part\n                      # cost halved)\n\n\ndef fill_logits(m) -> None:\n    \"\"\"A step program's first instructions when compiled with fill (m.fill: the engine's\n    streamed logits, BoardBackend.start(stream=...)): FILL_SENTINEL (-inf: VOP FILL keeps it;\n    the LM head's logits are finite) over this slice's logits in HEAD_CHUNK stores, so that\n    the host tells the pieces the LM head has written from the last token's. Then one word\n    loaded back from the last store (it waits for that ST, which completes only once the DRAM\n    has taken every write so far: the host's reads see the fill) into an RLD, which holds\n    every later instruction until the word is back: once the card's ICOUNT has counted the\n    instruction after the RLD, the fill has landed (fill_gate). Static addresses and no loop,\n    so ICOUNT counts each instruction before it once; the rest of the program is the one\n    compiled without the fill (TMEM's next-fit cursor put back). Nothing in the generate loop's\n    programs (lm_sink / lm_split).\"\"\"\n    if not getattr(m, \"fill\", False) or getattr(m, \"lm_sink\", None) is not None or \\\n            getattr(m, \"lm_split\", None) is not None:\n        return\n    b, sid = current(), ol.program_id()\n    cursor = b.tmem_next\n    n = min(HEAD_CHUNK, ol.tmem_words() // 8, m.v_loc)\n    t = ol.full([n], -math.inf)                     # FILL_SENTINEL\n    for c0 in range(0, m.v_loc, n):\n        k = min(n, m.v_loc - c0)\n        col = sid * m.v_loc + c0\n        ol.store(m.logits[0, col:col + k], t[:k])\n    last = sid * m.v_loc + m.v_loc - 1\n    b.rld(0, ol.load(m.logits[0, last:last + 1], out=t[0:1]), comment=\"logits fill landed\")\n    del t\n    b.tmem_next = cursor        # the rest of the program as compiled without the fill\n\n\ndef fill_gate(prog) -> int:\n    \"\"\"The ICOUNT past fill_logits' RLD in `prog` (a slice's instructions, or their words): the\n    instructions up to the first RLD, plus the one after it. (Instructions read back from the\n    program cache have no comments: there the first RLD must be into r0, as the fill's.)\"\"\"\n    if isinstance(prog, np.ndarray):\n        ops = np.asarray(prog, np.uint32).reshape(-1, 8)[:, 0] & 0xFF\n        at = np.flatnonzero(ops[:512] == I.RLD)         # near the start: no whole scan\n        if not len(at):\n            at = np.flatnonzero(ops == I.RLD)\n        if not len(at):\n            raise ValueError(\"no RLD: not a program compiled with fill\")\n        return int(at[0]) + 2\n    for i, ins in enumerate(prog):\n        if ins.op == I.RLD:\n            if ins.comment != \"logits fill landed\" and (ins.comment or ins.rd != 0):\n                raise ValueError(\"the program's first RLD is not fill_logits'\")\n            return i + 2\n    raise ValueError(\"no RLD: not a program compiled with fill\")\n\n\ndef step_descriptors(image, sid: int) -> SimpleNamespace:\n    \"\"\"image.descriptors(sid) for a decode step's program (compile_step, compile_decode): with\n    fill_logits when the image's engine streams the logits (image.stream_fill).\"\"\"\n    m = image.descriptors(sid)\n    m.fill = bool(getattr(image, \"stream_fill\", False))\n    return m\n\n\n@ol.jit\ndef qwen3_step(m, pos: int, block: int = ATTN_BLOCK, tok: int | None = None):\n    \"\"\"One decode token at position `pos`: x (the token's embedding) -> logits.\n\n    The layers run as a hardware loop; each layer appends its K/V at `pos` and attends over\n    positions 0..pos. Logits for this slice's vocabulary rows are stored to m.logits. `tok`:\n    the token's id, its inputs read from the image's tables (_inputs).\n    \"\"\"\n    fill_logits(m)\n    spec = m.spec\n    x, c, s_ = _inputs(m, pos, tok)\n    for lw in _layers(m):\n        x.set(_attention(x, lw, c, s_, pos, spec, block))\n        x.set(_mlp(x, lw, spec))\n    _lm_head(x, m, spec)\n\n\ndef _layers(m):\n    \"\"\"Each layer's descriptors in the order the layers run (m.runs, Image): a run of repeats\n    is one hardware loop over its unit (inside the loop the descriptors are the iteration's).\"\"\"\n    for first, unit, reps in m.runs:\n        if reps == 1:\n            for e in range(len(unit)):\n                yield m.layer(first + e)\n            continue\n        for it in ol.range(reps):\n            for e in range(len(unit)):\n                yield m.layer(first + e, it)\n\n\ndef _inputs(m, pos, tok=None):\n    \"\"\"The token's embedding row and its RoPE rows: from the I/O area (the host writes them),\n    or from the image's tables (Image(lookup=True)) at the token id and position -- at a\n    run-time position (RunPos), or at a compile-time token `tok` (a per-position program).\"\"\"\n    if isinstance(pos, RunPos):\n        x = _embed(m, pos.tok)\n        ol.release(pos.tok)                 # its argument registers serve addresses from here on\n        return x, ol.load(m.cos_t[pos.pos, :]), ol.load(m.sin_t[pos.pos, :])\n    if tok is None:\n        return ol.load(m.x), ol.load(m.cos), ol.load(m.sin)\n    return _embed(m, tok), ol.load(m.cos_t[pos, :]), ol.load(m.sin_t[pos, :])\n\n\ndef _embed(m, tok):\n    \"\"\"Token `tok`'s embedding row [1, H] (an int or a run-time value) from the image's tables:\n    the fp32 table's row, or the int8 row gathered on the device (Spec.embed \"int8\"); with the\n    table on the host (embed_host) the slot's row 0, once the host has served every request\n    (the generate loop's post of the token; before other runs the host writes the row).\"\"\"\n    eq = getattr(m, \"embed_q\", None)\n    if eq is None:\n        return ol.load(m.embed[tok:tok + 1, :])\n    mbox = getattr(m, \"embed_mbox\", None)\n    if mbox is not None:\n        MB.wait_served(mbox)\n        tok = 0\n    return next(_gather(m, eq, [tok]))\n\n\nclass OutTokens:\n    \"\"\"Rows' tokens from the generate area's out[] (a prefill run, docs/prefill.md): row r's\n    at out[p + k + r], p the run's first position; loaded by the run, so the program does not\n    depend on them (_inputs_rows's `tokens`).\"\"\"\n\n    def __init__(self, k: int = 0):\n        self.k = k\n\n\nS_RINGO = 32        # prompt runs: LFM2's ring rotation after the run (lfm2._ring_store)\nRUN_WORDS = {\"tpos\": G.S_TPOS, \"ring\": G.S_RING, \"ringo\": S_RINGO}\n\n\nclass RunWords:\n    \"\"\"A prompt run's position (docs/prefill.md): with a RunRows, the run-time arguments come\n    from the generate state's words (RUN_WORDS: tpos, LFM2's ring; the compiler's run_words,\n    no host arguments), loaded at the program's start once the kernel has named them, and\n    pos.words gives the kernel their TMEM addresses (LFM2's ringo); with a compile-time\n    position, nothing. `with RunWords(m, pos): kernel(...)`; the host writes the words before\n    each run (prefill.run: those the run_args name and the image's prompt_words).\"\"\"\n\n    def __init__(self, m, pos):\n        self.m, self.pos, self.run = m, pos, isinstance(pos, RunRows)\n\n    def __enter__(self):\n        if self.run:\n            b = current()\n            n = max(RUN_WORDS.values()) + 1\n            self.st = ol.load(self.m.gen.state[0:n])\n            self.at = b.stack[-1][-1]\n            b.run_words = {k: self.st.base + w for k, w in RUN_WORDS.items()}\n            self.pos.words = dict(b.run_words)          # (TMEM addresses for the kernel's RLDs)\n        return self\n\n    def __exit__(self, *exc):\n        if self.run and exc[0] is None:\n            b = current()\n            body = b.stack[-1]\n            i = next(j for j, x in enumerate(body) if x is self.at) + 1\n            body[i:i] = [I.rld(15 - k, b.run_words[v.name], mul=int(c),\n                               comment=f\"argument {c}*{v.name}\")\n                         for k, (v, c) in enumerate(b.run_args)]\n            b.run_words = None\n        return False\n\n\ndef _embed_word(m, t):\n    \"\"\"_embed of the token id in the one-word tile t (a prefill run's, docs/prefill.md): its\n    row's address from a scratch register (RLD MUL into a compiler.DevVar) instead of a\n    run-time argument; the int8 table's row and its scales from two.\"\"\"\n    b = current()\n    b.check_live(t)\n    if getattr(m, \"embed_mbox\", None) is not None:\n        raise CompileError(\"a token from DRAM needs the embedding table on the card\")\n    eq = getattr(m, \"embed_q\", None)\n    if eq is None:\n        e = m.embed\n        r = b.scratch()\n        b.emit(I.rld(r, t.base, mul=4 * e.strides[0], comment=\"the token's row\"))\n        row = ol.load(Tensor(Affine.of(e.base) + DevVar(\"token row\", r), (1, e.shape[1]),\n                             e.strides))\n        b.unscratch(r)\n        return row\n    rd, rs = b.scratch(), b.scratch()\n    b.emit(I.rld(rd, t.base, mul=eq.rs, comment=\"the token's row\"))\n    b.emit(I.rld(rs, t.base, mul=eq.srs, comment=\"its scales\"))\n    one = QTensor(Affine.of(eq.data) + DevVar(\"token row\", rd),\n                  Affine.of(eq.scale) + DevVar(\"token scales\", rs), (1, eq.shape[1]), eq.rs,\n                  eq.srs, eq.D, wf=eq.wf)\n    row = next(_gather(m, one, [0]))\n    b.unscratch(rd)\n    b.unscratch(rs)\n    return row\n\n\ndef _inputs_rows(m, rows, tokens=None, embed: bool = True):\n    \"\"\"_inputs for token rows (rows[r] = (sequence, position)): from the I/O area, or with\n    `tokens` (their ids, compile-time values) from the image's tables, the embedding row of\n    each token and the RoPE rows of each run of consecutive positions. rows a RunRows: its\n    tokens' rows (run-time ids) and its positions' RoPE rows from the tables; without `embed`\n    the RoPE rows alone (x None: a split run's later part, its x from DRAM).\"\"\"\n    if isinstance(rows, RunRows) and not embed:\n        c = ol.empty([rows.R, m.cosr.shape[1]], dense=True)\n        s_ = ol.empty([rows.R, m.sinr.shape[1]], dense=True)\n        ol.load(m.cos_t[rows.pos:rows.pos + rows.R, :], out=c)\n        ol.load(m.sin_t[rows.pos:rows.pos + rows.R, :], out=s_)\n        for t in rows.toks:                 # (the tokens: the first part's)\n            ol.release(t)\n        return None, c, s_\n    if not embed:\n        raise CompileError(\"RoPE rows alone: a run-time rows run's\")\n    if isinstance(rows, RunRows):\n        R = rows.R\n        x = ol.empty([R, m.xr.shape[1]], dense=True)\n        c = ol.empty([R, m.cosr.shape[1]], dense=True)\n        s_ = ol.empty([R, m.sinr.shape[1]], dense=True)\n        ol.load(m.cos_t[rows.pos:rows.pos + R, :], out=c)\n        ol.load(m.sin_t[rows.pos:rows.pos + R, :], out=s_)\n        if rows.toks_at is not None:        # the tokens from out[] (docs/prefill.md)\n            k = rows.toks_at\n            tk = ol.load(m.gen.out[rows.pos + k:rows.pos + k + R])\n            for r in range(R):\n                x[r:r + 1, :].set(_embed_word(m, tk[r:r + 1]))\n            del tk\n        mbox = getattr(m, \"embed_mbox\", None)\n        if mbox is not None and rows.toks:  # embed_host: the slot's rows 0 .. R - 1, which the\n            MB.wait_served(mbox)            # host writes for the run's tokens (before it, or\n            for t in rows.toks:             # served for a post of the program before it in the\n                ol.release(t)               # chain: the MTP loop's, docs/mtp.md 12)\n            for r, g in enumerate(_gather(m, m.embed_q, range(R))):\n                x[r:r + 1, :].set(g)\n            return x, c, s_\n        for r, t in enumerate(rows.toks):\n            x[r:r + 1, :].set(_embed(m, t))\n            ol.release(t)\n        return x, c, s_\n    R = len(rows)\n    if tokens is None:\n        return ol.load(m.xr[0:R, :]), ol.load(m.cosr[0:R, :]), ol.load(m.sinr[0:R, :])\n    if isinstance(tokens, OutTokens):\n        x = ol.empty([R, m.xr.shape[1]], dense=True)\n        c = ol.empty([R, m.cosr.shape[1]], dense=True)\n        s_ = ol.empty([R, m.sinr.shape[1]], dense=True)\n        p0 = rows[0][1] + tokens.k\n        tk = ol.load(m.gen.out[p0:p0 + R])\n        for r in range(R):\n            x[r:r + 1, :].set(_embed_word(m, tk[r:r + 1]))\n        del tk\n        for _, q0, r0, n in _runs(rows):\n            ol.load(m.cos_t[q0:q0 + n, :], out=c[r0:r0 + n, :])\n            ol.load(m.sin_t[q0:q0 + n, :], out=s_[r0:r0 + n, :])\n        return x, c, s_\n    eq = getattr(m, \"embed_q\", None)\n    # x, c and s first, side by side as the host path loads them: the gathers' temporaries\n    # after them are freed whole (TMEM does not fragment)\n    x = ol.empty([R, m.xr.shape[1]], dense=True)\n    c, s_ = ol.empty([R, m.cosr.shape[1]], dense=True), ol.empty([R, m.sinr.shape[1]], dense=True)\n    if eq is None:\n        for r, t in enumerate(tokens):\n            ol.load(m.embed[t:t + 1, :], out=x[r:r + 1, :])\n    for _, p0, r0, n in _runs(rows):\n        ol.load(m.cos_t[p0:p0 + n, :], out=c[r0:r0 + n, :])\n        ol.load(m.sin_t[p0:p0 + n, :], out=s_[r0:r0 + n, :])\n    if eq is not None:              # embed_host: the slot's rows (the host writes them first)\n        idx = range(len(tokens)) if getattr(m, \"embed_mbox\", None) is not None else tokens\n        for r, g in enumerate(_gather(m, eq, idx)):\n            x[r:r + 1, :].set(g)\n    return x, c, s_\n\n\ndef _gather(m, eq, toks):\n    \"\"\"The int8 embedding rows of tokens `toks` (ints or run-time values), gathered on the\n    device (kernels.gather.gather_row, one one-hot operand for all), one [1, H] tile at a\n    time.\"\"\"\n    oh = gather_operand(m.onehot)\n    for t in toks:\n        yield gather_row(oh, eq, t, \"int8\").reshape(1, eq.shape[1])\n\n\ndef _lm_head(x, m, spec):\n    \"\"\"Final norm and this slice's vocabulary rows of the LM head -> m.logits, or, with\n    m.lm_sink set (the generate loop: opentpu/llm/generate.py), each chunk's logits tile to\n    m.lm_sink(tile, first vocabulary row) instead (and to m.logits too with m.lm_keep: the\n    generate loop's debug mode). With m.lm_split (the first part of a split generate program)\n    x itself to that DRAM tensor instead: the second part runs the head. A spec with a\n    softcap (Gemma's final_logit_softcapping) caps the chunks a sink samples from (lib.softcap;\n    not Greedy's, a raw sink: the cap keeps the order, and m.logits stays raw).\"\"\"\n    split = getattr(m, \"lm_split\", None)\n    if split is not None:\n        ol.store(split, x)\n        return\n    sid = ol.program_id()\n    xs = ol.quantize(rmsnorm(x, ol.load(m.g_final), spec.eps))\n    chunk = min(HEAD_CHUNK, ol.tmem_words() // 8)\n    sink = getattr(m, \"lm_sink\", None)\n    for c0 in range(0, m.v_loc, chunk):\n        n = min(chunk, m.v_loc - c0)\n        col = sid * m.v_loc + c0\n        if sink is None:\n            ol.store(m.logits[:, col:col + n], ol.dot(xs, m.head[c0:c0 + n, :]))\n        else:\n            y = ol.dot(xs, m.head[c0:c0 + n, :])\n            if getattr(m, \"lm_keep\", False):\n                ol.store(m.logits[:, col:col + n], y)\n            cap = getattr(spec, \"softcap\", None)\n            if cap and not getattr(sink, \"raw\", False):\n                y = softcap(y, cap)\n            sink(y, col)\n\n\ndef _runs(rows):\n    \"\"\"Maximal runs of rows that continue one sequence at consecutive positions:\n    [(seq, first position, first row, count)].\"\"\"\n    out = []\n    for r, (sq, p) in enumerate(rows):\n        if out and out[-1][0] == sq and out[-1][1] + out[-1][3] == p:\n            out[-1] = (sq, out[-1][1], out[-1][2], out[-1][3] + 1)\n        else:\n            out.append((sq, p, r, 1))\n    return out\n\n\ndef _rope_rows_padded(x, c, s_, out=None):\n    \"\"\"rope_rows(x) on the first 2 * c.cols dimensions of each row (the others pass through),\n    into `out` (a view whose columns beyond x.cols are already zero) or a new tile padded like\n    _padded: the multi-row twin of _rope_padded, bit for bit.\"\"\"\n    d, D, rd = x.cols, ol.block_size(), 2 * c.cols\n    if out is None:\n        out = ol.zeros([x.rows, -(-d // D) * D]) if d % D else ol.empty(x.shape)\n    rope_rows(x[:, :rd], c, s_, out=out[:, :rd])\n    if rd < d:\n        out[:, rd:d].set(x[:, rd:])\n    return out\n\n\ndef _attention_rows(x, lw, c, s_, rows, spec, block: int, gated: bool = False,\n                    kv_only: bool = False):\n    \"\"\"x + W_o . attention(x) for R token rows; row r is token position rows[r][1] of sequence\n    rows[r][0] (its own KV cache), or rows is a RunRows (sequence 0, run-time positions; the\n    V^T appends a row at a time, each row's mask its own). Every row's K/V is appended first,\n    then each row attends\n    over positions 0..pos of its sequence -- for consecutive rows of one sequence (a prefill\n    chunk) that is exactly the causal mask. Each projection streams its weights once for all\n    R rows (ceil(R / MCOLS) MMs); the (row, KV head) pairs then run as one pipelined\n    flash-attention stream (_attend_heads). Per row the arithmetic is _attention's, so the\n    results are bit-identical to R decode steps: heads narrower than D (LFM2) are padded, RoPE\n    may cover part of a head (Qwen3.5), `gated` multiplies the output by sigmoid(W_gate x),\n    and a query group wider than the MXU attends in parts of MCOLS heads. A row's position may\n    be a run-time one (RunPos.offset: a layer-major prefill run), its K / V appended row by row.\n    kv_only: the rows' K / V appended, nothing else (no queries, no output: None; the MTP\n    layer's prompt rows in a layer-major prefill, qwen35.qwen35_mtp_kv_run).\"\"\"\n    d, G, eps = spec.head_dim, spec.n_q // spec.n_kv, spec.eps\n    R = rows.R if isinstance(rows, RunRows) else len(rows)\n    xs = ol.quantize(rmsnorm(x, ol.load(lw.g_in), eps))\n    k = ol.dot(xs, lw.wk)                       # [R, nkv_loc*d]\n    v = ol.dot(xs, lw.wv)\n    q = None if kv_only else ol.dot(xs, lw.wq)  # [R, nq_loc*d]\n    qn = None if kv_only else _load_opt(lw.qn)\n    kn = _load_opt(lw.kn)\n    c, s_ = _rope_gate(lw, c, s_)\n    scale = ol.LOG2E / math.sqrt(d)\n    heads = list(lw.kv.owned_heads(spec.n_kv))\n    nh = len(heads)\n    nq = nh * G\n    run = isinstance(rows, RunRows)\n    for j, hh in enumerate(heads):\n        kj = _rope_rows_padded(_norm_heads(k[:, j * d:(j + 1) * d], kn, eps), c, s_)\n        vj = _padded(v[:, j * d:(j + 1) * d])\n        if run:                                 # V^T at a run-time position: a row at a time\n            for r in range(R):\n                ol.kv_append(lw.kvs[0], hh, rows.pos + r, kj[r:r + 1, :], vj[r:r + 1, :])\n        elif isinstance(rows[0][1], RunPos):    # (rows of their own RunPos, likewise)\n            for r, (sq, p) in enumerate(rows):\n                ol.kv_append(lw.kvs[sq], hh, p.pos, kj[r:r + 1, :], vj[r:r + 1, :])\n        else:\n            for sq, p0, r0, n in _runs(rows):\n                ol.kv_append(lw.kvs[sq], hh, p0, kj[r0:r0 + n, :], vj[r0:r0 + n, :])\n        del kj, vj\n    del k, v\n    if kv_only:\n        return None\n    # queries as [R * nq, dk]: (row r, KV head j) is the G contiguous rows r*nq + j*G ...\n    dk = -(-d // ol.block_size()) * ol.block_size()\n    Q = ol.zeros([R * nq, dk]) if dk > d else ol.empty([R * nq, d])\n    for r in range(R):                          # a row's heads at once, as _attention's\n        _rope_padded(_norm_heads(q[r:r + 1, :].reshape(nq, d), qn, eps), c[r], s_[r],\n                     out=Q[r * nq:(r + 1) * nq, :])\n    del q\n    mc = min(G, ol.mxu_columns())\n    ent = [(r, j, g0, min(G, g0 + mc)) for r in range(R) for j in range(nh)\n           for g0 in range(0, G, mc)]\n    o = ol.empty([R, nq * d])\n\n    def emit(i, acc, l):\n        r, j, g0, g1 = ent[i]\n        o[r, (j * G + g0) * d:(j * G + g1) * d].reshape(g1 - g0, d).set(acc / l[:, None])\n\n    def seq(r):                                 # row r's extent: its bucket, or pos + 1\n        if run:\n            return rows.bucket_row(r)\n        p = rows[r][1]\n        return p.bucket if isinstance(p, RunPos) else p + 1\n\n    _attend_heads([Q[r * nq + j * G + g0:r * nq + j * G + g1, :] for r, j, g0, g1 in ent],\n                  [lw.kvs[0 if run else rows[r][0]] for r, *_ in ent],\n                  [heads[j] for _, j, _, _ in ent], [seq(r) for r, *_ in ent], block,\n                  scale, depth=ATTN_DEPTH, emit=emit)\n    del Q\n    if gated:                                   # after the heads: o * sigmoid(gate), rounded\n        for h0 in range(0, nq, mc):             # as _attention's (acc / l) * sg; mc heads at\n            cols = slice(h0 * d, min(nq, h0 + mc) * d)      # a time (TMEM)\n            o[:, cols].set(o[:, cols] * sigmoid(ol.dot(xs, lw.wgate[cols, :])))\n    o_all = ol.all_gather(o)                    # [R, n_q*d]\n    y = ol.all_gather(ol.dot(o_all, lw.wo))     # [R, H]\n    return x + y\n\n\n@ol.jit\ndef qwen3_rows(m, rows, logit_rows, block: int = ATTN_BLOCK, tokens=None):\n    \"\"\"R token rows at once (rows[r] = (sequence, position)): the rows' embeddings m.xr and\n    RoPE tables m.cosr / m.sinr, or those of `tokens` from the image's tables (_inputs_rows)\n    -> logits of the rows in `logit_rows` (a contiguous range, or empty: a prefill chunk that\n    is not the last one skips the LM head).\"\"\"\n    spec = m.spec\n    x, c, s_ = _inputs_rows(m, rows, tokens)\n    for lw in _layers(m):\n        x.set(_attention_rows(x, lw, c, s_, rows, spec, block))\n        x.set(_mlp(x, lw, spec))\n    _lm_head_rows(x, m, spec, logit_rows)\n\n\n@ol.jit\ndef qwen3_prompt_run(m, pos, R: int, kind: str, block: int = ATTN_BLOCK):\n    \"\"\"A prompt run of R rows (docs/prefill.md), qwen3_rows with its tokens from out[]: kind\n    \"P\", or \"L\" (the prompt's last run: its last row's logits). pos: a RunRows (toks_at 0) at\n    the run-time position in the generate state's tpos word (RunWords).\"\"\"\n    with RunWords(m, pos):\n        qwen3_rows.fn(m, pos, [R - 1] if kind == \"L\" else [], block)\n\n\ndef head_rows_chunk(rows: int) -> int:\n    \"\"\"The LM head's vocabulary rows per MM for `rows` token rows (their fp32 logits fit TMEM).\"\"\"\n    return min(HEAD_CHUNK, ol.tmem_words() // (8 * rows))\n\n\ndef _lm_head_rows(x, m, spec, logit_rows):\n    \"\"\"Final norm and this slice's vocabulary rows of the LM head for the rows `logit_rows`\n    of x (a contiguous range, or empty: nothing) -> m.logitsr, or, with m.lm_sinks (one sink\n    per logit row, generate.Greedy over head_rows_chunk's chunks: MTP's verify run), each\n    chunk's row r to sink r instead.\"\"\"\n    if not logit_rows:\n        return\n    sid = ol.program_id()\n    a, e = logit_rows[0], logit_rows[-1] + 1\n    xs = ol.quantize(rmsnorm(x[a:e, :], ol.load(m.g_final), spec.eps))\n    chunk = head_rows_chunk(e - a)\n    sinks = getattr(m, \"lm_sinks\", None)\n    for c0 in range(0, m.v_loc, chunk):\n        n = min(chunk, m.v_loc - c0)\n        col = sid * m.v_loc + c0\n        if sinks is None:\n            ol.store(m.logitsr[a:e, col:col + n], ol.dot(xs, m.head[c0:c0 + n, :]))\n            continue\n        y = ol.dot(xs, m.head[c0:c0 + n, :])\n        for r, sk in enumerate(sinks):\n            sk(y[r:r + 1, :], col)\n        del y\n\n\n# =============================================================================== engine\ndef device_config(spec: Spec, cap: int, batch: int = 1, rows: int = 1, wformat: str = \"int8\",\n                  head_format: str | None = None, lookup: bool = False,\n                  experts: int | None = None, embed_host: bool | None = None, **kw) -> Config:\n    \"\"\"The design configuration with DRAM sized for this model (power of two MiB).\"\"\"\n    probe = spec.image(design_config(DRAM_BYTES=1 << 40, **kw), cap, batch, rows, wformat,\n                       head_format, **({\"lookup\": True} if lookup and has_lookup(spec) else {}),\n                       **({\"experts\": experts} if experts is not None else {}),\n                       **({\"embed_host\": embed_host} if embed_host is not None else {}))\n    size = 1 << max(20, (probe.nbytes - 1).bit_length())\n    return design_config(DRAM_BYTES=size, **kw)\n\n\nclass IsaBackend:\n    \"\"\"The bit-exact ISA simulator, one persistent machine (DRAM keeps the KV cache).\n    adopt: the images (arrays of their own) become the machine's DRAM, grown to DRAM_BYTES in\n    place instead of copied, so a 4 GiB image is held once; the caller gives them up.\"\"\"\n\n    def __init__(self, cfg: Config, images: list, adopt: bool = False):\n        own = adopt and all(isinstance(m, np.ndarray) and m.dtype == np.uint8 and m.ndim == 1\n                            and m.flags.owndata and len(m) <= cfg.DRAM_BYTES for m in images)\n        self.machine = Machine(cfg, [[] for _ in range(cfg.S)],\n                               [None] * cfg.S if own else images)\n        if own:\n            for s, m in zip(self.machine.slices, images):\n                m.resize(cfg.DRAM_BYTES, refcheck=False)\n                s.dram = m\n\n    def write(self, s: int, addr: int, data: np.ndarray) -> None:\n        v = np.ascontiguousarray(data).view(np.uint8).reshape(-1)\n        self.machine.slices[s].dram[addr:addr + v.size] = v\n\n    def read(self, s: int, addr: int, nbytes: int) -> np.ndarray:\n        return self.machine.slices[s].dram[addr:addr + nbytes].copy()\n\n    args = True                 # run(programs, args): the run's arguments (R8..R15)\n    generates = True            # runs the generate loop (RLD, ARGMAX: Engine.generate_card)\n    chains = True               # and HALT CHAIN: one run crosses the attention buckets\n\n    def run(self, programs: list, args=None) -> dict:\n        self.machine.load(programs, args).run(max_steps=1 << 40)\n        return {\"instructions\": [s.icount for s in self.machine.slices]}\n\n\n_WORKER: tuple | None = None                # (image, block) in the compile worker process\n\n\ndef _worker_init(spec, cfg, cap, batch, rows, block, image_kw: dict,\n                 stream_fill: bool = False) -> None:\n    \"\"\"The worker's image: the engine's layout (spec.image with the engine's keywords: weight\n    formats, the resident decode's lookup tables, a MoE's expert slots; its programs must\n    address the same image), and its step programs as the engine's (stream_fill).\"\"\"\n    global _WORKER\n    image = spec.image(cfg, cap, batch, rows, **image_kw)\n    image.stream_fill = stream_fill\n    _WORKER = (image, block)\n    _exit_with_parent()\n\n\ndef _exit_with_parent() -> None:\n    \"\"\"A worker whose parent died (killed, or os._exit) would wait for work forever: it holds\n    its own end of the task pipe, so it never sees EOF. A watcher thread ends it.\"\"\"\n    import os\n    import threading\n    import time\n    parent = os.getppid()\n\n    def watch():\n        while os.getppid() == parent:\n            time.sleep(1.0)\n        os._exit(0)\n    threading.Thread(target=watch, daemon=True, name=\"otpu-parent-watch\").start()\n\n\ndef _worker_ready() -> bool:\n    return True\n\n\ndef worker_words(image, prog, run_args=None) -> np.ndarray:\n    \"\"\"A compile worker's program (one slice's) as the engine takes it: its words (Words: with\n    its run_args), and on a configuration whose sequencer takes wait entries (SEQ_WC) its\n    entries, computed here and kept beside the program cache's programs (waits.entries).\"\"\"\n    from ..isa import assemble\n    ra = run_args if run_args is not None else getattr(prog, \"run_args\", ())\n    w = Words.of(assemble(prog), ra)\n    if image.cfg.SEQ_WC:\n        w.waits = WC.entries(w, image.cfg.D, image.cfg.S, ra, prog=prog)\n    return w\n\n\ndef _worker_compile(pos: int) -> np.ndarray:\n    \"\"\"The worker process: the decode program for `pos`, assembled (one slice).\"\"\"\n    image, block = _WORKER\n    return worker_words(image, image.compile_step(pos, block)[0])\n\n\ndef _worker_decode(blocks: int, lo: int):\n    \"\"\"The worker process: the resident decode program of a bucket, assembled (one slice),\n    and its run_args (compile_decode).\"\"\"\n    image, block = _WORKER\n    progs, ra = image.compile_decode(blocks, lo, block)\n    return worker_words(image, progs[0], ra), ra\n\n\ndef layer_programs(image, key, block: int, hint: bool = False, em: bool = False,\n                   slot: int = 0):\n    \"\"\"Engine.prefill_layers' run of `key`: (layer (-1: the embed run), blocks, rows,\n    embedded), (layer, None, rows, True, compile-time position), (layer, blocks, rows, True,\n    \"tile\") (an expert-major run tiled: Engine.layer_tile), (\"x\", layer) (an expert run; (\"x\",\n    layer, C): of passes of C entries, Engine.em_pass), (\"m\", blocks, rows) (an MTP image's\n    KV rows of the MTP layer: compile_mtp_kv_run; (\"m\", blocks, rows, \"keep\"): expert-major's,\n    their residual kept in the chunk's rows; (\"m\", blocks, rows, \"xbuf\"): from the chunk's rows\n    whatever em), (\"v\", rows) (image rows into the chunk:\n    minicpmv.Image.compile_vis_run) or\n    \"head\" -> (programs, run_args); hint: a layer's run ends with the next MoE layer's hint\n    (Engine's layer_ahead \"hint\"); em: expert-major (Engine's expert_major); slot: the DeltaNet\n    states' and windows' slot of an MTP image (its committed one, mtp.MTPDecoder).\"\"\"\n    if key == \"head\":\n        return image.compile_prefill_head(**({\"em\": True} if em else {}))\n    if key[0] == \"x\":                       # ((\"x\", layer, C): passes of C entries)\n        return image.compile_expert_run(*key[1:])\n    if key[0] == \"m\":\n        return image.compile_mtp_kv_run(key[1], block, R=key[2], em=em and key[3:] != (\"xbuf\",),\n                                        keep=key[3:] == (\"keep\",))\n    if key[0] == \"v\":                       # ((\"v\", rows): image rows, minicpmv.Image)\n        return image.compile_vis_run(key[1], em=em)\n    if key[-1] == \"tile\":\n        from . import tiled as TL\n        return TL.compile_layer_tile(image, key[0], key[1], key[2], block,\n                                     **({\"slot\": slot} if slot else {}))\n    kw = {\"hint\": True} if hint and key[0] >= 0 else {}\n    if em:\n        kw[\"em\"] = True\n    if slot:\n        kw[\"slot\"] = slot\n    if key[1] is None:                      # (a compile-time position)\n        return image.compile_layer_run(key[0], key[4] // block + 1, block, R=key[2],\n                                       embedded=True, at=key[4], **kw)\n    return image.compile_layer_run(key[0], key[1], block, R=key[2], embedded=key[3], **kw)\n\n\ndef _worker_layer(key, hint: bool = False, em: bool = False, slot: int = 0):\n    \"\"\"The worker process: layer_programs' program, assembled (one slice), and its\n    run_args.\"\"\"\n    image, block = _WORKER\n    progs, ra = layer_programs(image, key, block, hint, em, slot)\n    return worker_words(image, progs[0], ra), ra\n\n\ndef _worker_chunk(seq: int, p0: int, n: int, left: int, fit: int, toks=None,\n                  whole: bool = True, logits: bool = True):\n    \"\"\"The worker process: fit_chunk's run, its program assembled (one slice).\"\"\"\n    image, block = _WORKER\n    n, progs, fit = fit_chunk(image, block, seq, p0, n, left, fit, toks, whole, logits)\n    return n, None if progs is None else worker_words(image, progs[0]), fit\n\n\ndef fit_chunk(image, block: int, seq: int, p0: int, n: int, left: int, fit: int,\n              tokens=None, whole: bool = True, logits: bool = True, **kw):\n    \"\"\"The next prefill run of sequence `seq` at position p0: up to n of the `left` remaining\n    prompt tokens, as many as fit TMEM and ACT RAM (at most `fit` rows) and the instruction\n    memory (attention is unrolled per row, head and block: the program grows with the context).\n    Only the prompt's last run computes logits (its last row; none without `logits`). Returns\n    (R, compile_rows' programs or None for R = 1, the rows that fit TMEM as far as known).\n    `tokens` (at least n): the run's inputs come from the image's tables (compile_rows tokens).\n    whole: R is at most MCOLS or a multiple of it (_whole_passes): each weight streams once per\n    MCOLS rows, so 5 rows at MCOLS 4 cost what 8 do; and an odd R takes R - 1 rows where they\n    cost less MXU time per row (prefer_rows: PAIR). kw: compile_rows' own (MTP decoding's\n    hidden, slot).\"\"\"\n    imem, mc = image.cfg.IMEM_WORDS, image.cfg.MCOLS if whole else 1 << 30\n    head = logits\n\n    def rows(r, logits):\n        return image.compile_rows([(seq, p0 + j) for j in range(r)], [r - 1] if logits else [],\n                                  block, **({} if tokens is None else {\"tokens\": tokens[:r]}),\n                                  **kw)\n    n = _whole_passes(min(n, fit, left), mc)\n    while n > 1:\n        try:\n            progs = rows(n, head and n == left)\n        except CompileError as e:\n            if \"TMEM\" not in str(e) and \"ACT RAM full\" not in str(e):\n                raise\n            fit = n - 1\n            n = _whole_passes(fit, mc)\n            continue\n        size = max(map(len, progs))\n        if size * 8 <= imem:\n            m = prefer_rows(image, n, lambda r: rows(r, False)) if whole else n\n            if m == n:\n                return n, progs, fit\n            return m, rows(m, False), fit\n        n = _whole_passes(min(n - 1, n * imem // (8 * size)), mc)  # ~ proportional to the rows\n    return 1, None, fit\n\n\ndef mxu_time(progs) -> float:\n    \"\"\"A run's MXU time, statically, in weight blocks: each MM's streamed rows times its K\n    blocks, half of that PAIRed (two 4-bit blocks a cycle), times its loops' counts (a loop\n    with a run-time count once); the slowest slice's.\"\"\"\n    best = 0.0\n    for prog in progs:\n        t, loops = 0.0, []                      # loops: (last instruction, count)\n        for pc, ins in enumerate(prog):\n            while loops and loops[-1][0] < pc:\n                loops.pop()\n            if ins.op == I.LOOP:\n                loops.append((pc + ins.w[0], ins.w[1] if ins.ra == 0 else 1))\n            elif ins.op == I.MM:\n                mult = math.prod(c for _, c in loops)\n                t += mult * (ins.w[3] & 0xFFFF) * ((ins.w[3] >> 16) & 0xFF) * \\\n                    (0.5 if ins.flags & I.F_PAIR else 1.0)\n        best = max(best, t)\n    return best\n\n\n# prefer_rows: R - 1 rows take over only at 10% less MXU time a row. mxu_time leaves out what a\n# run and a layer pay once (the run's start, the first weight chunks' latency, the instructions\n# besides the MMs), which R - 1 rows spread over fewer rows: in ld-memch's RTL co-sim (board\n# config, DDR3-1066, 133.33 MHz) Phi-4-mini's fp4-MLP layer is 6.1% cheaper a row at 2 rows by\n# mxu_time but 0.5% dearer (2 rows reach 89% of their MXU roofline, 3 rows 95%), and the 4B's\n# -25% is -13.8% (the card: -13.3%). The real layouts' R - 1 picks sit at -19 to -25%.\nPREFER_MARGIN = 0.10\n\n\ndef prefer_rows(image, n: int, compile) -> int:\n    \"\"\"The rows of a prefill run where n fit: n, or n - 1 for an odd n > 1 whose n - 1 rows\n    cost PREFER_MARGIN less MXU time per row (mxu_time of compile(r), a run of r rows without\n    logits). With PAIR a 4-bit MM of at most MCOLS / 2 rows streams two blocks a cycle, so 3\n    rows at MCOLS 4 pay 4's time and 2 cost less per row (the 4B: -13.8% a row in the co-sim);\n    an int8 MM streams once per MCOLS rows, so 3 rows cost less per row than 2 (Phi-4-mini),\n    and a mix falls between (docs/prefill.md 7). Kept per image and n, so a prompt run's\n    probe (prefill.r_max) and today's runs (fit_chunk) choose alike.\"\"\"\n    if n < 3 or n % 2 == 0:\n        return n\n    done = image.__dict__.setdefault(\"_prefer_rows\", {})\n    if n not in done:\n        a, b = mxu_time(compile(n)) / n, mxu_time(compile(n - 1)) / (n - 1)\n        done[n] = n - 1 if b <= (1 - PREFER_MARGIN) * a else n\n    return done[n]\n\n\ndef _whole_passes(n: int, mc: int) -> int:\n    \"\"\"The rows of a prefill run of at most n: n up to MCOLS (one pass of each weight), else\n    whole passes of MCOLS rows.\"\"\"\n    return n if n <= mc else n - n % mc\n\n\n\ndef _isa_host(poll):\n    \"\"\"The ISA simulator's WAITW hook (called when every slice waits on one): the host polls\n    until a waiting slice's WAITW holds or it has nothing left to do, as it keeps polling while\n    a card waits. One poll serves a request whole; an idle poll moves one part of an expert,\n    so an expert run waiting on a need's entry (docs/offload.md 13.11) takes several.\"\"\"\n    def host(m):\n        for _ in range(1 << 20):\n            if not poll() or any(s.holds(s.polling) for s in m.slices if s.polling is not None):\n                return\n    return host\n\nclass Engine:\n    \"\"\"Decoding on an openTPU backend: Qwen3, or any model whose Spec builds an image with\n    compile_step and compile_rows (LFM2: opentpu.llm.lfm2; Qwen3.5: opentpu.llm.qwen35).\n    step() feeds one token per device run; prefill() / prefill_chunks() feed a prompt `rows`\n    tokens per run (default PREFILL_ROWS), bit-identical to feeding it token by token.\n\n    backend: \"isa\" (default), or any object with write/read/run like IsaBackend (the RTL\n    simulator and the PCIe board driver implement the same interface). Optional backend hooks:\n    attach(engine), called once the engine exists; prepare(programs), called on the compile\n    thread with every precompiled program (the board assembles it there); start(programs) and\n    wait() -> stats, the two halves of run() (step compiles the next program in between);\n    streams (true: start(programs, stream=(addr, nbytes, piece)) and wait(feed) hand the logits\n    over in pieces, most of them during the run; the engine's stream_logits turns it off);\n    fills (true, with streams: the step programs fill their logits region themselves,\n    fill_logits, and the stream carries their ICOUNT gate, fill_gate); args (true: run / start\n    take args=words, the run's arguments: resident decode).\n\n    resident: decode with programs that take the position and the token as run arguments\n    (compile_decode, docs/isa.md \"Arguments\"): one program per attention bucket of `block`\n    positions, compiled once and kept in IMEM, the token's embedding and RoPE rows read from\n    tables in the image (Image(lookup=True)), so a step writes no inputs and loads no program.\n    Needs a backend with `args` (else it falls back), a model whose image has compile_decode\n    (Qwen3, LFM2, Qwen3.5) and batch 1; positions below the model's first run-time one\n    (LFM2, Qwen3.5: conv_k - 1) run per-position programs. Bit-identical to the per-position\n    programs.\n\n    device_inputs: with the image's tables (resident, or a model with an int8 embedding,\n    spec.embed: its rows are dequantized on the device only) the prefill runs and per-position\n    programs read their inputs from the image too, the token ids compiled into them\n    (compile_rows tokens, compile_step tok): the host writes no inputs and computes nothing of\n    the model. Without the tables the host writes the embedding rows and RoPE rows (of a table\n    computed once, as the image's). A per-position program with its token is compiled in its\n    step (pipeline: not ahead); resident decode compiles none.\n\n    pipeline: step() compiles the next position's program (it depends on the position only,\n    not on the token) while the backend runs the current one. Default: on for every backend\n    but \"isa\" (whose run holds the GIL: nothing to overlap). A precompile is used only for the\n    position it was made for; otherwise it is waited for and dropped (one trace at a time), so\n    results do not change. The compile runs in a worker process when the backend runs\n    assembled programs (runs_words: the board) and there is one slice -- a trace is 10-30 ms of\n    Python, and in a thread it would hold the GIL the step's host work needs -- else on a worker\n    thread; pipeline=\"thread\" forces the thread. The process starts with the engine; until it\n    is ready, steps compile in line.\n\n    release_weights: with the experts streamed from a pool file, the checkpoint's files are\n    released once the image is written and the slots warm (W.release(), a LazyWeights': its\n    mapped pages would stay in the page cache over the pool's, docs/offload.md 10.6; a later\n    read reopens its file). Default on; False keeps them. pool_map: the pool file's reads\n    touched through a read-only map (PoolFile's mapped, docs/offload.md 10.7). Default on.\n\n    layer_major: a MoE model's prompt layer by layer, runs of that many rows (prefill_layers,\n    docs/offload.md 13); pooled: the expert slots pooled for it, given back by `restore`\n    (\"lazy\" or \"eager\"); embed_runs: with the embedding rows from the host's table, its embed\n    runs and compile-time-position runs (default off while the card's port A keeps its beats\n    across runs, 13.6: token steps first, and layer 0's runs gather their rows); layer_ahead:\n    with pooled slots and a server that streams ahead (ExpertServer.ahead_layer), the next MoE\n    layer's experts sent while a layer runs (13.7): True for each layer's experts in index\n    order, or per MoE layer its expert indices in the order to send them (a static profile, most\n    used first; a shorter list sends fewer), or \"hint\": the card's own guess (13.9), each layer\n    run ends with the next MoE layer's router on its output rows, posted as a hint the server\n    adds to that layer's queue (each queue started empty; idle-poll parts of `ahead_part`\n    bytes, AHEAD_PART by default). expert_major: with layer_major and pooled slots, each MoE\n    layer of a chunk routes in its runs and computes its experts in one expert run, each chosen\n    expert once (docs/offload.md 13.11, 13.13); its server takes the scratch and the need lines\n    (ExpertServer.begin_prefill(expert_major=True, scratch=...)), the needs sent in idle-poll\n    parts of `ahead_part` bytes.\n\n    prog_cache: the bucket programs (the generate loop's, the resident decode's, MTP's loop's)\n    come from opentpu/progcache.py: compiled once per process and image layout, and kept on\n    disk for the next process. Default: on when OTPU_PROG_CACHE is set (to a directory, or 1\n    for the default one) and not 0. Off, every engine compiles its own (tests patch the\n    kernels' constants, which the cache's key does not see).\n\n    prompt_runs (docs/prefill.md): prefill_chunks runs a prompt (sequence 0) from programs at\n    run-time positions, its tokens from out[] (opentpu/llm/prefill.py): compiled once per\n    bucket and kind, not per prompt. A dense model's resident image (prefill.supported). With\n    the pipeline, bucket 1's are loaded or compiled on a thread as the engine starts\n    (prefill.warm). tile_runs (docs/tiled_prefill.md; None: OTPU_TILE's choice, on unless it\n    is 0: prefill.tile_flag): the prompt runs tiled (opentpu/llm/tiled.py), up to ACT_ROWS\n    rows a run, the image's I/O rows at least ACT_ROWS; False: today's. With expert_major a\n    MoE model's layer runs of more than one row (prefill.layer_tile_flag; layer_tile:\n    tiled.compile_layer_tile, on an image with the mask tiles): Qwen3.5-MoE's by default (not\n    with OTPU_TILE=0 as the image is built), Gemma 4's opt-in (tile_runs True or OTPU_TILE=1),\n    of `tile_rows` rows (None: tiled.LAYER_ROWS' 8 for Qwen3.5-MoE, else layer_major's), at\n    most ACT_ROWS; the calls that run layer-major (gate_expert_major's short ones) keep\n    layer_major's rows, untiled.\n\n    rollback(k) takes the context back to its first k tokens (a chat's next turn, whose\n    template renders the last reply differently from what was fed: opentpu/llm/snapshot.py).\n    A KV cache goes back to any position; state it does not hold (Qwen3.5's DeltaNet states and\n    windows, LFM2's convolution rings, Gemma 4's sliding rings past rollback_slack) comes from\n    a snapshot (snapshot()): `snapshots` of them kept, in an area of the device's DRAM after the\n    image (the image arrays grow to it) when it fits there, else on the host. Default 0: a\n    rollback of such a model starts over.\n    \"\"\"\n\n    def __init__(self, spec: Spec, W: dict, cap: int = 4096, cfg: Config | None = None,\n                 backend=\"isa\", block: int = ATTN_BLOCK, batch: int = 1,\n                 rows: int = PREFILL_ROWS, pipeline: bool | str | None = None,\n                 wformat: str = \"int8\", head_format: str | None = None,\n                 resident: bool = False, experts: int | None = None, pool_file=None,\n                 embed_host: bool | None = None, layer_major: int = 0, pooled: bool = True,\n                 restore: str = \"lazy\", embed_runs: bool = False, release_weights: bool = True,\n                 pool_map: bool = True, prog_cache: bool | None = None,\n                 prompt_runs: bool = False, layer_ahead=None, expert_major: bool = False,\n                 snapshots: int = 0, batch_area: bool = False, tile_runs: bool | None = None,\n                 tile_rows: int | None = None):\n        from . import prefill as PF\n        self.spec, self.cap, self.block = spec, cap, block\n        self.prog_cache = PC.enabled() if prog_cache is None else bool(prog_cache)\n        self.prompt_runs = prompt_runs\n        self.tile_runs = tile_runs          # (None: OTPU_TILE's choice, prefill.tile_flag:\n        #                                     on unless OTPU_TILE=0)\n        self.batch, self.rows = batch, max(rows, batch)\n        wkw = dict(wformat=wformat, head_format=head_format)\n        if experts is not None:             # a MoE model's expert slots per layer\n            wkw[\"experts\"] = experts\n        if embed_host is not None:          # the int8 embedding table on the host (default: the\n            wkw[\"embed_host\"] = embed_host  # image's choice, a MoE's untied table there)\n        # an int8 embedding is dequantized on the device (the image's tables), never the host\n        int8_embed = getattr(spec, \"embed\", \"f32\") == \"int8\"\n        # (batch > 1: the tables serve every sequence; sequence 0 keeps the resident decode,\n        # the generate loop and the prompt runs, whose programs address its KV caches)\n        lookup = (bool(resident) or int8_embed) and has_lookup(spec)\n        if lookup:\n            wkw[\"lookup\"] = True\n        self.cfg = cfg or device_config(spec, cap, batch=batch, rows=self.rows, **wkw)\n        if prompt_runs and PF.tile_flag(tile_runs) and self.cfg.S == 1 and \\\n                self.cfg.act_rows > self.rows:\n            # tiled prompt runs of up to ACT_ROWS rows (prefill.py; one slice): the image's I/O\n            # rows hold an L run's last row's logits (row T - 1)\n            self.rows = self.cfg.act_rows\n            if cfg is None:\n                self.cfg = device_config(spec, cap, batch=batch, rows=self.rows, **wkw)\n        try:\n            self.image = spec.image(self.cfg, cap, batch, self.rows, **wkw)\n        except MemoryError as e:            # an int8 embedding table of its own that does not\n            if embed_host is not None or not (lookup and int8_embed and has_embed_host(spec)):\n                raise                       # fit beside the rest: on the host (docs/offload.md\n            try:                            # 5.9)\n                self.image = spec.image(self.cfg, cap, batch, self.rows,\n                                        **{**wkw, \"embed_host\": True})\n            except (MemoryError, ValueError):\n                raise e from None\n        # the compile worker's image is built the same way, with the choices this image made\n        # (Gemma 4: the PLE table's place and format, the formats by fit)\n        self._image_kw = {**wkw, **getattr(self.image, \"choices\", {})}\n        # with the tables every run reads its inputs from the image (the token ids are compiled\n        # into the per-position and prefill programs); else the host writes them: the\n        # embedding rows and the RoPE rows of a table computed once, here\n        self.device_inputs = bool(getattr(self.image, \"lookup\", None))\n        self.embed = Embedding(spec, W, self.cfg.D)\n        # rows of tables the host keeps (Gemma 4 E4B's PLE records): read from the image's\n        # store and written before each run, data movement only\n        self._host_rows = getattr(self.image, \"host_rows\", None)\n        self._rope = None if self.device_inputs else \\\n            [np.stack(t) for t in zip(*(rope_tables(spec, p) for p in range(cap)))]\n        if pool_file is not None and getattr(self.image, \"offload\", None) is not None:\n            from .moe import open_pool, pool_key    # its read into the page cache runs during\n            pool_file = open_pool(self.image.offload, pool_file, mapped=pool_map,  # the build\n                                  key=pool_key(self.image, getattr(W, \"model_dir\", None),\n                                               getattr(W, \"mtp_from\", None)),\n                                  extra=(getattr(self.image, \"pool_extra\", None) or (0,))[0])\n        images = IC.build(self.image, W, self.layout)     # (opentpu/imgcache.py)\n        # rollback's snapshots of the state the KV caches do not hold (snapshot.py)\n        self.stateful = SN.stateful(self.image)\n        self._snaps = None\n        if snapshots and self.stateful:\n            self._snaps = SN.Snapshots(self.image, self.cfg, snapshots,\n                                       SN.Snapshots.area(self.image, self.cfg, snapshots))\n            if self._snaps.base is not None:\n                images = SN.grow(images, self._snaps.end())\n        self.snap_stats: list = []          # the snapshots' and restores' copies (stats)\n        # batched decode steps over the sequences' KV slots (opentpu/llm/batch.py): their area\n        # past the image (and the snapshots)\n        self.bat = None\n        if batch_area:\n            if batch < 2 or not self.image.lookup:\n                raise ValueError(\"batch_area needs batch > 1 and the lookup tables \"\n                                 \"(resident=True)\")\n            from . import batch as BA\n            self.bat = BA.alloc(self.image, self.cfg, batch, -(-len(images[0]) // 4096) * 4096)\n            if self.bat[\"end\"] + WC.area(self.cfg.IMEM_WORDS, self.cfg.SEQ_WC) > \\\n                    self.cfg.DRAM_BYTES:\n                raise MemoryError(\"no room in the DRAM for the batch area\")\n            images = SN.grow(images, self.bat[\"end\"])\n            BA.build(images, self.bat, spec, self.cfg)\n        self.backend = IsaBackend(self.cfg, images, adopt=True) if backend == \"isa\" else backend(\n            self.cfg, images)\n        self.resident = bool(resident) and lookup and bool(getattr(self.backend, \"args\", False))\n        # path (a), docs/offload.md: the experts stream into the image's slots; the host's\n        # server moves them (the ISA simulator calls it when every slice waits on WAITW; the\n        # card's backend polls it while a run is in flight)\n        self.server = None\n        if getattr(self.image, \"offload\", None) is not None:\n            self.server = self.image.serve(W, self.backend, pool_file)\n            if release_weights and pool_file is not None and hasattr(W, \"release\"):\n                W.release()                 # (the pool holds the experts; the image is written)\n        # rows of tables the host keeps, asked for by the generate loop (Gemma 4 E4B: each\n        # token's PLE record into the slot, opentpu.host.offload.RowServer)\n        rs = getattr(self.image, \"row_server\", None)\n        self.row_server = rs(self.backend) if rs is not None else None\n        if self.row_server is not None and self.server is not None:\n            self.row_server.mem = self.server.mem   # one memory, in order (BoardDram's queue)\n        servers = [x for x in (self.server, self.row_server) if x is not None]\n        if servers:\n            poll = servers[0].poll if len(servers) == 1 else \\\n                (lambda: sum(x.poll() for x in servers))\n            if isinstance(self.backend, IsaBackend):\n                self.backend.machine.host = _isa_host(poll)\n            elif hasattr(self.backend, \"host\"):\n                self.backend.host = poll\n                self.backend.servers = servers      # (rebased between runs: BoardBackend.start)\n        self._conv_lo = getattr(spec, \"conv_k\", 1) - 1    # the first run-time position\n        self._decodes: dict = {}            # resident: blocks -> (programs, run_args)\n        # a MoE model's prompt layer by layer, `layer_major` rows a run (prefill_layers; 0:\n        # token by token): its programs, (layer, blocks, rows, embedded) and \"head\" ->\n        # (programs, run_args)\n        self.layer_major = int(layer_major)\n        self.pooled, self.restore = pooled, restore     # (the expert slots during it)\n        self.embed_runs = embed_runs        # (the embed and compile-time-position runs with\n                                            # the embedding rows from the host: prefill_layers)\n        self.layer_ahead = layer_ahead      # (the next layer's experts sent during a layer's)\n        self.layer_hint = layer_ahead == \"hint\"     # (the runs' own guess of them: hints)\n        self.ahead_part = AHEAD_PART        # (with them: an idle poll's part, begin_prefill's)\n        self.expert_major = bool(expert_major)      # (a layer's experts in one run a chunk)\n        self.em_pass = None                 # (its passes' entries; None: the configuration's,\n                                            # moe.em_pass_rows, docs/offload.md 13.18)\n        self._layer_runs: dict = {}\n        self._layer_next: dict = {}         # their compiles in the worker processes: Futures\n        self._layer_slot = 0                # (the DeltaNet states' slot of the runs: an MTP\n                                            # image's committed one, prefill_layers' slot)\n        if self.layer_major and not (getattr(self.image, \"prefill_rows\", 0) and self.device_inputs\n                                     and getattr(self.backend, \"args\", False) and batch == 1):\n            raise ValueError(\"layer-major prefill needs an image with prefill rows and lookup \"\n                             \"tables (compile_layer_run), batch 1 and a backend with run \"\n                             \"arguments\")\n        if self.expert_major and not (self.layer_major and self.server is not None and pooled\n                                      and not self.layer_hint):\n            raise ValueError(\"expert-major MoE needs layer-major prefill, the expert server \"\n                             \"with pooled slots, and no layer hints (its runs post needs)\")\n        # expert-major runs of more than one row tiled (tiled.py's compile_layer_tile: the\n        # layer's weights once for the run's rows, up to ACT_ROWS of them; the image's mask\n        # tiles): Qwen3.5-MoE's by default, tiled.LAYER_ROWS rows a run, unless tile_runs is\n        # False or (None) OTPU_TILE=0 as the image is built; Gemma 4's opt-in (tile_runs True,\n        # or OTPU_TILE=1), layer_major's rows a run: prefill.layer_tile_flag\n        from . import tiled as TL\n        fam = TL.layer_family(self.image)\n        self.layer_tile = bool(self.expert_major and fam\n                               and PF.layer_tile_flag(tile_runs, fam in TL.LAYER_ROWS))\n        self.tile_rows = int(tile_rows or (min(TL.LAYER_ROWS[fam], self.cfg.act_rows)\n                                           if fam in TL.LAYER_ROWS else self.layer_major))\n        if self.layer_tile and self.tile_rows > self.cfg.act_rows:\n            raise ValueError(f\"tiled layer runs of {self.tile_rows} rows: one MM over them \"\n                             f\"needs ACT_ROWS >= {self.tile_rows} ({self.cfg.act_rows})\")\n        self._gens: dict = {}               # the generate loop: (blocks, mode) -> programs\n                                            # (a list, or split: (first parts, second parts))\n        self.gen_split = None               # split generate programs: None when a bucket's\n                                            # does not fit, True always, False never\n        self._chained: dict = {}            # mode -> (key, its buckets in the chain area)\n        self.gen_debug = False              # generate_card: the logits too (gen_logits)\n        self.gen_logits = None\n        self.poss = [0] * batch\n        # step(): stream the logits when the backend can (not while its wait serves the host)\n        self.stream_logits = getattr(self.backend, \"host\", None) is None\n        # ... and the step programs fill the region themselves (fill_logits) when the backend\n        # polls ICOUNT for the fill (BoardBackend.fills): the host writes nothing there\n        self.image.stream_fill = bool(self.stream_logits and self.cfg.S == 1\n                                      and getattr(self.backend, \"fills\", False))\n        # rows per run that fit TMEM (prefill_chunks), at most the image's fit_rows (Gemma 4:\n        # the ACT rows, so that a run streams the weights once)\n        self._fit_rows = min(self.rows, getattr(self.image, \"fit_rows\", self.rows))\n        self._run_rows_n = self.rows        # rows of the last prefill run (IMEM may cut it)\n        self.stats = []\n        self.pipeline = backend != \"isa\" if pipeline is None else bool(pipeline)\n        self._procs = (self.pipeline and pipeline != \"thread\" and self.cfg.S == 1\n                       and getattr(self.backend, \"runs_words\", False))\n        self._pool = None\n        self._ready = None                  # the worker process's start (process pipeline)\n        self._next = []                     # [(key, Future of a coming run's programs)]\n        # per-position decode programs precompiled ahead: three worker processes, so a\n        # compile can take three device runs (LFM2 fp4 on the card: a 13.5 ms run against a\n        # 16-30 ms trace, more on a host busy with other work; resident decode compiles none)\n        self._ahead = COMPILE_AHEAD if self._procs else 1\n        if self._procs:\n            self._start_pool()\n        if hasattr(self.backend, \"attach\"):\n            self.backend.attach(self)\n        if self.prompt_runs:                # bucket 1's prompt programs, ahead (prefill.warm)\n            from . import prefill as PF\n            PF.warm(self)\n        # the pool's experts the build took out of the page cache, read in again once its\n        # memory is freed (moe.rewarm); the server's pool_warm is that read\n        pf = getattr(self.server, \"pool_file\", None)\n        if pf is not None:\n            import gc\n\n            from .moe import rewarm\n            del images\n            gc.collect()\n            self.server.pool_warm = rewarm(pf)\n\n    # ---- the compile pipeline\n    def _compile(self, pos: int, tok: int | None = None) -> list:\n        progs = self.image.compile_step(pos, self.block,\n                                        **({} if tok is None else {\"tok\": int(tok)}))\n        prep = getattr(self.backend, \"prepare\", None)\n        if prep is not None:\n            prep(progs)\n        return progs\n\n    def _start_pool(self) -> None:\n        \"\"\"The compile worker process (spawned: it inherits no device or lock descriptor).\"\"\"\n        import multiprocessing as mp\n        from concurrent.futures import ProcessPoolExecutor\n        self._pool = ProcessPoolExecutor(\n            self._ahead, mp_context=mp.get_context(\"spawn\"), initializer=_worker_init,\n            initargs=(self.spec, self.cfg, self.cap, self.batch, self.rows, self.block,\n                      self._image_kw, self.image.stream_fill))\n        self._ready = self._pool.submit(_worker_ready)\n\n    def _take(self, key, fn, *args):\n        \"\"\"fn(*args), or the precompiled result (programs, or the worker process's assembled\n        words) when a compile in flight was made for `key`; the ones queued before it, or all\n        of them when none is for `key`, are waited for and dropped (the worker processes\n        start with no compile queued).\"\"\"\n        while self._next:\n            k, fut = self._next.pop(0)\n            res = fut.result()\n            if k == key:\n                return res\n        return fn(*args)\n\n    def _submit(self, key, fn, proc_fn, *args) -> None:\n        \"\"\"Start the compile for `key` (pipeline only): proc_fn(*args) in the worker process,\n        else fn(*args) on the compile thread.\"\"\"\n        if not self.pipeline:\n            return\n        if self._procs:\n            if self._ready.done():\n                self._next.append((key, self._pool.submit(proc_fn, *args)))\n            return\n        if self._pool is None:\n            from concurrent.futures import ThreadPoolExecutor\n            self._pool = ThreadPoolExecutor(1, thread_name_prefix=\"otpu-compile\")\n        self._next.append((key, self._pool.submit(fn, *args)))\n\n    def _program(self, pos: int):\n        \"\"\"The step program for `pos`: the precompiled one when it is for `pos`.\"\"\"\n        return self._take((\"step\", pos), self._compile, pos)\n\n    @property\n    def layout(self) -> tuple:\n        \"\"\"What decides the image's layout and so its programs (opentpu/progcache.py).\"\"\"\n        return (self.spec, self.cfg, self.cap, self.batch, self.rows, self.block,\n                tuple(sorted(self._image_kw.items())))\n\n    def _compile_decode(self, blocks: int, lo: int | None = None):\n        \"\"\"lo: the bucket's first position (_worker_decode's; the compile thread gets it too).\"\"\"\n        lo = max((blocks - 1) * self.block, self._conv_lo) if lo is None else lo\n        progs, ra = self.image.compile_decode(blocks, lo, self.block)\n        prep = getattr(self.backend, \"prepare\", None)\n        if prep is not None:\n            prep(progs)\n        return progs, ra\n\n    def _decode(self, pos: int):\n        \"\"\"Resident decode: (programs, run_args) of the bucket of `pos` (compiled once), or\n        None for a per-position program.\"\"\"\n        if not self.resident or pos < self._conv_lo:\n            return None\n        b = pos // self.block + 1\n        if b not in self._decodes:\n            progs, ra = self.cached(self._decode_what(b),\n                                    lambda: self._take((\"decode\", b), self._compile_decode, b))\n            if isinstance(progs, np.ndarray):   # a worker's words: with their run_args\n                progs = Words.of(progs, ra)\n            self._decodes[b] = (progs, ra)\n        return self._decodes[b]\n\n    def cached(self, what, compile):\n        \"\"\"compile() -> (programs, run_args), through the program cache with prog_cache.\"\"\"\n        return PC.get(self.layout, what, compile) if self.prog_cache else compile()\n\n    def _decode_what(self, b: int) -> tuple:\n        what = (\"decode\", b, max((b - 1) * self.block, self._conv_lo))\n        return what + (\"fill\",) if self.image.stream_fill else what    # fill_logits' or not\n\n    def _prefetch(self, pos: int) -> None:\n        \"\"\"Precompile the steps at pos .. pos + ahead - 1 (those not in flight yet); resident:\n        the bucket of pos and, DECODE_LEAD positions before its end, the next one.\"\"\"\n        queued = {k for k, _ in self._next}\n        if self.resident and pos >= self._conv_lo:\n            for p in (pos, pos + DECODE_LEAD):\n                b = p // self.block + 1\n                if p < self.cap and b not in self._decodes and (\"decode\", b) not in queued \\\n                        and not (self.prog_cache and PC.has(self.layout, self._decode_what(b))):\n                    self._submit((\"decode\", b), self._compile_decode, _worker_decode, b,\n                                 max((b - 1) * self.block, self._conv_lo))\n            return\n        if self.device_inputs:              # its program has the token: compiled in step()\n            return\n        for p in range(pos, min(pos + self._ahead, self.cap)):\n            if (\"step\", p) not in queued:\n                self._submit((\"step\", p), self._compile, _worker_compile, p)\n\n    def _drain(self) -> None:\n        nxt, self._next = self._next, []\n        for _, fut in nxt:\n            fut.result()\n\n    @property\n    def pos(self) -> int:\n        \"\"\"Next position of sequence 0 (the only one unless batch > 1).\"\"\"\n        return self.poss[0]\n\n    @pos.setter\n    def pos(self, v: int) -> None:\n        self.poss[0] = v\n\n    def reset(self, seq: int | None = None) -> None:\n        \"\"\"Forget the context (the KV cache is overwritten from position 0 on).\"\"\"\n        for s in range(self.batch) if seq is None else [seq]:\n            self.poss[s] = 0\n        if self._snaps is not None and (seq is None or seq == 0):\n            self._snaps.drop_above(0)\n\n    @property\n    def snapshot_bytes(self) -> int:\n        \"\"\"The device area of the snapshots (bytes; 0 on the host or without).\"\"\"\n        sn = self._snaps\n        return 0 if sn is None or sn.base is None else sn.n * sn.nbytes\n\n    def snapshot(self, slot: int = 0) -> bool:\n        \"\"\"Keep the context's state at its position for a later rollback (snapshot.py): a copy\n        of the state regions (`slot`: the DeltaNet states' committed slot, Spec.mtp) replacing\n        the oldest snapshot. False where there is nothing to keep (an image whose KV caches\n        hold the whole context) or no room (snapshots=0).\"\"\"\n        if self._snaps is None:\n            return False\n        self.snap_stats.append(dict(self._snaps.save(self, self.pos, slot), op=\"snapshot\",\n                                    pos=self.pos))\n        return True\n\n    def rollback(self, k: int, slot: int = 0) -> int:\n        \"\"\"Take sequence 0's context back to at most its first k tokens (the tokens from k on\n        are to change): returns the position t <= k it continues from, the KV caches and state\n        then those of a context fed its first t tokens, bit for bit. The KV caches go back to k\n        (the write position moves); with state they do not hold (stateful) and further back\n        than the image's rollback_slack, t is the latest snapshot's at or before k, restored\n        into `slot`, or 0 (a new context) with none. Snapshots after t are dropped.\"\"\"\n        if k >= self.pos:\n            return self.pos\n        self._drain()\n        t = max(0, k)\n        if self.stateful and self.pos - t > getattr(self.image, \"rollback_slack\", 0):\n            j = None if self._snaps is None else self._snaps.best(t)\n            t = 0 if j is None else self._snaps.at[j]\n            if t:\n                self.snap_stats.append(dict(self._snaps.restore(self, j, slot), op=\"restore\",\n                                            pos=t))\n        if self._snaps is not None:\n            self._snaps.drop_above(t)\n        self.pos = t\n        return t\n\n    def adopt(self, pos: int, seq: int = 0) -> None:\n        \"\"\"Sequence `seq`'s KV caches and state were written from outside (the server's KV\n        store putting a saved context back, opentpu/serve/kvio.py): it continues from `pos`.\n        The snapshots, another context's, are dropped; precompiles in flight are waited for.\"\"\"\n        if not 0 <= pos <= self.cap:\n            raise ValueError(f\"position {pos} outside the KV cache (cap {self.cap})\")\n        self._drain()\n        self.poss[seq] = pos\n        if self._snaps is not None and seq == 0:\n            self._snaps.at.clear()\n            self._snaps.host.clear()\n\n    def step(self, token: int, on_start=None, sink=None) -> np.ndarray:\n        \"\"\"Feed one token at the next position; returns the logits [vocab] for the next one.\n        on_start() is called once the device runs (host work that can overlap the run: the\n        chat hands the previous token to its interface there). sink (a sampler's\n        pick.stream(context), chat.sampler) gets the logits too: begin(vocab), then feed(lo,\n        values) per piece -- on a backend that streams them (BoardBackend.streams), most\n        pieces while the run goes on, so the sampler's work on them is off the token's\n        critical path.\"\"\"\n        if self.pos >= self.cap:\n            raise RuntimeError(\"KV cache full\")\n        io, S = self.image.io, self.cfg.S\n        dec = self._decode(self.pos)\n        if dec is None and self.device_inputs:  # the token's inputs from the image's tables\n            progs, kw = self._compile(self.pos, token), {}\n        elif dec is None:\n            x = F.ftz(self.embed[token].astype(np.float32))\n            cos, sin = self._rope[0][self.pos], self._rope[1][self.pos]\n            if io[\"cos\"] == io[\"x\"] + x.nbytes and io[\"sin\"] == io[\"cos\"] + cos.nbytes:\n                parts = [(io[\"x\"], np.concatenate([x, cos, sin]))]      # one transfer\n            else:\n                parts = [(io[\"x\"], x), (io[\"cos\"], cos), (io[\"sin\"], sin)]\n            for s in range(S):\n                for a, v in parts:\n                    self.backend.write(s, a, v)\n            progs, kw = self._program(self.pos), {}\n        else:                               # the token and position as run arguments\n            progs, ra = dec\n            kw = {\"args\": arg_words(ra, RunPos.values(int(token), self.pos,\n                                                      getattr(self.spec, \"conv_k\", 1),\n                                                      self.block))}\n        self._write_host_rows([token])\n        start = getattr(self.backend, \"start\", None)\n        v_loc = self.image.v_loc\n        vocab = S * v_loc\n        stream = None\n        if start is not None and S == 1 and self.stream_logits and \\\n                getattr(self.backend, \"streams\", False):\n            piece = 4 * min(HEAD_CHUNK, self.cfg.TMEM_WORDS // 8)     # _lm_head's chunks\n            stream = (io[\"logits\"], 4 * vocab, piece)\n            if self.image.stream_fill:      # the program fills the region (fill_logits)\n                stream += (fill_gate(progs if isinstance(progs, np.ndarray) else progs[0]),)\n        if start is None:\n            if sink is not None:\n                sink.begin(vocab)\n            self._prefetch(self.pos + 1)\n            if on_start is not None:\n                on_start()\n            st = self.backend.run(progs, **kw)\n        elif stream is None:                # compile while the device runs, not while the\n            start(progs, **kw)              # host copies the program\n            if sink is not None:            # after the start: off the halt -> run path\n                sink.begin(vocab)\n            self._prefetch(self.pos + 1)\n            if on_start is not None:\n                on_start()\n            st = self.backend.wait()\n        else:\n            logits = np.empty(vocab, np.float32)\n\n            def feed(o, w):\n                v = logits[o // 4:o // 4 + len(w)]\n                v[:] = w.view(np.float32)\n                if sink is not None:\n                    sink.feed(o // 4, v)\n            start(progs, stream=stream, **kw)\n            if sink is not None:            # after the start: off the halt -> run path\n                sink.begin(vocab)\n            self._prefetch(self.pos + 1)\n            if on_start is not None:\n                on_start()\n            st = self.backend.wait(feed)\n        self.stats.append(st)\n        if stream is None:\n            logits = np.concatenate([self.backend.read(s, io[\"logits\"] + 4 * s * v_loc,\n                                                       4 * v_loc).view(np.float32)\n                                     for s in range(S)])\n            if sink is not None:\n                sink.feed(0, logits)\n        self.pos += 1\n        return logits\n\n    def run_rows(self, rows, tokens, logit_rows) -> np.ndarray:\n        \"\"\"One device run over token rows (rows[r] = (sequence, position)); returns the logits\n        of `logit_rows` ([n, vocab]).\"\"\"\n        self._drain()\n        return self._run_rows(rows, tokens, logit_rows,\n                              self.image.compile_rows(rows, logit_rows, self.block,\n                                                      **self._tokens_kw(tokens)))\n\n    def _write_host_rows(self, tokens) -> None:\n        if self.row_server is not None:     # a request the last run posted, served first: its\n            self.row_server.poll()          # row must not land after these\n            flush = getattr(self.row_server.mem, \"flush\", None)\n            if flush is not None:           # (BoardDram: written by its DMA thread)\n                flush()\n        if self._host_rows is not None:\n            for a, v in self._host_rows(tokens):\n                for s in range(self.cfg.S):\n                    self.backend.write(s, a, v)\n\n    def _tokens_kw(self, tokens) -> dict:\n        \"\"\"compile_rows' tokens, with device inputs (the host writes none).\"\"\"\n        return {\"tokens\": [int(t) for t in tokens]} if self.device_inputs else {}\n\n    def _run_rows(self, rows, tokens, logit_rows, programs) -> np.ndarray:\n        io, S, spec = self.image.io, self.cfg.S, self.spec\n        if any(p >= self.cap for _, p in rows):\n            raise RuntimeError(\"KV cache full\")\n        if not self.device_inputs:\n            x = F.ftz(self.embed[[int(t) for t in tokens]].astype(np.float32))\n            ps = [p for _, p in rows]\n            for s in range(S):\n                self.backend.write(s, io[\"x\"], x)\n                self.backend.write(s, io[\"cos\"], self._rope[0][ps])\n                self.backend.write(s, io[\"sin\"], self._rope[1][ps])\n        self._write_host_rows(tokens)\n        st = self.backend.run(programs)\n        st[\"rows\"] = len(rows)\n        self.stats.append(st)\n        v, v_loc = spec.vocab, self.image.v_loc\n        out = [np.concatenate([self.backend.read(s, io[\"logits\"] + 4 * (r * v + s * v_loc),\n                                                 4 * v_loc).view(np.float32) for s in range(S)])\n               for r in logit_rows]\n        return np.array(out, np.float32).reshape(len(logit_rows), v)\n\n    def _chunk(self, seq: int, p0: int, n: int, left: int, fit: int, toks=None,\n               whole: bool = True, logits: bool = True):\n        \"\"\"fit_chunk, its programs prepared for the backend.\"\"\"\n        n, progs, fit = fit_chunk(self.image, self.block, seq, p0, n, left, fit, toks, whole,\n                                  logits)\n        prep = getattr(self.backend, \"prepare\", None)\n        if progs is not None and prep is not None:\n            prep(progs)\n        return n, progs, fit\n\n    def prefill_chunks(self, tokens, seq: int = 0, chunk: int | None = None,\n                       logits: bool = True, vis=None):\n        \"\"\"Feed a prompt to sequence `seq` in device runs of up to `chunk` tokens (default:\n        the image's rows); yields (the tokens of the run, logits) after each run, the logits\n        after the prompt's last token with the last run and None before (always None without\n        `logits`: no run computes them, a part of a prompt that goes on later).\n\n        A run of R > 1 tokens is one qwen3_rows program (the model's compile_rows): every\n        weight streams once for the R rows (ceil(R / MCOLS) MMs), each row attends causally\n        over the cache and the rows before it, and only the last run computes logits, for its\n        last row. Per row the arithmetic is the decode kernel's, so the KV cache and logits\n        are bit-identical to feeding the tokens one by one -- but with PAIR, a 4-bit MM of a\n        run of more than MCOLS / 2 rows does not pair as the decode kernel's does, and its\n        sums round in another order (qwen35_rows; tests/test_qwen35.py\n        test_prefill_pair_sum_order). A run shrinks when its program\n        does not fit TMEM or IMEM (long contexts); a single token runs the decode kernel.\n        Without `chunk` a run of more than MCOLS rows takes whole passes of MCOLS rows (each\n        pass streams every weight: fit_chunk).\n        With the pipeline, the next run's program (after the last run: the first decode\n        step's) is compiled while the device runs the current one. With layer_major (a MoE\n        model) sequence 0's prompt goes layer by layer (prefill_layers), in one part: its runs'\n        stats are one entry, their cycles summed. vis: prefill_layers' image rows (MiniCPM-V;\n        the layer-major prompt only).\"\"\"\n        from . import prefill as PF\n        tokens = [int(t) for t in tokens]\n        if self.layer_major and seq == 0 and chunk is None:\n            if tokens:                                  # (docs/offload.md 13)\n                k = len(self.stats)\n                lg = self.prefill_layers(tokens, logits, **({} if vis is None else\n                                                            {\"vis\": vis}))\n                runs = self.stats[k:]\n                self.stats[k:] = [{\"cycles\": sum((s or {}).get(\"cycles\") or 0 for s in runs),\n                                   \"runs\": len(runs), \"rows\": len(tokens)}]\n                yield tokens, lg\n            return\n        if vis is not None and max(vis, default=-1) >= 0:\n            raise ValueError(\"image rows go in a layer-major prompt (Engine(layer_major=R))\")\n        if self.prompt_runs and seq == 0 and chunk is None and PF.supported(self) \\\n                and PF.covers(self, self.poss[0], self.poss[0] + len(tokens)):\n            yield from PF.chunks(self, tokens, logits)  # docs/prefill.md\n            return\n        whole = chunk is None               # else runs of exactly `chunk` where they fit\n        chunk = self.rows if chunk is None else max(1, min(chunk, self.rows))\n        i = 0\n        while i < len(tokens):\n            p0, left = self.poss[seq], len(tokens) - i\n            key = (\"rows\", seq, p0, chunk, left, self._fit_rows,\n                   self._chunk_toks(tokens[i:], chunk), whole, logits)\n            n, progs, self._fit_rows = self._take(key, self._chunk, *key[1:])\n            part, last = tokens[i:i + n], n == left\n            head = last and logits\n            if not last:\n                self._run_rows_n = n\n            if progs is None and seq == 0:\n                lg = self.step(part[0])\n            else:\n                rows, lr = [(seq, p0 + j) for j in range(n)], [n - 1] if head else []\n                if progs is None:\n                    progs = self.image.compile_rows(rows, lr, self.block,\n                                                    **self._tokens_kw(part))\n                if not last:\n                    self._prefetch_chunks(seq, p0 + n, chunk, left - n, tokens[i + n:],\n                                          whole, logits)\n                elif seq == 0 and logits:\n                    self._prefetch(p0 + n)\n                lg = self._run_rows(rows, part, lr, progs)\n                lg = lg[0] if head else None\n                self.poss[seq] += n\n            i += n\n            yield part, (lg if head else None)\n\n    def _chunk_toks(self, rest, chunk: int):\n        \"\"\"The tokens a prefill run's program is compiled with (device inputs: its first\n        `chunk` of `rest`, the run takes as many as fit), or None.\"\"\"\n        return tuple(rest[:chunk]) if self.device_inputs else None\n\n    def _prefetch_chunks(self, seq: int, p0: int, chunk: int, left: int, rest=(),\n                         whole: bool = True, logits: bool = True) -> None:\n        \"\"\"Precompile the runs of a prompt from position p0 on, as many as the pipeline has\n        workers (a chunk's trace can take longer than its run: Qwen3.5 on the card), each\n        predicted to take as many rows as the last one (TMEM and IMEM limit a run: the program\n        grows with the context); a run whose prediction turns out wrong is waited for and\n        dropped (_take), so the programs do not change.\"\"\"\n        queued = {k for k, _ in self._next}\n        for _ in range(self._ahead):\n            if left <= 0:\n                break\n            key = (\"rows\", seq, p0, chunk, left, self._fit_rows, self._chunk_toks(rest, chunk),\n                   whole, logits)\n            if key not in queued:\n                self._submit(key, self._chunk, _worker_chunk, *key[1:])\n            n = min(chunk, self._fit_rows, self._run_rows_n, left)\n            n = _whole_passes(n, self.cfg.MCOLS) if whole else n\n            p0, left, rest = p0 + n, left - n, rest[n:]\n\n    def prefill(self, tokens, seq: int = 0, chunk: int | None = None) -> np.ndarray:\n        \"\"\"Feed a prompt to sequence `seq`; returns the logits after its last token\n        (prefill_chunks; chunk=1 runs token by token with the decode kernel; layer_major:\n        prefill_layers).\"\"\"\n        if self.layer_major and seq == 0 and chunk is None:\n            return self.prefill_layers(tokens)\n        logits = None\n        for _, logits in self.prefill_chunks(tokens, seq, chunk):\n            pass\n        return logits\n\n    def prefill_layers(self, tokens, logits: bool = True, vis=None, mtp=None,\n                       slot: int = 0, keep: bool = False, fix=None) -> np.ndarray | None:\n        \"\"\"A MoE model's prompt layer by layer (docs/offload.md, layer-major prefill): each\n        chunk of the image's prefill rows passes a layer before the next, in runs of\n        `layer_major` rows (the image's compile_layer_run: the first row's position and chunk\n        row as run arguments; a run stays in one attention block), so that the expert slots\n        serve one layer at a time; then the LM head of the last row (none without `logits`: a\n        part of a prompt that goes on later; returns None). It starts at any position (a chat's\n        next turn continues the context). Runs of more than one row\n        start from the chunk's embedding rows (one embed run a token). A model with\n        convolutions (conv_k > 1) runs its rows before position conv_k - 1 at compile-time\n        positions, from their embedding rows too. With the embedding rows from the host's table\n        (embed_host) and not `embed_runs`, there are no embed runs: the rows before conv_k - 1\n        run token by token (prefill_chunks) and layer 0's runs gather their rows from the\n        host's slot. (The card's port A keeps the beat of its last read and its prefetch run\n        across runs, and the host's writes do not drop them: embed runs back to back read the\n        slot's scale beat first and got the first row's scales, docs/offload.md 13.6. A run\n        whose first scale read follows a layer's is safe; embed_runs=True brings the embed and\n        compile-time-position runs back on a bitstream that drops them at RUN.) The expert\n        server's slots are pooled for the prompt (ExpertServer.begin_prefill: every slot serves\n        the running layer) and given back to their layers before the head runs (end_prefill:\n        `restore`, \"lazy\" by default). With the process pipeline the runs' programs compile in\n        the worker processes ahead of their runs, in their order (_precompile_layers). With\n        `layer_ahead` the server is given the next MoE layer's experts to send while a layer\n        runs (ExpertServer.ahead_layer, between runs: the first MoE layer's after begin_prefill,\n        the next one's before each layer's first run in a chunk, the first one's again before a\n        chunk's last layer when another chunk follows); a request still names its own. With\n        \"hint\" those calls name none: the layer's runs post the next layer's experts as hints\n        (their router on the run's output rows), which the server queues. With `expert_major`\n        (docs/offload.md 13.11) each MoE layer of a chunk is its runs (their rows routed, the\n        experts they chose posted as needs, the shared expert) and then one expert run (each\n        chosen expert once, on the rows that chose it); the next layer's runs (the last\n        layer's: the head's) sum the outputs. The rows live in a scratch the server carves\n        from the first expert slots for the prefill (begin_prefill's scratch: the first\n        chunk's records, moe.em_record a row), so the head runs before end_prefill hands them\n        back. Bit-identical to step() token by token (the states, the KV cache, the logits):\n        only the slots the experts sit in move. Returns the logits after the last token.\n\n        vis: each token's row of the image's projector output (`vis`, MiniCPM-V's image rows:\n        minicpmv.Image), or -1 for a text token (None: all text). An image token's layer-0 input\n        is that row: layer 0 takes a chunk's image tokens in runs of their own (consecutive vis\n        rows), each a copy run ((\"v\", n): vis_copy_run, the rows into the chunk's residual rows\n        or records) and an embedded layer run; text runs are as without images.\n\n        An MTP image's (Spec.mtp, mtp.MTPDecoder; docs/mtp.md 12): `mtp` the token after each\n        of `tokens` (None from the first row whose next token is not known: the last row's,\n        the head's pick), and after each chunk's last layer runs of its rows that have one\n        append the MTP layer's K / V ((\"m\", blocks, rows): qwen35_mtp_kv_run, the host's slot\n        rows the next tokens' embedding rows: an image token's too, its placeholder's); the\n        head also stores the last row's hidden (m.hid[0]) for its draft. From conv_k - 1 on.\n        slot: the DeltaNet states' and windows' slot (the MTP decoder's committed one). keep:\n        the last row's residual stays in its chunk row after the prompt (expert-major: its K / V\n        run keeps it there, (\"m\", ..., \"keep\")), self.kept (its position, the row), for a\n        snapshot after it (mtp.MTPDecoder.snapshot). fix (q, its residual row): first the MTP\n        layer's K / V row at q = Engine.pos - 1 again, its next token tokens[0], from that row\n        (written to chunk row 0; (\"m\", blocks, 1[, \"xbuf\"])): a context rolled back to a snapshot\n        whose next token changed (mtp.MTPDecoder.rollback), bit for bit the row a run of q\n        through the model would append.\"\"\"\n        if mtp is None and not slot:\n            return self._prefill_layers(tokens, logits, None, vis)\n        K = getattr(self.spec, \"conv_k\", 1)\n        if mtp is not None and (not getattr(self.spec, \"mtp\", False) or len(mtp) != len(tokens)\n                                or self.pos < K - 1):\n            raise ValueError(\"an MTP prefill: an MTP image, a next token (or None) per token, \"\n                             \"from conv_k - 1 on\")\n        if fix is not None and (fix[0] != self.pos - 1 or fix[0] < K - 1 or mtp is None):\n            raise ValueError(f\"fix: the MTP layer's row before Engine.pos {self.pos} from \"\n                             f\"conv_k - 1 on, in an MTP prefill (row {fix[0]})\")\n        self._layer_slot = slot\n        try:\n            return self._prefill_layers(tokens, logits, mtp, vis, keep, fix)\n        finally:\n            self._layer_slot = 0\n\n    def _prefill_layers(self, tokens, logits: bool, mtp, vis=None, keep: bool = False,\n                        fix=None) -> np.ndarray | None:\n        from . import tiled as TL\n        img, K, B, R = self.image, getattr(self.spec, \"conv_k\", 1), self.block, self.layer_major\n        self._drain()\n        tokens = [int(t) for t in tokens]\n        if self.pos + len(tokens) > self.cap:\n            raise RuntimeError(\"KV cache full\")\n        vis = None if vis is None or max(vis, default=-1) < 0 else [int(v) for v in vis]\n        if vis is not None and len(vis) != len(tokens):\n            raise ValueError(f\"vis: {len(vis)} rows for {len(tokens)} tokens\")\n        part = []\n\n        def run(key, vals):\n            progs, ra, words = self._layer_run(key)\n            progs = progs if words is None else words   # (the board: the same words object\n            start = getattr(self.backend, \"start\", None)    # again loads nothing)\n            if start is None:\n                self.stats.append(self.backend.run(progs, args=arg_words(ra, vals)))\n            else:\n                start(progs, args=arg_words(ra, vals))\n                self.stats.append(self.backend.wait())\n\n        host = bool(getattr(img, \"embed_host\", False)) and not self.embed_runs\n        if host and self.pos < K - 1:   # the rows before conv_k - 1 token by token (no embed\n            n = min(len(tokens), K - 1 - self.pos)          # or compile-time-position runs)\n            if vis is not None and max(vis[:n]) >= 0:\n                raise ValueError(f\"an image row before position {K - 1}\")\n            for _, lg in self.prefill_chunks(tokens[:n], 0, 1, logits and n == len(tokens)):\n                pass\n            tokens = tokens[n:]\n            vis = None if vis is None else vis[n:]\n            if not tokens:\n                return lg if logits else None\n        em = self.expert_major\n        tile = em and self.layer_tile   # (expert-major runs tiled, of T rows: layer 0's from the\n        T = self.tile_rows if tile else R               # host's slot or from vis untiled, R)\n        mo = getattr(self.spec, \"moe\", None)\n        self.kept = None\n        if fix is not None:             # (the MTP layer's row before Engine.pos again)\n            q = fix[0]\n            fix = ((\"m\", q // B + 1, 1) + ((\"xbuf\",) if em else ()),\n                   dict(RunPos.values(tokens[0], q, K, B), row=0), fix[1])\n        chunks, p0 = [], self.pos       # each chunk's runs: (key, run arguments, the host's rows\n        for c0 in range(0, len(tokens), img.prefill_rows):  # written before it, or None)\n            part, runs = tokens[c0:c0 + img.prefill_rows], []\n            vp = None if vis is None else vis[c0:c0 + len(part)]\n            low = max(0, min(len(part), K - 1 - p0))    # rows at compile-time positions\n            if vp is not None and max(vp[:low], default=-1) >= 0:\n                raise ValueError(f\"an image row before position {K - 1}\")\n            for i, t in enumerate([] if host else part[:len(part) if R > 1 else low]):\n                runs.append(((-1, (p0 + i) // B + 1, 1, True),  # (embed_host: the token's row)\n                             dict(RunPos.values(t, p0 + i, K, B), row=i), [t]))\n            for li in range(self.spec.layers):\n                i = 0\n                while i < len(part):\n                    p = p0 + i\n                    if i < low:\n                        n = min(R, low - i)\n                        runs.append(((li, None, n, True, p), {\"row\": i}, None))\n                    else:\n                        n = min(T, len(part) - i, B - p % B)\n                        if li == 0 and vp is not None:      # a run of text or of image rows\n                            j, im = i + 1, vp[i] >= 0\n                            while j < i + n and (vp[j] >= 0) == im and \\\n                                    (not im or vp[j] == vp[j - 1] + 1):\n                                j += 1\n                            n = j - i\n                            if im:                          # (the rows from vis, then layer 0\n                                n = min(n, R)               # on them, untiled)\n                                runs.append(((\"v\", n), {\"row\": i, \"src\": vp[i]}, None))\n                                runs.append(((0, p // B + 1, n, True),\n                                             dict(RunPos.values(part[i], p, K, B), row=i), None))\n                                i += n\n                                continue\n                        gather = li == 0 and (R == 1 or host)   # (the run gathers its rows:\n                        if gather and tile:                     # the host's; untiled)\n                            n = min(n, R, TL.untiled_rows(img))\n                        key = (li, p // B + 1, n, R > 1 and not gather)\n                        if tile and n > 1 and not gather:\n                            key += (\"tile\",)                    # (tiled.compile_layer_tile)\n                        runs.append((key, dict(RunPos.values(part[i], p, K, B), row=i),\n                                     part[i:i + n] if gather else None))\n                    i += n\n                if em and li >= mo.first:               # the layer's expert run\n                    runs.append(((\"x\", li) + ((self.em_pass,) if self.em_pass else ()),\n                                 {\"rows\": len(part), \"entries\": len(part) * mo.k},\n                                 None))\n            nx = [] if mtp is None else mtp[c0:c0 + len(part)]\n            have = next((i for i, t in enumerate(nx) if t is None), len(nx))\n            i = 0\n            while i < have:                 # the MTP layer's K / V of the rows with their next\n                p = p0 + i                  # token (its embedding row the host's)\n                n = min(img.grows, have - i, B - p % B)\n                runs.append(((\"m\", p // B + 1, n), dict(RunPos.values(part[i], p, K, B), row=i),\n                             [int(t) for t in nx[i:i + n]]))\n                i += n\n            chunks.append((part, runs))\n            p0 += len(part)\n        last = None if not (keep and mtp is not None and mtp[-1] is not None) else \\\n            next((j for j, (k, _, _) in reversed(list(enumerate(chunks[-1][1]))) if k[0] == \"m\"),\n                 None)\n        if last is not None:            # (its rows end at the part's last)\n            k, vals, rows = chunks[-1][1][last]\n            if em:\n                chunks[-1][1][last] = (k + (\"keep\",), vals, rows)\n            self.kept = (p0 - 1, len(chunks[-1][0]) - 1)\n        self._precompile_layers(([fix[0]] if fix is not None else []) +\n                                [k for _, runs in chunks for k, _, _ in runs] +\n                                ([\"head\"] if logits else []))\n        srv = self.server if self.pooled else None\n        send = getattr(srv, \"ahead_layer\", None) if self.layer_ahead else None\n        if srv is not None and hasattr(srv, \"begin_prefill\"):\n            kw = {} if send is None else {\"ahead\": True} if not self.layer_hint else \\\n                {\"ahead\": True, \"part\": self.ahead_part}\n            if em:                          # (the scratch: the first chunk's rows' records;\n                from .moe import em_record  # the needs go in idle-poll parts, as hints')\n                kw.update(expert_major=True, part=self.ahead_part, scratch=len(chunks[0][0]) *\n                          em_record(self.spec.hidden, mo.k))\n            srv.begin_prefill(**kw)\n        if fix is not None:             # its residual row into chunk row 0, the next token's\n            self.backend.write(0, img.io[\"xbuf\"], np.asarray(fix[2], np.float32))   # row\n            self._write_host_rows(tokens[:1])\n            run(fix[0], fix[1])\n        if send is not None:\n            self._send_ahead(send, 0)\n            first = self.spec.moe.first             # (the model's MoE layers: not an MTP\n            nm = img.offload.layers - bool(getattr(self.spec, \"mtp\", False))    # layer's)\n        for c, (part, runs) in enumerate(chunks):\n            cur = -1\n            for key, vals, rows in runs:\n                if send is not None and isinstance(key[0], int) and key[0] > cur:   # a layer's\n                                                        # first run:\n                    cur = key[0]                        # the next MoE layer's experts, or\n                    j = cur + 1 - first                 # the first's for the next chunk\n                    if cur + 1 == self.spec.layers and c + 1 < len(chunks):\n                        self._send_ahead(send, 0)\n                    elif 0 < j < nm:\n                        self._send_ahead(send, j)\n                if rows is not None:\n                    self._write_host_rows(rows)\n                try:\n                    run(key, vals)\n                except Exception as e:      # an expert run's WAITW timeout: where its needs\n                    if key[0] != \"x\" or not hasattr(srv, \"need_report\"):    # stand (13.14)\n                        raise\n                    raise RuntimeError(f\"expert run of layer {key[1]}: {e} \"\n                                       f\"({srv.need_report()})\") from e\n            self.pos += len(part)\n        if em and logits:                   # (the head reads the scratch: before it goes)\n            run(\"head\", {\"row\": len(part) - 1})\n        if srv is not None and hasattr(srv, \"end_prefill\"):    # (the last run has halted; an\n            srv.end_prefill(self.restore)                       # all-hit request it posted is\n                                                                # served first: settle)\n        if not logits:\n            return None\n        if not em:\n            run(\"head\", {\"row\": len(part) - 1})\n        io, S, v_loc = img.io, self.cfg.S, img.v_loc\n        return np.concatenate([self.backend.read(s, io[\"logits\"] + 4 * s * v_loc, 4 * v_loc)\n                               .view(np.float32) for s in range(S)])\n\n    def _send_ahead(self, send, j: int) -> None:\n        \"\"\"MoE layer j's experts to the server's ahead_layer, as global ids in layer_ahead's\n        order.\"\"\"\n        E = self.image.offload.E\n        order = range(E) if self.layer_ahead is True else () if self.layer_hint else \\\n            self.layer_ahead[j]\n        send(j, [j * E + int(e) for e in order])\n\n    def _layer_run(self, key):\n        \"\"\"prefill_layers' programs, compiled once (layer_programs' key) -> (programs, run_args,\n        the program assembled for a backend that runs words, else None); programs None when a\n        worker process compiled it (_precompile_layers). The runs of the states' slot 1 (an\n        MTP image's, _layer_slot) are kept under (key, \"slot\", 1).\"\"\"\n        ck = self._slot_key(key)\n        if ck not in self._layer_runs:\n            fut = self._layer_next.pop(ck, None)\n            if fut is not None and not fut.done() and not self._ready.done():\n                fut.cancel()                # the workers still starting: compiled here\n                fut = None\n            if fut is not None:             # (the words with their run_args: Words)\n                words, ra = fut.result()\n                self._layer_runs[ck] = (None, ra, Words.of(words, ra))\n            else:\n                progs, ra = layer_programs(self.image, key, self.block, self.layer_hint,\n                                           self.expert_major, self._layer_slot)\n                words = Words.of(I.assemble(progs[0]), ra) \\\n                    if getattr(self.backend, \"runs_words\", False) else None\n                self._layer_runs[ck] = (progs, ra, words)\n        return self._layer_runs[ck]\n\n    def _slot_key(self, key):\n        return key if not self._layer_slot else (key, \"slot\", self._layer_slot)\n\n    def _precompile_layers(self, keys) -> None:\n        \"\"\"prefill_layers' runs not compiled yet, compiled by the worker processes in the order\n        they run (the process pipeline): the card runs a layer while the next one's programs\n        compile (22-46 ms each against a layer's 200-460 ms, docs/offload.md 13.7). Queued\n        while the workers start too (a prompt right after the engine: the 26B's); until they\n        are up, _layer_run compiles a run here and drops its compile.\"\"\"\n        if not self._procs:\n            return\n        for k in dict.fromkeys(keys):\n            ck = self._slot_key(k)\n            if ck not in self._layer_runs and ck not in self._layer_next:\n                self._layer_next[ck] = self._pool.submit(_worker_layer, k, self.layer_hint,\n                                                         self.expert_major,\n                                                         *([self._layer_slot]\n                                                           if self._layer_slot else []))\n\n    def step_batch(self, tokens) -> np.ndarray:\n        \"\"\"One token for each of the first len(tokens) sequences, each at its own next\n        position (weights streamed once for all); returns logits [len(tokens), vocab].\"\"\"\n        n = len(tokens)\n        if n > self.batch:\n            raise ValueError(f\"{n} tokens for {self.batch} sequences\")\n        lg = self.run_rows([(s, self.poss[s]) for s in range(n)], tokens, list(range(n)))\n        for s in range(n):\n            self.poss[s] += 1\n        return lg\n\n    def generate_batch(self, prompts, max_new: int = 32, chunk: int | None = None) -> list:\n        \"\"\"Greedy generation for several prompts (one sequence each) decoded together; a\n        finished sequence (EOS, max_new, or its KV cache full) leaves the batch's runs, its\n        last token not fed (as generate).\"\"\"\n        n = len(prompts)\n        nxt = [int(np.argmax(self.prefill(p, seq=s, chunk=chunk)))\n               for s, p in enumerate(prompts)]\n        out = [[] for _ in range(n)]\n        done = [False] * n\n        for _ in range(max_new):\n            for s in range(n):\n                if not done[s]:\n                    out[s].append(nxt[s])\n                    done[s] = (nxt[s] in self.spec.eos or len(out[s]) >= max_new\n                               or self.poss[s] >= self.cap)\n            live = [s for s in range(n) if not done[s]]\n            if not live:\n                break\n            lg = self.run_rows([(s, self.poss[s]) for s in live], [nxt[s] for s in live],\n                               list(range(len(live))))\n            for s, r in zip(live, lg):\n                self.poss[s] += 1\n                nxt[s] = int(np.argmax(r))\n        return out\n\n    # ---- the decode loop on the device (opentpu/llm/generate.py)\n    @property\n    def can_generate(self) -> bool:\n        \"\"\"generate_card works here: resident decode on a backend that runs the generate\n        programs (the ISA simulator; the card with the ISA's RLD and ARGMAX).\"\"\"\n        return (self.resident and self.image.lookup.get(\"gen\") is not None\n                and bool(getattr(self.backend, \"generates\", False)))\n\n    def _generate_prog(self, blocks: int, samp=None):\n        \"\"\"The generate program of a bucket, greedy or sampled as `samp` (G.Sampling) is\n        compiled for (once per bucket and samp.key), chaining to the next bucket's when the\n        backend runs HALT CHAIN; with self.gen_debug the LM head also stores the logits (each\n        token's over the last: generate_card reads the last token's).\"\"\"\n        key = (blocks, None if samp is None else samp.key, self.gen_debug)\n        if key not in self._gens:\n            lo = max((blocks - 1) * self.block, self._conv_lo)\n            chain = bool(getattr(self.backend, \"chains\", False))\n            progs = self.cached((\"gen\", blocks, lo, chain, key[1], self.gen_debug,\n                                 self.gen_split),\n                                lambda: (G.compile_bucket(self.image, blocks, lo, self.block,\n                                                          chain=chain, samp=samp,\n                                                          debug=self.gen_debug,\n                                                          split=self.gen_split), None))[0]\n            prep = getattr(self.backend, \"prepare\", None)\n            if prep is not None:\n                for p in (progs if isinstance(progs, tuple) else (progs,)):\n                    prep(p)\n            self._gens[key] = progs\n        return self._gens[key]\n\n    def _generate_chain(self, b0: int, b1: int, samp=None) -> None:\n        \"\"\"Buckets b0 + 1 .. b1 in the chain area of samp's mode and its table (each written\n        once per samp.key).\"\"\"\n        g = self.image.lookup[\"gen\"]\n        mode = int(samp is not None)\n        key = (None if samp is None else samp.key, self.gen_debug)\n        if self._chained.get(mode, (key,))[0] != key:\n            self._chained.pop(mode)            # compiled for other sampling buffers\n        have = self._chained.setdefault(mode, (key, set()))[1]\n        # a split bucket chains back to its own first part: b0's programs too\n        lo = b0 if isinstance(self._generate_prog(b0, samp), tuple) else b0 + 1\n        new = [k for k in range(lo, b1 + 1) if k not in have]\n        if not new:\n            return\n        if getattr(self.backend, \"waitc\", False):   # (their wait entries at once: the workers)\n            items = [(np.asarray(I.assemble(prog), np.uint32), None, prog)\n                     for k in new for pj in (lambda p: p if isinstance(p, tuple) else (p,))(\n                         self._generate_prog(k, samp)) for prog in pj]\n            WC.entries_many(items, self.cfg.D, self.cfg.S,\n                            self._pool if self._procs and self._ready.done() else None)\n        for k in new:\n            progs = self._generate_prog(k, samp)\n            for j, pj in enumerate(progs if isinstance(progs, tuple) else (progs,)):\n                for s, prog in enumerate(pj):\n                    self.backend.write(s, G.prog_slot(g, k, mode, j),\n                                       G.slot_words(self.backend, prog))\n        have |= set(new)\n        for s in range(self.cfg.S):\n            words = {}\n            for k in have:\n                progs = self._generate_prog(k, samp)\n                words[k] = (tuple(I.assemble(p[s]) for p in progs) if isinstance(progs, tuple)\n                            else I.assemble(progs[s]))\n            self.backend.write(s, G.ptab_addr(g, mode), G.ptab_words(g, {\n                k: w[0] if isinstance(w, tuple) else w for k, w in words.items()}, mode))\n            self.backend.write(s, G.ptab2_addr(g, mode), G.ptab_words(g, {\n                k: w if isinstance(w, tuple) else (w,) for k, w in words.items()}, mode,\n                split=True))\n\n    def _generate_inputs(self, samp, p: int, nb: int, context, rng) -> None:\n        \"\"\"The sampled loop's per-run inputs: the uniforms of positions p + 1 .. p + nb (the\n        host's generator), and, with the repetition penalty, its factors for the context's ids\n        (the device adds the tokens it generates).\"\"\"\n        g = self.image.lookup[\"gen\"]\n        u = np.minimum(rng.random(nb).astype(np.float32), np.float32(1 - 2.0 ** -24))\n        pa = pb = None\n        if samp.pen:\n            V = G._vpad(self.spec)\n            pa, pb = np.ones(V, np.float32), np.ones(V, np.float32)\n            ix = np.unique(np.asarray(list(context), np.int64))\n            pa[ix] = np.float32(1.0) / np.float32(samp.penalty)\n            pb[ix] = samp.penalty\n        for s in range(self.cfg.S):\n            self.backend.write(s, g[\"uni\"] + 4 * (p + 1), u)\n            if pa is not None:\n                self.backend.write(s, g[\"pa\"], pa)\n                self.backend.write(s, g[\"pb\"], pb)\n\n    def generate_card(self, tok: int, n: int, stop_ids=None, on_token=None,\n                      stop=None, sampling=None, context=(), rng=None) -> list:\n        \"\"\"Feed `tok` at the next position and generate up to n tokens after it on the device:\n        the generate loop picks each token there and feeds it back, and stops at a stop id\n        (default: the model's EOS ids; the stop id is returned, not fed). Greedy, or with\n        `sampling` (G.Sampling: temperature, top-k, top-p, repetition penalty over `context`,\n        the ids so far with tok; the uniforms from `rng`, a numpy Generator). One device run\n        per attention bucket reached (one in all with HALT CHAIN); the logits never leave the\n        device. on_token(t) for each token as the host reads it; stop() (polled while the card\n        runs, on backends that stream the tokens) halts the loop after the token in flight.\n        Returns the tokens; self.pos is then the position of the last one (fed next, unless it\n        is a stop id).\"\"\"\n        if not self.can_generate:\n            raise RuntimeError(\"generate_card needs resident decode on a backend that runs \"\n                               \"the generate loop\")\n        samp = sampling\n        if samp is not None and rng is None:\n            raise ValueError(\"a sampled generate_card needs rng (the uniforms)\")\n        ids = list(self.spec.eos if stop_ids is None else stop_ids)\n        n = min(n, self.cap - self.pos)\n        out, g, ctx = [], self.image.lookup[\"gen\"], list(context)\n        while n > 0:\n            p = self.pos\n            if p < self._conv_lo:             # before the first run-time position\n                lg = self.step(tok)\n                got = [int(np.argmax(lg)) if samp is None else\n                       G.reference_pick(lg, samp, ctx, rng.random(), self.cfg.S,\n                                        getattr(self.spec, \"softcap\", None))]\n                if on_token is not None:\n                    on_token(got[0])\n            else:\n                b0 = p // self.block + 1\n                b1 = b0\n                if getattr(self.backend, \"chains\", False):     # the whole run on the device\n                    b1 = (p + n - 1) // self.block + 1\n                    self._generate_chain(b0, b1, samp)\n                progs = self._generate_prog(b0, samp)\n                if isinstance(progs, tuple):      # split: the run starts at the first part\n                    progs = progs[0]\n                nb = min(n, b1 * self.block - p)\n                if samp is not None:\n                    self._generate_inputs(samp, p, nb, ctx, rng)\n                self._write_host_rows([tok])        # the first token's rows (then the loop's\n                for s in range(self.cfg.S):         # requests, served while it runs)\n                    self.backend.write(s, g[\"state\"], G.state_words(self.spec, tok, p, n, ids,\n                                                                    self.block, samp))\n                    self.backend.write(s, g[\"out\"] + 4 * (p + 1),\n                                       np.full(nb, G.OUT_MARK, np.uint32))\n                runner = getattr(self.backend, \"run_generate\", None)\n                if runner is not None:     # the card: tokens as they land, stop() halts\n                    st, got = runner(progs, g[\"out\"] + 4 * (p + 1), nb, on_token, stop,\n                                     g[\"state\"])\n                else:\n                    st = self.backend.run(progs)\n                    w = self.backend.read(0, g[\"out\"] + 4 * (p + 1), 4 * nb).view(np.uint32)\n                    k = int(np.argmax(w == G.OUT_MARK)) if (w == G.OUT_MARK).any() else nb\n                    got = [int(x) for x in w[:k].view(np.float32)]\n                    if on_token is not None:\n                        for t in got:\n                            on_token(t)\n                self.stats.append(st)\n                self.pos += len(got)\n                if self.gen_debug:          # the logits of the run's last token\n                    io, v = self.image.io, self.image.v_loc\n                    self.gen_logits = np.concatenate([\n                        self.backend.read(s, io[\"logits\"] + 4 * s * v, 4 * v).view(np.float32)\n                        for s in range(self.cfg.S)])\n            out += got\n            ctx += got\n            n -= len(got)\n            if not got or got[-1] in ids or (stop is not None and stop()):\n                break\n            tok = got[-1]\n        return out\n\n    def generate(self, prompt, max_new: int = 32, sampler=None, on_token=None) -> list:\n        \"\"\"Greedy (or `sampler(logits) -> id`) generation; stops at an EOS token. The sampler\n        gets the logits Hugging Face's model returns: with the spec's final soft cap (Gemma's\n        final_logit_softcapping), which step() and prefill() leave out (greedy: their argmax,\n        the cap keeps the order); chat.sampler without its softcap samples them.\"\"\"\n        from .gemma4 import softcap\n        cap = getattr(self.spec, \"softcap\", None)\n        if sampler is not None and cap and getattr(sampler, \"softcap\", None):\n            raise ValueError(\"generate caps the logits it hands the sampler: a sampler with \"\n                             \"no softcap\")\n        logits = self.prefill(prompt)\n        out = []\n        for _ in range(max_new):\n            t = int(np.argmax(logits)) if sampler is None else \\\n                int(sampler(softcap(self.spec, logits) if cap else logits))\n            out.append(t)\n            if on_token:\n                on_token(t)\n            if t in self.spec.eos or self.pos >= self.cap:\n                break\n            logits = self.step(t)\n        return out\n"});
